/// One transaction-visible enum definition. Member storage belongs to the
/// startup-sized catalog slab, so copying this view never copies label data.
#[derive(Debug, Clone, Copy)]
pub struct EnumDefinition<'a> {
    catalog: &'a std::sync::Mutex<TypeCatalog>,
    member_image: usize,
    member_count: usize,
    pub(crate) database: DatabaseOid,
    pub created_at: u64,
    pub schema: SqlName,
    pub name: SqlName,
    pub ownership: Ownership,
    pub ddl_state: CatalogDdlState,
}

impl EnumDefinition<'_> {
    pub fn members(&self) -> EnumMemberIter<'_> {
        EnumMemberIter {
            catalog: self.catalog,
            next_slot: self.member_image,
            end_slot: self.member_image + self.member_count,
        }
    }

    pub fn sort_of(&self, label: &str) -> Option<f64> {
        self.members()
            .find(|member| member.label.as_str() == label)
            .map(|member| member.sort)
    }

    pub(crate) fn visible_to(&self, txid: u32) -> bool {
        self.ddl_state.visible_to(txid)
    }
}

pub struct EnumMemberIter<'a> {
    catalog: &'a std::sync::Mutex<TypeCatalog>,
    next_slot: usize,
    end_slot: usize,
}

impl Iterator for EnumMemberIter<'_> {
    type Item = EnumMember;

    fn next(&mut self) -> Option<Self::Item> {
        if self.next_slot == self.end_slot {
            return None;
        }
        let member = self
            .catalog
            .lock()
            .expect("type catalog lock poisoned")
            .enum_members[self.next_slot];
        self.next_slot += 1;
        Some(member)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = self.end_slot - self.next_slot;
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for EnumMemberIter<'_> {}

pub(crate) struct EnumReplayMembers<'a> {
    catalog: std::sync::MutexGuard<'a, TypeCatalog>,
    start: usize,
    count: usize,
}

impl std::ops::Deref for EnumReplayMembers<'_> {
    type Target = [EnumMember];

    fn deref(&self) -> &Self::Target {
        &self.catalog.enum_members[self.start..self.start + self.count]
    }
}

impl std::ops::DerefMut for EnumReplayMembers<'_> {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.catalog.enum_members[self.start..self.start + self.count]
    }
}

impl EnumDef {
    pub(crate) const EMPTY: Self = EnumDef {
        database: DatabaseOid::POSTGRES,
        created_at: 0,
        schema: SqlName::EMPTY,
        name: SqlName::EMPTY,
        ownership: Ownership::BOOTSTRAP,
        member_count: 0,
        pending_definition: None,
        ddl_state: CatalogDdlState::Absent,
    };

    pub(crate) fn visible_to(&self, txid: u32) -> bool {
        self.ddl_state.visible_to(txid)
    }

    pub(crate) fn definition_for(&self, txid: u32) -> Self {
        self.pending_definition
            .filter(|pending| pending.txid == txid)
            .map_or(*self, |pending| Self {
                schema: pending.schema,
                name: pending.name,
                member_count: pending.member_count,
                pending_definition: None,
                ..*self
            })
    }
}

/// The validated parameters of a `CREATE TYPE ... AS ENUM` / `ALTER TYPE`,
/// computed by the executor and handed to storage (apart from `live`/`pending`).
#[derive(Clone, Copy)]
pub struct EnumSpec<'a> {
    pub members: &'a [EnumMember],
}

/// One validated attribute of a named composite. `user_type` preserves the
/// stable name used to rebind catalog slots after recovery.
#[derive(Debug, Clone, Copy)]
pub struct CompositeFieldDef {
    /// Stable physical attribute number. Dropping an attribute never changes
    /// another attribute's number, which keeps old row values decodable.
    pub attribute_number: u16,
    pub name: SqlName,
    pub ctype: ColType,
    pub type_mod: i32,
    pub collation: Collation,
    pub user_type: Option<UserTypeName>,
    pub dropped: bool,
    pub not_null: bool,
}

impl CompositeFieldDef {
    pub(crate) const EMPTY: Self = Self {
        attribute_number: 0,
        name: SqlName::EMPTY,
        ctype: ColType::Bool,
        type_mod: -1,
        collation: Collation::None,
        user_type: None,
        dropped: true,
        not_null: false,
    };
}

/// A durable, named record layout. The type and field list are one catalog
/// object, so field access never needs to reparse a declaration string.
#[derive(Debug, Clone, Copy)]
pub struct CompositeDef {
    pub(crate) database: DatabaseOid,
    pub created_at: u64,
    pub schema: SqlName,
    pub name: SqlName,
    pub ownership: Ownership,
    pub fields: [CompositeFieldDef; MAX_COMPOSITE_FIELDS],
    pub n_fields: usize,
    pub(crate) pending_definition: Option<PendingCompositeDefinition>,
    pub ddl_state: CatalogDdlState,
}

/// A transaction-private composite layout. Attribute numbers are physical and
/// therefore remain stable across add/drop/rename operations.
#[derive(Debug, Clone, Copy)]
pub(crate) struct PendingCompositeDefinition {
    pub txid: u32,
    pub schema: SqlName,
    pub name: SqlName,
    pub fields: [CompositeFieldDef; MAX_COMPOSITE_FIELDS],
    pub n_fields: usize,
}

impl CompositeDef {
    pub(crate) const EMPTY: Self = Self {
        database: DatabaseOid::POSTGRES,
        created_at: 0,
        schema: SqlName::EMPTY,
        name: SqlName::EMPTY,
        ownership: Ownership::BOOTSTRAP,
        fields: [CompositeFieldDef::EMPTY; MAX_COMPOSITE_FIELDS],
        n_fields: 0,
        pending_definition: None,
        ddl_state: CatalogDdlState::Absent,
    };

    pub fn fields(&self) -> &[CompositeFieldDef] {
        &self.fields[..self.n_fields]
    }

    pub fn active_fields(&self) -> impl Iterator<Item = &CompositeFieldDef> {
        self.fields().iter().filter(|field| !field.dropped)
    }

    /// The field layout visible to one transaction. Returning a borrow into
    /// the catalog, rather than a copied definition, preserves the identity of
    /// transaction-private attribute names through Describe/RowDescription.
    pub fn fields_for(&self, txid: u32) -> &[CompositeFieldDef] {
        match self
            .pending_definition
            .as_ref()
            .filter(|pending| pending.txid == txid)
        {
            Some(pending) => &pending.fields[..pending.n_fields],
            None => self.fields(),
        }
    }

    pub fn active_fields_for(&self, txid: u32) -> impl Iterator<Item = &CompositeFieldDef> {
        self.fields_for(txid).iter().filter(|field| !field.dropped)
    }

    pub fn active_field_count(&self) -> usize {
        self.active_fields().count()
    }

    pub fn active_field(&self, index: usize) -> Option<&CompositeFieldDef> {
        self.active_fields().nth(index)
    }

    pub fn active_field_index(&self, name: &str) -> Option<usize> {
        self.fields()
            .iter()
            .position(|field| !field.dropped && field.name.as_str() == name)
    }

    pub(crate) fn visible_to(&self, txid: u32) -> bool {
        self.ddl_state.visible_to(txid)
    }

    pub(crate) fn definition_for(&self, txid: u32) -> Self {
        self.pending_definition
            .filter(|pending| pending.txid == txid)
            .map_or(*self, |pending| Self {
                schema: pending.schema,
                name: pending.name,
                fields: pending.fields,
                n_fields: pending.n_fields,
                pending_definition: None,
                ..*self
            })
    }
}

#[derive(Clone, Copy)]
pub struct CompositeSpec {
    pub fields: [CompositeFieldDef; MAX_COMPOSITE_FIELDS],
    pub n_fields: usize,
}

/// A sequence's declared integer type: it sets the default MIN/MAXVALUE and the
/// `pg_sequence.seqtypid` the catalog reports.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SeqType {
    Smallint,
    Integer,
    Bigint,
}

impl SeqType {
    /// The type's representable range, bounding explicit MIN/MAXVALUE.
    pub fn bounds(self) -> (i64, i64) {
        match self {
            SeqType::Smallint => (i16::MIN as i64, i16::MAX as i64),
            SeqType::Integer => (i32::MIN as i64, i32::MAX as i64),
            SeqType::Bigint => (i64::MIN, i64::MAX),
        }
    }

    /// `pg_type` OID (`int2`/`int4`/`int8`), for `pg_sequence.seqtypid`.
    pub fn oid(self) -> i32 {
        match self {
            SeqType::Smallint => 21,
            SeqType::Integer => 23,
            SeqType::Bigint => 20,
        }
    }

    pub fn sql_name(self) -> &'static str {
        match self {
            SeqType::Smallint => "smallint",
            SeqType::Integer => "integer",
            SeqType::Bigint => "bigint",
        }
    }

    pub fn to_u8(self) -> u8 {
        match self {
            SeqType::Smallint => 0,
            SeqType::Integer => 1,
            SeqType::Bigint => 2,
        }
    }

    pub fn from_u8(v: u8) -> SeqType {
        match v {
            0 => SeqType::Smallint,
            1 => SeqType::Integer,
            _ => SeqType::Bigint,
        }
    }
}

/// A named sequence generator. Its *existence* (`live`/`pending`) is
/// transactional catalog state, mirroring [`ViewDef`]. Ordinary value advances
/// survive `ROLLBACK`, while a staged definition owns a private value image
/// until commit. Definitions and mutable values share one catalog boundary.
#[derive(Clone, Copy)]
pub struct SequenceDef {
    pub(crate) database: DatabaseOid,
    pub created_at: u64,
    cache_generation: u64,
    pub schema: SqlName,
    pub name: SqlName,
    pub ownership: Ownership,
    pub data_type: SeqType,
    pub increment: i64,
    pub min_value: i64,
    pub max_value: i64,
    pub start_value: i64,
    pub cache: i64,
    pub cycle: bool,
    pub persistence: RelationPersistence,
    /// The table column whose lifetime owns this sequence. Names, rather than
    /// slots, keep the dependency stable across checkpoint restore and
    /// catalog-slot reuse.
    pub owner: Option<SequenceOwner>,
    /// The serial/identity column whose omitted values this sequence generates.
    /// This is deliberately separate from `owner`: PostgreSQL permits a serial
    /// sequence's OWNED BY dependency to be removed without changing the
    /// column's `nextval` default.
    pub generator_for: Option<SequenceOwner>,
    pub(crate) pending_definition: Option<PendingSequenceDefinition>,
    ddl_state: CatalogDdlState,
}

impl SequenceDef {
    const EMPTY: Self = Self {
        database: DatabaseOid::POSTGRES,
        created_at: 0,
        cache_generation: 0,
        schema: SqlName::EMPTY,
        name: SqlName::EMPTY,
        ownership: Ownership::BOOTSTRAP,
        data_type: SeqType::Bigint,
        increment: 1,
        min_value: 1,
        max_value: i64::MAX,
        start_value: 1,
        cache: 1,
        cycle: false,
        persistence: RelationPersistence::Permanent,
        owner: None,
        generator_for: None,
        pending_definition: None,
        ddl_state: CatalogDdlState::Absent,
    };
}

#[derive(Clone, Copy, Debug)]
struct SequenceValue {
    /// The last value handed out (meaningful only when `is_called`); on CREATE /
    /// RESTART it holds the start value with `is_called == false`, so the first
    /// `nextval` returns it unchanged (PostgreSQL's `setval(seq, start, false)`).
    last_value: i64,
    is_called: bool,
    log_count: i64,
    /// The value changed since it was last journaled. Sequence advances remain
    /// nontransactional when the surrounding transaction rolls back.
    dirty: bool,
    generation: u64,
    staged_generation: u64,
}

impl SequenceValue {
    const fn initial(value: i64) -> Self {
        Self {
            last_value: value,
            is_called: false,
            log_count: 0,
            dirty: false,
            generation: 0,
            staged_generation: 0,
        }
    }
}

#[derive(Clone, Copy, Debug)]
struct SequenceValues {
    committed: SequenceValue,
    pending: SequenceValue,
}

impl SequenceValues {
    const fn initial(value: i64) -> Self {
        Self {
            committed: SequenceValue::initial(value),
            pending: SequenceValue::initial(value),
        }
    }
}

struct SequenceCatalog {
    definitions: FixedVec<SequenceDef>,
    values: FixedVec<SequenceValues>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct SequenceCacheIdentity {
    created_at: u64,
    generation: u64,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct PendingSequenceDefinition {
    pub txid: u32,
    pub schema: SqlName,
    pub name: SqlName,
    pub spec: SeqSpec,
    pub owner: Option<SequenceOwner>,
    pub generator_for: Option<SequenceOwner>,
    pub persistence: RelationPersistence,
    pub last_value: i64,
    pub is_called: bool,
    pub log_count: i64,
    /// A staged RESTART owns its temporary value image. Other definition
    /// changes do not make `nextval` transactional.
    pub restarted: bool,
}

#[derive(Debug, Clone, Copy)]
pub(crate) enum SequenceValueState {
    Committed {
        last_value: i64,
        is_called: bool,
        log_count: i64,
        dirty: bool,
        generation: u64,
        staged_generation: u64,
    },
    Pending {
        last_value: i64,
        is_called: bool,
        log_count: i64,
        dirty: bool,
        generation: u64,
        staged_generation: u64,
    },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SequenceOwner {
    pub table_schema: SqlName,
    pub table: SqlName,
    pub column: SqlName,
}

fn rebind_sequence_column(
    link: Option<SequenceOwner>,
    old: &TableDef,
    new: &TableDef,
    column_mapping: &[Option<SqlName>; MAX_COLUMNS],
    require_generator: bool,
) -> Option<SequenceOwner> {
    let mut link = link?;
    if link.table_schema != old.schema || link.table != old.name {
        return Some(link);
    }
    let old_column = old.column_index(link.column.as_str())?;
    let target_name = column_mapping[old_column]?;
    let target = new
        .column_index(target_name.as_str())
        .filter(|&column| !require_generator || new.columns()[column].auto_increment)?;
    link.table_schema = new.schema;
    link.table = new.name;
    link.column = new.columns()[target].name;
    Some(link)
}

/// The tunable parameters of a sequence, computed and validated by the executor
/// from the CREATE/ALTER options, then handed to storage. Kept apart from the
/// live value state.
#[derive(Debug, Clone, Copy)]
pub(crate) struct SeqSpec {
    pub data_type: SeqType,
    pub increment: i64,
    pub min_value: i64,
    pub max_value: i64,
    pub start_value: i64,
    pub cache: i64,
    pub cycle: bool,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SequenceCreateSpec {
    pub schema: SqlName,
    pub name: SqlName,
    pub spec: SeqSpec,
    pub owner: Option<SequenceOwner>,
    pub generator_for: Option<SequenceOwner>,
    pub persistence: RelationPersistence,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct SequenceAlteration {
    pub schema: SqlName,
    pub name: SqlName,
    pub spec: SeqSpec,
    pub owner: Option<SequenceOwner>,
    pub generator_for: Option<SequenceOwner>,
    pub persistence: RelationPersistence,
    pub restart: Option<i64>,
}

impl SequenceDef {
    pub(crate) fn cache_identity(&self) -> SequenceCacheIdentity {
        SequenceCacheIdentity {
            created_at: self.created_at,
            generation: self.cache_generation,
        }
    }

    pub(crate) fn visible_to(&self, txid: u32) -> bool {
        self.ddl_state.visible_to(txid)
    }

    pub(crate) fn definition_for(&self, txid: u32) -> Self {
        self.pending_definition
            .filter(|pending| pending.txid == txid)
            .map_or_else(
                || *self,
                |pending| Self {
                    schema: pending.schema,
                    name: pending.name,
                    data_type: pending.spec.data_type,
                    increment: pending.spec.increment,
                    min_value: pending.spec.min_value,
                    max_value: pending.spec.max_value,
                    start_value: pending.spec.start_value,
                    cache: pending.spec.cache,
                    cycle: pending.spec.cycle,
                    owner: pending.owner,
                    generator_for: pending.generator_for,
                    persistence: pending.persistence,
                    cache_generation: self.cache_generation.wrapping_add(1),
                    pending_definition: None,
                    ..*self
                },
            )
    }

    fn next_after(&self, current: i64) -> Result<i64, SqlError> {
        let next = current.checked_add(self.increment);
        if self.increment > 0 {
            match next {
                Some(value) if value <= self.max_value => Ok(value),
                _ if self.cycle => Ok(self.min_value),
                _ => Err(sql_err!(
                    sqlstate::SEQUENCE_GENERATOR_LIMIT_EXCEEDED,
                    "nextval: reached maximum value of sequence \"{}\" ({})",
                    self.name.as_str(),
                    self.max_value
                )),
            }
        } else {
            match next {
                Some(value) if value >= self.min_value => Ok(value),
                _ if self.cycle => Ok(self.max_value),
                _ => Err(sql_err!(
                    sqlstate::SEQUENCE_GENERATOR_LIMIT_EXCEEDED,
                    "nextval: reached minimum value of sequence \"{}\" ({})",
                    self.name.as_str(),
                    self.min_value
                )),
            }
        }
    }

    fn reserve_values_with(
        &self,
        value: &mut SequenceValue,
        requested: i64,
    ) -> Result<(i64, i64, bool), SqlError> {
        debug_assert!(requested > 0);
        let first = if value.is_called {
            self.next_after(value.last_value)?
        } else {
            value.last_value
        };
        let step = i128::from(self.increment);
        let requested = i128::from(requested);
        let available = if step > 0 {
            (i128::from(self.max_value) - i128::from(first)) / step + 1
        } else {
            (i128::from(first) - i128::from(self.min_value)) / -step + 1
        };
        let reserved = requested.min(available);
        let last = i128::from(first) + (reserved - 1) * step;
        let reserved = i64::try_from(reserved).expect("requested cache count is i64");
        value.last_value = i64::try_from(last).expect("sequence bounds constrain reserved value");
        value.is_called = true;
        let previous_log_count = value.log_count;
        let prelogged = previous_log_count < reserved;
        value.log_count = if prelogged {
            let trailing = if step > 0 {
                (i128::from(self.max_value) - last) / step
            } else {
                (last - i128::from(self.min_value)) / -step
            };
            i64::try_from(trailing.min(32)).expect("prelogged sequence count is bounded")
        } else {
            previous_log_count - reserved
        };
        value.dirty = true;
        value.generation = value.generation.wrapping_add(1);
        Ok((first, reserved, prelogged))
    }

    /// Validates a `setval` target is within `[min, max]` (22003), without
    /// moving the generator.
    pub fn check_setval(&self, value: i64) -> Result<(), SqlError> {
        if value < self.min_value || value > self.max_value {
            return Err(sql_err!(
                sqlstate::NUMERIC_OUT_OF_RANGE,
                "setval: value {} is out of bounds for sequence \"{}\" ({}..{})",
                value,
                self.name.as_str(),
                self.min_value,
                self.max_value
            ));
        }
        Ok(())
    }

    fn set_value_with(
        &self,
        value: i64,
        is_called: bool,
        state: &mut SequenceValue,
    ) -> Result<i64, SqlError> {
        self.check_setval(value)?;
        state.last_value = value;
        state.is_called = is_called;
        state.log_count = 0;
        state.dirty = true;
        state.generation = state.generation.wrapping_add(1);
        Ok(value)
    }
}

/// PostgreSQL 18's `INDEX_MAX_KEYS` boundary is 32 attributes, including
/// INCLUDE columns. Source:
/// https://github.com/postgres/postgres/blob/REL_18_STABLE/src/include/pg_config_manual.h
pub(crate) const MAX_INDEX_COLS: usize = 32;
/// Durable WAL count width for one BRIN maintenance image. Configuration can
/// reserve any smaller per-index capacity at startup.
pub(crate) const MAX_BRIN_UNSUMMARIZED_RANGES: usize = u8::MAX as usize;

#[derive(Clone, Copy, Debug)]
pub(crate) struct BrinMaintenanceState {
    pub(crate) index_created_at: u64,
    /// Physical range geometry captured when the index was built. ALTERing
    /// the reloption affects a future rebuild, not existing summary tuples.
    pub(crate) pages_per_range: u32,
    /// Exclusive logical page boundary covered when the index was built or
    /// new ranges were last discovered. It is rounded to pages_per_range.
    pub(crate) summarized_until_page: u64,
    pub(crate) count: u8,
    pub(crate) wal_dirty: bool,
}

impl BrinMaintenanceState {
    const EMPTY: Self = Self {
        index_created_at: 0,
        pages_per_range: 0,
        summarized_until_page: 0,
        count: 0,
        wal_dirty: false,
    };
}

struct BrinMaintenance {
    states: FixedVec<BrinMaintenanceState>,
    unsummarized_ranges: FixedVec<u64>,
}

/// Comparison contract selected for one explicit btree index key.
///
/// An omitted class remains `None` in [`IndexDef`] so `pg_get_indexdef` can
/// distinguish implicit defaults from explicitly written classes. Once
/// resolved, a class is either one of the closed built-ins or one durable
/// user-catalog identity; a catalog name or slot can never masquerade as an
/// executable class.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum IndexOperatorClass {
    Btree(crate::sql::types::BtreeOperatorClass),
    Hash(crate::sql::types::HashOperatorClass),
    Brin(crate::sql::types::BrinOperatorClass),
    Gist(crate::sql::types::GistOperatorClass),
    Gin(crate::sql::types::GinOperatorClass),
    SpGist(crate::sql::types::SpGistOperatorClass),
    Catalog(OperatorClassOid),
}

impl IndexOperatorClass {
    pub(crate) const fn oid(self) -> i32 {
        match self {
            Self::Btree(class) => class.oid(),
            Self::Hash(class) => class.oid(),
            Self::Brin(class) => class.oid(),
            Self::Gist(class) => class.oid(),
            Self::Gin(class) => class.oid(),
            Self::SpGist(class) => class.oid(),
            Self::Catalog(oid) => oid.get(),
        }
    }
}

/// Maximum stored source length of a partial-index membership predicate.
///
/// Predicate text is catalog data, not request-owned parser memory. A fixed
/// representation keeps the definition replayable without runtime growth.
pub(crate) const INDEX_PREDICATE_MAX: usize = CHECK_SQL_MAX;
/// Maximum canonical source length of one expression index key.
pub(crate) const INDEX_EXPRESSION_MAX: usize = CHECK_SQL_MAX;

/// Copies validated partial-index predicate source into its durable bounded
/// representation.
pub(crate) fn index_predicate_stackstr(
    predicate: &str,
) -> Result<StackStr<INDEX_PREDICATE_MAX>, SqlError> {
    let value = StackStr::from_str(predicate);
    if value.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "index predicate exceeds {} bytes",
            INDEX_PREDICATE_MAX
        ));
    }
    Ok(value)
}

/// Copies validated expression-key source into its durable bounded form.
pub(crate) fn index_expression_stackstr(
    expression: &str,
) -> Result<StackStr<INDEX_EXPRESSION_MAX>, SqlError> {
    let value = StackStr::from_str(expression);
    if value.is_truncated() {
        return Err(sql_err!(
            sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "index expression exceeds {} bytes",
            INDEX_EXPRESSION_MAX
        ));
    }
    Ok(value)
}

pub(crate) const USER_DATABASE_OID_BASE: i32 = 16_383;
pub(crate) const TABLESPACE_LOCATION_MAX: usize = 256;

/// Stable database identity. Catalog slots are reusable, so session, ACL,
/// setting, WAL, and object identities carry this OID instead.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) struct DatabaseOid(i32);

impl DatabaseOid {
    pub(crate) const TEMPLATE1: Self = Self(1);
    pub(crate) const TEMPLATE0: Self = Self(4);
    pub(crate) const POSTGRES: Self = Self(5);

    pub(crate) const fn parse(oid: i32) -> Option<Self> {
        if oid == Self::TEMPLATE1.0
            || oid == Self::TEMPLATE0.0
            || oid == Self::POSTGRES.0
            || oid > USER_DATABASE_OID_BASE
        {
            Some(Self(oid))
        } else {
            None
        }
    }

    pub(crate) const fn get(self) -> i32 {
        self.0
    }

    fn next_after(self) -> Option<Self> {
        self.0.checked_add(1).and_then(Self::parse)
    }
}

fn current_database() -> DatabaseOid {
    crate::sql::execution_database_oid()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum DatabaseEncoding {
    Utf8,
    SqlAscii,
}

impl DatabaseEncoding {
    pub(crate) const fn code(self) -> i32 {
        match self {
            Self::SqlAscii => 0,
            Self::Utf8 => 6,
        }
    }

    pub(crate) const fn from_code(code: u8) -> Option<Self> {
        match code {
            0 => Some(Self::SqlAscii),
            6 => Some(Self::Utf8),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum DatabaseLocaleProvider {
    Builtin,
    Libc,
}

impl DatabaseLocaleProvider {
    pub(crate) const fn code(self) -> u8 {
        match self {
            Self::Builtin => b'b',
            Self::Libc => b'c',
        }
    }

    pub(crate) const fn from_code(code: u8) -> Option<Self> {
        match code {
            b'b' => Some(Self::Builtin),
            b'c' => Some(Self::Libc),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct DatabaseDefinition {
    pub name: SqlName,
    pub encoding: DatabaseEncoding,
    pub locale_provider: DatabaseLocaleProvider,
    pub collate: StackStr<128>,
    pub ctype: StackStr<128>,
    pub locale: StackStr<128>,
    pub collation_version: StackStr<64>,
    pub allow_connections: bool,
    pub connection_limit: i32,
    pub is_template: bool,
    /// Stable internal tablespace identifier; zero and one name the built-ins.
    pub tablespace: u16,
}

impl DatabaseDefinition {
    const EMPTY: Self = Self {
        name: SqlName::EMPTY,
        encoding: DatabaseEncoding::Utf8,
        locale_provider: DatabaseLocaleProvider::Libc,
        collate: StackStr::new(),
        ctype: StackStr::new(),
        locale: StackStr::new(),
        collation_version: StackStr::new(),
        allow_connections: false,
        connection_limit: -1,
        is_template: false,
        tablespace: 0,
    };

    fn builtin(name: &str, template: bool, allow_connections: bool, locale: &str) -> Self {
        Self {
            name: SqlName::parse(name).expect("built-in database name fits"),
            encoding: DatabaseEncoding::Utf8,
            locale_provider: DatabaseLocaleProvider::Libc,
            collate: StackStr::from_str(locale),
            ctype: StackStr::from_str(locale),
            locale: StackStr::new(),
            collation_version: StackStr::new(),
            allow_connections,
            connection_limit: -1,
            is_template: template,
            tablespace: 0,
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct PendingDatabaseDefinition {
    pub txid: u32,
    pub definition: DatabaseDefinition,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct DatabaseDef {
    pub oid: DatabaseOid,
    pub definition: DatabaseDefinition,
    pub pending: Option<PendingDatabaseDefinition>,
    pub ownership: Ownership,
    pub ddl_state: CatalogDdlState,
}

impl DatabaseDef {
    const EMPTY: Self = Self {
        oid: DatabaseOid::POSTGRES,
        definition: DatabaseDefinition::EMPTY,
        pending: None,
        ownership: Ownership::BOOTSTRAP,
        ddl_state: CatalogDdlState::Absent,
    };

    fn name_blocker(&self, name: SqlName, txid: u32) -> Option<u32> {
        if self.ddl_state == CatalogDdlState::Absent {
            return None;
        }
        if let Some(pending) = self.pending
            && pending.definition.name == name
            && pending.txid != txid
        {
            return Some(pending.txid);
        }
        (self.definition_for(txid).name == name)
            .then(|| self.ddl_state.pending_txid())
            .flatten()
            .filter(|owner| *owner != txid)
    }

    fn builtin(
        oid: DatabaseOid,
        name: &str,
        template: bool,
        allow_connections: bool,
        locale: &str,
    ) -> Self {
        Self {
            oid,
            definition: DatabaseDefinition::builtin(name, template, allow_connections, locale),
            pending: None,
            ownership: Ownership::BOOTSTRAP,
            ddl_state: CatalogDdlState::Present,
        }
    }

    pub(crate) fn visible_to(&self, txid: u32) -> bool {
        self.ddl_state.visible_to(txid)
    }

    pub(crate) fn definition_for(&self, txid: u32) -> DatabaseDefinition {
        self.pending
            .filter(|pending| pending.txid == txid)
            .map_or(self.definition, |pending| pending.definition)
    }
}

