    pub(crate) fn set_object_owner(
        &mut self,
        object: AccessObject,
        owner: usize,
        txid: u32,
    ) -> Option<PendingOwnership> {
        if object.class == AccessClass::LargeObject {
            let mut catalog = self
                .large_objects
                .lock()
                .expect("large object catalog lock poisoned");
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::Routine {
            let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
            let ownership = &mut routines[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::EventTrigger {
            let mut event_triggers = self
                .event_triggers
                .lock()
                .expect("event trigger catalog lock poisoned");
            let trigger = &mut event_triggers[usize::from(object.slot)];
            let ownership = &mut trigger.definition.ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            if let Some(pending) = &mut trigger.pending {
                if txid == 0 {
                    pending.definition.ownership.owner = owner as u16;
                    pending.definition.ownership.pending = None;
                } else {
                    pending.definition.ownership.pending = Some(PendingOwnership {
                        txid,
                        owner: owner as u16,
                    });
                }
            }
            return prior;
        }
        if object.class == AccessClass::Statistics {
            let mut catalog = self
                .extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned");
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::Sequence {
            let mut catalog = self.sequence_catalog();
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::Database {
            let mut catalog = self.database_catalog();
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::Index {
            let mut catalog = self.index_catalog();
            let ownership = &mut catalog[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::View {
            let mut catalog = self.view_rule_catalog();
            let ownership = &mut catalog.views[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::MaterializedView {
            let mut matviews = self.matview_catalog();
            let ownership = &mut matviews[usize::from(object.slot)].ownership;
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        if object.class == AccessClass::Tablespace {
            unreachable!("tablespace ownership is synchronized separately");
        }
        if object.class == AccessClass::Schema {
            unreachable!("schema ownership is synchronized separately");
        }
        if object.class == AccessClass::Extension {
            unreachable!("extension ownership is synchronized separately");
        }
        if matches!(
            object.class,
            AccessClass::ForeignDataWrapper | AccessClass::ForeignServer
        ) {
            let class = if object.class == AccessClass::ForeignDataWrapper {
                foreign::ForeignObjectClass::Wrapper
            } else {
                foreign::ForeignObjectClass::Server
            };
            return self
                .foreign_catalog()
                .stage_owner(class, usize::from(object.slot), owner as u16, txid)
                .expect("foreign ownership conflict is handled at the DDL boundary");
        }
        if matches!(
            object.class,
            AccessClass::Domain | AccessClass::Enum | AccessClass::Composite
        ) {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let ownership = match object.class {
                AccessClass::Domain => &mut catalog.domains[usize::from(object.slot)].ownership,
                AccessClass::Enum => &mut catalog.enums[usize::from(object.slot)].ownership,
                AccessClass::Composite => {
                    &mut catalog.composites[usize::from(object.slot)].ownership
                }
                _ => unreachable!(),
            };
            let prior = ownership.pending;
            if txid == 0 {
                ownership.owner = owner as u16;
                ownership.pending = None;
            } else {
                ownership.pending = Some(PendingOwnership {
                    txid,
                    owner: owner as u16,
                });
            }
            return prior;
        }
        let ownership = self.ownership_mut(object);
        let prior = ownership.pending;
        if txid == 0 {
            ownership.owner = owner as u16;
            ownership.pending = None;
        } else {
            ownership.pending = Some(PendingOwnership {
                txid,
                owner: owner as u16,
            });
        }
        prior
    }

    pub(crate) fn commit_object_owner(&mut self, object: AccessObject, txid: u32) {
        if object.class == AccessClass::LargeObject {
            let mut catalog = self
                .large_objects
                .lock()
                .expect("large object catalog lock poisoned");
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Routine {
            let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
            let ownership = &mut routines[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::EventTrigger {
            let mut event_triggers = self
                .event_triggers
                .lock()
                .expect("event trigger catalog lock poisoned");
            let trigger = &mut event_triggers[usize::from(object.slot)];
            let ownership = &mut trigger.definition.ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            if let Some(definition) = &mut trigger.pending {
                let ownership = &mut definition.definition.ownership;
                if let Some(pending) = ownership.pending
                    && pending.txid == txid
                {
                    ownership.owner = pending.owner;
                    ownership.pending = None;
                }
            }
            return;
        }
        if object.class == AccessClass::Statistics {
            let mut catalog = self
                .extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned");
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Sequence {
            let mut catalog = self.sequence_catalog();
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Database {
            let mut catalog = self.database_catalog();
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Index {
            let mut catalog = self.index_catalog();
            let ownership = &mut catalog[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::View {
            let mut catalog = self.view_rule_catalog();
            let ownership = &mut catalog.views[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::MaterializedView {
            let mut matviews = self.matview_catalog();
            let ownership = &mut matviews[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Tablespace {
            let mut tablespaces = self
                .tablespaces
                .lock()
                .expect("tablespace catalog lock poisoned");
            let ownership = &mut tablespaces[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Schema {
            let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
            let ownership = &mut schemas[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if object.class == AccessClass::Extension {
            let mut catalog = self.extension_catalog();
            let ownership = &mut catalog.definitions[usize::from(object.slot)].ownership;
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        if matches!(
            object.class,
            AccessClass::ForeignDataWrapper | AccessClass::ForeignServer
        ) {
            let class = if object.class == AccessClass::ForeignDataWrapper {
                foreign::ForeignObjectClass::Wrapper
            } else {
                foreign::ForeignObjectClass::Server
            };
            self.foreign_catalog()
                .commit_owner(class, usize::from(object.slot), txid);
            return;
        }
        if matches!(
            object.class,
            AccessClass::Domain | AccessClass::Enum | AccessClass::Composite
        ) {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let ownership = match object.class {
                AccessClass::Domain => &mut catalog.domains[usize::from(object.slot)].ownership,
                AccessClass::Enum => &mut catalog.enums[usize::from(object.slot)].ownership,
                AccessClass::Composite => {
                    &mut catalog.composites[usize::from(object.slot)].ownership
                }
                _ => unreachable!(),
            };
            if let Some(pending) = ownership.pending
                && pending.txid == txid
            {
                ownership.owner = pending.owner;
                ownership.pending = None;
            }
            return;
        }
        let ownership = self.ownership_mut(object);
        if let Some(pending) = ownership.pending
            && pending.txid == txid
        {
            ownership.owner = pending.owner;
            ownership.pending = None;
        }
    }

    pub(crate) fn restore_object_owner(
        &mut self,
        object: AccessObject,
        prior: Option<PendingOwnership>,
    ) {
        if object.class == AccessClass::LargeObject {
            self.large_objects
                .lock()
                .expect("large object catalog lock poisoned")
                .definitions[usize::from(object.slot)]
            .ownership
            .pending = prior;
            return;
        }
        if object.class == AccessClass::Sequence {
            self.sequence_catalog().definitions[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::Database {
            self.database_catalog().definitions[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::Index {
            self.index_catalog()[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::View {
            self.view_rule_catalog().views[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::MaterializedView {
            self.matview_catalog()[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::Tablespace {
            self.tablespaces
                .lock()
                .expect("tablespace catalog lock poisoned")[usize::from(object.slot)]
            .ownership
            .pending = prior;
            return;
        }
        if object.class == AccessClass::Schema {
            self.schemas.lock().expect("schema catalog lock poisoned")[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if object.class == AccessClass::Extension {
            self.extension_catalog().definitions[usize::from(object.slot)]
                .ownership
                .pending = prior;
            return;
        }
        if matches!(
            object.class,
            AccessClass::ForeignDataWrapper | AccessClass::ForeignServer
        ) {
            let class = if object.class == AccessClass::ForeignDataWrapper {
                foreign::ForeignObjectClass::Wrapper
            } else {
                foreign::ForeignObjectClass::Server
            };
            self.foreign_catalog()
                .rollback_owner(class, usize::from(object.slot), prior);
            return;
        }
        if object.class == AccessClass::Routine {
            self.routines.lock().expect("routine catalog lock poisoned")
                [usize::from(object.slot)]
            .ownership
            .pending = prior;
            return;
        }
        if object.class == AccessClass::EventTrigger {
            let mut event_triggers = self
                .event_triggers
                .lock()
                .expect("event trigger catalog lock poisoned");
            let trigger = &mut event_triggers[usize::from(object.slot)];
            trigger.definition.ownership.pending = prior;
            if let Some(definition) = &mut trigger.pending {
                definition.definition.ownership.pending = prior;
            }
            return;
        }
        if object.class == AccessClass::Statistics {
            self.extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned")
                .definitions[usize::from(object.slot)]
            .ownership
            .pending = prior;
            return;
        }
        if matches!(
            object.class,
            AccessClass::Domain | AccessClass::Enum | AccessClass::Composite
        ) {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            match object.class {
                AccessClass::Domain => {
                    catalog.domains[usize::from(object.slot)].ownership.pending = prior
                }
                AccessClass::Enum => {
                    catalog.enums[usize::from(object.slot)].ownership.pending = prior
                }
                AccessClass::Composite => {
                    catalog.composites[usize::from(object.slot)]
                        .ownership
                        .pending = prior
                }
                _ => unreachable!(),
            }
            return;
        }
        self.ownership_mut(object).pending = prior;
    }

    fn acl_visible(entry: &AclEntry, txid: u32) -> (bool, u16, u16, PrivilegeSet, PrivilegeSet) {
        match entry.pending {
            Some(pending) if pending.txid == txid => (
                pending.privileges.0 != 0,
                pending.grantee,
                pending.grantor,
                pending.privileges,
                pending.grant_options,
            ),
            _ => (
                entry.live,
                entry.grantee,
                entry.grantor,
                entry.privileges,
                entry.grant_options,
            ),
        }
    }

    pub(crate) fn change_acl(
        &self,
        object: AccessObject,
        grantee: u16,
        grantor: u16,
        privileges: PrivilegeSet,
        grant_options: PrivilegeSet,
        txid: u32,
    ) -> Result<(usize, Option<PendingAcl>), SqlError> {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let slot = catalog
            .objects
            .iter()
            .position(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) = Self::acl_visible(entry, txid);
                entry.object == object
                    && visible_grantee == grantee
                    && visible_grantor == grantor
                    && (entry.live || entry.pending.is_some())
            })
            .or_else(|| {
                catalog.objects.iter().position(|entry| {
                    entry.object.slot == u16::MAX && !entry.live && entry.pending.is_none()
                })
            })
            .unwrap_or(catalog.objects.len());
        if slot == catalog.objects.len() {
            catalog
                .objects
                .push(AclEntry {
                    object,
                    grantee,
                    grantor,
                    privileges: PrivilegeSet::NONE,
                    grant_options: PrivilegeSet::NONE,
                    live: false,
                    pending: None,
                })
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many object privilege entries (limit {})",
                        catalog.objects.capacity()
                    )
                })?;
        } else if catalog.objects[slot].object.slot == u16::MAX {
            catalog.objects[slot].object = object;
            catalog.objects[slot].grantee = grantee;
            catalog.objects[slot].grantor = grantor;
        }
        let entry = &mut catalog.objects[slot];
        let prior = entry.pending;
        if txid == 0 {
            entry.grantee = grantee;
            entry.grantor = grantor;
            entry.privileges = privileges;
            entry.grant_options = grant_options;
            entry.live = privileges.0 != 0;
            entry.pending = None;
        } else {
            entry.pending = Some(PendingAcl {
                txid,
                grantee,
                grantor,
                privileges,
                grant_options,
            });
        }
        Ok((slot, prior))
    }

    fn acl_to_entries(
        entries: &[AclEntry],
        object: AccessObject,
        grantee: u16,
        txid: u32,
    ) -> (PrivilegeSet, PrivilegeSet) {
        entries
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, _, _, _) = Self::acl_visible(entry, txid);
                entry.object == object && visible_grantee == grantee
            })
            .fold(
                (PrivilegeSet::NONE, PrivilegeSet::NONE),
                |(privileges, grant_options), entry| {
                    let (visible, _, _, entry_privileges, entry_grant_options) =
                        Self::acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            grant_options.union(entry_grant_options),
                        )
                    } else {
                        (privileges, grant_options)
                    }
                },
            )
    }

    pub(crate) fn acl_from(
        &self,
        object: AccessObject,
        grantee: u16,
        grantor: u16,
        txid: u32,
    ) -> (PrivilegeSet, PrivilegeSet) {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        catalog
            .objects
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) = Self::acl_visible(entry, txid);
                entry.object == object
                    && visible_grantee == grantee
                    && visible_grantor == grantor
                    && (entry.live || entry.pending.is_some())
            })
            .fold(
                (PrivilegeSet::NONE, PrivilegeSet::NONE),
                |(privileges, grant_options), entry| {
                    let (visible, _, _, entry_privileges, entry_grant_options) =
                        Self::acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            grant_options.union(entry_grant_options),
                        )
                    } else {
                        (privileges, grant_options)
                    }
                },
            )
    }

    pub(crate) fn acl_state(&self, slot: usize, txid: u32) -> (PrivilegeSet, PrivilegeSet) {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let (visible, _, _, privileges, grant_options) =
            Self::acl_visible(&catalog.objects[slot], txid);
        if visible {
            (privileges, grant_options)
        } else {
            (PrivilegeSet::NONE, PrivilegeSet::NONE)
        }
    }

    pub(crate) fn acl_entry_visible(&self, slot: usize, txid: u32) -> bool {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        Self::acl_visible(&catalog.objects[slot], txid).0
    }

    pub(crate) fn commit_acl(&self, slot: usize, txid: u32) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let Some(pending) = catalog.objects[slot]
            .pending
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        {
            let entry = &mut catalog.objects[slot];
            entry.grantee = pending.grantee;
            entry.grantor = pending.grantor;
            entry.privileges = pending.privileges;
            entry.grant_options = pending.grant_options;
            entry.live = pending.privileges.0 != 0;
            entry.pending = None;
        }
        Self::deduplicate_acl(&mut catalog.objects, slot);
    }

    fn deduplicate_acl(entries: &mut FixedVec<AclEntry>, slot: usize) {
        let object = entries[slot].object;
        let grantee = entries[slot].grantee;
        let grantor = entries[slot].grantor;
        let Some(canonical) = entries.iter().enumerate().find_map(|(candidate, entry)| {
            (candidate != slot
                && entry.object == object
                && entry.grantee == grantee
                && entry.grantor == grantor
                && entry.object.slot != u16::MAX
                && entry.pending.is_none())
            .then_some(candidate)
        }) else {
            return;
        };
        let privileges = entries[slot].privileges;
        let grant_options = entries[slot].grant_options;
        entries[canonical].privileges = entries[canonical].privileges.union(privileges);
        entries[canonical].grant_options = entries[canonical].grant_options.union(grant_options);
        entries[canonical].live = entries[canonical].privileges.0 != 0;
        entries[slot].object.slot = u16::MAX;
        entries[slot].privileges = PrivilegeSet::NONE;
        entries[slot].grant_options = PrivilegeSet::NONE;
        entries[slot].live = false;
    }

    pub(crate) fn restore_acl_pending(&self, slot: usize, prior: Option<PendingAcl>) {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .objects[slot]
            .pending = prior;
    }

    fn parameter_acl_visible(
        entry: &ParameterAclEntry,
        txid: u32,
    ) -> (
        bool,
        u16,
        u16,
        crate::sql::ast::ParameterPrivileges,
        crate::sql::ast::ParameterPrivileges,
    ) {
        match entry.pending {
            Some(pending) if pending.txid == txid => (
                pending.privileges.bits() != 0,
                pending.grantee,
                pending.grantor,
                pending.privileges,
                pending.grant_options,
            ),
            _ => (
                entry.live,
                entry.grantee,
                entry.grantor,
                entry.privileges,
                entry.grant_options,
            ),
        }
    }

    pub(crate) fn change_parameter_acl(
        &self,
        parameter: crate::sql::ast::ParameterName,
        grantee: u16,
        grantor: u16,
        privileges: crate::sql::ast::ParameterPrivileges,
        grant_options: crate::sql::ast::ParameterPrivileges,
        txid: u32,
    ) -> Result<(usize, Option<PendingParameterAcl>), SqlError> {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let slot = catalog
            .parameters
            .iter()
            .position(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) =
                    Self::parameter_acl_visible(entry, txid);
                entry.parameter == parameter
                    && visible_grantee == grantee
                    && visible_grantor == grantor
                    && (entry.live || entry.pending.is_some())
            })
            .or_else(|| {
                catalog.parameters.iter().position(|entry| {
                    entry.parameter.is_empty() && !entry.live && entry.pending.is_none()
                })
            })
            .unwrap_or(catalog.parameters.len());
        if slot == catalog.parameters.len() {
            catalog
                .parameters
                .push(ParameterAclEntry {
                    parameter,
                    grantee,
                    grantor,
                    privileges: crate::sql::ast::ParameterPrivileges::NONE,
                    grant_options: crate::sql::ast::ParameterPrivileges::NONE,
                    live: false,
                    pending: None,
                })
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many parameter privilege entries (limit {})",
                        catalog.parameters.capacity()
                    )
                })?;
        } else if catalog.parameters[slot].parameter.is_empty() {
            catalog.parameters[slot].parameter = parameter;
            catalog.parameters[slot].grantee = grantee;
            catalog.parameters[slot].grantor = grantor;
        }
        let entry = &mut catalog.parameters[slot];
        let prior = entry.pending;
        if txid == 0 {
            entry.grantee = grantee;
            entry.grantor = grantor;
            entry.privileges = privileges;
            entry.grant_options = grant_options;
            entry.live = privileges.bits() != 0;
            entry.pending = None;
        } else {
            entry.pending = Some(PendingParameterAcl {
                txid,
                grantee,
                grantor,
                privileges,
                grant_options,
            });
        }
        Ok((slot, prior))
    }

    pub(crate) fn parameter_acl_from(
        &self,
        parameter: crate::sql::ast::ParameterName,
        grantee: u16,
        grantor: u16,
        txid: u32,
    ) -> (
        crate::sql::ast::ParameterPrivileges,
        crate::sql::ast::ParameterPrivileges,
    ) {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        catalog
            .parameters
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) =
                    Self::parameter_acl_visible(entry, txid);
                entry.parameter == parameter
                    && visible_grantee == grantee
                    && visible_grantor == grantor
            })
            .fold(
                (
                    crate::sql::ast::ParameterPrivileges::NONE,
                    crate::sql::ast::ParameterPrivileges::NONE,
                ),
                |(privileges, grant_options), entry| {
                    let (visible, _, _, entry_privileges, entry_options) =
                        Self::parameter_acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            grant_options.union(entry_options),
                        )
                    } else {
                        (privileges, grant_options)
                    }
                },
            )
    }

    fn parameter_acl_to_entries(
        entries: &[ParameterAclEntry],
        parameter: crate::sql::ast::ParameterName,
        grantee: u16,
        txid: u32,
    ) -> (
        crate::sql::ast::ParameterPrivileges,
        crate::sql::ast::ParameterPrivileges,
    ) {
        entries
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, _, _, _) = Self::parameter_acl_visible(entry, txid);
                entry.parameter == parameter && visible_grantee == grantee
            })
            .fold(
                (
                    crate::sql::ast::ParameterPrivileges::NONE,
                    crate::sql::ast::ParameterPrivileges::NONE,
                ),
                |(privileges, grant_options), entry| {
                    let (visible, _, _, entry_privileges, entry_options) =
                        Self::parameter_acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            grant_options.union(entry_options),
                        )
                    } else {
                        (privileges, grant_options)
                    }
                },
            )
    }

    pub(crate) fn has_parameter_privilege(
        &self,
        parameter: crate::sql::ast::ParameterName,
        role: usize,
        required: crate::sql::ast::ParameterPrivileges,
        txid: u32,
    ) -> bool {
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, false, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut effective =
            Self::parameter_acl_to_entries(&catalog.parameters, parameter, PUBLIC_ROLE, txid).0;
        for (candidate, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective.union(
                    Self::parameter_acl_to_entries(
                        &catalog.parameters,
                        parameter,
                        candidate as u16,
                        txid,
                    )
                    .0,
                );
            }
        }
        effective.contains(required)
    }

    pub(crate) fn has_parameter_grant_option(
        &self,
        parameter: crate::sql::ast::ParameterName,
        role: usize,
        required: crate::sql::ast::ParameterPrivileges,
        txid: u32,
    ) -> bool {
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, false, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut effective =
            Self::parameter_acl_to_entries(&catalog.parameters, parameter, PUBLIC_ROLE, txid).1;
        for (candidate, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective.union(
                    Self::parameter_acl_to_entries(
                        &catalog.parameters,
                        parameter,
                        candidate as u16,
                        txid,
                    )
                    .1,
                );
            }
        }
        effective.contains(required)
    }

    pub(crate) fn dependent_parameter_acl_slots(
        &self,
        parameter: crate::sql::ast::ParameterName,
        grantor: u16,
        privileges: crate::sql::ast::ParameterPrivileges,
        txid: u32,
        output: &mut [usize],
    ) -> usize {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut count = 0usize;
        for (slot, entry) in catalog.parameters.iter().enumerate() {
            let (visible, _, entry_grantor, entry_privileges, _) =
                Self::parameter_acl_visible(entry, txid);
            if visible
                && entry.parameter == parameter
                && entry_grantor == grantor
                && entry_privileges.bits() & privileges.bits() != 0
            {
                output[count] = slot;
                count += 1;
            }
        }
        count
    }

    pub(crate) fn parameter_acl_entry(&self, slot: usize) -> ParameterAclEntry {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .parameters[slot]
    }

    pub(crate) fn parameter_acl_identity(&self, slot: usize, txid: u32) -> (u16, u16) {
        let (_, grantee, grantor, _, _) =
            Self::parameter_acl_visible(&self.parameter_acl_entry(slot), txid);
        (grantee, grantor)
    }

    pub(crate) fn parameter_acl_state(
        &self,
        slot: usize,
        txid: u32,
    ) -> (
        crate::sql::ast::ParameterPrivileges,
        crate::sql::ast::ParameterPrivileges,
    ) {
        let (_, _, _, privileges, grant_options) =
            Self::parameter_acl_visible(&self.parameter_acl_entry(slot), txid);
        (privileges, grant_options)
    }

    pub(crate) fn parameter_acl_entries_visible(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ParameterAclEntry)> + '_ {
        ParameterAclIter {
            catalog: &self.acl_catalog,
            next_slot: 0,
            mode: ParameterAclIterMode::Visible(txid),
        }
    }

    pub(crate) fn parameter_acl_entry_count(&self) -> usize {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .parameters
            .len()
    }

    pub(crate) fn checkpoint_parameter_acls(
        &self,
    ) -> impl Iterator<Item = (usize, ParameterAclEntry)> + '_ {
        ParameterAclIter {
            catalog: &self.acl_catalog,
            next_slot: 0,
            mode: ParameterAclIterMode::Checkpoint,
        }
    }

    pub(crate) fn commit_parameter_acl(&self, slot: usize, txid: u32) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let Some(pending) = catalog.parameters[slot].pending else {
            return;
        };
        if pending.txid != txid {
            return;
        }
        let entry = &mut catalog.parameters[slot];
        entry.grantee = pending.grantee;
        entry.grantor = pending.grantor;
        entry.privileges = pending.privileges;
        entry.grant_options = pending.grant_options;
        entry.live = pending.privileges.bits() != 0;
        entry.pending = None;
        if !entry.live {
            entry.parameter = crate::sql::ast::ParameterName::EMPTY;
            entry.privileges = crate::sql::ast::ParameterPrivileges::NONE;
            entry.grant_options = crate::sql::ast::ParameterPrivileges::NONE;
        }
    }

    pub(crate) fn restore_parameter_acl_pending(
        &self,
        slot: usize,
        prior: Option<PendingParameterAcl>,
    ) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        catalog.parameters[slot].pending = prior;
        if !catalog.parameters[slot].live && prior.is_none() {
            catalog.parameters[slot].parameter = crate::sql::ast::ParameterName::EMPTY;
        }
    }

    pub(crate) fn acl_identity(&self, slot: usize, txid: u32) -> (u16, u16) {
        let entry = self.acl_entry(slot);
        let (_, grantee, grantor, _, _) = Self::acl_visible(&entry, txid);
        (grantee, grantor)
    }

    pub(crate) fn change_acl_identity(
        &self,
        slot: usize,
        grantee: u16,
        grantor: u16,
        txid: u32,
    ) -> Option<PendingAcl> {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let entry = &mut catalog.objects[slot];
        let prior = entry.pending;
        let (_, _, _, privileges, grant_options) = Self::acl_visible(entry, txid);
        if txid == 0 {
            entry.grantee = grantee;
            entry.grantor = grantor;
            entry.pending = None;
        } else {
            entry.pending = Some(PendingAcl {
                txid,
                grantee,
                grantor,
                privileges,
                grant_options,
            });
        }
        if txid == 0 {
            Self::deduplicate_acl(&mut catalog.objects, slot);
        }
        prior
    }

    fn default_acl_visible(
        entry: &DefaultAclEntry,
        txid: u32,
    ) -> (bool, PrivilegeSet, PrivilegeSet) {
        match entry.pending {
            Some(pending) if pending.txid == txid => {
                (pending.defined, pending.privileges, pending.grant_options)
            }
            _ => (entry.defined, entry.privileges, entry.grant_options),
        }
    }

    pub(crate) const fn default_acl_baseline(
        owner: u16,
        schema: u16,
        class: DefaultPrivilegeClass,
        grantee: u16,
    ) -> (PrivilegeSet, PrivilegeSet) {
        if schema != DEFAULT_ACL_ALL_SCHEMAS {
            return (PrivilegeSet::NONE, PrivilegeSet::NONE);
        }
        if grantee == owner {
            let all = class.all_privileges();
            return (all, PrivilegeSet::NONE);
        }
        if grantee == PUBLIC_ROLE {
            return (class.default_public_privileges(), PrivilegeSet::NONE);
        }
        (PrivilegeSet::NONE, PrivilegeSet::NONE)
    }

    pub(crate) fn default_acl_state(
        &self,
        owner: u16,
        schema: u16,
        class: DefaultPrivilegeClass,
        grantee: u16,
        txid: u32,
    ) -> (bool, PrivilegeSet, PrivilegeSet) {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .defaults
            .iter()
            .find(|entry| {
                entry.database == current_database()
                    && entry.owner == owner
                    && entry.schema == schema
                    && entry.class == class
                    && entry.grantee == grantee
            })
            .map(|entry| Self::default_acl_visible(entry, txid))
            .unwrap_or((false, PrivilegeSet::NONE, PrivilegeSet::NONE))
    }

    pub(crate) fn default_acl_effective(
        &self,
        owner: u16,
        schema: u16,
        class: DefaultPrivilegeClass,
        grantee: u16,
        txid: u32,
    ) -> (PrivilegeSet, PrivilegeSet) {
        let (defined, privileges, grant_options) =
            self.default_acl_state(owner, schema, class, grantee, txid);
        if defined {
            (privileges, grant_options)
        } else {
            Self::default_acl_baseline(owner, schema, class, grantee)
        }
    }

    pub(crate) fn change_default_acl(
        &self,
        key: DefaultAclKey,
        defined: bool,
        privileges: PrivilegeSet,
        grant_options: PrivilegeSet,
        txid: u32,
    ) -> Result<(usize, Option<PendingDefaultAcl>), SqlError> {
        let DefaultAclKey {
            owner,
            schema,
            class,
            grantee,
        } = key;
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let slot = catalog
            .defaults
            .iter()
            .position(|entry| {
                entry.database == current_database()
                    && entry.owner == owner
                    && entry.schema == schema
                    && entry.class == class
                    && entry.grantee == grantee
            })
            .or_else(|| {
                catalog
                    .defaults
                    .iter()
                    .position(|entry| entry.owner == PUBLIC_ROLE && entry.pending.is_none())
            })
            .unwrap_or(catalog.defaults.len());
        if slot == catalog.defaults.len() {
            catalog
                .defaults
                .push(DefaultAclEntry {
                    database: current_database(),
                    owner,
                    schema,
                    class,
                    grantee,
                    defined: false,
                    privileges: PrivilegeSet::NONE,
                    grant_options: PrivilegeSet::NONE,
                    pending: None,
                })
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many default privilege entries (limit {})",
                        catalog.defaults.capacity()
                    )
                })?;
        } else if catalog.defaults[slot].owner == PUBLIC_ROLE {
            let entry = &mut catalog.defaults[slot];
            entry.database = current_database();
            entry.owner = owner;
            entry.schema = schema;
            entry.class = class;
            entry.grantee = grantee;
            entry.defined = false;
            entry.privileges = PrivilegeSet::NONE;
            entry.grant_options = PrivilegeSet::NONE;
        }
        let entry = &mut catalog.defaults[slot];
        let prior = entry.pending;
        if txid == 0 {
            entry.defined = defined;
            entry.privileges = privileges;
            entry.grant_options = grant_options;
            entry.pending = None;
            if !defined {
                entry.owner = PUBLIC_ROLE;
            }
        } else {
            entry.pending = Some(PendingDefaultAcl {
                txid,
                defined,
                privileges,
                grant_options,
            });
        }
        Ok((slot, prior))
    }

    pub(crate) fn default_acl_entry(&self, slot: usize) -> DefaultAclEntry {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .defaults[slot]
    }

    pub(crate) fn default_acl_entry_count(&self) -> usize {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .defaults
            .len()
    }

    pub(crate) fn default_acl_entries(
        &self,
    ) -> impl Iterator<Item = (usize, DefaultAclEntry)> + '_ {
        DefaultAclIter {
            catalog: &self.acl_catalog,
            database: Some(current_database()),
            next_slot: 0,
        }
    }

    pub(crate) fn commit_default_acl(&self, slot: usize, txid: u32) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let entry = &mut catalog.defaults[slot];
        if let Some(pending) = entry.pending
            && pending.txid == txid
        {
            entry.defined = pending.defined;
            entry.privileges = pending.privileges;
            entry.grant_options = pending.grant_options;
            entry.pending = None;
            if !entry.defined {
                entry.owner = PUBLIC_ROLE;
            }
        }
    }

    pub(crate) fn restore_default_acl_pending(
        &self,
        slot: usize,
        prior: Option<PendingDefaultAcl>,
    ) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let entry = &mut catalog.defaults[slot];
        entry.pending = prior;
        if prior.is_none() && !entry.defined {
            entry.owner = PUBLIC_ROLE;
        }
    }

    pub(crate) fn acl_entry(&self, slot: usize) -> AclEntry {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .objects[slot]
    }

    pub(crate) fn acl_entry_count(&self) -> usize {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .objects
            .len()
    }

    pub(crate) fn acl_entries(&self) -> impl Iterator<Item = (usize, AclEntry)> + '_ {
        ObjectAclIter {
            storage: self,
            next_slot: 0,
            checkpoint: false,
        }
    }

    pub(crate) fn dependent_acl_slots(
        &self,
        object: AccessObject,
        grantor: u16,
        privileges: PrivilegeSet,
        txid: u32,
        output: &mut [usize],
    ) -> usize {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut count = 0usize;
        for (slot, entry) in catalog.objects.iter().enumerate() {
            let (visible, _, entry_grantor, entry_privileges, _) = Self::acl_visible(entry, txid);
            if visible
                && entry.object == object
                && entry_grantor == grantor
                && entry_privileges.0 & privileges.0 != 0
            {
                output[count] = slot;
                count += 1;
            }
        }
        count
    }

    fn column_acl_visible(
        entry: &ColumnAclEntry,
        txid: u32,
    ) -> (bool, u16, u16, PrivilegeSet, PrivilegeSet) {
        match entry.pending {
            Some(pending) if pending.txid == txid => (
                pending.privileges.0 != 0,
                pending.grantee,
                pending.grantor,
                pending.privileges,
                pending.grant_options,
            ),
            _ => (
                entry.live,
                entry.grantee,
                entry.grantor,
                entry.privileges,
                entry.grant_options,
            ),
        }
    }

    pub(crate) fn change_column_acl(
        &self,
        target: ColumnPrivilegeTarget,
        grantee: u16,
        grantor: u16,
        privileges: PrivilegeSet,
        grant_options: PrivilegeSet,
        txid: u32,
    ) -> Result<(usize, Option<PendingAcl>), SqlError> {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let slot = catalog
            .columns
            .iter()
            .position(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) =
                    Self::column_acl_visible(entry, txid);
                entry.target == target
                    && visible_grantee == grantee
                    && visible_grantor == grantor
                    && (entry.live || entry.pending.is_some())
            })
            .or_else(|| {
                catalog.columns.iter().position(|entry| {
                    entry.target.relation.slot == u16::MAX && !entry.live && entry.pending.is_none()
                })
            })
            .unwrap_or(catalog.columns.len());
        if slot == catalog.columns.len() {
            catalog
                .columns
                .push(ColumnAclEntry {
                    target,
                    grantee,
                    grantor,
                    privileges: PrivilegeSet::NONE,
                    grant_options: PrivilegeSet::NONE,
                    live: false,
                    pending: None,
                })
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many column privilege entries (limit {})",
                        catalog.columns.capacity()
                    )
                })?;
        } else if catalog.columns[slot].target.relation.slot == u16::MAX {
            let entry = &mut catalog.columns[slot];
            entry.target = target;
            entry.grantee = grantee;
            entry.grantor = grantor;
        }
        let entry = &mut catalog.columns[slot];
        let prior = entry.pending;
        if txid == 0 {
            entry.grantee = grantee;
            entry.grantor = grantor;
            entry.privileges = privileges;
            entry.grant_options = grant_options;
            entry.live = privileges.0 != 0;
            entry.pending = None;
        } else {
            entry.pending = Some(PendingAcl {
                txid,
                grantee,
                grantor,
                privileges,
                grant_options,
            });
        }
        Ok((slot, prior))
    }

    pub(crate) fn column_acl_from(
        &self,
        target: ColumnPrivilegeTarget,
        grantee: u16,
        grantor: u16,
        txid: u32,
    ) -> (PrivilegeSet, PrivilegeSet) {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        catalog
            .columns
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, visible_grantor, _, _) =
                    Self::column_acl_visible(entry, txid);
                entry.target == target && visible_grantee == grantee && visible_grantor == grantor
            })
            .fold(
                (PrivilegeSet::NONE, PrivilegeSet::NONE),
                |(privileges, options), entry| {
                    let (visible, _, _, entry_privileges, entry_options) =
                        Self::column_acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            options.union(entry_options),
                        )
                    } else {
                        (privileges, options)
                    }
                },
            )
    }

    fn column_acl_to_entries(
        entries: &[ColumnAclEntry],
        target: ColumnPrivilegeTarget,
        grantee: u16,
        txid: u32,
    ) -> (PrivilegeSet, PrivilegeSet) {
        entries
            .iter()
            .filter(|entry| {
                let (_, visible_grantee, _, _, _) = Self::column_acl_visible(entry, txid);
                entry.target == target && visible_grantee == grantee
            })
            .fold(
                (PrivilegeSet::NONE, PrivilegeSet::NONE),
                |(privileges, options), entry| {
                    let (visible, _, _, entry_privileges, entry_options) =
                        Self::column_acl_visible(entry, txid);
                    if visible {
                        (
                            privileges.union(entry_privileges),
                            options.union(entry_options),
                        )
                    } else {
                        (privileges, options)
                    }
                },
            )
    }

    pub(crate) fn column_acl_entries(&self) -> impl Iterator<Item = (usize, ColumnAclEntry)> + '_ {
        ColumnAclIter {
            storage: self,
            next_slot: 0,
            checkpoint: false,
        }
    }

    pub(crate) fn column_acl_entry_count(&self) -> usize {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .columns
            .len()
    }

    /// Enumerate the durable column-ACL targets attached to one relation.
    /// Object-level grant-option revocation must visit only targets that can
    /// actually have downstream grants; a view has no backing `TableDef` to
    /// use as a surrogate column list.
    pub(crate) fn column_acl_targets(
        &self,
        relation: AccessObject,
        txid: u32,
        output: &mut [ColumnPrivilegeTarget],
    ) -> usize {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut count = 0usize;
        for entry in catalog.columns.iter() {
            let (visible, _, _, _, _) = Self::column_acl_visible(entry, txid);
            if !visible
                || entry.target.relation != relation
                || output[..count].contains(&entry.target)
            {
                continue;
            }
            output[count] = entry.target;
            count += 1;
        }
        count
    }

    /// Whether a role has a privilege on at least one explicitly-granted
    /// column. This is the only legal relation-level admission for a view
    /// without an object-level grant; exact projected-column checks still run
    /// at the query-scope boundary.
    pub(crate) fn has_any_column_privilege(
        &self,
        relation: AccessObject,
        role: usize,
        privilege: PrivilegeSet,
        txid: u32,
    ) -> bool {
        for slot in 0..self.column_acl_entry_count() {
            let entry = self.column_acl_entry(slot);
            let (visible, _, _, _, _) = Self::column_acl_visible(&entry, txid);
            if visible
                && entry.target.relation == relation
                && self.has_column_privilege(entry.target, role, privilege, txid)
            {
                return true;
            }
        }
        false
    }

    pub(crate) fn dependent_column_acl_slots(
        &self,
        target: ColumnPrivilegeTarget,
        grantor: u16,
        privileges: PrivilegeSet,
        txid: u32,
        output: &mut [usize],
    ) -> usize {
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut count = 0usize;
        for (slot, entry) in catalog.columns.iter().enumerate() {
            let (visible, _, entry_grantor, entry_privileges, _) =
                Self::column_acl_visible(entry, txid);
            if visible
                && entry.target == target
                && entry_grantor == grantor
                && entry_privileges.0 & privileges.0 != 0
            {
                output[count] = slot;
                count += 1;
            }
        }
        count
    }

    pub(crate) fn column_acl_entry(&self, slot: usize) -> ColumnAclEntry {
        self.acl_catalog
            .lock()
            .expect("ACL catalog lock poisoned")
            .columns[slot]
    }

    pub(crate) fn column_acl_identity(&self, slot: usize, txid: u32) -> (u16, u16) {
        let entry = self.column_acl_entry(slot);
        let (_, grantee, grantor, _, _) = Self::column_acl_visible(&entry, txid);
        (grantee, grantor)
    }

    pub(crate) fn column_acl_state(&self, slot: usize, txid: u32) -> (PrivilegeSet, PrivilegeSet) {
        let entry = self.column_acl_entry(slot);
        let (visible, _, _, privileges, options) = Self::column_acl_visible(&entry, txid);
        if visible {
            (privileges, options)
        } else {
            (PrivilegeSet::NONE, PrivilegeSet::NONE)
        }
    }

    pub(crate) fn change_column_acl_identity(
        &self,
        slot: usize,
        grantee: u16,
        grantor: u16,
        txid: u32,
    ) -> Option<PendingAcl> {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let entry = &mut catalog.columns[slot];
        let prior = entry.pending;
        let (_, _, _, privileges, grant_options) = Self::column_acl_visible(entry, txid);
        if txid == 0 {
            entry.grantee = grantee;
            entry.grantor = grantor;
            entry.pending = None;
        } else {
            entry.pending = Some(PendingAcl {
                txid,
                grantee,
                grantor,
                privileges,
                grant_options,
            });
        }
        prior
    }

    pub(crate) fn commit_column_acl(&self, slot: usize, txid: u32) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let Some(pending) = catalog.columns[slot]
            .pending
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        let entry = &mut catalog.columns[slot];
        entry.grantee = pending.grantee;
        entry.grantor = pending.grantor;
        entry.privileges = pending.privileges;
        entry.grant_options = pending.grant_options;
        entry.live = pending.privileges.0 != 0;
        entry.pending = None;
        if !entry.live {
            entry.target.relation.slot = u16::MAX;
        }
    }

    pub(crate) fn restore_column_acl_pending(&self, slot: usize, prior: Option<PendingAcl>) {
        let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        catalog.columns[slot].pending = prior;
        if prior.is_none() && !catalog.columns[slot].live {
            catalog.columns[slot].target.relation.slot = u16::MAX;
        }
    }

    fn role_graph_scratch(&self) -> std::sync::MutexGuard<'_, FixedVec<bool>> {
        let workspace = crate::sql::execution_query_workspace().index();
        self.role_graph_scratch[workspace]
            .lock()
            .expect("role graph scratch lock poisoned")
    }

    pub(crate) fn has_column_privilege(
        &self,
        target: ColumnPrivilegeTarget,
        role: usize,
        privilege: PrivilegeSet,
        txid: u32,
    ) -> bool {
        if self.has_object_privilege(target.relation, role, privilege, txid) {
            return true;
        }
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, true, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut effective =
            Self::column_acl_to_entries(&catalog.columns, target, PUBLIC_ROLE, txid).0;
        for (slot, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective.union(
                    Self::column_acl_to_entries(&catalog.columns, target, slot as u16, txid).0,
                );
            }
        }
        effective.contains(privilege)
    }

    pub(crate) fn has_column_grant_option(
        &self,
        target: ColumnPrivilegeTarget,
        role: usize,
        privilege: PrivilegeSet,
        txid: u32,
    ) -> bool {
        if self.has_object_grant_option(target.relation, role, privilege, txid) {
            return true;
        }
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, true, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut effective =
            Self::column_acl_to_entries(&catalog.columns, target, PUBLIC_ROLE, txid).1;
        for (slot, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective.union(
                    Self::column_acl_to_entries(&catalog.columns, target, slot as u16, txid).1,
                );
            }
        }
        effective.contains(privilege)
    }

    fn reachable_roles(
        &self,
        member: usize,
        txid: u32,
        require_inherit: bool,
        require_set: bool,
        out: &mut [bool],
    ) {
        out.fill(false);
        if member >= out.len() {
            return;
        }
        out[member] = true;
        let catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        loop {
            let mut changed = false;
            for membership in catalog.memberships.iter() {
                if !membership.visible_to(txid)
                    || !out[membership.member as usize]
                    || (require_inherit && !membership.options_to(txid).inherit)
                    || (require_set && !membership.options_to(txid).set)
                {
                    continue;
                }
                let role = membership.role as usize;
                if !out[role] {
                    out[role] = true;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
    }

    /// Whether a role's grants are visible through the current effective role.
    /// PostgreSQL information-schema privilege views expose grants held or
    /// issued by enabled roles, not every catalog ACL entry.
    pub(crate) fn role_is_enabled(&self, role: u16, txid: u32) -> bool {
        if role == PUBLIC_ROLE {
            return true;
        }
        let Some(current) = self.current_role_slot(txid) else {
            return false;
        };
        if self.role(current).attributes_to(txid).superuser {
            return true;
        }
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(current, txid, true, false, &mut roles);
        roles.get(role as usize).copied().unwrap_or(false)
    }

    pub(crate) fn has_object_privilege(
        &self,
        object: AccessObject,
        role: usize,
        privilege: PrivilegeSet,
        txid: u32,
    ) -> bool {
        if self.role(role).attributes_to(txid).superuser || self.object_owner(object, txid) == role
        {
            return true;
        }
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, true, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let acl_defined = catalog.objects.iter().any(|entry| {
            entry.object == object
                && entry.object.slot != u16::MAX
                && (entry.live || entry.pending.is_some())
        });
        let mut effective = if !acl_defined {
            default_public_object_privileges(object.class)
        } else {
            Self::acl_to_entries(&catalog.objects, object, PUBLIC_ROLE, txid).0
        };
        for (slot, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective
                    .union(Self::acl_to_entries(&catalog.objects, object, slot as u16, txid).0);
            }
        }
        effective.contains(privilege)
    }

    pub(crate) fn require_schema_create(&self, schema: &str, txid: u32) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        if self.is_current_temporary_schema(schema) {
            return self.require_temporary_privilege(txid);
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        self.require_schema_create_as(schema, role, txid)
    }

    pub(crate) fn require_schema_create_as(
        &self,
        schema: &str,
        role: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let schema_slot = self.find_schema_visible(schema, txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema \"{}\" does not exist",
                schema
            )
        })?;
        let object = AccessObject {
            class: AccessClass::Schema,
            slot: schema_slot as u16,
        };
        if self.has_object_privilege(object, role, PrivilegeSet::CREATE, txid) {
            Ok(())
        } else {
            Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for schema {}",
                schema
            ))
        }
    }

    pub(crate) fn require_schema_usage(&self, schema: &str, txid: u32) -> Result<(), SqlError> {
        if txid == 0 || schema == "pg_catalog" {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        self.require_schema_usage_as(schema, role, txid)
    }

    pub(crate) fn require_schema_usage_as(
        &self,
        schema: &str,
        role: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        if txid == 0 || schema == "pg_catalog" {
            return Ok(());
        }
        if self.is_current_temporary_schema(schema) {
            return Ok(());
        }
        let schema_slot = self.find_schema_visible(schema, txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema \"{}\" does not exist",
                schema
            )
        })?;
        let object = AccessObject {
            class: AccessClass::Schema,
            slot: schema_slot as u16,
        };
        if self.has_object_privilege(object, role, PrivilegeSet::USAGE, txid) {
            Ok(())
        } else {
            Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for schema {}",
                schema
            ))
        }
    }

    pub(crate) fn require_type_usage(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<(), SqlError> {
        self.require_schema_usage(schema, txid)?;
        let object = self
            .domain_slot(schema, name, txid)
            .map(|slot| AccessObject {
                class: AccessClass::Domain,
                slot: slot as u16,
            })
            .or_else(|| {
                self.enum_slot(schema, name, txid).map(|slot| AccessObject {
                    class: AccessClass::Enum,
                    slot: slot as u16,
                })
            })
            .or_else(|| {
                self.composite_slot(schema, name, txid)
                    .map(|slot| AccessObject {
                        class: AccessClass::Composite,
                        slot: slot as u16,
                    })
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "type \"{}.{}\" does not exist",
                    schema,
                    name
                )
            })?;
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        if self.has_object_privilege(object, role, PrivilegeSet::USAGE, txid) {
            Ok(())
        } else {
            Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for type {}",
                name
            ))
        }
    }

    pub(crate) fn require_owner(
        &self,
        object: AccessObject,
        txid: u32,
        object_type: &str,
    ) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let owner = self.object_owner(object, txid);
        if self.role(role).attributes_to(txid).superuser
            || owner == role
            || self.role_can_set(role, owner, txid)
        {
            return Ok(());
        }
        let (_, name) = self.access_object_name(object);
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of {} {}",
            object_type,
            name.as_str()
        ))
    }

    pub(crate) fn require_language_usage(&self, name: &str, txid: u32) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let oid = crate::sql::catalog::procedural_language_oid(name).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "language \"{}\" does not exist",
                name
            )
        })?;
        let slot = u16::try_from(oid).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "language OID {} cannot be represented by the fixed ACL identity",
                oid
            )
        })?;
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let object = AccessObject {
            class: AccessClass::Language,
            slot,
        };
        if self.has_object_privilege(object, role, PrivilegeSet::USAGE, txid) {
            return Ok(());
        }
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for language {}",
            name
        ))
    }

    pub(crate) fn require_routine_owner(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let routine = self.routine(slot);
        let owner = routine.ownership.owner_to(txid) as usize;
        if self.role(role).attributes_to(txid).superuser
            || owner == role
            || self.role_can_set(role, owner, txid)
        {
            return Ok(());
        }
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of function {}",
            routine.name_for(txid).as_str()
        ))
    }

    pub(crate) fn require_catalog_owner(
        &self,
        owner: i32,
        txid: u32,
        object_type: &str,
        name: &str,
    ) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let owner = self.role_slot_by_oid(owner, txid).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "catalog owner role does not exist"
            )
        })?;
        if self.role(role).attributes_to(txid).superuser
            || owner == role
            || self.role_can_set(role, owner, txid)
        {
            Ok(())
        } else {
            Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "must be owner of {} {}",
                object_type,
                name
            ))
        }
    }

    pub(crate) fn initial_catalog_owner(&self, txid: u32) -> i32 {
        Self::role_oid(usize::from(self.initial_ownership(txid).owner_to(txid)))
    }

    pub(crate) fn require_routine_execute(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let object = Self::routine_access_object(slot);
        if self.has_object_privilege(object, role, PrivilegeSet::EXECUTE, txid) {
            return Ok(());
        }
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "permission denied for function {}",
            self.routine(slot).name.as_str()
        ))
    }

    pub(crate) fn has_object_grant_option(
        &self,
        object: AccessObject,
        role: usize,
        privilege: PrivilegeSet,
        txid: u32,
    ) -> bool {
        if self.role(role).attributes_to(txid).superuser || self.object_owner(object, txid) == role
        {
            return true;
        }
        let mut roles = self.role_graph_scratch();
        self.reachable_roles(role, txid, true, false, &mut roles);
        let catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
        let mut effective = Self::acl_to_entries(&catalog.objects, object, PUBLIC_ROLE, txid).1;
        for (slot, inherited) in roles.iter().copied().enumerate() {
            if inherited {
                effective = effective
                    .union(Self::acl_to_entries(&catalog.objects, object, slot as u16, txid).1);
            }
        }
        effective.contains(privilege)
    }

    pub fn create_role(
        &self,
        name: SqlName,
        attributes: RoleAttributes,
        txid: u32,
    ) -> Result<(usize, Option<PendingRole>), SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if catalog
            .roles
            .iter()
            .any(|role| role.visible_to(txid) && role.name_to(txid) == name)
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "role \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(owner) = catalog.roles.iter().find_map(|role| {
            (role.name == name)
                .then_some(role.pending)
                .flatten()
                .filter(|pending| pending.txid != txid)
                .map(|pending| pending.txid)
        }) {
            drop(catalog);
            self.wait_for_transaction(txid, owner)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on role \"{}\"",
                name.as_str()
            ));
        }
        let Some(slot) = catalog
            .roles
            .iter()
            .position(|role| !role.live && role.pending.is_none())
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many roles (limit {})",
                catalog.roles.len()
            ));
        };
        let prior = catalog.roles[slot].pending;
        catalog.roles[slot] = RoleDef {
            name,
            attributes: RoleAttributes::ORDINARY,
            live: false,
            pending: Some(PendingRole {
                txid,
                exists: true,
                name,
                attributes,
            }),
        };
        Ok((slot, prior))
    }

    pub fn alter_role(
        &self,
        slot: usize,
        attributes: RoleAttributes,
        txid: u32,
    ) -> Result<Option<PendingRole>, SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if let Some(pending) = catalog.roles[slot].pending
            && pending.txid != txid
        {
            let role_name = catalog.roles[slot].name;
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on role \"{}\"",
                role_name.as_str()
            ));
        }
        let prior = catalog.roles[slot].pending;
        let name = catalog.roles[slot].name_to(txid);
        catalog.roles[slot].pending = Some(PendingRole {
            txid,
            exists: true,
            name,
            attributes,
        });
        Ok(prior)
    }

    pub fn rename_role(
        &self,
        slot: usize,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingRole>, SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if catalog
            .roles
            .iter()
            .position(|role| role.visible_to(txid) && role.name_to(txid) == name)
            .is_some_and(|existing| existing != slot)
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "role \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(pending) = catalog.roles[slot].pending
            && pending.txid != txid
        {
            let role_name = catalog.roles[slot].name;
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on role \"{}\"",
                role_name.as_str()
            ));
        }
        let prior = catalog.roles[slot].pending;
        let mut attributes = catalog.roles[slot].attributes_to(txid);
        if matches!(attributes.password, Some(RoleCredential::Md5(_))) {
            attributes.password = None;
        }
        catalog.roles[slot].pending = Some(PendingRole {
            txid,
            exists: true,
            name,
            attributes,
        });
        Ok(prior)
    }

    pub fn drop_role_in(&self, slot: usize, txid: u32) -> Result<Option<PendingRole>, SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if let Some(pending) = catalog.roles[slot].pending
            && pending.txid != txid
        {
            let role_name = catalog.roles[slot].name;
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on role \"{}\"",
                role_name.as_str()
            ));
        }
        let prior = catalog.roles[slot].pending;
        let name = catalog.roles[slot].name_to(txid);
        let attributes = catalog.roles[slot].attributes_to(txid);
        catalog.roles[slot].pending = Some(PendingRole {
            txid,
            exists: false,
            name,
            attributes,
        });
        Ok(prior)
    }

    pub fn commit_role_change(&self, slot: usize) {
        let dropped = {
            let mut catalog = self
                .role_catalog
                .lock()
                .expect("role catalog lock poisoned");
            let Some(pending) = catalog.roles[slot].pending.take() else {
                return;
            };
            catalog.roles[slot].live = pending.exists;
            catalog.roles[slot].name = pending.name;
            catalog.roles[slot].attributes = pending.attributes;
            if !pending.exists {
                catalog.roles[slot].name = SqlName::EMPTY;
            }
            !pending.exists
        };
        if dropped {
            self.drop_comments_by_subid(CommentClass::Role, Self::role_oid(slot) as u32);
        }
    }

    pub fn rollback_role_change(&self, slot: usize, prior: Option<PendingRole>) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        catalog.roles[slot].pending = prior;
        if !catalog.roles[slot].live && prior.is_none() {
            catalog.roles[slot].name = SqlName::EMPTY;
            catalog.roles[slot].attributes = RoleAttributes::ORDINARY;
        }
    }

    /// Committed role install used by WAL and manifest recovery.
    pub fn install_role(
        &self,
        name: SqlName,
        attributes: RoleAttributes,
    ) -> Result<usize, SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if let Some(slot) = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name == name)
        {
            catalog.roles[slot].attributes = attributes;
            return Ok(slot);
        }
        let Some(slot) = catalog
            .roles
            .iter()
            .position(|role| !role.live && role.pending.is_none())
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many roles (limit {})",
                catalog.roles.len()
            ));
        };
        catalog.roles[slot] = RoleDef {
            name,
            attributes,
            live: true,
            pending: None,
        };
        Ok(slot)
    }

    pub fn remove_role(&self, name: &str) {
        let mut roles = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if let Some(slot) = roles
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == name)
        {
            self.drop_comments_by_subid(CommentClass::Role, Self::role_oid(slot) as u32);
            let mut catalog = self.acl_catalog.lock().expect("ACL catalog lock poisoned");
            for entry in catalog.objects.iter_mut() {
                if entry.grantee == slot as u16 || entry.grantor == slot as u16 {
                    entry.object.slot = u16::MAX;
                    entry.live = false;
                    entry.privileges = PrivilegeSet::NONE;
                    entry.grant_options = PrivilegeSet::NONE;
                    entry.pending = None;
                }
            }
            for entry in catalog.columns.iter_mut() {
                if entry.grantee == slot as u16 || entry.grantor == slot as u16 {
                    entry.target.relation.slot = u16::MAX;
                    entry.live = false;
                    entry.privileges = PrivilegeSet::NONE;
                    entry.grant_options = PrivilegeSet::NONE;
                    entry.pending = None;
                }
            }
            for entry in catalog.parameters.iter_mut() {
                if entry.grantee == slot as u16 || entry.grantor == slot as u16 {
                    entry.parameter = crate::sql::ast::ParameterName::EMPTY;
                    entry.live = false;
                    entry.privileges = crate::sql::ast::ParameterPrivileges::NONE;
                    entry.grant_options = crate::sql::ast::ParameterPrivileges::NONE;
                    entry.pending = None;
                }
            }
            for entry in catalog.defaults.iter_mut() {
                if entry.owner == slot as u16 || entry.grantee == slot as u16 {
                    entry.owner = PUBLIC_ROLE;
                    entry.defined = false;
                    entry.privileges = PrivilegeSet::NONE;
                    entry.grant_options = PrivilegeSet::NONE;
                    entry.pending = None;
                }
            }
            drop(catalog);
            roles.roles[slot] = RoleDef {
                name: SqlName::EMPTY,
                attributes: RoleAttributes::ORDINARY,
                live: false,
                pending: None,
            };
            for membership in roles.memberships.iter_mut() {
                if membership.role as usize == slot
                    || membership.member as usize == slot
                    || membership.grantor as usize == slot
                {
                    *membership = RoleMembership {
                        role: 0,
                        member: 0,
                        grantor: 0,
                        options: RoleMembershipOptions::DEFAULT,
                        live: false,
                        pending: None,
                    };
                }
            }
            for setting in roles.settings.iter_mut() {
                if setting.scope.role() == Some(slot as u16) {
                    *setting = RoleSetting::EMPTY;
                }
            }
        }
    }

    /// WAL replay keeps the catalog slot, and therefore its shared-object
    /// comment identity, when a role is renamed.
    pub fn replay_rename_role(&self, name: &str, new_name: &str) -> Result<(), SqlError> {
        let new_name = SqlName::parse(new_name)?;
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let Some(slot) = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == name)
        else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "journal renames unknown role \"{}\"",
                name
            ));
        };
        if catalog
            .roles
            .iter()
            .position(|role| role.live && role.name == new_name)
            .is_some_and(|existing| existing != slot)
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "journal renames role to existing role \"{}\"",
                new_name.as_str()
            ));
        }
        catalog.roles[slot].name = new_name;
        if matches!(
            catalog.roles[slot].attributes.password,
            Some(RoleCredential::Md5(_))
        ) {
            catalog.roles[slot].attributes.password = None;
        }
        Ok(())
    }

    pub fn role_membership_count(&self) -> usize {
        self.role_catalog
            .lock()
            .expect("role catalog lock poisoned")
            .memberships
            .len()
    }

    pub fn role_membership(&self, slot: usize) -> RoleMembership {
        self.role_catalog
            .lock()
            .expect("role catalog lock poisoned")
            .memberships[slot]
    }

    pub fn live_role_memberships(&self) -> impl Iterator<Item = (usize, RoleMembership)> + '_ {
        RoleMembershipIter {
            catalog: &self.role_catalog,
            next_slot: 0,
            live_only: true,
        }
    }

    pub fn find_role_membership_visible(
        &self,
        role: usize,
        member: usize,
        txid: u32,
    ) -> Option<usize> {
        self.role_catalog
            .lock()
            .expect("role catalog lock poisoned")
            .memberships
            .iter()
            .position(|membership| {
                membership.visible_to(txid)
                    && membership.role as usize == role
                    && membership.member as usize == member
            })
    }

    pub fn change_role_membership(
        &self,
        role: usize,
        member: usize,
        grantor: usize,
        options: RoleMembershipOptions,
        exists: bool,
        txid: u32,
    ) -> Result<(usize, Option<PendingRoleMembership>), SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let existing = catalog.memberships.iter().position(|membership| {
            (membership.live || membership.pending.is_some())
                && membership.role as usize == role
                && membership.member as usize == member
        });
        let slot = match existing {
            Some(slot) => slot,
            None if !exists => {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role membership does not exist"
                ));
            }
            None => catalog
                .memberships
                .iter()
                .position(|membership| !membership.live && membership.pending.is_none())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many role memberships (limit {})",
                        catalog.memberships.len()
                    )
                })?,
        };
        if let Some(pending) = catalog.memberships[slot].pending
            && pending.txid != txid
        {
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent role membership DDL"
            ));
        }
        let prior = catalog.memberships[slot].pending;
        if existing.is_none() {
            catalog.memberships[slot].role = role as u16;
            catalog.memberships[slot].member = member as u16;
        }
        catalog.memberships[slot].pending = Some(PendingRoleMembership {
            txid,
            exists,
            grantor: grantor as u16,
            options,
        });
        Ok((slot, prior))
    }

    pub fn commit_role_membership_change(&self, slot: usize) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let Some(pending) = catalog.memberships[slot].pending.take() else {
            return;
        };
        catalog.memberships[slot].live = pending.exists;
        catalog.memberships[slot].grantor = pending.grantor;
        catalog.memberships[slot].options = pending.options;
        if !pending.exists {
            catalog.memberships[slot].role = 0;
            catalog.memberships[slot].member = 0;
            catalog.memberships[slot].grantor = 0;
        }
    }

    pub fn rollback_role_membership_change(
        &self,
        slot: usize,
        prior: Option<PendingRoleMembership>,
    ) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        catalog.memberships[slot].pending = prior;
        if !catalog.memberships[slot].live && prior.is_none() {
            catalog.memberships[slot].role = 0;
            catalog.memberships[slot].member = 0;
            catalog.memberships[slot].grantor = 0;
        }
    }

    pub fn install_role_membership(
        &self,
        role_name: &str,
        member_name: &str,
        grantor_name: &str,
        options: RoleMembershipOptions,
    ) -> Result<usize, SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let role = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == role_name)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "membership role \"{}\" does not exist",
                    role_name
                )
            })?;
        let member = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == member_name)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "membership member \"{}\" does not exist",
                    member_name
                )
            })?;
        let grantor = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == grantor_name)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "membership grantor \"{}\" does not exist",
                    grantor_name
                )
            })?;
        if let Some(slot) = catalog.memberships.iter().position(|membership| {
            membership.visible_to(0)
                && membership.role as usize == role
                && membership.member as usize == member
        }) {
            catalog.memberships[slot].grantor = grantor as u16;
            catalog.memberships[slot].options = options;
            return Ok(slot);
        }
        let slot = catalog
            .memberships
            .iter()
            .position(|membership| !membership.live && membership.pending.is_none())
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many role memberships (limit {})",
                    catalog.memberships.len()
                )
            })?;
        catalog.memberships[slot] = RoleMembership {
            role: role as u16,
            member: member as u16,
            grantor: grantor as u16,
            options,
            live: true,
            pending: None,
        };
        Ok(slot)
    }

    pub(crate) fn role_settings(&self) -> impl Iterator<Item = (usize, RoleSetting)> + '_ {
        RoleSettingIter {
            catalog: &self.role_catalog,
            next_slot: 0,
        }
    }

    pub(crate) fn role_setting_count(&self) -> usize {
        self.role_catalog
            .lock()
            .expect("role catalog lock poisoned")
            .settings
            .len()
    }

    pub(crate) fn change_role_setting(
        &self,
        scope: RoleSettingScope,
        name: SqlName,
        value: Option<StackStr<ROLE_SETTING_VALUE_MAX>>,
        txid: u32,
    ) -> Result<(usize, Option<PendingRoleSetting>), SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let existing = catalog.settings.iter().position(|setting| {
            (setting.live || setting.pending.is_some())
                && setting.scope == scope
                && setting.name == name
        });
        let slot = match existing {
            Some(slot) => slot,
            None if value.is_none() => {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "role setting does not exist"
                ));
            }
            None => catalog
                .settings
                .iter()
                .position(|setting| !setting.live && setting.pending.is_none())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many role settings (limit {})",
                        catalog.settings.len()
                    )
                })?,
        };
        if let Some(pending) = catalog.settings[slot].pending
            && pending.txid != txid
        {
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent role setting DDL"
            ));
        }
        let prior = catalog.settings[slot].pending;
        if existing.is_none() {
            catalog.settings[slot].scope = scope;
            catalog.settings[slot].name = name;
        }
        catalog.settings[slot].pending = Some(PendingRoleSetting {
            txid,
            exists: value.is_some(),
            value: value.unwrap_or_default(),
        });
        Ok((slot, prior))
    }

    pub(crate) fn commit_role_setting(&self, slot: usize) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let Some(pending) = catalog.settings[slot].pending.take() else {
            return;
        };
        catalog.settings[slot].live = pending.exists;
        catalog.settings[slot].value = pending.value;
        if !pending.exists {
            catalog.settings[slot] = RoleSetting::EMPTY;
        }
    }

    pub(crate) fn rollback_role_setting(&self, slot: usize, prior: Option<PendingRoleSetting>) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        catalog.settings[slot].pending = prior;
        if !catalog.settings[slot].live && prior.is_none() {
            catalog.settings[slot] = RoleSetting::EMPTY;
        }
    }

    pub(crate) fn install_role_setting(
        &self,
        scope: RoleSettingScope,
        name: SqlName,
        value: Option<StackStr<ROLE_SETTING_VALUE_MAX>>,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        if let Some(slot) = catalog
            .settings
            .iter()
            .position(|setting| setting.live && setting.scope == scope && setting.name == name)
        {
            if let Some(value) = value {
                catalog.settings[slot].value = value;
            } else {
                catalog.settings[slot] = RoleSetting::EMPTY;
            }
            return Ok(());
        }
        let Some(value) = value else {
            return Ok(());
        };
        let slot = catalog
            .settings
            .iter()
            .position(|setting| !setting.live && setting.pending.is_none())
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many role settings (limit {})",
                    catalog.settings.len()
                )
            })?;
        catalog.settings[slot] = RoleSetting {
            scope,
            name,
            value,
            live: true,
            pending: None,
        };
        Ok(())
    }

    fn system_settings_catalog(&self) -> std::sync::MutexGuard<'_, FixedVec<SystemSetting>> {
        self.system_settings
            .lock()
            .expect("system settings catalog lock poisoned")
    }

    pub(crate) fn system_settings(
        &self,
    ) -> core::iter::Enumerate<core::array::IntoIter<SystemSetting, MAX_SYSTEM_SETTINGS>> {
        let catalog = self.system_settings_catalog();
        let image: [SystemSetting; MAX_SYSTEM_SETTINGS] =
            core::array::from_fn(|slot| catalog[slot]);
        image.into_iter().enumerate()
    }

    fn validate_system_setting_value(
        value: Option<StackStr<ROLE_SETTING_VALUE_MAX>>,
    ) -> Result<(), SqlError> {
        if value.is_some_and(|value| value.is_truncated()) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "system setting exceeds its fixed value capacity"
            ));
        }
        Ok(())
    }

    pub(crate) fn change_system_setting(
        &self,
        name: SqlName,
        value: Option<StackStr<ROLE_SETTING_VALUE_MAX>>,
        txid: u32,
    ) -> Result<Option<(usize, Option<PendingRoleSetting>)>, SqlError> {
        Self::validate_system_setting_value(value)?;
        let mut catalog = self.system_settings_catalog();
        let existing = catalog.iter().position(|setting| {
            (setting.live || setting.pending.is_some()) && setting.name == name
        });
        let slot = match existing {
            Some(slot) => slot,
            None if value.is_none() => {
                return Ok(None);
            }
            None => catalog
                .iter()
                .position(|setting| !setting.live && setting.pending.is_none())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many system settings (limit {})",
                        MAX_SYSTEM_SETTINGS
                    )
                })?,
        };
        if let Some(pending) = catalog[slot].pending
            && pending.txid != txid
        {
            drop(catalog);
            self.wait_for_transaction(txid, pending.txid)?;
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent system setting DDL"
            ));
        }
        let prior = catalog[slot].pending;
        if existing.is_none() {
            catalog[slot].name = name;
        }
        catalog[slot].pending = Some(PendingRoleSetting {
            txid,
            exists: value.is_some(),
            value: value.unwrap_or_default(),
        });
        Ok(Some((slot, prior)))
    }

    pub(crate) fn commit_system_setting(&self, slot: usize) {
        let mut catalog = self.system_settings_catalog();
        let Some(pending) = catalog[slot].pending.take() else {
            return;
        };
        catalog[slot].live = pending.exists;
        catalog[slot].value = pending.value;
        if !pending.exists {
            catalog[slot] = SystemSetting::EMPTY;
        }
    }

    pub(crate) fn rollback_system_setting(&self, slot: usize, prior: Option<PendingRoleSetting>) {
        let mut catalog = self.system_settings_catalog();
        catalog[slot].pending = prior;
        if !catalog[slot].live && prior.is_none() {
            catalog[slot] = SystemSetting::EMPTY;
        }
    }

    pub(crate) fn install_system_setting(
        &self,
        name: SqlName,
        value: Option<StackStr<ROLE_SETTING_VALUE_MAX>>,
    ) -> Result<(), SqlError> {
        Self::validate_system_setting_value(value)?;
        let mut catalog = self.system_settings_catalog();
        if let Some(slot) = catalog
            .iter()
            .position(|setting| (setting.live || setting.pending.is_some()) && setting.name == name)
        {
            if catalog[slot].pending.is_some() {
                return Err(sql_err!(
                    sqlstate::OBJECT_IN_USE,
                    "cannot replay a system setting with an unresolved transactional image"
                ));
            }
            if let Some(value) = value {
                catalog[slot].value = value;
            } else {
                catalog[slot] = SystemSetting::EMPTY;
            }
            return Ok(());
        }
        let Some(value) = value else { return Ok(()) };
        let slot = catalog
            .iter()
            .position(|setting| !setting.live && setting.pending.is_none())
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many system settings (limit {})",
                    MAX_SYSTEM_SETTINGS
                )
            })?;
        catalog[slot] = SystemSetting {
            name,
            value,
            live: true,
            pending: None,
        };
        Ok(())
    }

    pub fn remove_role_membership(&self, role_name: &str, member_name: &str) {
        let mut catalog = self
            .role_catalog
            .lock()
            .expect("role catalog lock poisoned");
        let role = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == role_name);
        let member = catalog
            .roles
            .iter()
            .position(|role| role.live && role.name.as_str() == member_name);
        let (Some(role), Some(member)) = (role, member) else {
            return;
        };
        if let Some(slot) = catalog.memberships.iter().position(|membership| {
            membership.visible_to(0)
                && membership.role as usize == role
                && membership.member as usize == member
        }) {
            catalog.memberships[slot].live = false;
        }
    }

    /// Whether `member` may SET ROLE to `target`, following membership edges
    /// whose SET option is true.
    pub fn role_can_set(&self, member: usize, target: usize, txid: u32) -> bool {
        self.role_reaches(member, target, txid, true)
    }

    pub fn role_is_member_of(&self, member: usize, target: usize, txid: u32) -> bool {
        self.role_reaches(member, target, txid, false)
    }

    fn role_reaches(&self, member: usize, target: usize, txid: u32, require_set: bool) -> bool {
        if member == target {
            return true;
        }
        let mut visited = self.role_graph_scratch();
        self.reachable_roles(member, txid, false, require_set, &mut visited);
        visited.get(target).copied().unwrap_or(false)
    }

    pub fn role_can_admin(&self, member: usize, target: usize, txid: u32) -> bool {
        RoleMembershipIter {
            catalog: &self.role_catalog,
            next_slot: 0,
            live_only: false,
        }
        .any(|(_, membership)| {
            membership.visible_to(txid)
                && membership.role as usize == target
                && membership.options_to(txid).admin
                && self.role_is_member_of(member, membership.member as usize, txid)
        })
    }

    pub fn role_can_admin_excluding(
        &self,
        member: usize,
        target: usize,
        excluded: usize,
        txid: u32,
    ) -> bool {
        RoleMembershipIter {
            catalog: &self.role_catalog,
            next_slot: 0,
            live_only: false,
        }
        .any(|(slot, membership)| {
            slot != excluded
                && membership.visible_to(txid)
                && membership.role as usize == target
                && membership.options_to(txid).admin
                && self.role_is_member_of(member, membership.member as usize, txid)
        })
    }

    pub fn role_has_grants_from(&self, role: usize, grantor: usize, txid: u32) -> bool {
        RoleMembershipIter {
            catalog: &self.role_catalog,
            next_slot: 0,
            live_only: false,
        }
        .any(|(_, membership)| {
            membership.visible_to(txid)
                && membership.role as usize == role
                && membership.grantor_to(txid) as usize == grantor
        })
    }

    /// Committed schemas with their slot indices, for checkpoint and catalog
    /// output.
    pub fn live_schemas(&self) -> impl Iterator<Item = (usize, SchemaDef)> + '_ {
        SchemaIter {
            catalog: &self.schemas,
            next_slot: 0,
        }
        .filter(|(_, schema)| {
            schema.database == current_database() && schema.ddl_state == CatalogDdlState::Present
        })
    }

    /// Schemas visible to `txid`, for catalog output inside a transaction.
    pub fn visible_schemas(&self, txid: u32) -> impl Iterator<Item = (usize, SchemaDef)> + '_ {
        SchemaIter {
            catalog: &self.schemas,
            next_slot: 0,
        }
        .filter(move |(_, schema)| schema.database == current_database() && schema.visible_to(txid))
    }

    // --- Object comments (`COMMENT ON ...`) ---

    fn comment_database(&self, class: CommentClass) -> Option<DatabaseOid> {
        (!matches!(
            class,
            CommentClass::Tablespace | CommentClass::Database | CommentClass::Role
        ))
        .then_some(current_database())
    }

    fn comment_identity_uses_subid(class: CommentClass) -> bool {
        matches!(
            class,
            CommentClass::Role
                | CommentClass::ForeignDataWrapper
                | CommentClass::ForeignServer
                | CommentClass::Cast
                | CommentClass::Operator
                | CommentClass::OperatorFamily
                | CommentClass::OperatorClass
                | CommentClass::AccessMethod
                | CommentClass::ProceduralLanguage
        )
    }

    fn comment_catalog(&self) -> std::sync::MutexGuard<'_, CommentCatalog> {
        self.comments.lock().expect("comment catalog lock poisoned")
    }

    /// The comment text `txid` sees on this object, or `None` for none. Reads
    /// the transaction's own uncommitted overlay when present, else committed.
    pub fn comment_text(
        &self,
        class: CommentClass,
        schema: &str,
        name: &str,
        subid: u32,
        txid: u32,
    ) -> Option<StackStr<COMMENT_MAX>> {
        let comments = self.comment_catalog();
        comments
            .entries
            .iter()
            .find(|c| {
                c.matches_to(
                    self.comment_database(class),
                    class,
                    schema,
                    name,
                    subid,
                    txid,
                )
            })
            .and_then(|comment| match comment.pending {
                Some(pending) if pending.txid == txid => pending.text,
                _ => comment.live,
            })
    }

    /// Committed comment entries carrying text, for the checkpoint and
    /// `pg_description`.
    pub fn live_comments(&self) -> impl Iterator<Item = CommentEntry> + '_ {
        LiveCommentIter {
            catalog: &self.comments,
            database: current_database(),
            next_slot: 0,
        }
    }

    /// Comments `txid` can see (own uncommitted overlay, else committed) that
    /// carry text, as `(class, schema, name, subid, text)` — for
    /// `pg_description`, `obj_description` and `col_description`.
    pub fn comments_visible(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (CommentClass, SqlName, SqlName, u32, StackStr<COMMENT_MAX>)> + '_
    {
        VisibleCommentIter {
            catalog: &self.comments,
            database: current_database(),
            txid,
            next_slot: 0,
        }
    }

    pub(crate) fn comment_capacity(&self) -> usize {
        self.comment_catalog().entries.len()
    }

    pub(crate) fn comment_for_event_trigger(
        &self,
        slot: usize,
        txid: u32,
    ) -> Option<(CommentClass, SqlName, SqlName, u32)> {
        let comments = self.comment_catalog();
        let comment = comments
            .entries
            .get(slot)?
            .used
            .then_some(&comments.entries[slot])?;
        let identity = comment
            .pending_identity
            .filter(|identity| identity.txid == txid);
        Some((
            comment.class,
            identity.map_or(comment.schema, |identity| identity.schema),
            identity.map_or(comment.name, |identity| identity.name),
            comment.subid,
        ))
    }

    /// Moves the transaction-visible identity of a table-constraint comment.
    /// The table slot is durable for the life of the relation; the current
    /// constraint catalog OID is derived only when exposing pg_catalog.
    pub(crate) fn stage_constraint_comment_rename(
        &self,
        table: usize,
        schema: SqlName,
        old_name: SqlName,
        new_name: SqlName,
        txid: u32,
    ) -> Option<(usize, Option<PendingCommentIdentity>)> {
        let database = Some(current_database());
        let mut comments = self.comment_catalog();
        let slot = comments.entries.iter().position(|comment| {
            comment.matches_to(
                database,
                CommentClass::Constraint,
                schema.as_str(),
                old_name.as_str(),
                table as u32,
                txid,
            )
        })?;
        let prior = comments.entries[slot].pending_identity;
        comments.entries[slot].pending_identity = Some(PendingCommentIdentity {
            txid,
            schema,
            name: new_name,
        });
        Some((slot, prior))
    }

    pub(crate) fn restore_comment_identity_pending(
        &self,
        slot: usize,
        prior: Option<PendingCommentIdentity>,
    ) {
        let mut comments = self.comment_catalog();
        comments.entries[slot].pending_identity = prior;
        comments.reap(slot);
    }

    fn stage_trigger_comment_rename(
        &self,
        old_name: SqlName,
        new_name: SqlName,
        subid: u32,
        txid: u32,
    ) {
        let mut comments = self.comment_catalog();
        for comment in comments.entries.iter_mut().filter(|comment| {
            comment.matches_to(
                Some(current_database()),
                CommentClass::Trigger,
                "",
                old_name.as_str(),
                subid,
                txid,
            )
        }) {
            comment.pending_identity = Some(PendingCommentIdentity {
                txid,
                schema: comment.schema,
                name: new_name,
            });
        }
    }

    fn stage_object_comment_identity(
        &self,
        class: CommentClass,
        old_schema: SqlName,
        old_name: SqlName,
        new_schema: SqlName,
        new_name: SqlName,
        txid: u32,
    ) {
        let database = Some(current_database());
        let mut comments = self.comment_catalog();
        for comment in comments.entries.iter_mut().filter(|comment| {
            comment.used
                && comment.database == database
                && comment.class == class
                && ((comment.schema == old_schema && comment.name == old_name)
                    || comment.pending_identity.is_some_and(|identity| {
                        identity.txid == txid
                            && identity.schema == old_schema
                            && identity.name == old_name
                    }))
        }) {
            let changed = old_schema != new_schema || old_name != new_name;
            comment.pending_identity = changed.then_some(PendingCommentIdentity {
                txid,
                schema: new_schema,
                name: new_name,
            });
        }
    }

    fn commit_object_comment_identity(
        &self,
        class: CommentClass,
        old_schema: SqlName,
        old_name: SqlName,
        txid: u32,
    ) {
        let database = Some(current_database());
        let mut comments = self.comment_catalog();
        for comment in comments.entries.iter_mut().filter(|comment| {
            comment.used
                && comment.database == database
                && comment.class == class
                && comment.schema == old_schema
                && comment.name == old_name
                && comment
                    .pending_identity
                    .is_some_and(|pending| pending.txid == txid)
        }) {
            let pending = comment
                .pending_identity
                .take()
                .expect("filtered pending comment identity");
            comment.schema = pending.schema;
            comment.name = pending.name;
        }
    }

    fn replay_object_comment_identity(
        &self,
        class: CommentClass,
        old_schema: SqlName,
        old_name: SqlName,
        new_schema: SqlName,
        new_name: SqlName,
    ) {
        if old_schema == new_schema && old_name == new_name {
            return;
        }
        let database = Some(current_database());
        let mut comments = self.comment_catalog();
        for comment in comments.entries.iter_mut().filter(|comment| {
            comment.used
                && comment.database == database
                && comment.class == class
                && comment.schema == old_schema
                && comment.name == old_name
        }) {
            comment.schema = new_schema;
            comment.name = new_name;
            comment.pending_identity = None;
        }
    }

    /// Sets (or, with `text == None`, removes) a comment as `txid`'s
    /// uncommitted overlay. Returns the slot and the prior overlay, for the
    /// transaction's undo log. A fresh key claims a free slot; exhausting the
    /// slab is a loud error.
    pub fn set_comment(
        &self,
        class: CommentClass,
        schema: SqlName,
        name: SqlName,
        subid: u32,
        text: Option<StackStr<COMMENT_MAX>>,
        txid: u32,
    ) -> Result<(usize, Option<PendingComment>), SqlError> {
        let database = self.comment_database(class);
        let mut comments = self.comment_catalog();
        if let Some(slot) = comments.entries.iter().position(|c| {
            c.database == database
                && c.class == class
                && c.subid == subid
                && (Self::comment_identity_uses_subid(class)
                    || c.matches_to(database, class, schema.as_str(), name.as_str(), subid, txid))
        }) {
            let prior = comments.entries[slot].pending.take();
            comments.entries[slot].pending = Some(PendingComment { txid, text });
            return Ok((slot, prior));
        }
        let Some(slot) = comments.entries.iter().position(|c| !c.used) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many object comments (limit {})",
                comments.entries.capacity()
            ));
        };
        comments.entries[slot] = CommentEntry {
            used: true,
            database,
            class,
            schema,
            name,
            subid,
            live: None,
            pending: Some(PendingComment { txid, text }),
            pending_identity: None,
        };
        Ok((slot, None))
    }

    /// Rollback: restores the comment slot's prior uncommitted overlay,
    /// freeing the slot if it now holds nothing.
    pub fn restore_comment_pending(&self, slot: usize, prior: Option<PendingComment>) {
        let mut comments = self.comment_catalog();
        comments.entries[slot].pending = prior;
        comments.reap(slot);
    }

    /// Commit: promotes `txid`'s overlay to the committed value and returns the
    /// object identity plus the new committed text, for journaling.
    pub fn commit_comment(
        &self,
        slot: usize,
        txid: u32,
    ) -> Option<(
        CommentClass,
        SqlName,
        SqlName,
        u32,
        Option<StackStr<COMMENT_MAX>>,
    )> {
        let mut comments = self.comment_catalog();
        let entry = &mut comments.entries[slot];
        match entry.pending {
            Some(p) if p.txid == txid => {
                if let Some(identity) = entry
                    .pending_identity
                    .take()
                    .filter(|identity| identity.txid == txid)
                {
                    entry.schema = identity.schema;
                    entry.name = identity.name;
                }
                entry.pending = None;
                entry.live = p.text;
                let out = (
                    entry.class,
                    entry.schema,
                    entry.name,
                    entry.subid,
                    entry.live,
                );
                comments.reap(slot);
                Some(out)
            }
            _ => None,
        }
    }

    /// Committed apply (journal replay and checkpoint load): sets the committed
    /// text directly, with no transactional overlay.
    pub fn apply_comment(
        &self,
        class: CommentClass,
        schema: SqlName,
        name: SqlName,
        subid: u32,
        text: Option<StackStr<COMMENT_MAX>>,
    ) -> Result<(), SqlError> {
        let database = self.comment_database(class);
        let mut comments = self.comment_catalog();
        if let Some(slot) = comments.entries.iter().position(|c| {
            c.database == database
                && c.class == class
                && c.subid == subid
                && (Self::comment_identity_uses_subid(class)
                    || c.matches(database, class, schema.as_str(), name.as_str(), subid))
        }) {
            comments.entries[slot].live = text;
            comments.reap(slot);
            return Ok(());
        }
        if text.is_none() {
            return Ok(());
        }
        let Some(slot) = comments.entries.iter().position(|c| !c.used) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many object comments (limit {})",
                comments.entries.capacity()
            ));
        };
        comments.entries[slot] = CommentEntry {
            used: true,
            database,
            class,
            schema,
            name,
            subid,
            live: text,
            pending: None,
            pending_identity: None,
        };
        Ok(())
    }

    /// Drops every comment on a relation (all columns and the relation itself)
    /// or a schema, for when the object is dropped. Committed removal.
    pub fn drop_object_comments(&self, class: CommentClass, schema: &str, name: &str) {
        let database = self.comment_database(class);
        let mut comments = self.comment_catalog();
        for slot in 0..comments.entries.len() {
            let c = &comments.entries[slot];
            if c.used
                && c.database == database
                && c.class == class
                && c.pending.is_none()
                && c.name.as_str() == name
                && c.schema.as_str() == schema
            {
                comments.entries[slot].live = None;
                comments.reap(slot);
            }
        }
    }

    fn drop_comments_by_subid(&self, class: CommentClass, subid: u32) {
        let database = self.comment_database(class);
        let mut comments = self.comment_catalog();
        for slot in 0..comments.entries.len() {
            let comment = &comments.entries[slot];
            if comment.used
                && comment.database == database
                && comment.class == class
                && comment.pending.is_none()
                && comment.subid == subid
            {
                comments.entries[slot].live = None;
                comments.reap(slot);
            }
        }
    }

    /// Committed create (journal replay): the schema is immediately part of
    /// the durable image.
    pub fn create_schema(&self, name: SqlName) -> Result<usize, SqlError> {
        self.alloc_schema(name, CatalogDdlState::Present, None)
    }

    /// Transactional create: the schema exists only for `txid` until commit.
    pub fn create_schema_in(&self, name: SqlName, txid: u32) -> Result<usize, SqlError> {
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        if !self.has_current_database_create_privilege(role, txid) {
            let database = self.database_definition(self.current_database_slot(txid), txid);
            return Err(sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied for database {}",
                database.name.as_str()
            ));
        }
        self.alloc_schema(name, CatalogDdlState::PendingCreate { txid }, None)
    }

    fn alloc_schema(
        &self,
        name: SqlName,
        ddl_state: CatalogDdlState,
        ownership: Option<Ownership>,
    ) -> Result<usize, SqlError> {
        let txid = ddl_state.pending_txid().unwrap_or(0);
        let ownership = ownership.unwrap_or_else(|| self.initial_ownership(txid));
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        if let Some(blocker) = schemas.iter().find_map(|schema| {
            (schema.database == current_database() && schema.name == name)
                .then(|| schema.pending_owner_other_than(txid))
                .flatten()
        }) {
            drop(schemas);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if schemas.iter().any(|schema| {
            schema.database == current_database() && schema.visible_to(txid) && schema.name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_SCHEMA,
                "schema \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(slot) = schemas
            .iter()
            .position(|schema| schema.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many schemas (limit {})",
                schemas.len()
            ));
        };
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Schema,
            slot: slot as u16,
        });
        schemas[slot] = SchemaDef {
            database: current_database(),
            name,
            ownership,
            ddl_state,
        };
        Ok(slot)
    }

    /// Committed drop (journal replay).
    pub fn drop_schema(&self, slot: usize) {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        let name = schemas[slot].name;
        self.drop_object_comments(CommentClass::Schema, "", name.as_str());
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Schema,
            slot: slot as u16,
        });
        schemas[slot] = SchemaDef::EMPTY;
    }

    /// Transactional drop: the schema stays visible to other transactions
    /// until `txid` commits. The owner's own pending-create evaporates.
    pub fn drop_schema_in(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        if let Some(blocker) = schemas[slot].pending_owner_other_than(txid) {
            let name = schemas[slot].name;
            drop(schemas);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let schema = &mut schemas[slot];
        schema.ddl_state = schema.ddl_state.drop_by(txid);
        Ok(())
    }

    /// Promotes an uncommitted CREATE SCHEMA into the committed catalog.
    pub fn commit_schema_create(&self, slot: usize) {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        schemas[slot].ddl_state = schemas[slot].ddl_state.commit_create();
        schemas[slot].ownership = schemas[slot].ownership.committed();
    }

    /// Applies a committed DROP SCHEMA.
    pub fn commit_schema_drop(&self, slot: usize) {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        let name = schemas[slot].name;
        self.drop_object_comments(CommentClass::Schema, "", name.as_str());
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Schema,
            slot: slot as u16,
        });
        schemas[slot] = SchemaDef::EMPTY;
    }

    /// Rolls back an uncommitted CREATE SCHEMA, freeing the slot.
    pub fn rollback_schema_create(&self, slot: usize) {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        if schemas[slot].ddl_state.rollback_create() == CatalogDdlState::Absent {
            self.clear_object_acl_entries(AccessObject {
                class: AccessClass::Schema,
                slot: slot as u16,
            });
            schemas[slot] = SchemaDef::EMPTY;
        }
    }

    /// Rolls back an uncommitted DROP SCHEMA: it returns to the committed
    /// image unchanged.
    pub fn rollback_schema_drop(&self, slot: usize, txid: u32) {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        schemas[slot].ddl_state = schemas[slot].ddl_state.rollback_drop(txid);
    }

    /// Rename one namespace and every durable identity that names it. Catalog
    /// slots remain stable; no old-name alias survives the transition.
    pub(crate) fn rename_schema(
        &mut self,
        slot: usize,
        name: SqlName,
    ) -> Result<SqlName, SqlError> {
        let mut schemas = self.schemas.lock().expect("schema catalog lock poisoned");
        let prior = schemas[slot].name;
        if prior == name {
            return Ok(prior);
        }
        if schemas.iter().enumerate().any(|(other, schema)| {
            other != slot
                && schema.database == current_database()
                && schema.ddl_state != CatalogDdlState::Absent
                && schema.name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_SCHEMA,
                "schema \"{}\" already exists",
                name.as_str()
            ));
        }

        // A stored definition records the search path that bound its
        // unqualified names. Check every replacement before changing any
        // catalog identity, so a fixed-capacity path never leaves a partial
        // rename behind.
        for rule in self.rule_entries().map(|(_, entry)| entry).filter(|rule| {
            rule.database == current_database() && rule.ddl_state != CatalogDdlState::Absent
        }) {
            let mut path = rule.definition.creation_path;
            rename_schema_path(&mut path, prior, name)?;
            let mut source = rule.definition.source;
            rename_schema_qualified_sql(&mut source, prior, name)?;
            if let Some(pending) = rule.pending {
                let mut path = pending.definition.creation_path;
                rename_schema_path(&mut path, prior, name)?;
                let mut source = pending.definition.source;
                rename_schema_qualified_sql(&mut source, prior, name)?;
            }
        }
        for (_, definition) in (RoutineIter {
            catalog: &self.routines,
            next_slot: 0,
            lookup: None,
        })
        .filter(|(_, definition)| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            let mut path = definition.creation_path;
            rename_schema_path(&mut path, prior, name)?;
            let mut body = definition.body;
            rename_schema_qualified_sql(&mut body, prior, name)?;
            if let Some(pending) = definition.pending_definition {
                let mut path = pending.creation_path;
                rename_schema_path(&mut path, prior, name)?;
                let mut body = pending.body;
                rename_schema_qualified_sql(&mut body, prior, name)?;
            }
        }
        {
            let matviews = self.matview_catalog();
            for definition in matviews.iter().filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            }) {
                let mut path = definition.creation_path;
                rename_schema_path(&mut path, prior, name)?;
                let mut sql = definition.sql;
                rename_schema_qualified_sql(&mut sql, prior, name)?;
            }
        }
        for table_slot in 0..self.tables.len() {
            let table = &self.tables[table_slot];
            if table.database != current_database() || (!table.live && table.pending_ddl.is_none())
            {
                continue;
            }
            let mut definition = table.def;
            rename_table_sql_identity(&mut definition, prior, name)?;
            let mut tail = table.pending_def_tail;
            while let Some(pending_slot) = tail {
                let pending = &self.pending_table_defs[pending_slot as usize];
                let mut definition = pending.version.def;
                rename_table_sql_identity(&mut definition, prior, name)?;
                tail = pending.previous;
            }
        }
        for (_, definition) in (DomainIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        })
        .filter(|(_, definition)| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            if let Some(default) = definition.default_expr {
                let mut default = default;
                rename_schema_qualified_sql(&mut default, prior, name)?;
            }
            for check in definition.checks.iter().take(definition.n_checks) {
                let mut expression = check.expression;
                rename_schema_qualified_sql(&mut expression, prior, name)?;
            }
        }
        for definition in self
            .matching_indexes(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            })
            .map(|(_, definition)| definition)
        {
            for expression in definition.expressions.iter().flatten() {
                let mut expression = *expression;
                rename_schema_qualified_sql(&mut expression, prior, name)?;
            }
            if let Some(predicate) = definition.predicate {
                let mut predicate = predicate;
                rename_schema_qualified_sql(&mut predicate, prior, name)?;
            }
        }

        schemas[slot].name = name;
        drop(schemas);

        for table_slot in 0..self.tables.len() {
            if self.tables[table_slot].database != current_database() {
                continue;
            }
            let table = &mut self.tables[table_slot];
            if !table.live && table.pending_ddl.is_none() {
                continue;
            }
            rename_schema_name(&mut table.def.schema, prior, name);
            for column in table.def.columns.iter_mut().take(table.def.n_columns) {
                rename_user_type_schema(&mut column.user_type, prior, name);
            }
            for key in table.def.fkeys.iter_mut().take(table.def.n_fkeys) {
                rename_schema_name(&mut key.parent_schema, prior, name);
            }
            rename_table_sql_identity(&mut table.def, prior, name)?;
            table.mark_dirty();
            let mut tail = table.pending_def_tail;
            while let Some(pending_slot) = tail {
                let entry = &mut self.pending_table_defs[pending_slot as usize];
                let pending = &mut entry.version;
                rename_schema_name(&mut pending.def.schema, prior, name);
                for column in pending.def.columns.iter_mut().take(pending.def.n_columns) {
                    rename_user_type_schema(&mut column.user_type, prior, name);
                }
                for key in pending.def.fkeys.iter_mut().take(pending.def.n_fkeys) {
                    rename_schema_name(&mut key.parent_schema, prior, name);
                }
                rename_table_sql_identity(&mut pending.def, prior, name)?;
                tail = entry.previous;
            }
        }

        {
            let mut catalog = self.view_rule_catalog();
            for definition in catalog.views.iter_mut().filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            }) {
                rename_schema_name(&mut definition.schema, prior, name);
                if let Some(pending) = &mut definition.pending_schema {
                    rename_schema_name(&mut pending.schema, prior, name);
                }
            }
            for definition in catalog.rules.iter_mut().filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            }) {
                rename_schema_path(&mut definition.definition.creation_path, prior, name)?;
                rename_schema_qualified_sql(&mut definition.definition.source, prior, name)?;
                if let Some(pending) = &mut definition.pending {
                    rename_schema_path(&mut pending.definition.creation_path, prior, name)?;
                    rename_schema_qualified_sql(&mut pending.definition.source, prior, name)?;
                }
            }
        }
        {
            let mut catalog = self.sequence_catalog();
            for definition in catalog.definitions.iter_mut().filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            }) {
                rename_schema_name(&mut definition.schema, prior, name);
                if let Some(owner) = &mut definition.owner {
                    rename_schema_name(&mut owner.table_schema, prior, name);
                }
                if let Some(generator) = &mut definition.generator_for {
                    rename_schema_name(&mut generator.table_schema, prior, name);
                }
                if let Some(pending) = &mut definition.pending_definition {
                    rename_schema_name(&mut pending.schema, prior, name);
                    if let Some(owner) = &mut pending.owner {
                        rename_schema_name(&mut owner.table_schema, prior, name);
                    }
                    if let Some(generator) = &mut pending.generator_for {
                        rename_schema_name(&mut generator.table_schema, prior, name);
                    }
                }
            }
        }
        for definition in self.index_catalog().iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.schema, prior, name);
            for expression in definition.expressions.iter_mut().flatten() {
                rename_schema_qualified_sql(expression, prior, name)?;
            }
            if let Some(predicate) = &mut definition.predicate {
                rename_schema_qualified_sql(predicate, prior, name)?;
            }
        }
        let mut type_catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        for definition in type_catalog.domains.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.schema, prior, name);
            rename_user_type_schema(&mut definition.base_domain, prior, name);
            rename_user_type_schema(&mut definition.base_user_type, prior, name);
            if let Some(default) = &mut definition.default_expr {
                rename_schema_qualified_sql(default, prior, name)?;
            }
            for check in definition.checks.iter_mut().take(definition.n_checks) {
                rename_schema_qualified_sql(&mut check.expression, prior, name)?;
            }
            if let Some(pending) = &mut definition.pending_definition
                && let Some(identity) = &mut pending.identity
            {
                rename_schema_name(&mut identity.schema, prior, name);
            }
        }
        for definition in type_catalog.enums.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending_definition {
                rename_schema_name(&mut pending.schema, prior, name);
            }
        }
        for definition in type_catalog.composites.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.schema, prior, name);
            for field in definition.fields.iter_mut().take(definition.n_fields) {
                rename_user_type_schema(&mut field.user_type, prior, name);
            }
            if let Some(pending) = &mut definition.pending_definition {
                rename_schema_name(&mut pending.schema, prior, name);
                for field in pending.fields.iter_mut().take(pending.n_fields) {
                    rename_user_type_schema(&mut field.user_type, prior, name);
                }
            }
        }
        drop(type_catalog);
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        for definition in routines.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending_identity {
                rename_schema_name(&mut pending.schema, prior, name);
            }
            rename_routine_arguments_schema(
                &mut definition.arguments,
                definition.argument_count,
                prior,
                name,
            );
            rename_routine_parameters_schema(
                &mut definition.parameters,
                definition.parameter_count,
                prior,
                name,
            );
            rename_routine_arguments_schema(
                &mut definition.result_columns,
                definition.result_column_count,
                prior,
                name,
            );
            rename_routine_kind_schema(&mut definition.kind, prior, name);
            rename_schema_path(&mut definition.creation_path, prior, name)?;
            rename_schema_qualified_sql(&mut definition.body, prior, name)?;
            if let Some(pending) = &mut definition.pending_definition {
                rename_routine_arguments_schema(
                    &mut pending.arguments,
                    pending.argument_count,
                    prior,
                    name,
                );
                rename_routine_parameters_schema(
                    &mut pending.parameters,
                    pending.parameter_count,
                    prior,
                    name,
                );
                rename_routine_arguments_schema(
                    &mut pending.result_columns,
                    pending.result_column_count,
                    prior,
                    name,
                );
                rename_routine_kind_schema(&mut pending.kind, prior, name);
                rename_schema_path(&mut pending.creation_path, prior, name)?;
                rename_schema_qualified_sql(&mut pending.body, prior, name)?;
            }
        }
        drop(routines);
        let mut text_catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        for definition in text_catalog.collations.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending {
                rename_schema_name(&mut pending.definition.schema, prior, name);
            }
        }
        for definition in text_catalog.conversions.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending {
                rename_schema_name(&mut pending.definition.schema, prior, name);
            }
        }
        for definition in text_catalog
            .text_search_objects
            .iter_mut()
            .filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            })
        {
            if definition.definition.schema() == prior {
                definition.definition.rename(Some(name), None);
            }
            if let Some(pending) = &mut definition.pending
                && pending.definition.schema() == prior
            {
                pending.definition.rename(Some(name), None);
            }
        }
        drop(text_catalog);
        let mut operator_catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        for definition in operator_catalog.operators.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending {
                rename_schema_name(&mut pending.definition.schema, prior, name);
            }
        }
        for definition in operator_catalog.families.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending {
                rename_schema_name(&mut pending.definition.schema, prior, name);
            }
        }
        for definition in operator_catalog.classes.iter_mut().filter(|definition| {
            definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
        }) {
            rename_schema_name(&mut definition.definition.schema, prior, name);
            if let Some(pending) = &mut definition.pending {
                rename_schema_name(&mut pending.definition.schema, prior, name);
            }
        }
        drop(operator_catalog);
        {
            let mut catalog = self
                .extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned");
            for definition in catalog.definitions.iter_mut().filter(|definition| {
                definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
            }) {
                rename_schema_name(&mut definition.mutable.schema, prior, name);
                if let Some(pending) = &mut definition.pending_definition {
                    rename_schema_name(&mut pending.definition.schema, prior, name);
                }
            }
        }

        {
            let mut matviews = self.matview_catalog();
            for definition in matviews.iter_mut() {
                if definition.database == current_database()
                    && definition.ddl_state != CatalogDdlState::Absent
                {
                    rename_schema_path(&mut definition.creation_path, prior, name)?;
                    rename_schema_qualified_sql(&mut definition.sql, prior, name)?;
                }
            }
        }
        for slot in 0..self.rule_count() {
            if self.rule(slot).database == current_database()
                && self.rule(slot).ddl_state != CatalogDdlState::Absent
            {
                let image =
                    self.committed_dependency_image(StoredQueryDependencyOwner::Rule(slot as u16));
                self.with_dependency_image_mut(image, |dependencies| {
                    rename_dependency_schema(dependencies, prior, name)
                });
            }
        }
        for slot in 0..self.matview_count() {
            let definition = self.matview(slot);
            if definition.database == current_database()
                && definition.ddl_state != CatalogDdlState::Absent
            {
                let image = self.matview_dependency_image(slot);
                self.with_dependency_image_mut(image, |dependencies| {
                    rename_dependency_schema(dependencies, prior, name)
                });
            }
        }
        for (slot, policy) in (PolicyIter {
            catalog: &self.policy_catalog,
            next_slot: 0,
        }) {
            if policy.database == current_database() && policy.ddl_state != CatalogDdlState::Absent
            {
                let image = self
                    .committed_dependency_image(StoredQueryDependencyOwner::Policy(slot as u16));
                self.with_dependency_image_mut(image, |dependencies| {
                    rename_dependency_schema(dependencies, prior, name)
                });
            }
        }
        for slot in 0..self.routine_count() {
            let routine = self.routine(slot);
            if routine.database == current_database()
                && routine.ddl_state != CatalogDdlState::Absent
            {
                let image = self
                    .committed_dependency_image(StoredQueryDependencyOwner::Routine(slot as u16));
                self.with_dependency_image_mut(image, |dependencies| {
                    rename_dependency_schema(dependencies, prior, name)
                });
            }
        }
        {
            let mut catalog = self
                .stored_query_dependencies
                .lock()
                .expect("stored-query dependency catalog lock poisoned");
            for slot in 0..catalog.pending.len() {
                let pending = catalog.pending[slot];
                if pending.used {
                    let image = self.stored_query_dependency_pending_base + slot;
                    rename_dependency_schema(
                        catalog.image_mut(
                            image,
                            pending.count,
                            self.stored_query_dependencies_per_image,
                        ),
                        prior,
                        name,
                    );
                }
            }
        }
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used && comment.database == Some(current_database()) {
                if comment.class == CommentClass::Schema && comment.name == prior {
                    comment.name = name;
                }
                rename_schema_name(&mut comment.schema, prior, name);
                if let Some(identity) = &mut comment.pending_identity {
                    rename_schema_name(&mut identity.schema, prior, name);
                }
            }
        }
        Ok(prior)
    }

    fn extension_catalog(&self) -> std::sync::MutexGuard<'_, ExtensionCatalog> {
        self.extension_catalog
            .lock()
            .expect("extension catalog lock poisoned")
    }

    pub(crate) fn extension(&self, slot: usize) -> ExtensionDef {
        self.extension_catalog().definitions[slot]
    }

    pub(crate) fn extension_count(&self) -> usize {
        self.extension_catalog().definitions.len()
    }

    pub(crate) fn extensions_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ExtensionDef)> + '_ {
        ExtensionIter {
            catalog: &self.extension_catalog,
            next_slot: 0,
        }
        .filter(move |(_, extension)| {
            extension.database == current_database() && extension.visible_to(txid)
        })
    }

    pub(crate) fn extension_slot(&self, name: &str, txid: u32) -> Option<usize> {
        self.extension_catalog()
            .definitions
            .iter()
            .position(|extension| {
                extension.database == current_database()
                    && extension.visible_to(txid)
                    && extension.name.as_str() == name
            })
    }

    pub(crate) fn create_extension(
        &self,
        name: SqlName,
        namespace: usize,
        relocatable: bool,
        version: ExtensionVersion,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if namespace >= self.schema_count() || !self.schema_def(namespace).visible_to(txid) {
            return Err(sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema for extension \"{}\" does not exist",
                name.as_str()
            ));
        }
        let ownership = self.initial_ownership(txid);
        let mut catalog = self.extension_catalog();
        if catalog.definitions.iter().any(|extension| {
            extension.database == current_database()
                && extension.visible_to(txid)
                && extension.name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "extension \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(owner) = catalog.definitions.iter().find_map(|extension| {
            (extension.database == current_database() && extension.name == name)
                .then(|| extension.pending_owner_other_than(txid))
                .flatten()
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, owner, name.as_str()));
        }
        let slot = catalog
            .definitions
            .iter()
            .position(|extension| extension.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many extensions (limit {})",
                    catalog.definitions.len()
                )
            })?;
        let created_at = self.catalog_sequence.next();
        catalog.definitions[slot] = ExtensionDef {
            database: current_database(),
            created_at,
            name,
            namespace: namespace as u16,
            relocatable,
            version,
            ownership,
            pending: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn install_extension(
        &self,
        name: SqlName,
        namespace: usize,
        relocatable: bool,
        version: ExtensionVersion,
        owner: usize,
        created_at: u64,
    ) -> Result<usize, SqlError> {
        let mut catalog = self.extension_catalog();
        let definition = ExtensionDef {
            database: current_database(),
            created_at,
            name,
            namespace: namespace as u16,
            relocatable,
            version,
            ownership: Ownership {
                owner: owner as u16,
                pending: None,
            },
            pending: None,
            ddl_state: CatalogDdlState::Present,
        };
        if let Some(slot) = catalog.definitions.iter().position(|extension| {
            extension.database == current_database()
                && extension.ddl_state == CatalogDdlState::Present
                && extension.name == name
        }) {
            catalog.definitions[slot] = definition;
            drop(catalog);
            self.catalog_sequence.observe(created_at);
            return Ok(slot);
        }
        let slot = catalog
            .definitions
            .iter()
            .position(|extension| extension.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many extensions (limit {})",
                    catalog.definitions.len()
                )
            })?;
        catalog.definitions[slot] = definition;
        drop(catalog);
        self.catalog_sequence.observe(created_at);
        Ok(slot)
    }

    pub(crate) fn alter_extension_definition(
        &self,
        slot: usize,
        namespace: usize,
        relocatable: bool,
        version: ExtensionVersion,
        txid: u32,
    ) -> Result<Option<PendingExtensionDefinition>, SqlError> {
        if namespace >= self.schema_count() || !self.schema_def(namespace).visible_to(txid) {
            return Err(sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "schema does not exist"
            ));
        }
        let mut catalog = self.extension_catalog();
        if let Some(blocker) = catalog.definitions[slot].pending_owner_other_than(txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let prior = catalog.definitions[slot].pending;
        catalog.definitions[slot].pending = Some(PendingExtensionDefinition {
            txid,
            namespace: namespace as u16,
            relocatable,
            version,
        });
        Ok(prior)
    }

    pub(crate) fn commit_extension_create(&self, slot: usize, txid: u32) {
        let mut catalog = self.extension_catalog();
        let extension = &mut catalog.definitions[slot];
        extension.ddl_state = extension.ddl_state.commit_create();
        if let Some(pending) = extension.ownership.pending
            && pending.txid == txid
        {
            extension.ownership.owner = pending.owner;
            extension.ownership.pending = None;
        }
    }

    pub(crate) fn rollback_extension_create(&self, slot: usize) {
        let mut catalog = self.extension_catalog();
        Self::clear_extension_dependencies_for_in(&mut catalog, slot, 0);
        Self::clear_extension_configs_for_in(&mut catalog, slot);
        catalog.definitions[slot] = ExtensionDef::EMPTY;
        drop(catalog);
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Extension,
            slot: slot as u16,
        });
    }

    pub(crate) fn commit_extension_alter(&self, slot: usize, txid: u32) {
        let mut catalog = self.extension_catalog();
        let extension = &mut catalog.definitions[slot];
        if let Some(pending) = extension.pending
            && pending.txid == txid
        {
            extension.namespace = pending.namespace;
            extension.relocatable = pending.relocatable;
            extension.version = pending.version;
            extension.pending = None;
        }
    }

    pub(crate) fn rollback_extension_alter(
        &self,
        slot: usize,
        prior: Option<PendingExtensionDefinition>,
    ) {
        self.extension_catalog().definitions[slot].pending = prior;
    }

    pub(crate) fn drop_extension_in(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        let mut catalog = self.extension_catalog();
        if let Some(blocker) = catalog.definitions[slot].pending_owner_other_than(txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.drop_by(txid);
        Ok(())
    }

    pub(crate) fn commit_extension_drop(&self, slot: usize) {
        let mut catalog = self.extension_catalog();
        let name = catalog.definitions[slot].name;
        let object = AccessObject {
            class: AccessClass::Extension,
            slot: slot as u16,
        };
        for dependency in catalog.dependencies.iter_mut() {
            if dependency.extension as usize == slot || dependency.object == object {
                *dependency = ExtensionDependency::EMPTY;
            }
        }
        Self::clear_extension_configs_for_in(&mut catalog, slot);
        catalog.definitions[slot] = ExtensionDef::EMPTY;
        drop(catalog);
        self.drop_object_comments(CommentClass::Extension, "", name.as_str());
        self.clear_object_acl_entries(object);
    }

    pub(crate) fn rollback_extension_drop(&self, slot: usize, txid: u32) {
        let mut catalog = self.extension_catalog();
        catalog.definitions[slot].ddl_state =
            catalog.definitions[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn extension_dependencies_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ExtensionDependency)> + '_ {
        ExtensionDependencyIter {
            catalog: &self.extension_catalog,
            next_slot: 0,
        }
        .filter(move |(_, dependency)| dependency.visible_to(txid))
    }

    pub(crate) fn extension_dependency(&self, slot: usize) -> ExtensionDependency {
        self.extension_catalog().dependencies[slot]
    }

    fn clear_extension_dependencies_for_object(&self, object: AccessObject) {
        for dependency in self.extension_catalog().dependencies.iter_mut() {
            if dependency.object == object {
                *dependency = ExtensionDependency::EMPTY;
            }
        }
    }

    fn extension_member_of_in(
        catalog: &ExtensionCatalog,
        object: AccessObject,
        txid: u32,
    ) -> Option<usize> {
        catalog
            .dependencies
            .iter()
            .find(|dependency| {
                dependency.visible_to(txid)
                    && dependency.kind == ExtensionDependencyKind::Member
                    && dependency.object == object
            })
            .map(|dependency| dependency.extension as usize)
    }

    pub(crate) fn extension_member_of(&self, object: AccessObject, txid: u32) -> Option<usize> {
        Self::extension_member_of_in(&self.extension_catalog(), object, txid)
    }

    pub(crate) fn require_not_extension_member(
        &self,
        object: AccessObject,
        txid: u32,
        kind: &str,
    ) -> Result<(), SqlError> {
        let catalog = self.extension_catalog();
        let Some(extension) = Self::extension_member_of_in(&catalog, object, txid) else {
            return Ok(());
        };
        let extension_name = catalog.definitions[extension].name;
        drop(catalog);
        let (_, name) = self.access_object_name_to(object, txid);
        Err(sql_err!(
            sqlstate::DEPENDENT_OBJECTS_STILL_EXIST,
            "cannot drop {} \"{}\" because extension \"{}\" requires it",
            kind,
            name.as_str(),
            extension_name.as_str()
        ))
    }

    pub(crate) fn change_extension_dependency(
        &self,
        extension: usize,
        object: AccessObject,
        kind: ExtensionDependencyKind,
        exists: bool,
        txid: u32,
    ) -> Result<(usize, Option<PendingExtensionDependency>), SqlError> {
        if !self.access_object_visible_to(object, txid)
            || (object.class == AccessClass::Extension && kind != ExtensionDependencyKind::Required)
        {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "extension dependency target does not exist"
            ));
        }
        let mut catalog = self.extension_catalog();
        if !catalog.definitions[extension].visible_to(txid) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "extension does not exist"
            ));
        }
        if exists
            && kind == ExtensionDependencyKind::Member
            && let Some(other) = Self::extension_member_of_in(&catalog, object, txid)
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "object is already a member of extension \"{}\"",
                catalog.definitions[other].name.as_str()
            ));
        }
        let existing = catalog.dependencies.iter().position(|dependency| {
            dependency.extension as usize == extension
                && dependency.object == object
                && dependency.kind == kind
                && (dependency.live || dependency.pending.is_some())
        });
        let slot = if let Some(slot) = existing {
            slot
        } else {
            if !exists {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "object is not a member of extension \"{}\"",
                    catalog.definitions[extension].name.as_str()
                ));
            }
            catalog
                .dependencies
                .iter()
                .position(|dependency| !dependency.live && dependency.pending.is_none())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many extension dependencies (limit {})",
                        catalog.dependencies.len()
                    )
                })?
        };
        if let Some(pending) = catalog.dependencies[slot].pending
            && pending.txid != txid
        {
            let name = catalog.definitions[extension].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, name.as_str()));
        }
        let prior = catalog.dependencies[slot].pending;
        if existing.is_none() {
            catalog.dependencies[slot].extension = extension as u16;
            catalog.dependencies[slot].object = object;
            catalog.dependencies[slot].kind = kind;
        }
        catalog.dependencies[slot].pending = Some(PendingExtensionDependency { txid, exists });
        Ok((slot, prior))
    }

    pub(crate) fn commit_extension_dependency(&self, slot: usize, txid: u32) {
        let mut catalog = self.extension_catalog();
        let dependency = &mut catalog.dependencies[slot];
        if let Some(pending) = dependency.pending
            && pending.txid == txid
        {
            dependency.live = pending.exists;
            dependency.pending = None;
            if !dependency.live {
                *dependency = ExtensionDependency::EMPTY;
            }
        }
    }

    pub(crate) fn rollback_extension_dependency(
        &self,
        slot: usize,
        prior: Option<PendingExtensionDependency>,
    ) {
        let mut catalog = self.extension_catalog();
        catalog.dependencies[slot].pending = prior;
        if !catalog.dependencies[slot].live && prior.is_none() {
            catalog.dependencies[slot] = ExtensionDependency::EMPTY;
        }
    }

    fn clear_extension_dependencies_for_in(
        catalog: &mut ExtensionCatalog,
        extension: usize,
        txid: u32,
    ) {
        for dependency in catalog.dependencies.iter_mut() {
            if dependency.extension as usize == extension
                && (txid == 0
                    || dependency
                        .pending
                        .is_some_and(|pending| pending.txid == txid))
            {
                *dependency = ExtensionDependency::EMPTY;
            }
        }
    }

    pub(crate) fn extension_configs_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ExtensionConfig)> + '_ {
        ExtensionConfigIter {
            catalog: &self.extension_catalog,
            next_slot: 0,
        }
        .filter(move |(_, config)| config.visible_to(txid))
    }

    pub(crate) fn extension_config(&self, slot: usize) -> ExtensionConfig {
        self.extension_catalog().configs[slot]
    }

    pub(crate) fn extension_config_slot(
        &self,
        extension: usize,
        relation: ExtensionConfigRelation,
        txid: u32,
    ) -> Option<usize> {
        self.extension_catalog().configs.iter().position(|config| {
            config.extension as usize == extension
                && config.relation == relation
                && config.visible_to(txid)
        })
    }

    pub(crate) fn change_extension_config(
        &self,
        extension: usize,
        relation: ExtensionConfigRelation,
        condition: ExtensionConfigCondition,
        exists: bool,
        txid: u32,
    ) -> Result<(usize, Option<PendingExtensionConfig>), SqlError> {
        self.change_extension_config_with_ordinal(
            extension, relation, condition, exists, None, txid,
        )
    }

    pub(crate) fn replay_extension_config(
        &self,
        extension: usize,
        relation: ExtensionConfigRelation,
        condition: ExtensionConfigCondition,
        exists: bool,
        ordinal: u16,
    ) -> Result<(usize, Option<PendingExtensionConfig>), SqlError> {
        self.change_extension_config_with_ordinal(
            extension,
            relation,
            condition,
            exists,
            Some(ordinal),
            0,
        )
    }

    fn change_extension_config_with_ordinal(
        &self,
        extension: usize,
        relation: ExtensionConfigRelation,
        condition: ExtensionConfigCondition,
        exists: bool,
        recovered_ordinal: Option<u16>,
        txid: u32,
    ) -> Result<(usize, Option<PendingExtensionConfig>), SqlError> {
        let object = relation.access_object();
        if !self.access_object_visible_to(object, txid) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "extension configuration relation does not exist"
            ));
        }
        let mut catalog = self.extension_catalog();
        if !catalog.definitions[extension].visible_to(txid) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "extension does not exist"
            ));
        }
        if exists && Self::extension_member_of_in(&catalog, object, txid) != Some(extension) {
            drop(catalog);
            let (_, name) = self.access_object_name_to(object, txid);
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "table \"{}\" is not a member of the extension being created",
                name.as_str()
            ));
        }
        let existing = catalog.configs.iter().position(|config| {
            config.extension as usize == extension
                && config.relation == relation
                && (config.live || config.pending.is_some())
        });
        let slot = if let Some(slot) = existing {
            slot
        } else {
            if !exists {
                return Err(sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "relation is not an extension configuration relation"
                ));
            }
            catalog
                .configs
                .iter()
                .position(|config| !config.live && config.pending.is_none())
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many extension configuration relations (limit {})",
                        catalog.configs.len()
                    )
                })?
        };
        if let Some(pending) = catalog.configs[slot].pending
            && pending.txid != txid
        {
            let name = catalog.definitions[extension].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, name.as_str()));
        }
        let prior = catalog.configs[slot].pending;
        if existing.is_none() {
            let ordinal = if let Some(ordinal) = recovered_ordinal {
                if catalog.configs.iter().any(|config| {
                    config.extension as usize == extension
                        && (config.live || config.pending.is_some())
                        && config.ordinal == ordinal
                }) {
                    return Err(sql_err!(
                        sqlstate::DATA_EXCEPTION,
                        "duplicate extension configuration ordinal"
                    ));
                }
                ordinal
            } else {
                catalog
                    .configs
                    .iter()
                    .filter(|config| {
                        config.extension as usize == extension
                            && (config.live || config.pending.is_some())
                    })
                    .map(|config| config.ordinal)
                    .max()
                    .map_or(0, |ordinal| ordinal.saturating_add(1))
            };
            catalog.configs[slot].extension = extension as u16;
            catalog.configs[slot].ordinal = ordinal;
            catalog.configs[slot].relation = relation;
        } else if let Some(ordinal) = recovered_ordinal
            && catalog.configs[slot].ordinal != ordinal
        {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "extension configuration ordinal changed during recovery"
            ));
        }
        catalog.configs[slot].pending = Some(PendingExtensionConfig {
            txid,
            exists,
            condition,
        });
        Ok((slot, prior))
    }

    pub(crate) fn commit_extension_config(&self, slot: usize, txid: u32) {
        let mut catalog = self.extension_catalog();
        let config = &mut catalog.configs[slot];
        if let Some(pending) = config.pending
            && pending.txid == txid
        {
            config.live = pending.exists;
            config.condition = pending.condition;
            config.pending = None;
            if !config.live {
                *config = ExtensionConfig::EMPTY;
            }
        }
    }

    pub(crate) fn rollback_extension_config(
        &self,
        slot: usize,
        prior: Option<PendingExtensionConfig>,
    ) {
        let mut catalog = self.extension_catalog();
        catalog.configs[slot].pending = prior;
        if !catalog.configs[slot].live && prior.is_none() {
            catalog.configs[slot] = ExtensionConfig::EMPTY;
        }
    }

    fn clear_extension_configs_for_in(catalog: &mut ExtensionCatalog, extension: usize) {
        for config in catalog.configs.iter_mut() {
            if config.extension as usize == extension {
                *config = ExtensionConfig::EMPTY;
            }
        }
    }

    /// Computes the effective path a raw `search_path` value denotes for this
    /// session: `"$user"` becomes the session user, missing schemas are
    /// skipped (PostgreSQL validates lazily, not at SET), and `pg_catalog` is
    /// implicit first unless the path places it explicitly.
    pub fn compute_path(&self, raw: &str, user: &str, txid: u32) -> PathContext {
        assert!(
            raw.len() <= crate::sql::guc::SEARCH_PATH_BYTES,
            "search path passed to resolution has already crossed its GUC boundary"
        );
        let mut entries = [PathEntry::Catalog; MAX_PATH_ENTRIES];
        let mut n = 0;
        let mut explicit_catalog = false;
        let mut name_buf = [0u8; 63];
        // Elements split on commas outside double quotes (the stored form is
        // canonical: only double-quoted elements may embed commas).
        let mut rest = raw.trim();
        while !rest.is_empty() {
            let mut in_quotes = false;
            let mut split = rest.len();
            for (i, c) in rest.char_indices() {
                match c {
                    '"' => in_quotes = !in_quotes,
                    ',' if !in_quotes => {
                        split = i;
                        break;
                    }
                    _ => {}
                }
            }
            let element = rest[..split].trim();
            rest = rest.get(split + 1..).unwrap_or("").trim_start();
            if element.is_empty() {
                continue;
            }
            // Unquote a `"quoted name"` element ("" is an embedded quote).
            let name: &str = if element.starts_with('"') {
                let inner = element.trim_matches('"');
                let mut len = 0;
                let mut bytes = inner.bytes().peekable();
                while let Some(b) = bytes.next() {
                    if len == name_buf.len() {
                        break;
                    }
                    name_buf[len] = b;
                    len += 1;
                    if b == b'"' {
                        // "" collapses to one quote.
                        bytes.next();
                    }
                }
                core::str::from_utf8(&name_buf[..len]).unwrap_or(inner)
            } else {
                element
            };
            let name = if name == "$user" { user } else { name };
            if name == "pg_catalog" {
                if !explicit_catalog {
                    assert!(n < MAX_PATH_ENTRIES, "bounded search path fits resolver");
                    entries[n] = PathEntry::Catalog;
                    n += 1;
                    explicit_catalog = true;
                }
                continue;
            }
            if let Some(slot) = self.find_schema_visible(name, txid) {
                let entry = PathEntry::Schema(slot as u16);
                if !entries[..n].contains(&entry) {
                    assert!(n < MAX_PATH_ENTRIES, "bounded search path fits resolver");
                    entries[n] = entry;
                    n += 1;
                }
            }
        }
        if !explicit_catalog {
            assert!(n < MAX_PATH_ENTRIES, "bounded search path fits resolver");
            // Implicit pg_catalog precedes everything, as PostgreSQL has it.
            let mut shifted = [PathEntry::Catalog; MAX_PATH_ENTRIES];
            shifted[1..=n].copy_from_slice(&entries[..n]);
            return PathContext {
                entries: shifted,
                n: n + 1,
                explicit_catalog: false,
            };
        }
        PathContext {
            entries,
            n,
            explicit_catalog: true,
        }
    }

    pub fn path(&self) -> PathContext {
        execution_path()
    }

    /// Installs the running statement's path, returning the previous one so a
    /// nested resolution context (a view body under its creator's path) can
    /// restore it.
    pub fn swap_path(&self, path: PathContext) -> PathContext {
        replace_execution_path(path)
    }

    /// Resolves a possibly-qualified relation name under the current path.
    /// `None` means no visible relation matches (the caller owns the 42P01
    /// wording, which differs between qualified and bare spellings).
    pub fn resolve_relation(
        &self,
        qualifier: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<ResolvedRelation> {
        let path = self.path();
        self.resolve_relation_under(&path, qualifier, name, txid)
    }

    /// [`Self::resolve_relation`] under an explicit path — a view body
    /// resolves under its creator's path, not the running statement's.
    pub fn resolve_relation_under(
        &self,
        path: &PathContext,
        qualifier: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<ResolvedRelation> {
        if crate::sql::catalog::is_catalog_relation(qualifier, name) {
            return Some(ResolvedRelation::Catalog);
        }
        if let Some(schema) = qualifier {
            if schema == "pg_temp" {
                return self
                    .temporary_schema()
                    .ok()
                    .and_then(|schema| self.relation_in(schema.as_str(), name, txid));
            }
            if schema.starts_with("pg_temp_") && !self.is_current_temporary_schema(schema) {
                return None;
            }
            return self.relation_in(schema, name, txid);
        }
        if let Ok(schema) = self.temporary_schema()
            && let Some(found) = self.relation_in(schema.as_str(), name, txid)
        {
            return Some(found);
        }
        for entry in path.entries() {
            match entry {
                PathEntry::Catalog => {
                    if crate::sql::catalog::is_catalog_relation(None, name) {
                        return Some(ResolvedRelation::Catalog);
                    }
                }
                PathEntry::Schema(slot) => {
                    let schema_name = self.schema_def(*slot as usize).name;
                    if let Some(found) = self.relation_in(schema_name.as_str(), name, txid) {
                        return Some(found);
                    }
                }
            }
        }
        None
    }

    pub(crate) fn schema_is_on_path(&self, schema: SqlName) -> bool {
        self.path().entries().iter().any(|entry| {
            matches!(entry, PathEntry::Schema(slot) if self.schema_def(*slot as usize).name == schema)
        })
    }

    fn relation_in(&self, schema: &str, name: &str, txid: u32) -> Option<ResolvedRelation> {
        if let Some(t) = self.find_visible(schema, name, txid) {
            if self.table_def(t, txid).persistence == RelationPersistence::Temporary {
                self.mark_temporary_transaction(txid);
            }
            return Some(ResolvedRelation::Table(t));
        }
        let view = self.view_rule_catalog().views.iter().position(|v| {
            v.database == current_database()
                && v.visible_to(txid)
                && v.schema_for(txid).as_str() == schema
                && v.name_for(txid).as_str() == name
        });
        if let Some(slot) = view
            && self.view(slot).persistence == RelationPersistence::Temporary
        {
            self.mark_temporary_transaction(txid);
        }
        view.map(ResolvedRelation::View)
    }

    /// The kind of a relation named `name` in `schema` (visible to `txid`), or
    /// `None` if no relation of that name exists there. A materialized view
    /// shares its backing table's slot, so it is tested before a plain table.
    fn non_index_relation_kind_in(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Option<StoredRelKind> {
        if self.find_matview(schema, name, txid).is_some() {
            return Some(StoredRelKind::Matview);
        }
        if let Some(slot) = self.find_visible(schema, name, txid) {
            return Some(if self.table_def(slot, txid).kind == TableKind::Foreign {
                StoredRelKind::ForeignTable
            } else {
                StoredRelKind::Table
            });
        }
        if self.find_view(schema, name, txid).is_some() {
            return Some(StoredRelKind::View);
        }
        if self.find_sequence(schema, name, txid).is_some() {
            return Some(StoredRelKind::Sequence);
        }
        None
    }

    pub fn relation_kind_in(&self, schema: &str, name: &str, txid: u32) -> Option<StoredRelKind> {
        if let Some(kind) = self.non_index_relation_kind_in(schema, name, txid) {
            return Some(kind);
        }
        if self.index_catalog().iter().any(|i| {
            i.database == current_database()
                && i.visible_to(txid)
                && i.schema.as_str() == schema
                && i.name_for(txid).as_str() == name
        }) {
            return Some(StoredRelKind::Index);
        }
        None
    }

    /// Resolves a possibly-qualified relation name to `(schema, kind)` under the
    /// current path, for `COMMENT ON`. PostgreSQL binds the name to the first
    /// schema on the path that holds *any* relation of that name, then checks
    /// the kind — so this returns that first match regardless of kind.
    pub fn classify_relation(
        &self,
        qualifier: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<(SqlName, StoredRelKind)> {
        if let Some(schema) = qualifier {
            if schema == "pg_temp" {
                let temporary = self.temporary_schema().ok()?;
                return self
                    .relation_kind_in(temporary.as_str(), name, txid)
                    .map(|kind| (temporary, kind));
            }
            if schema.starts_with("pg_temp_") && !self.is_current_temporary_schema(schema) {
                return None;
            }
            return self
                .relation_kind_in(schema, name, txid)
                .map(|k| (SqlName::parse(schema).unwrap_or(SqlName::EMPTY), k));
        }
        if let Ok(temporary) = self.temporary_schema()
            && let Some(kind) = self.relation_kind_in(temporary.as_str(), name, txid)
        {
            return Some((temporary, kind));
        }
        for entry in self.path().entries() {
            if let PathEntry::Schema(slot) = entry {
                let schema_name = self.schema_def(*slot as usize).name;
                if let Some(k) = self.relation_kind_in(schema_name.as_str(), name, txid) {
                    return Some((schema_name, k));
                }
            }
        }
        None
    }

    /// The 1-based column number of `column` in the relation at `table_slot`, or
    /// `None` if the relation has no such column.
    pub fn column_number(&self, table_slot: usize, column: &str, txid: u32) -> Option<u32> {
        let def = self.table_def(table_slot, txid);
        def.columns()
            .iter()
            .position(|c| c.name.as_str() == column)
            .map(|i| i as u32 + 1)
    }

    /// The schema a new relation lands in: the qualifier if it names a
    /// visible schema, else the first schema of the path. `relation` is only
    /// for the error message.
    pub fn creation_schema(
        &self,
        qualifier: Option<&str>,
        relation: &str,
        txid: u32,
    ) -> Result<SqlName, SqlError> {
        if let Some(schema) = qualifier {
            if schema == "pg_catalog" || schema == "information_schema" {
                return Err(sql_err!(
                    crate::sql::eval::sqlstate::INSUFFICIENT_PRIVILEGE,
                    "permission denied to create \"{}.{}\"",
                    schema,
                    relation
                ));
            }
            if self.find_schema_visible(schema, txid).is_none() {
                return Err(sql_err!(
                    sqlstate::INVALID_SCHEMA_NAME,
                    "schema \"{}\" does not exist",
                    schema
                ));
            }
            return SqlName::parse(schema);
        }
        // An explicit pg_catalog at the head of the path is the creation
        // target, which PostgreSQL then refuses.
        let path = self.path();
        if path.explicit_catalog && path.entries().first() == Some(&PathEntry::Catalog) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INSUFFICIENT_PRIVILEGE,
                "permission denied to create \"pg_catalog.{}\"",
                relation
            ));
        }
        let Some(slot) = path.first_schema() else {
            return Err(sql_err!(
                sqlstate::INVALID_SCHEMA_NAME,
                "no schema has been selected to create in"
            ));
        };
        Ok(self.schema_def(slot as usize).name)
    }

    /// Live SQL tables with their slot indices, excluding internal storage.
    pub fn live_tables(&self) -> impl Iterator<Item = (usize, &Table)> {
        self.tables.iter().enumerate().filter(|(slot, table)| {
            *slot != self.large_object_page_table()
                && table.database == current_database()
                && table.live
        })
    }

    /// Floors every serial column's sequence at the maximum value stored in
    /// its rows. Run once after recovery: a journal or checkpoint written
    /// before sequences were journaled carries no positions, and handing out
    /// a value at or below an existing row's would violate the key.
    pub fn reconcile_serials(&mut self) {
        for i in 0..self.tables.len() {
            if !self.tables[i].live {
                continue;
            }
            let n_columns = self.tables[i].def.n_columns;
            let mut auto = [false; MAX_COLUMNS];
            let mut any = false;
            for (c, slot) in auto.iter_mut().enumerate().take(n_columns) {
                *slot = self.tables[i].def.columns()[c].auto_increment;
                any |= *slot;
            }
            if !any {
                continue;
            }
            let mut schema = [crate::sql::types::ColType::Bool; MAX_COLUMNS];
            self.tables[i].def.schema(&mut schema);
            let mut max = [0i64; MAX_COLUMNS];
            let mut rowids: Vec<(u64, RowHome)> = Vec::new();
            for (rowid, state) in self.resident_rows(i).iter() {
                if let Some(home) = state.visible_at(0, SNAPSHOT_ALL, u64::MAX).flatten() {
                    rowids.push((rowid, home));
                }
            }
            for (rowid, home) in rowids {
                let mut vals = [0i64; MAX_COLUMNS];
                let mut have = [false; MAX_COLUMNS];
                self.with_row_bytes(i, rowid, home, |bytes| {
                    let mut row = [crate::sql::types::Datum::Null; MAX_COLUMNS];
                    if rowenc::decode(bytes, &schema[..n_columns], &mut row).is_err() {
                        return Ok(());
                    }
                    for c in 0..n_columns {
                        if !auto[c] {
                            continue;
                        }
                        let v = match row[c] {
                            crate::sql::types::Datum::Int2(x) => i64::from(x),
                            crate::sql::types::Datum::Int4(x) => i64::from(x),
                            crate::sql::types::Datum::Int8(x) => x,
                            _ => continue,
                        };
                        vals[c] = v;
                        have[c] = true;
                    }
                    Ok(())
                })
                .unwrap_or(());
                for c in 0..n_columns {
                    if have[c] {
                        max[c] = max[c].max(vals[c]);
                    }
                }
            }
            for c in 0..n_columns {
                if auto[c] {
                    let prior = self.table_serial_value(i, c);
                    self.replay_table_serial_value(i, c, prior.max(max[c]), 0)
                        .expect("recovered serial column exists");
                }
            }
        }
    }

    /// Attaches the spilled-row read path. The local temporary store is always
    /// present; its durable block stack is optional.
    pub(crate) fn attach_spill(&mut self, reader: SpillReader) {
        self.spill = Some(reader);
    }

    pub fn spill_attached(&self) -> bool {
        self.spill
            .as_ref()
            .is_some_and(|reader| reader.blocks.is_some())
    }

    /// Cumulative traffic through the provider-neutral block stack.
    ///
    /// A database without object storage has no spill stack and therefore
    /// reports zeros. Callers compare snapshots around an operation; the
    /// counters themselves are deliberately process-local observability.
    pub(crate) fn block_io_stats(&self) -> crate::store::BlockIoStats {
        self.spill
            .as_ref()
            .and_then(|reader| reader.blocks.as_ref())
            .map(|blocks| blocks.lock().expect("block store lock poisoned").io_stats())
            .unwrap_or_default()
    }

    /// Leases one startup-sized external-run producer. A nested materializer
    /// gets a distinct producer instead of resetting an outer run in progress.
    pub(crate) fn external_sorter(
        &self,
    ) -> Result<
        std::sync::MutexGuard<'_, Box<crate::sql::external::ExternalSorter>>,
        crate::sql::eval::SqlError,
    > {
        let Some(spill) = self.spill.as_ref().filter(|spill| spill.blocks.is_some()) else {
            return Err(crate::sql_err!(
                crate::sql::eval::sqlstate::FEATURE_NOT_SUPPORTED,
                "external query runs require durable object storage"
            ));
        };
        if let Some(lease) = try_mutex_pool(&spill.external_sorters, "external sorter") {
            return Ok(lease);
        }
        Err(crate::sql_err!(
            crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "external query run producer pool exhausted (maximum nesting {})",
            EXTERNAL_RUN_CONTEXTS
        ))
    }

    /// Leases one independent immutable-run cursor. Exhaustion is loud instead
    /// of aliasing scratch across nested materializers.
    pub(crate) fn external_run_reader(
        &self,
    ) -> Result<
        std::sync::MutexGuard<'_, crate::sql::external::ExternalRunReader>,
        crate::sql::eval::SqlError,
    > {
        let Some(spill) = self.spill.as_ref().filter(|spill| spill.blocks.is_some()) else {
            return Err(crate::sql_err!(
                crate::sql::eval::sqlstate::FEATURE_NOT_SUPPORTED,
                "external query runs require durable object storage"
            ));
        };
        for reader in spill.external_readers.iter() {
            match reader.try_lock() {
                Ok(lease) => return Ok(lease),
                Err(std::sync::TryLockError::WouldBlock) => {}
                Err(std::sync::TryLockError::Poisoned(error)) => {
                    panic!("external run reader lock poisoned: {error}")
                }
            }
        }
        Err(crate::sql_err!(
            crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
            "external query run reader pool exhausted (maximum nesting {})",
            EXTERNAL_RUN_CONTEXTS
        ))
    }

    /// Returns an owned capability for consuming immutable external runs
    /// without retaining an immutable borrow of the mutable database state.
    pub(crate) fn external_run_access(
        &self,
    ) -> Result<ExternalRunAccess, crate::sql::eval::SqlError> {
        let Some(spill) = self.spill.as_ref().filter(|spill| spill.blocks.is_some()) else {
            return Err(crate::sql_err!(
                crate::sql::eval::sqlstate::FEATURE_NOT_SUPPORTED,
                "external query runs require durable object storage"
            ));
        };
        let blocks = spill.blocks.as_ref().expect("filtered above");
        Ok(ExternalRunAccess {
            blocks: std::sync::Arc::as_ptr(blocks),
            readers: std::sync::Arc::as_ptr(&spill.external_readers),
        })
    }

    /// Runs one short operation against the provider-neutral tiered block
    /// stack. The borrow must not cross a source-row callback: a spilled scan
    /// releases its own block context before invoking that callback precisely
    /// so execution work can issue nested reads or writes here.
    pub(crate) fn with_block_store<R>(
        &self,
        operation: impl FnOnce(&mut dyn crate::store::BlockStore) -> R,
    ) -> Option<R> {
        let reader = self.spill.as_ref()?;
        let mut blocks = reader
            .blocks
            .as_ref()?
            .lock()
            .expect("block store lock poisoned");
        Some(operation(&mut *blocks))
    }

    /// Number of immutable row generations currently backing a table.
    pub(crate) fn spill_generation_count(&self, table_slot: usize) -> usize {
        self.tables[table_slot].n_spill_ssts
    }

    /// The bytes of a visible row, wherever they live: a heap row borrows the
    /// heap directly; a spilled row is fetched through the cache tiers into
    /// `arena`. The two lifetimes unify, so call sites keep their shapes.
    /// The merged walk behind the row-state seam: every SST-resident rowid
    /// of `slot`'s spill list that no map entry shadows, in ascending rowid
    /// order — the newest member's verdict wins a rowid, and a tombstone
    /// verdict suppresses it. Cursors keep one resident data block per
    /// member (leased from the spill reader's context pool), advancing
    /// through the sparse index; only keys are parsed here — row bytes are
    /// fetched later, by `row_bytes`, exactly as for any spilled row.
    fn spill_merged_walk(
        &self,
        slot: usize,
        emit: &mut dyn FnMut(u64, u32, u32, u64) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<(), SqlError> {
        let table = &self.tables[slot];
        let n = table.n_spill_ssts;
        if n == 0 {
            return Ok(());
        }
        let Some(spill) = &self.spill else {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "table has spill SSTs but no spill reader is attached"
            ));
        };
        let walk_id = spill.next_walk_id();
        let Some(mut cursor_lease) = try_mutex_pool(&spill.cursor_contexts, "spill cursor") else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "row-state cursor nesting exceeds the statement-list boundary"
            ));
        };
        cursor_lease.fill(MemberCursor::EMPTY);
        let cursors: &mut [MemberCursor] = &mut cursor_lease;
        {
            let Some(mut context) = try_mutex_pool(&spill.scan_contexts, "spill scan context")
            else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "row-state block context is already in use"
                ));
            };
            context.owner = walk_id;
            context.pax_values_owner = None;
            for (member, cursor) in cursors[..n].iter_mut().enumerate() {
                Self::cursor_advance(spill, table, member, cursor, &mut context)?;
            }
        }
        loop {
            let mut min: Option<u64> = None;
            for cursor in cursors[..n].iter() {
                if let Some((key, ..)) = cursor.head {
                    min = Some(min.map_or(key.rowid, |rowid: u64| rowid.min(key.rowid)));
                }
            }
            let Some(rowid) = min else { return Ok(()) };
            let Some(mut context) = try_mutex_pool(&spill.scan_contexts, "spill scan context")
            else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "row-state block context is already in use"
                ));
            };
            if context.owner != walk_id {
                // A nested walk ran while this walk's row callback was active
                // and reused the buffers. Parsed heads are owned values and
                // remain valid; only buffer-residency claims are stale.
                for cursor in &mut cursors[..n] {
                    cursor.loaded = None;
                    cursor.loaded_len = 0;
                    cursor.loaded_type = None;
                }
                context.owner = walk_id;
                context.pax_values_owner = None;
            }
            // Consume every version of this row from every member. The
            // greatest commit LSN admitted by the statement snapshot wins;
            // equal keys prefer the newer list member.
            let mut verdict: Option<SpillVersion> = None;
            for (member, cursor) in cursors[..n].iter_mut().enumerate() {
                while let Some((key, tombstone, len)) = cursor.head
                    && key.rowid == rowid
                {
                    if key.commit_lsn <= self.commit_snapshot()
                        && verdict.is_none_or(|current| {
                            key.commit_lsn > current.commit_lsn
                                || (key.commit_lsn == current.commit_lsn
                                    && member as u32 > current.member)
                        })
                    {
                        verdict = Some(SpillVersion {
                            len: (!tombstone).then_some(len),
                            member: member as u32,
                            commit_lsn: key.commit_lsn,
                        });
                    }
                    Self::cursor_advance(spill, table, member, cursor, &mut context)?;
                }
            }
            drop(context);
            if let Some(SpillVersion {
                len: Some(len),
                member,
                commit_lsn,
            }) = verdict
                && self.tables[slot].rows.get(&rowid).is_none()
                && emit(rowid, len, member, commit_lsn)?.is_break()
            {
                return Ok(());
            }
        }
    }

    /// The payload-carrying form of [`Self::spill_merged_walk`]. A sequential
    /// scan already has the winning entry's data block resident while it
    /// merges versions. Copying that entry into statement storage before the
    /// cursor advances avoids turning every row in the block into a second
    /// SST point lookup. The context is released before `emit`, so nested
    /// execution still uses the normal bounded reader pool.
    #[expect(clippy::too_many_arguments, reason = "merged row decoder state")]
    fn spill_merged_walk_bytes<'a>(
        &self,
        slot: usize,
        arena: &'a crate::mem::arena::Arena,
        recycle_rows: bool,
        decoded_columns: Option<&[bool; MAX_COLUMNS]>,
        coalesce_packed: bool,
        overlay_mode: SpillOverlayMode,
        resume: Option<(&mut [MemberCursor], &mut u64, &mut usize, usize, u64)>,
        emit: &mut dyn FnMut(
            u64,
            u64,
            SpilledRowRepresentation<'a>,
        ) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[slot];
        let n = table.n_spill_ssts;
        if n == 0 {
            return Ok(true);
        }
        let Some(spill) = &self.spill else {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "table has spill SSTs but no spill reader is attached"
            ));
        };
        let mut cursor_lease;
        let mut local_walk_id = 0;
        let mut local_initialized = 0;
        let (cursors, walk_id, initialized, max_rows, max_object_gets) =
            if let Some((cursors, walk_id, initialized, max_rows, max_object_gets)) = resume {
                if cursors.len() < n {
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "checkpoint spill cursor has {} members for {} generations",
                        cursors.len(),
                        n
                    ));
                }
                (cursors, walk_id, initialized, max_rows, max_object_gets)
            } else {
                cursor_lease = Some(
                    try_mutex_pool(&spill.cursor_contexts, "spill cursor").ok_or_else(|| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "row-state cursor nesting exceeds the statement-list boundary"
                        )
                    })?,
                );
                (
                    &mut ***cursor_lease.as_mut().expect("installed cursor lease"),
                    &mut local_walk_id,
                    &mut local_initialized,
                    usize::MAX,
                    u64::MAX,
                )
            };
        if *walk_id == 0 {
            *walk_id = spill.next_walk_id();
            cursors.fill(MemberCursor::EMPTY);
            *initialized = 0;
        }
        let io_before = self.block_io_stats();
        if *initialized < n {
            let Some(mut context) = try_mutex_pool(&spill.scan_contexts, "spill scan context")
            else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "row-state block context is already in use"
                ));
            };
            if context.owner != *walk_id {
                for cursor in &mut cursors[..*initialized] {
                    cursor.loaded = None;
                    cursor.loaded_len = 0;
                    cursor.loaded_type = None;
                    cursor.pax_layout = None;
                }
            }
            context.owner = *walk_id;
            context.pax_values_owner = None;
            while *initialized < n {
                Self::cursor_advance(
                    spill,
                    table,
                    *initialized,
                    &mut cursors[*initialized],
                    &mut context,
                )?;
                *initialized += 1;
                if self.block_io_stats().saturating_sub(io_before).object_gets >= max_object_gets {
                    return Ok(false);
                }
            }
        }
        let mut walked = 0usize;
        loop {
            if walked == max_rows {
                return Ok(false);
            }
            let mark = recycle_rows.then(|| arena.mark());
            let mut min: Option<u64> = None;
            for cursor in cursors[..n].iter() {
                if let Some((key, ..)) = cursor.head {
                    min = Some(min.map_or(key.rowid, |rowid: u64| rowid.min(key.rowid)));
                }
            }
            let Some(rowid) = min else { return Ok(true) };
            walked += 1;
            let Some(mut context) = try_mutex_pool(&spill.scan_contexts, "spill scan context")
            else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "row-state block context is already in use"
                ));
            };
            if context.owner != *walk_id {
                // Heads and logical next positions are owned cursor state.
                // Only their claims on the shared block buffers are stale.
                for cursor in &mut cursors[..n] {
                    cursor.loaded = None;
                    cursor.loaded_len = 0;
                    cursor.loaded_type = None;
                    cursor.pax_layout = None;
                }
                context.owner = *walk_id;
                context.pax_values_owner = None;
            }
            let mut verdict: Option<SpillVersion> = None;
            for (member, cursor) in cursors[..n].iter().enumerate() {
                if let Some((key, tombstone, len)) = cursor.head
                    && key.rowid == rowid
                    && key.commit_lsn <= self.commit_snapshot()
                    && verdict.is_none_or(|current| {
                        key.commit_lsn > current.commit_lsn
                            || (key.commit_lsn == current.commit_lsn
                                && member as u32 > current.member)
                    })
                {
                    verdict = Some(SpillVersion {
                        len: (!tombstone).then_some(len),
                        member: member as u32,
                        commit_lsn: key.commit_lsn,
                    });
                }
            }
            let representation = if let Some(SpillVersion {
                len: Some(len),
                member,
                commit_lsn,
            }) = verdict
                && match overlay_mode {
                    SpillOverlayMode::VisibleScan => self.tables[slot]
                        .rows
                        .get(&rowid)
                        .is_none_or(|state| Self::redundant_spilled_row_state(&state)),
                    SpillOverlayMode::CommittedCheckpoint => {
                        self.tables[slot].rows.get(&rowid).is_none_or(|state| {
                            matches!(
                                state.committed,
                                Some(RowHome::Spilled {
                                    commit_lsn: current,
                                    ..
                                }) if current == commit_lsn
                            )
                        })
                    }
                } {
                let cursor = &mut cursors[member as usize];
                let (key, tombstone, _copied) = cursor.head.ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "selected spill version has no resident cursor head"
                    )
                })?;
                if cursor.loaded != Some(cursor.ordinal) {
                    let expected = cursor.head;
                    cursor.offset = cursor.head_offset;
                    cursor.raw_row = cursor.head_raw_row;
                    cursor.head = None;
                    Self::cursor_advance(spill, table, member as usize, cursor, &mut context)?;
                    if cursor.head != expected {
                        return Err(sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "reloaded spill cursor head does not match its retained version"
                        ));
                    }
                }
                let representation = if cursor.loaded_type
                    == Some(crate::store::BlockType::SstDataPaxV2)
                {
                    let layout = cursor.pax_layout.ok_or_else(|| {
                        sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "PAX descriptor has no validated layout"
                        )
                    })?;
                    let owner = (member as usize, cursor.ordinal);
                    if context.pax_values_owner != Some(owner) {
                        let ScanContext {
                            member_blocks,
                            member_raw_blocks,
                            pax_column_buf,
                            pax_values_buf,
                            pax_value_extents,
                            pax_values_owner,
                            pax_row_buf,
                            ..
                        } = &mut *context;
                        let mut blocks = spill.relation_blocks(table);
                        let mut at = 0usize;
                        let mut loaded_container = None;
                        pax_value_extents.fill(None);
                        for column in 0..layout.columns() {
                            if decoded_columns.is_some_and(|columns| !columns[column]) {
                                continue;
                            }
                            let reference = layout
                                .column_ref(
                                    &member_raw_blocks[member as usize][..cursor.raw_len],
                                    column,
                                )
                                .map_err(spill_read_error)?;
                            let (len, block_type) = match reference {
                                crate::store::DataBlockRef::Packed {
                                    container,
                                    offset,
                                    length,
                                    id,
                                } if coalesce_packed => {
                                    let container_len = if let Some((loaded, len)) =
                                        loaded_container
                                        && loaded == container
                                    {
                                        len
                                    } else {
                                        let (len, block_type) = blocks
                                            .get(&container, pax_column_buf)
                                            .map_err(|error| {
                                                spill_read_error(crate::store::SstError::Store(
                                                    error,
                                                ))
                                            })?;
                                        if block_type
                                            != crate::store::BlockType::SstPackedContainerV1
                                        {
                                            return Err(sql_err!(
                                                sqlstate::INTERNAL_ERROR,
                                                "PAX column container has the wrong block type"
                                            ));
                                        }
                                        loaded_container = Some((container, len));
                                        len
                                    };
                                    crate::store::decode_packed_extent(
                                        &pax_column_buf[..container_len],
                                        offset as usize,
                                        length as usize,
                                        &id,
                                        &mut member_blocks[member as usize],
                                    )
                                    .map_err(|error| {
                                        spill_read_error(crate::store::SstError::Store(error))
                                    })?
                                }
                                _ => crate::store::read_data_block_raw_ref(
                                    &mut *blocks,
                                    reference,
                                    &mut member_blocks[member as usize],
                                    pax_column_buf,
                                )
                                .map_err(spill_read_error)?,
                            };
                            if block_type != crate::store::BlockType::SstDataPaxColumnV1 {
                                return Err(sql_err!(
                                    sqlstate::INTERNAL_ERROR,
                                    "PAX descriptor column reference has the wrong block type"
                                ));
                            }
                            let end = at.checked_add(len).ok_or_else(|| {
                                sql_err!(sqlstate::INTERNAL_ERROR, "PAX extent length overflows")
                            })?;
                            if end > pax_values_buf.len() {
                                return Err(sql_err!(
                                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                                    "PAX column extents exceed the fixed scan vector buffer"
                                ));
                            }
                            pax_values_buf[at..end]
                                .copy_from_slice(&member_blocks[member as usize][..len]);
                            pax_value_extents[column] = Some((at, end));
                            at = end;
                        }
                        *pax_values_owner = Some(owner);
                        let _ = (member_raw_blocks, pax_row_buf);
                    }
                    let encoded_len = {
                        let ScanContext {
                            member_raw_blocks,
                            pax_values_buf,
                            pax_value_extents,
                            pax_row_buf,
                            ..
                        } = &mut *context;
                        crate::store::copy_pax_v2_row_from_extents(
                            &layout,
                            &member_raw_blocks[member as usize][..cursor.raw_len],
                            cursor.head_raw_row,
                            decoded_columns,
                            pax_values_buf,
                            pax_value_extents,
                            pax_row_buf,
                        )
                        .map_err(spill_read_error)?
                    };
                    if decoded_columns.is_none() && encoded_len != len as usize {
                        return Err(sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "PAX descriptor row length does not match its cursor header"
                        ));
                    }
                    let mut schema = [ColType::Bool; MAX_COLUMNS];
                    table.def.schema(&mut schema);
                    let encoded = arena.alloc_slice_with(encoded_len, |_| 0u8).map_err(|_| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "spilled PAX rows exceed the statement arena; raise work_arena_bytes"
                        )
                    })?;
                    encoded.copy_from_slice(&context.pax_row_buf[..encoded_len]);
                    let values = arena
                        .alloc_slice_with(layout.columns(), |_| Datum::Null)
                        .map_err(|_| {
                            sql_err!(
                                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                                "spilled PAX values exceed the statement arena; raise work_arena_bytes"
                            )
                        })?;
                    rowenc::decode(encoded, &schema[..layout.columns()], values).map_err(
                        |error| SqlError {
                            sqlstate: error.sqlstate,
                            message: stack_format!(
                                192,
                                "spilled PAX row {} failed to decode: {}",
                                rowid,
                                error.message.as_str()
                            ),
                        },
                    )?;
                    SpilledRowRepresentation::Values(&*values)
                } else {
                    let output = arena.alloc_slice_with(len as usize, |_| 0u8).map_err(|_| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "spilled scan rows exceed the statement arena; raise work_arena_bytes"
                        )
                    })?;
                    let (copied_key, copied_tombstone, copied) = {
                        let mut blocks = spill.relation_blocks(table);
                        crate::store::copy_block_entry_at(
                            &mut *blocks,
                            &context.member_blocks[member as usize][..cursor.loaded_len],
                            cursor.head_offset,
                            output,
                        )
                        .map_err(spill_read_error)?
                    };
                    if copied_key != key || copied_tombstone != tombstone {
                        return Err(sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "merged spill cursor payload does not match its selected version"
                        ));
                    }
                    if copied != len as usize {
                        return Err(sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "merged spill cursor payload length does not match its selected version"
                        ));
                    }
                    SpilledRowRepresentation::Encoded(&*output)
                };
                if tombstone || key.rowid != rowid || key.commit_lsn != commit_lsn {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "merged spill cursor payload does not match its selected version"
                    ));
                }
                Some((commit_lsn, representation))
            } else {
                None
            };
            for (member, cursor) in cursors[..n].iter_mut().enumerate() {
                while cursor.head.is_some_and(|(key, ..)| key.rowid == rowid) {
                    Self::cursor_advance(spill, table, member, cursor, &mut context)?;
                }
            }
            drop(context);
            let emitted = if let Some((commit_lsn, representation)) = representation {
                emit(rowid, commit_lsn, representation)
            } else {
                Ok(core::ops::ControlFlow::Continue(()))
            };
            if let Some(mark) = mark {
                // SAFETY: recycling callers consume the copied row and all
                // values derived from it synchronously in `emit`.
                unsafe { arena.rewind_to(mark) };
            }
            if emitted?.is_break() {
                return Ok(false);
            }
            if self.block_io_stats().saturating_sub(io_before).object_gets >= max_object_gets {
                return Ok(false);
            }
        }
    }

    /// Streams spill rows in bounded batches with bytes carried by the merged
    /// cursor. Mutable overlay rows stay in the row-state seam; redundant
    /// committed spill metadata does not force a second object read.
    pub(crate) fn for_each_spilled_row_batch<'a, 'callback>(
        &self,
        table_slot: usize,
        arena: &'a crate::mem::arena::Arena,
        recycle_rows: bool,
        decoded_columns: Option<u64>,
        each: &mut SpilledRowBatchVisitor<'a, 'callback>,
    ) -> Result<(), SqlError> {
        let decoded_columns = decoded_columns.map(|mask| {
            core::array::from_fn(|column| {
                column < u64::BITS as usize && mask & (1u64 << column) != 0
            })
        });
        let rows = arena
            .alloc_slice_with(SPILL_SCAN_BATCH_ROWS, |_| SpilledRow {
                rowid: 0,
                representation: SpilledRowRepresentation::Encoded(&[]),
            })
            .map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "spilled scan batch exceeds the statement arena; raise work_arena_bytes"
                )
            })?;
        let rows = &mut *rows;
        let batch_mark = recycle_rows.then(|| arena.mark());
        let mut len = 0usize;
        let mut stopped = false;
        let mut result = self
            .spill_merged_walk_bytes(
                table_slot,
                arena,
                false,
                decoded_columns.as_ref(),
                decoded_columns.is_none(),
                SpillOverlayMode::VisibleScan,
                None,
                &mut |rowid, _commit_lsn, representation| {
                    rows[len] = SpilledRow {
                        rowid,
                        representation,
                    };
                    len += 1;
                    if len != rows.len() {
                        return Ok(core::ops::ControlFlow::Continue(()));
                    }
                    match each(&rows[..len])? {
                        core::ops::ControlFlow::Continue(()) => {
                            if let Some(mark) = batch_mark {
                                // SAFETY: `each` consumed this batch synchronously.
                                unsafe { arena.rewind_to(mark) };
                            }
                            len = 0;
                            Ok(core::ops::ControlFlow::Continue(()))
                        }
                        core::ops::ControlFlow::Break(()) => {
                            stopped = true;
                            Ok(core::ops::ControlFlow::Break(()))
                        }
                    }
                },
            )
            .map(|_| ());
        if result.is_ok() && !stopped && len != 0 {
            result = each(&rows[..len]).map(|_| ());
        }
        if let Some(mark) = batch_mark {
            // SAFETY: the batch callback consumes every row synchronously.
            unsafe { arena.rewind_to(mark) };
        }
        result
    }

    /// Whether the spill list has no resident row-state overlay. In that
    /// state a physical scan can stream its already-merged rows directly;
    /// any overlay requires the ordinary row-state seam to preserve MVCC
    /// shadowing and mixed physical ordering.
    pub(crate) fn spill_rows_are_unshadowed(&self, table_slot: usize) -> bool {
        self.tables[table_slot].rows.is_empty()
    }

    /// Whether an unshadowed sequential spill walk costs no more durable block
    /// traffic than a value-index probe. Both estimates use only
    /// manifest and ANALYZE metadata, so choosing the access path cannot warm
    /// the cache or perform a speculative read.
    pub(crate) fn sequential_spill_scan_is_cheaper(
        &self,
        table_slot: usize,
        expected_rows: u64,
        txid: u32,
    ) -> bool {
        if !self.spill_rows_are_unshadowed(table_slot) {
            return false;
        }
        let generations = self.spill_generation_count(table_slot) as u64;
        if generations == 0 {
            return false;
        }
        let statistics = self.table_statistics(table_slot, txid);
        let rows = self.planning_row_estimate(table_slot);
        let width = if statistics.valid {
            statistics.average_row_width.max(1)
        } else {
            32
        };
        let full_scan_blocks = rows
            .saturating_mul(u64::from(width))
            .div_ceil(crate::store::MAX_PAYLOAD as u64)
            .saturating_add(generations.saturating_mul(2));
        let index_blocks = generations.saturating_mul(3).saturating_add(
            expected_rows
                .saturating_mul(u64::from(width))
                .div_ceil(crate::store::MAX_PAYLOAD as u64),
        );
        full_scan_blocks <= index_blocks
    }

    /// Steps one member cursor to its next entry, loading blocks (through
    /// the cache tiers) as it crosses block boundaries.
    fn cursor_advance(
        spill: &SpillReader,
        table: &Table,
        member: usize,
        cursor: &mut MemberCursor,
        context: &mut ScanContext,
    ) -> Result<(), SqlError> {
        cursor.head = None;
        if cursor.done {
            return Ok(());
        }
        let handle = table.spill_ssts[member].expect("cursor members exist");
        loop {
            if let Some((ordinal, leaf)) = cursor.prefetched_leaf {
                let mut blocks = spill.relation_blocks(table);
                if let Some(reference) = crate::store::take_prefetched_index_first_data(
                    &mut *blocks,
                    &leaf,
                    &mut context.index_buf,
                    handle.uses_packed_references(),
                )
                .map_err(spill_read_error)?
                {
                    cursor.prefetched_leaf = None;
                    if let crate::store::DataBlockRef::Direct(id) = reference {
                        crate::store::prefetch_data_block(&mut *blocks, Some(id))
                            .map_err(spill_read_error)?;
                        cursor.prefetched_data = Some((ordinal, reference));
                    }
                }
            }
            if cursor.loaded != Some(cursor.ordinal) {
                // A released scan context may have lost this block while the
                // logical cursor retained its next byte offset. A genuine
                // move to a later block starts at zero.
                let resume_offset = if cursor.loaded.is_none() {
                    cursor.offset
                } else {
                    0
                };
                let resume_raw_row = cursor.loaded.is_none().then_some(cursor.raw_row);
                let mut blocks = spill.relation_blocks(table);
                // Both index shapes resolve through one helper; the index
                // buffer is scratch for the descent and the decompression
                // bounce alike.
                let id = if let Some((ordinal, id)) = cursor.prefetched_data
                    && ordinal == cursor.ordinal
                {
                    cursor.prefetched_data = None;
                    id
                } else {
                    let Some((id, next)) = crate::store::locate_data_block_with_next(
                        &mut *blocks,
                        &handle,
                        &mut context.index_buf,
                        cursor.ordinal,
                    )
                    .map_err(spill_read_error)?
                    else {
                        cursor.done = true;
                        return Ok(());
                    };
                    match next {
                        Some(crate::store::DataBlockLookahead::Data(next)) => {
                            if let crate::store::DataBlockRef::Direct(next_id) = next {
                                crate::store::prefetch_data_block(&mut *blocks, Some(next_id))
                                    .map_err(spill_read_error)?;
                            }
                            cursor.prefetched_data = Some((cursor.ordinal + 1, next));
                        }
                        Some(crate::store::DataBlockLookahead::Leaf(leaf)) => {
                            crate::store::BlockStore::prefetch(&mut *blocks, &leaf).map_err(
                                |error| spill_read_error(crate::store::SstError::Store(error)),
                            )?;
                            cursor.prefetched_leaf = Some((cursor.ordinal + 1, leaf));
                        }
                        None => {}
                    }
                    id
                };
                let (raw_len, loaded_type) = crate::store::read_data_block_raw_ref(
                    &mut *blocks,
                    id,
                    &mut context.member_raw_blocks[member],
                    &mut context.member_blocks[member],
                )
                .map_err(spill_read_error)?;
                let loaded_len = if loaded_type == crate::store::BlockType::SstDataPaxV2 {
                    0
                } else {
                    crate::store::decode_data_block(
                        &context.member_raw_blocks[member][..raw_len],
                        loaded_type,
                        &mut context.member_blocks[member],
                    )
                    .map_err(spill_read_error)?
                };
                cursor.loaded_len = loaded_len;
                cursor.raw_len = raw_len;
                cursor.raw_row = 0;
                cursor.pax_layout = (loaded_type == crate::store::BlockType::SstDataPaxV2)
                    .then(|| {
                        crate::store::pax_layout(&context.member_raw_blocks[member][..raw_len])
                    })
                    .transpose()
                    .map_err(spill_read_error)?;
                if cursor.pax_layout.is_some() {
                    cursor.raw_row = resume_raw_row.unwrap_or(0);
                }
                cursor.loaded_type = Some(loaded_type);
                cursor.loaded = Some(cursor.ordinal);
                cursor.offset = resume_offset;
            }
            if cursor.loaded_type == Some(crate::store::BlockType::SstDataPaxV2) {
                let layout = cursor.pax_layout.as_ref().ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "PAX block has no validated layout"
                    )
                })?;
                if cursor.raw_row == layout.rows() {
                    cursor.ordinal += 1;
                    continue;
                }
                let row = cursor.raw_row;
                let (key, tombstone) = layout
                    .row_key(&context.member_raw_blocks[member][..cursor.raw_len], row)
                    .map_err(spill_read_error)?;
                let len = if tombstone {
                    0
                } else {
                    layout
                        .row_len(&context.member_raw_blocks[member][..cursor.raw_len], row)
                        .map_err(spill_read_error)?
                };
                cursor.head_raw_row = row;
                cursor.raw_row += 1;
                cursor.head_offset = 0;
                cursor.head = Some((key, tombstone, len));
                return Ok(());
            }
            let head_offset = cursor.offset;
            if cursor.loaded_type.is_none() || cursor.raw_len == 0 {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "spill cursor advanced without a complete loaded block state"
                ));
            }
            match crate::store::block_keys_at(
                &context.member_blocks[member][..cursor.loaded_len],
                head_offset,
            ) {
                Some((key, tombstone, len, next)) => {
                    cursor.offset = next;
                    cursor.head_offset = head_offset;
                    cursor.head = Some((key, tombstone, len));
                    return Ok(());
                }
                None => {
                    cursor.ordinal += 1;
                }
            }
        }
    }

    /// The newest object-resident version admitted by `snapshot`. Every SST
    /// is consulted because a newer run may contain only too-new versions;
    /// a tombstone remains a first-class verdict.
    fn spill_probe_at(
        &self,
        slot: usize,
        rowid: u64,
        snapshot: u64,
    ) -> Result<Option<SpillVersion>, SqlError> {
        let table = &self.tables[slot];
        if table.n_spill_ssts == 0 {
            return Ok(None);
        }
        let Some(spill) = &self.spill else {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "table has spill SSTs but no spill reader is attached"
            ));
        };
        let Some(mut scratch) = try_mutex_pool(&spill.scratch, "spill row scratch") else {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "spill fetches nested deeper than the reader scratch"
            ));
        };
        let scratch = &mut *scratch;
        // This multi-SST probe reuses the decoded buffer without preserving a
        // single row block, so it invalidates the point-reader cache.
        scratch.decoded_data_ref = None;
        let mut reader = crate::store::SstReader::over(
            &mut scratch.index_buf,
            &mut scratch.data_buf,
            &mut scratch.decoded_buf,
            &mut scratch.column_buf,
            &mut scratch.assembly_buf,
        );
        let mut best: Option<SpillVersion> = None;
        for member in 0..table.n_spill_ssts {
            let handle = table.spill_ssts[member].expect("counted");
            let verdict = {
                let mut blocks = spill.relation_blocks(table);
                reader.probe_at(&mut *blocks, &handle, rowid, snapshot)
            }
            .map_err(spill_read_error)?;
            if let Some(probe) = verdict
                && best.is_none_or(|current| {
                    probe.key.commit_lsn > current.commit_lsn
                        || (probe.key.commit_lsn == current.commit_lsn
                            && member as u32 > current.member)
                })
            {
                best = Some(SpillVersion {
                    len: probe.len,
                    member: member as u32,
                    commit_lsn: probe.key.commit_lsn,
                });
            }
        }
        Ok(best)
    }

    /// The one place a table's row states are enumerated. The bounded map is
    /// an overlay of pending changes and hot/resident rows; the merged SST
    /// walk synthesizes every remaining snapshot-visible state directly from
    /// the provider-neutral object store through the cache tiers. The callback
    /// therefore takes state by value, and errors stay visible to every SQL
    /// consumer.
    ///
    /// `Break` stops the walk early; the callback's own error aborts it.
    pub fn for_each_row_state(
        &self,
        table_slot: usize,
        each: &mut dyn for<'row> FnMut(u64, RowRead<'row>) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<(), SqlError> {
        // The overlay first: pending changes and hot rows, whose entries
        // shadow anything the spill list holds for the same rowid.
        if self
            .for_each_resident_row_state(table_slot, each)?
            .is_break()
        {
            return Ok(());
        }
        if self.tables[table_slot].n_spill_ssts == 0 {
            return Ok(());
        }
        // Then everything that lives only in the bucket, synthesized.
        self.spill_merged_walk(table_slot, &mut |rowid, len, member, commit_lsn| {
            each(
                rowid,
                RowRead::immutable(RowState {
                    committed: Some(RowHome::Spilled {
                        len,
                        sst: member,
                        commit_lsn,
                    }),
                    committed_lsn: commit_lsn,
                    checkpoint_change_lsn: 0,
                    history: CommittedHistory::empty(),
                    pending: PendingVersions::empty(),
                }),
            )
        })
    }

    pub(crate) fn resident_rows(&self, table_slot: usize) -> RowReadView<'_> {
        RowReadView::new(&self.row_versions, &self.tables[table_slot].rows)
    }

    pub(crate) fn for_each_resident_row_state(
        &self,
        table_slot: usize,
        each: &mut dyn for<'row> FnMut(u64, RowRead<'row>) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<core::ops::ControlFlow<()>, SqlError> {
        let view = RowReadView::new(&self.row_versions, &self.tables[table_slot].rows);
        for (rowid, state) in view.iter() {
            if each(rowid, state)?.is_break() {
                return Ok(core::ops::ControlFlow::Break(()));
            }
        }
        Ok(core::ops::ControlFlow::Continue(()))
    }

    pub(crate) fn for_each_scan_overlay_row_state(
        &self,
        table_slot: usize,
        each: &mut dyn for<'row> FnMut(u64, RowRead<'row>) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<core::ops::ControlFlow<()>, SqlError> {
        let view = RowReadView::new(&self.row_versions, &self.tables[table_slot].rows);
        for (rowid, state) in view.iter() {
            if Self::redundant_spilled_row_state(&state) {
                continue;
            }
            if each(rowid, state)?.is_break() {
                return Ok(core::ops::ControlFlow::Break(()));
            }
        }
        Ok(core::ops::ControlFlow::Continue(()))
    }

    /// Resumes resident rows changed after one published value-index base and
    /// records the exact row identities represented by the delta. Heap rows
    /// contribute replacement entries and tombstones only suppress the base.
    /// A spilled row was captured by a successful row checkpoint; its base
    /// entry remains current when this binding stayed clean.
    #[expect(clippy::too_many_arguments, reason = "checkpoint row stream boundary")]
    pub(crate) fn for_each_value_binding_delta_entry_batch(
        &self,
        table_slot: usize,
        binding: usize,
        after_lsn: u64,
        cursor: &mut CheckpointValueCursor,
        changed_rowids: &mut Vec<u64>,
        output: &mut [u8],
        max_rows: usize,
        each: &mut dyn for<'entry> FnMut(
            CheckpointValueEntry<'entry>,
        ) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<bool, SqlError> {
        let rows = self.tables[table_slot].rows.read();
        let mut walked = 0usize;
        while cursor.resident_slot < rows.backing_slot_count() && walked < max_rows {
            let slot = cursor.resident_slot;
            cursor.resident_slot += 1;
            let Some((&rowid, state)) = rows.entry_at_slot(slot) else {
                continue;
            };
            if state.committed_lsn <= after_lsn {
                continue;
            }
            walked += 1;
            let home = match state.committed {
                Some(home @ RowHome::Heap(_)) => home,
                None => {
                    if changed_rowids.len() == changed_rowids.capacity() {
                        return Err(sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "checkpoint value-index changed-row set exceeds table_rows ({})",
                            changed_rowids.capacity()
                        ));
                    }
                    changed_rowids.push(rowid);
                    continue;
                }
                // A spilled image was already captured by a successful row
                // checkpoint. If this binding stayed clean, its base entry
                // remains current; a binding-changing row cannot spill until
                // the matching value generation publishes.
                Some(RowHome::Spilled { .. }) => continue,
            };
            if changed_rowids.len() == changed_rowids.capacity() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "checkpoint value-index changed-row set exceeds table_rows ({})",
                    changed_rowids.capacity()
                ));
            }
            changed_rowids.push(rowid);
            let Some((key_len, payload_len, hash)) =
                self.encode_value_binding_entry(table_slot, binding, rowid, home, output)?
            else {
                continue;
            };
            let (key, payload) = output[..key_len + payload_len].split_at(key_len);
            if each(CheckpointValueEntry {
                rowid,
                commit_lsn: state.committed_lsn,
                hash,
                key,
                payload,
            })?
            .is_break()
            {
                return Ok(false);
            }
        }
        Ok(cursor.resident_slot == rows.backing_slot_count())
    }

    /// Resumes a complete checkpoint value-index source walk for at most
    /// `max_rows` physical rowids. The cursor advances before `each` may stop
    /// the batch, so a later beat never revisits an emitted row.
    #[expect(clippy::too_many_arguments, reason = "checkpoint row stream boundary")]
    pub(crate) fn for_each_value_binding_entry_batch(
        &self,
        table_slot: usize,
        binding: usize,
        cursor: &mut CheckpointValueCursor,
        arena: &crate::mem::arena::Arena,
        output: &mut [u8],
        max_rows: usize,
        max_object_gets: u64,
        each: &mut dyn for<'entry> FnMut(
            CheckpointValueEntry<'entry>,
        ) -> Result<core::ops::ControlFlow<()>, SqlError>,
    ) -> Result<bool, SqlError> {
        let mut walked = 0usize;
        if !cursor.resident_done {
            let rows = self.tables[table_slot].rows.read();
            while cursor.resident_slot < rows.backing_slot_count() && walked < max_rows {
                let slot = cursor.resident_slot;
                cursor.resident_slot += 1;
                let Some((&rowid, state)) = rows.entry_at_slot(slot) else {
                    continue;
                };
                walked += 1;
                // Spill-resident committed rows belong to the merged walk
                // even when a later statement adds a pending version.
                let Some(RowHome::Heap(location)) = state.committed else {
                    continue;
                };
                let home = RowHome::Heap(location);
                let Some((key_len, payload_len, hash)) = self
                    .encode_value_binding_entry(table_slot, binding, rowid, home, output)
                    .map_err(|error| SqlError {
                        sqlstate: error.sqlstate,
                        message: stack_format!(
                            192,
                            "resident checkpoint value source row {}: {}",
                            rowid,
                            error.message.as_str()
                        ),
                    })?
                else {
                    continue;
                };
                let (key, payload) = output[..key_len + payload_len].split_at(key_len);
                if each(CheckpointValueEntry {
                    rowid,
                    commit_lsn: state.committed_lsn,
                    hash,
                    key,
                    payload,
                })?
                .is_break()
                {
                    return Ok(false);
                }
            }
            if cursor.resident_slot != rows.backing_slot_count() {
                return Ok(false);
            }
            cursor.resident_done = true;
        }
        if walked == max_rows {
            return Ok(false);
        }
        if cursor.spill_done {
            return Ok(true);
        }

        let mut schema = [ColType::Bool; MAX_COLUMNS];
        let n_columns = self.tables[table_slot].def.schema(&mut schema);
        let dependency_mask = self.tables[table_slot].enforcers[binding]
            .expect("binding")
            .dependency_mask;
        // PAX source reads need only key, predicate, expression, and INCLUDE
        // dependencies. Unselected values decode as NULL and are never read.
        let decoded_columns =
            core::array::from_fn(|column| column < n_columns && dependency_mask.contains(column));
        let decoded_count = decoded_columns[..n_columns]
            .iter()
            .filter(|&&selected| selected)
            .count();
        let done = self.spill_merged_walk_bytes(
            table_slot,
            arena,
            true,
            Some(&decoded_columns),
            decoded_count.saturating_mul(2) >= n_columns,
            SpillOverlayMode::CommittedCheckpoint,
            Some((
                &mut cursor.members,
                &mut cursor.spill_walk_id,
                &mut cursor.spill_initialized,
                max_rows - walked,
                max_object_gets,
            )),
            &mut |rowid, commit_lsn, representation| {
                let mut decoded = [Datum::Null; MAX_COLUMNS];
                let values = match representation {
                    SpilledRowRepresentation::Encoded(bytes) => {
                        rowenc::decode(bytes, &schema[..n_columns], &mut decoded).map_err(
                            |error| SqlError {
                                sqlstate: error.sqlstate,
                                message: stack_format!(
                                    192,
                                    "spilled checkpoint value source row {}: {}",
                                    rowid,
                                    error.message.as_str()
                                ),
                            },
                        )?;
                        &decoded[..n_columns]
                    }
                    SpilledRowRepresentation::Values(values) => values,
                };
                let Some((key_len, payload_len, hash)) =
                    self.encode_value_binding_values(table_slot, binding, values, output)?
                else {
                    return Ok(core::ops::ControlFlow::Continue(()));
                };
                let (key, payload) = output[..key_len + payload_len].split_at(key_len);
                each(CheckpointValueEntry {
                    rowid,
                    commit_lsn,
                    hash,
                    key,
                    payload,
                })
            },
        )?;
        cursor.spill_done = done;
        Ok(done)
    }

    fn redundant_spilled_row_state(state: &RowState) -> bool {
        matches!(state.committed, Some(RowHome::Spilled { .. }))
            && state.checkpoint_change_lsn == 0
            && state.history.is_empty()
            && state.pending.is_none()
    }

    /// One row's state by id, through the same seam as the enumeration.
    pub fn row_state(&self, table_slot: usize, rowid: u64) -> Result<Option<RowRead<'_>>, SqlError> {
        if let Some(state) = RowReadView::point(&self.row_versions, &self.tables[table_slot].rows, rowid) {
            return Ok(Some(state));
        }
        Ok(self
            .spill_probe_at(table_slot, rowid, u64::MAX)?
            .and_then(|version| {
                version.len.map(|len| RowRead::immutable(RowState {
                    committed: Some(RowHome::Spilled {
                        len,
                        sst: version.member,
                        commit_lsn: version.commit_lsn,
                    }),
                    committed_lsn: version.commit_lsn,
                    checkpoint_change_lsn: 0,
                    history: CommittedHistory::empty(),
                    pending: PendingVersions::empty(),
                }))
            }))
    }

    /// Returns only a row state already present in the bounded mutable
    /// overlay. Immutable index generations use this to detect keys shadowed
    /// by later changes without point-reading the immutable table for every
    /// unchanged index entry.
    pub(crate) fn resident_row_state(&self, table_slot: usize, rowid: u64) -> Option<RowRead<'_>> {
        RowReadView::point(&self.row_versions, &self.tables[table_slot].rows, rowid)
    }

    /// The single visibility choke point for heap and object-resident row
    /// versions. Pending command visibility wins first; then the resident
    /// committed chain; finally immutable SSTs supply an older admissible
    /// image when the resident chain no longer carries it.
    pub fn visible_row_home(
        &self,
        table_slot: usize,
        rowid: u64,
        state: RowRead<'_>,
        txid: u32,
    ) -> Result<Option<RowHome>, SqlError> {
        self.visible_row_home_at(
            table_slot,
            rowid,
            state,
            txid,
            self.read_snapshot(),
            self.commit_snapshot(),
        )
    }

    /// Visibility with explicit command and commit snapshots. DDL validation
    /// uses `SNAPSHOT_ALL` to include every change made earlier in the current
    /// transaction; ordinary scans call `visible_row_home`.
    pub fn visible_row_home_at(
        &self,
        table_slot: usize,
        rowid: u64,
        state: RowRead<'_>,
        txid: u32,
        command_snapshot: u32,
        commit_snapshot: u64,
    ) -> Result<Option<RowHome>, SqlError> {
        let visible = state.visible_at(txid, command_snapshot, commit_snapshot);
        drop(state);
        if let Some(home) = visible {
            return Ok(home);
        }
        Ok(self
            .spill_probe_at(table_slot, rowid, commit_snapshot)?
            .and_then(|version| {
                version.len.map(|len| RowHome::Spilled {
                    len,
                    sst: version.member,
                    commit_lsn: version.commit_lsn,
                })
            }))
    }

    /// How many rows `txid` sees, through the same seam — under the current
    /// command snapshot, so it matches what the scan loop iterates.
    pub fn visible_row_count(&self, table_slot: usize, txid: u32) -> Result<usize, SqlError> {
        let mut count = 0usize;
        self.for_each_row_state(table_slot, &mut |rowid, state| {
            if self
                .visible_row_home(table_slot, rowid, state, txid)?
                .is_some()
            {
                count += 1;
            }
            Ok(core::ops::ControlFlow::Continue(()))
        })?;
        Ok(count)
    }

    /// Rebuilds planner statistics from the same MVCC-visible row seam every
    /// query uses. An empty `selected_columns` means every column; otherwise
    /// only the named column statistics are replaced while table cardinality
    /// and row width are always refreshed.
    pub(crate) fn analyze_table(
        &mut self,
        table_slot: usize,
        txid: u32,
        selected_columns: &[usize],
        arena: &crate::mem::arena::Arena,
    ) -> Result<TableStatistics, SqlError> {
        const REGISTERS: usize = 64;

        fn add_distinct(registers: &mut [u8; REGISTERS], hash: u64) {
            let index = (hash as usize) & (REGISTERS - 1);
            let tail = hash >> REGISTERS.trailing_zeros();
            let rank = tail.leading_zeros().saturating_add(1).min(63) as u8;
            registers[index] = registers[index].max(rank);
        }

        fn distinct_estimate(registers: &[u8; REGISTERS]) -> u64 {
            let mut inverse_sum = 0.0f64;
            let mut zeros = 0usize;
            for &register in registers {
                inverse_sum += 2.0f64.powi(-i32::from(register));
                zeros += usize::from(register == 0);
            }
            let count = REGISTERS as f64;
            let raw = 0.709 * count * count / inverse_sum;
            let corrected = if raw <= 2.5 * count && zeros > 0 {
                count * (count / zeros as f64).ln()
            } else {
                raw
            };
            corrected.round().max(0.0) as u64
        }

        let definition = *self.table_def(table_slot, txid);
        let mut schema = [ColType::Bool; MAX_COLUMNS];
        let n_columns = definition.schema(&mut schema);
        let mut selected = [false; MAX_COLUMNS];
        if selected_columns.is_empty() {
            selected[..n_columns].fill(true);
        } else {
            for &column in selected_columns {
                selected[column] = true;
            }
        }

        let mut rows = 0u64;
        let mut row_bytes = 0u64;
        let mut nulls = [0u64; MAX_COLUMNS];
        let mut widths = [0u64; MAX_COLUMNS];
        let mut non_nulls = [0u64; MAX_COLUMNS];
        let mut registers = [[0u8; REGISTERS]; MAX_COLUMNS];
        let mut observe = |values: &[Datum], encoded_len: usize| {
            rows = rows.saturating_add(1);
            row_bytes = row_bytes.saturating_add(encoded_len as u64);
            for column in 0..n_columns {
                if !selected[column] {
                    continue;
                }
                let value = values[column];
                if value.is_null() {
                    nulls[column] = nulls[column].saturating_add(1);
                    continue;
                }
                non_nulls[column] = non_nulls[column].saturating_add(1);
                // A one-column row encoding contributes a two-byte count
                // and one bitmap byte; remove that framing to retain the
                // value's actual stored width.
                let width = rowenc::encoded_len(core::slice::from_ref(&value)).saturating_sub(3);
                widths[column] = widths[column].saturating_add(width as u64);
                let index = [column as u16];
                add_distinct(&mut registers[column], hash_key(values, &index));
            }
        };
        // Overlay rows carry every pending or newer committed image. Spilled
        // rows absent from that overlay stream below with their payload from
        // the already resident merge cursor, avoiding one object point read
        // per row during cold ANALYZE.
        let _ = self.for_each_scan_overlay_row_state(table_slot, &mut |rowid, state| {
            let Some(home) = self.visible_row_home(table_slot, rowid, state, txid)? else {
                return Ok(core::ops::ControlFlow::Continue(()));
            };
            self.with_row_bytes(table_slot, rowid, home, |bytes| {
                let mut values = [Datum::Null; MAX_COLUMNS];
                rowenc::decode(bytes, &schema[..n_columns], &mut values)?;
                observe(&values[..n_columns], bytes.len());
                Ok(())
            })?;
            Ok(core::ops::ControlFlow::Continue(()))
        })?;
        self.spill_merged_walk_bytes(
            table_slot,
            arena,
            true,
            None,
            true,
            SpillOverlayMode::VisibleScan,
            None,
            &mut |_rowid, _commit_lsn, representation| {
                match representation {
                    SpilledRowRepresentation::Encoded(bytes) => {
                        let mut values = [Datum::Null; MAX_COLUMNS];
                        rowenc::decode(bytes, &schema[..n_columns], &mut values)?;
                        observe(&values[..n_columns], bytes.len());
                    }
                    SpilledRowRepresentation::Values(values) => {
                        observe(values, rowenc::encoded_len(values));
                    }
                }
                Ok(core::ops::ControlFlow::Continue(()))
            },
        )?;

        let mut statistics = self.table_statistics(table_slot, txid);
        statistics.valid = true;
        statistics.rows = rows;
        statistics.average_row_width = row_bytes
            .checked_div(rows)
            .unwrap_or(0)
            .min(u64::from(u32::MAX)) as u32;
        statistics.analyzed_generation = self.tables[table_slot].generation;
        for column in 0..n_columns {
            if !selected[column] {
                continue;
            }
            let distinct_values = distinct_estimate(&registers[column]).min(non_nulls[column]);
            statistics.columns[column] = ColumnStatistics {
                valid: rows != 0,
                null_fraction_ppm: nulls[column]
                    .saturating_mul(1_000_000)
                    .checked_div(rows)
                    .unwrap_or(0)
                    .min(u64::from(u32::MAX)) as u32,
                distinct_values,
                distinct_fraction_ppm: if rows != 0 && distinct_values.saturating_mul(10) > rows {
                    distinct_values
                        .saturating_mul(1_000_000)
                        .checked_div(rows)
                        .unwrap_or(0)
                        .min(1_000_000) as u32
                } else {
                    0
                },
                average_width: widths[column]
                    .checked_div(non_nulls[column])
                    .unwrap_or(0)
                    .min(u64::from(u32::MAX)) as u32,
            };
        }
        self.write_table_statistics(table_slot, txid, statistics)?;
        // PostgreSQL updates pg_class's relation statistics in place:
        // reltuples/relpages remain changed even if the surrounding
        // transaction rolls back. Column pg_statistic rows stay in the
        // transaction-private version written above.
        let committed = &mut self.tables[table_slot].statistics;
        committed.valid = statistics.valid;
        committed.rows = statistics.rows;
        committed.average_row_width = statistics.average_row_width;
        committed.analyzed_generation = statistics.analyzed_generation;
        self.tables[table_slot].statistics_dirty = true;
        self.tables[table_slot].statistics_wal_dirty = true;
        Ok(statistics)
    }

    pub(crate) fn table_statistics(&self, table_slot: usize, txid: u32) -> TableStatistics {
        if self.tables[table_slot].pending_statistics_txid == Some(txid)
            && let Some(slot) = self.tables[table_slot].pending_statistics_tail
        {
            return self.pending_table_statistics[slot as usize].statistics;
        }
        self.tables[table_slot].statistics
    }

    pub(crate) fn pending_table_statistics(
        &self,
        table_slot: usize,
        txid: u32,
    ) -> Option<TableStatistics> {
        (self.tables[table_slot].pending_statistics_txid == Some(txid))
            .then(|| self.tables[table_slot].pending_statistics_tail)
            .flatten()
            .map(|slot| self.pending_table_statistics[slot as usize].statistics)
    }

    fn write_table_statistics(
        &mut self,
        table_slot: usize,
        txid: u32,
        statistics: TableStatistics,
    ) -> Result<(), SqlError> {
        if let Some(owner) = self.tables[table_slot].pending_statistics_txid
            && owner != txid
        {
            return Err(sql_err!(
                sqlstate::SERIALIZATION_FAILURE,
                "could not serialize ANALYZE of relation \"{}\"",
                self.tables[table_slot].def.name.as_str()
            ));
        }
        let previous = self.tables[table_slot].pending_statistics_tail;
        if previous.is_some_and(|slot| {
            self.pending_table_statistics[slot as usize].depth
                >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "relation \"{}\" exceeds max_catalog_versions_per_object ({})",
                self.tables[table_slot].def.name.as_str(),
                self.max_catalog_versions_per_object
            ));
        }
        let depth = previous.map_or(1, |slot| {
            self.pending_table_statistics[slot as usize].depth + 1
        });
        let slot = match self
            .pending_table_statistics
            .iter()
            .position(|entry| !entry.used)
        {
            Some(slot) => {
                self.pending_table_statistics[slot] = PendingTableStatisticsSlot {
                    used: true,
                    previous,
                    depth,
                    statistics,
                };
                slot
            }
            None => {
                let slot = self.pending_table_statistics.len();
                self.pending_table_statistics
                    .push(PendingTableStatisticsSlot {
                        used: true,
                        previous,
                        depth,
                        statistics,
                    })
                    .map_err(|_| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "pending table-statistics pool is exhausted"
                        )
                    })?;
                slot
            }
        };
        self.tables[table_slot].pending_statistics_tail = Some(slot as u32);
        self.tables[table_slot].pending_statistics_txid = Some(txid);
        Ok(())
    }

    pub(crate) fn rollback_table_statistics(&mut self, table_slot: usize, txid: u32) {
        if self.tables[table_slot].pending_statistics_txid != Some(txid) {
            return;
        }
        let Some(slot) = self.tables[table_slot].pending_statistics_tail else {
            return;
        };
        let previous = self.pending_table_statistics[slot as usize].previous;
        self.pending_table_statistics[slot as usize].used = false;
        self.tables[table_slot].pending_statistics_tail = previous;
        if previous.is_none() {
            self.tables[table_slot].pending_statistics_txid = None;
        }
    }

    fn clear_pending_table_statistics(&mut self, table_slot: usize) {
        let mut tail = self.tables[table_slot].pending_statistics_tail.take();
        while let Some(slot) = tail {
            let entry = &mut self.pending_table_statistics[slot as usize];
            tail = entry.previous;
            entry.used = false;
        }
        self.tables[table_slot].pending_statistics_txid = None;
    }

    pub(crate) fn commit_table_statistics(&mut self, table_slot: usize, txid: u32) {
        let Some(statistics) = self.pending_table_statistics(table_slot, txid) else {
            return;
        };
        self.tables[table_slot].statistics = statistics;
        self.tables[table_slot].statistics_dirty = true;
        self.clear_pending_table_statistics(table_slot);
    }

    /// Cardinality estimate that never performs object I/O. ANALYZE wins; an
    /// unspilled table can otherwise use its complete resident map exactly,
    /// while a spilled table uses a conservative floor until statistics are
    /// collected.
    pub(crate) fn planning_row_estimate(&self, table_slot: usize) -> u64 {
        let table = &self.tables[table_slot];
        if table.statistics.valid {
            table.statistics.rows
        } else if table.n_spill_ssts == 0 {
            table.rows.len() as u64
        } else {
            (table.rows.len() as u64).max(1_000)
        }
    }

    pub(crate) fn statistics_dirty(&self) -> bool {
        self.tables
            .iter()
            .any(|table| table.live && table.statistics_dirty)
    }

    pub(crate) fn statistics_wal_dirty(&self, table_slot: usize) -> bool {
        self.tables[table_slot].statistics_wal_dirty
    }

    pub(crate) fn clear_statistics_wal_dirty(&mut self, table_slot: usize) {
        self.tables[table_slot].statistics_wal_dirty = false;
    }

    pub(crate) fn install_table_statistics(
        &mut self,
        table_slot: usize,
        statistics: TableStatistics,
    ) {
        self.tables[table_slot].statistics = statistics;
        self.tables[table_slot].statistics_dirty = false;
        self.tables[table_slot].statistics_wal_dirty = false;
        self.clear_pending_table_statistics(table_slot);
    }

    pub(crate) fn replay_table_statistics(
        &mut self,
        table_slot: usize,
        statistics: TableStatistics,
    ) {
        self.tables[table_slot].statistics = statistics;
        self.tables[table_slot].statistics_dirty = true;
        self.tables[table_slot].statistics_wal_dirty = false;
        self.clear_pending_table_statistics(table_slot);
    }

    pub fn row_bytes<'a>(
        &'a self,
        table_slot: usize,
        rowid: u64,
        home: RowHome,
        arena: &'a crate::mem::arena::Arena,
    ) -> Result<&'a [u8], SqlError> {
        match home {
            RowHome::Heap(loc) => Ok(self.heap.get(loc)),
            RowHome::Spilled {
                len,
                sst,
                commit_lsn,
            } => {
                let Some(spill) = &self.spill else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "row is spilled but no spill reader is attached"
                    ));
                };
                let Some(handle) = self.tables[table_slot]
                    .spill_ssts
                    .get(sst as usize)
                    .copied()
                    .flatten()
                else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "row is spilled but its table has no spill SST"
                    ));
                };
                let out = arena.alloc_slice_with(len as usize, |_| 0u8).map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "spilled rows exceed the statement arena; raise work_arena_bytes"
                    )
                })?;
                // Both borrows are per-fetch; the copy into the arena ends
                // them before returning.
                let Some(mut scratch) = try_mutex_pool(&spill.scratch, "spill row scratch") else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled-row fetches nested deeper than the reader supports"
                    ));
                };
                let mut blocks = spill.relation_blocks(&self.tables[table_slot]);
                let SpillScratch {
                    index_buf,
                    data_buf,
                    decoded_buf,
                    column_buf,
                    assembly_buf,
                    decoded_data_ref,
                    ..
                } = &mut *scratch;
                let mut reader = crate::store::SstReader::over(
                    index_buf,
                    data_buf,
                    decoded_buf,
                    column_buf,
                    assembly_buf,
                );
                reader.restore_cached_data_block(
                    handle.format,
                    (*decoded_data_ref).and_then(|(cached_handle, reference, cached_len)| {
                        (cached_handle == handle).then_some((reference, cached_len))
                    }),
                );
                let got = reader
                    .get_at(&mut *blocks, &handle, rowid, commit_lsn, out)
                    .map_err(spill_read_error)?;
                *decoded_data_ref = reader
                    .cached_data_block()
                    .map(|(reference, cached_len)| (handle, reference, cached_len));
                match got {
                    Some(probe) if probe.key.commit_lsn == commit_lsn && probe.len == Some(len) => {
                        Ok(&out[..len as usize])
                    }
                    Some(_) => Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled row version mismatch"
                    )),
                    None => Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled row missing from its SST"
                    )),
                }
            }
        }
    }

    /// Hands a visible row's bytes to `f` without arena residency: a heap row
    /// borrows the heap; a spilled row is fetched into the spill reader's own
    /// scratch for the duration of the call. For consume-in-place readers
    /// (constraint scans) whose decoded values do not outlive the closure.
    /// `f` must not fetch another spilled row (the scratch is singular).
    pub fn with_row_bytes<R>(
        &self,
        table_slot: usize,
        rowid: u64,
        home: RowHome,
        f: impl FnOnce(&[u8]) -> Result<R, SqlError>,
    ) -> Result<R, SqlError> {
        match home {
            RowHome::Heap(loc) => f(self.heap.get(loc)),
            RowHome::Spilled {
                len,
                sst,
                commit_lsn,
            } => {
                let Some(spill) = &self.spill else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "row is spilled but no spill reader is attached"
                    ));
                };
                let Some(handle) = self.tables[table_slot]
                    .spill_ssts
                    .get(sst as usize)
                    .copied()
                    .flatten()
                else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "row is spilled but its table has no spill SST"
                    ));
                };
                let Some(mut scratch) = try_mutex_pool(&spill.scratch, "spill row scratch") else {
                    return Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled-row fetches nested deeper than the reader supports"
                    ));
                };
                let SpillScratch {
                    index_buf,
                    data_buf,
                    decoded_buf,
                    column_buf,
                    assembly_buf,
                    bounce_buf,
                    decoded_data_ref,
                } = &mut *scratch;
                // The assembly buffer doubles as the row destination: `get`
                // assembles a chained row into the caller buffer directly, so
                // the two uses never overlap. The reader's own staging slot is
                // the bounce buffer (a compressed data block decompresses
                // through it).
                let row_buf = &mut assembly_buf[..len as usize];
                let got = {
                    let mut blocks = spill.relation_blocks(&self.tables[table_slot]);
                    let mut reader = crate::store::SstReader::over(
                        index_buf,
                        data_buf,
                        decoded_buf,
                        column_buf,
                        bounce_buf,
                    );
                    reader.restore_cached_data_block(
                        handle.format,
                        (*decoded_data_ref).and_then(|(cached_handle, reference, cached_len)| {
                            (cached_handle == handle).then_some((reference, cached_len))
                        }),
                    );
                    let got = reader
                        .get_at(&mut *blocks, &handle, rowid, commit_lsn, row_buf)
                        .map_err(spill_read_error)?;
                    *decoded_data_ref = reader
                        .cached_data_block()
                        .map(|(reference, cached_len)| (handle, reference, cached_len));
                    got
                };
                match got {
                    Some(probe) if probe.key.commit_lsn == commit_lsn && probe.len == Some(len) => {
                        f(&row_buf[..len as usize])
                    }
                    Some(_) => Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled row version mismatch"
                    )),
                    None => Err(sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "spilled row missing from its SST"
                    )),
                }
            }
        }
    }

    /// Marks every committed heap row of every live table as spilled to its
    /// just-checkpointed SST, so the following compaction drops the bytes
    /// from RAM. Only called after a successful checkpoint whose handles are
    /// installed on the tables; rows with no SST (empty tables) are left.
    pub fn evict_committed(&mut self) {
        for i in 0..self.tables.len() {
            if self.tables[i].def.persistence != RelationPersistence::Temporary {
                self.evict_committed_table(i);
            }
        }
    }

    /// Marks committed heap rows of one freshly-spilled table as local SST
    /// residents. Temporary spill uses this narrower form because a durable
    /// table may have changed since its last manifest publication.
    pub(crate) fn evict_committed_table(&mut self, slot: usize) {
        if !self.tables[slot].live || self.tables[slot].n_spill_ssts == 0 {
            return;
        }
        let table = &mut self.tables[slot];
        let newest = (table.n_spill_ssts - 1) as u32;
        for (_, state) in table.rows.iter_mut() {
            if let Some(RowHome::Heap(loc)) = state.committed {
                let sst = table
                    .spill_through_lsn
                    .iter()
                    .take(table.n_spill_ssts)
                    .position(|&through_lsn| through_lsn != 0 && state.committed_lsn <= through_lsn)
                    .map_or(newest, |generation| generation as u32);
                state.committed = Some(RowHome::Spilled {
                    len: loc.len,
                    sst,
                    commit_lsn: state.committed_lsn,
                });
            }
        }
    }

    /// Records the commit boundary captured by a locally published generation.
    /// Heap rows remain warm until pressure evicts them; the boundaries then
    /// map each row to the first generation that contains its current image.
    pub(crate) fn set_spill_generation_through(
        &mut self,
        slot: usize,
        generation: usize,
        through_lsn: u64,
    ) {
        let table = &mut self.tables[slot];
        debug_assert!(generation < table.n_spill_ssts);
        table.spill_through_lsn[generation] = through_lsn;
    }

    pub(crate) fn release_table_histories(&mut self, slot: usize) {
        let row_versions = self.row_versions.exclusive();
        let (tables, versions) = (&mut self.tables, &mut row_versions.committed_row_versions);
        for (_, state) in tables[slot].rows.iter_mut() {
            prune_committed_history(versions, &mut state.history, None);
        }
    }

    pub(crate) fn clear_table_dirty_through(&mut self, slot: usize, generation: u64) {
        if self.tables[slot].generation == generation {
            let table = &mut self.tables[slot];
            table.dirty = false;
            for (_, state) in table.rows.iter_mut() {
                state.checkpoint_change_lsn = 0;
            }
        }
    }

    /// A full rewrite: the new SST holds every committed row, so the list
    /// collapses to it and every spilled map entry is remapped to slot 0.
    pub(crate) fn collapse_spill(&mut self, slot: usize, handle: crate::store::SstHandle) {
        let table = &mut self.tables[slot];
        table.spill_ssts.fill(None);
        table.spill_through_lsn.fill(0);
        table.spill_ssts[0] = Some(handle);
        table.n_spill_ssts = 1;
        for (_, state) in table.rows.iter_mut() {
            if let Some(RowHome::Spilled {
                len, commit_lsn, ..
            }) = state.committed
            {
                state.committed = Some(RowHome::Spilled {
                    len,
                    sst: 0,
                    commit_lsn,
                });
            }
        }
    }

    /// Paced compaction merged the adjacent spill-SST pair at (`at`,
    /// `at + 1`) into one (`None` when nothing in the pair survived): the
    /// merged member takes position `at`, later members shift down, and every
    /// spilled row's index follows. A live row can only reference a dropped
    /// pair when the merge kept it, so `None` never strands one.
    pub(crate) fn merge_spill_pair(
        &mut self,
        slot: usize,
        at: usize,
        handle: Option<crate::store::SstHandle>,
    ) {
        let table = &mut self.tables[slot];
        let removed = if handle.is_some() { 1u32 } else { 2u32 };
        let mut n = 0;
        table.spill_ssts.copy_within(0..at, 0);
        table.spill_through_lsn.copy_within(0..at, 0);
        n += at;
        if let Some(h) = handle {
            table.spill_ssts[n] = Some(h);
            table.spill_through_lsn[n] =
                table.spill_through_lsn[at].max(table.spill_through_lsn[at + 1]);
            n += 1;
        }
        for i in at + 2..table.n_spill_ssts {
            table.spill_ssts[n] = table.spill_ssts[i];
            table.spill_through_lsn[n] = table.spill_through_lsn[i];
            n += 1;
        }
        table.spill_ssts[n..].fill(None);
        table.spill_through_lsn[n..].fill(0);
        table.n_spill_ssts = n;
        let at = at as u32;
        for (_, state) in table.rows.iter_mut() {
            if let Some(RowHome::Spilled {
                len,
                sst,
                commit_lsn,
            }) = state.committed
            {
                let sst = if sst < at {
                    sst
                } else if sst == at || sst == at + 1 {
                    at
                } else {
                    sst - removed
                };
                state.committed = Some(RowHome::Spilled {
                    len,
                    sst,
                    commit_lsn,
                });
            }
        }
    }

    /// A delta flush: the new SST (heap rows + tombstones) joins the list;
    /// existing spilled entries keep their slots. The caller guarantees the
    /// list has room.
    pub(crate) fn append_spill(&mut self, slot: usize, handle: crate::store::SstHandle) {
        let table = &mut self.tables[slot];
        assert!(
            table.n_spill_ssts < table.spill_ssts.len(),
            "delta flush into a full list"
        );
        table.spill_ssts[table.n_spill_ssts] = Some(handle);
        table.spill_through_lsn[table.n_spill_ssts] = 0;
        table.n_spill_ssts += 1;
    }

    /// Installs a cold-start spill list verbatim (entries were installed with
    /// their slots by the manifest scan).
    pub(crate) fn set_spill_list(&mut self, slot: usize, handles: &[crate::store::SstHandle]) {
        self.set_spill_list_from_iter(slot, handles.len(), handles.iter().copied());
    }

    pub(crate) fn set_spill_list_from_iter(
        &mut self,
        slot: usize,
        len: usize,
        handles: impl Iterator<Item = crate::store::SstHandle>,
    ) {
        let table = &mut self.tables[slot];
        assert!(
            len <= table.spill_ssts.len(),
            "validated spill list fits configured capacity"
        );
        table.spill_ssts.fill(None);
        table.spill_through_lsn.fill(0);
        let mut installed = 0;
        for handle in handles {
            assert!(installed < len, "spill iterator exceeds declared length");
            table.spill_ssts[installed] = Some(handle);
            installed += 1;
        }
        assert_eq!(
            installed, len,
            "spill iterator is shorter than declared length"
        );
        table.n_spill_ssts = len;
    }

    /// Clears a table's shadowing deletion markers only after the manifest
    /// referencing their SST tombstones has published. A failed publication
    /// keeps the markers, so its retry cannot lose a delete.
    pub(crate) fn clear_tombstones(&mut self, slot: usize) {
        let table = &mut self.tables[slot];
        // The installed SSTs now carry (or moot) every deletion, so the row
        // overlay markers are done shadowing older generations.
        loop {
            let mut batch = [0u64; 512];
            let mut n = 0usize;
            for (rowid, state) in table.rows.iter() {
                if state.committed.is_none() && state.history.is_empty() && state.pending.is_none()
                {
                    batch[n] = rowid;
                    n += 1;
                    if n == batch.len() {
                        break;
                    }
                }
            }
            if n == 0 {
                return;
            }
            for &rowid in &batch[..n] {
                table.rows.remove(&rowid);
            }
        }
    }

    pub fn table_count(&self) -> usize {
        self.large_object_page_table as usize
    }

    /// Resolves a logical insert target to its owning leaf.  One typed catalog
    /// representation drives VALUES, COPY, MERGE and logical apply alike.
    pub fn partition_target(
        &self,
        table: usize,
        values: &[crate::sql::types::Datum],
        txid: u32,
    ) -> Result<usize, SqlError> {
        let mut current = table;
        loop {
            let definition = self.table_def(current, txid);
            let Some(PartitionScheme {
                strategy,
                keys,
                n_keys,
            }) = definition.partition.scheme
            else {
                if let Some(PartitionAttachment { parent, bound, .. }) =
                    definition.partition.attachment
                    && !self.partition_attachment_accepts(
                        usize::from(parent),
                        current,
                        bound,
                        values,
                        txid,
                    )?
                {
                    return Err(sql_err!(
                        crate::sql::eval::sqlstate::CHECK_VIOLATION,
                        "new row for relation \"{}\" violates partition constraint",
                        definition.name.as_str()
                    ));
                }
                return Ok(current);
            };
            current = self.partition_child_target(current, strategy, keys, n_keys, values, txid)?;
        }
    }

    /// Verifies the complete attachment chain of a leaf after `BEFORE ROW`
    /// triggers have had an opportunity to rewrite its partition keys.
    pub(crate) fn validate_partition_target(
        &self,
        leaf: usize,
        values: &[crate::sql::types::Datum],
        txid: u32,
    ) -> Result<(), SqlError> {
        let mut child = leaf;
        while let Some(PartitionAttachment { parent, bound, .. }) =
            self.table_def(child, txid).partition.attachment
        {
            if !self.partition_attachment_accepts(
                usize::from(parent),
                child,
                bound,
                values,
                txid,
            )? {
                return Err(sql_err!(
                    crate::sql::eval::sqlstate::CHECK_VIOLATION,
                    "new row for relation \"{}\" violates partition constraint",
                    self.table_def(child, txid).name.as_str()
                ));
            }
            child = usize::from(parent);
        }
        Ok(())
    }

    pub(crate) fn partition_child_target(
        &self,
        parent_slot: usize,
        strategy: PartitionStrategy,
        keys: [u16; MAX_PARTITION_KEYS],
        n_keys: u8,
        values: &[crate::sql::types::Datum],
        txid: u32,
    ) -> Result<usize, SqlError> {
        let mut default = None;
        let mut match_slot = None;
        for child in 0..self.table_count() {
            if !self.table(child).visible_to(txid) {
                continue;
            }
            let Some(PartitionAttachment {
                parent,
                bound,
                state,
            }) = self.table_def(child, txid).partition.attachment
            else {
                continue;
            };
            if usize::from(parent) != parent_slot || !state.routable() {
                continue;
            }
            if matches!(bound, PartitionBound::Default) {
                default = Some(child);
            } else if partition_bound_matches(strategy, keys, n_keys, bound, values)?
                && match_slot.replace(child).is_some()
            {
                return Err(sql_err!(
                    crate::sql::eval::sqlstate::INTERNAL_ERROR,
                    "overlapping partition bounds in relation \"{}\"",
                    self.table_def(parent_slot, txid).name.as_str()
                ));
            }
        }
        match_slot.or(default).ok_or_else(|| {
            sql_err!(
                crate::sql::eval::sqlstate::CHECK_VIOLATION,
                "no partition of relation \"{}\" found for row",
                self.table_def(parent_slot, txid).name.as_str()
            )
        })
    }

    pub(crate) fn partition_attachment_accepts(
        &self,
        parent: usize,
        child: usize,
        bound: PartitionBound,
        values: &[crate::sql::types::Datum],
        txid: u32,
    ) -> Result<bool, SqlError> {
        let Some(PartitionScheme {
            strategy,
            keys,
            n_keys,
        }) = self.table_def(parent, txid).partition.scheme
        else {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INTERNAL_ERROR,
                "partition parent is not partitioned"
            ));
        };
        if !matches!(bound, PartitionBound::Default) {
            return partition_bound_matches(strategy, keys, n_keys, bound, values);
        }
        for sibling in 0..self.table_count() {
            if sibling == child || !self.table(sibling).visible_to(txid) {
                continue;
            }
            let Some(PartitionAttachment {
                parent: sibling_parent,
                bound,
                ..
            }) = self.table_def(sibling, txid).partition.attachment
            else {
                continue;
            };
            if usize::from(sibling_parent) == parent
                && !matches!(bound, PartitionBound::Default)
                && partition_bound_matches(strategy, keys, n_keys, bound, values)?
            {
                return Ok(false);
            }
        }
        Ok(true)
    }

    /// Expands a logical relation through both ordinary inheritance and
    /// partition attachment without allocating. A non-partitioned relation
    /// contributes its own rows before its descendants; partitioned relations
    /// contribute only their leaves. The caller supplies bounded storage sized
    /// from the configured table catalog.
    pub fn relation_leaf_slots(
        &self,
        root: usize,
        txid: u32,
        out: &mut [usize],
    ) -> Result<usize, SqlError> {
        fn visit(
            storage: &Storage,
            root: usize,
            txid: u32,
            out: &mut [usize],
            n: &mut usize,
        ) -> Result<(), SqlError> {
            if out[..*n].contains(&root) {
                return Ok(());
            }
            if !storage.table_def(root, txid).partition.is_partitioned() {
                if *n == out.len() {
                    return Err(sql_err!(
                        crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "relation scan exceeds configured table capacity"
                    ));
                }
                out[*n] = root;
                *n += 1;
            }
            for child in 0..storage.table_count() {
                if !storage.relation_visible_to_current_session(child, txid) {
                    continue;
                }
                let child_def = storage.table_def(child, txid);
                let partition_child = child_def.partition.attachment.is_some_and(|attachment| {
                    usize::from(attachment.parent) == root && attachment.state.routable()
                });
                if !partition_child && !child_def.inheritance.contains(root) {
                    continue;
                }
                visit(storage, child, txid, out, n)?;
            }
            Ok(())
        }
        let mut n = 0;
        visit(self, root, txid, out, &mut n)?;
        Ok(n)
    }

    /// Routes writes by partition bounds; scans use `relation_leaf_slots`.
    pub fn partition_leaf_slots(
        &self,
        root: usize,
        txid: u32,
        out: &mut [usize],
    ) -> Result<usize, SqlError> {
        fn visit(
            storage: &Storage,
            root: usize,
            txid: u32,
            out: &mut [usize],
            n: &mut usize,
        ) -> Result<(), SqlError> {
            let mut found = false;
            for child in 0..storage.table_count() {
                if !storage.relation_visible_to_current_session(child, txid) {
                    continue;
                }
                let Some(PartitionAttachment { parent, state, .. }) =
                    storage.table_def(child, txid).partition.attachment
                else {
                    continue;
                };
                if usize::from(parent) != root || !state.routable() {
                    continue;
                }
                found = true;
                visit(storage, child, txid, out, n)?;
            }
            if !found && !storage.table_def(root, txid).partition.is_partitioned() {
                if *n == out.len() {
                    return Err(sql_err!(
                        crate::sql::eval::sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "partition scan exceeds configured table capacity"
                    ));
                }
                out[*n] = root;
                *n += 1;
            }
            Ok(())
        }
        let mut n = 0;
        visit(self, root, txid, out, &mut n)?;
        Ok(n)
    }

    /// Whether a relation has a direct partition or ordinary-inheritance
    /// descendant visible to the current session and transaction.
    pub fn relation_has_descendants(&self, root: usize, txid: u32) -> bool {
        (0..self.table_count()).any(|child| {
            self.relation_visible_to_current_session(child, txid)
                && (self
                    .table_def(child, txid)
                    .partition
                    .attachment
                    .is_some_and(|attachment| usize::from(attachment.parent) == root)
                    || self.table_def(child, txid).inheritance.contains(root))
        })
    }

    /// Whether `table` is a physical descendant of `ancestor` in the catalog
    /// snapshot. Attachment slots are typed and acyclic at DDL time, so this
    /// walk cannot reinterpret an unrelated table as part of the hierarchy.
    pub(crate) fn partition_descends_from(
        &self,
        mut table: usize,
        ancestor: usize,
        txid: u32,
    ) -> bool {
        while let Some(attachment) = self.table_def(table, txid).partition.attachment {
            table = usize::from(attachment.parent);
            if table == ancestor {
                return true;
            }
        }
        false
    }

    /// Whether `table` is an ordinary-inheritance or partition descendant of
    /// `ancestor` in the visible catalog. The bounded depth guard turns a
    /// corrupted durable cycle into a false relation instead of an unbounded
    /// recovery or scan walk; DDL validates and prevents that state normally.
    pub(crate) fn relation_descends_from(&self, table: usize, ancestor: usize, txid: u32) -> bool {
        fn visit(
            storage: &Storage,
            table: usize,
            ancestor: usize,
            txid: u32,
            depth: usize,
        ) -> bool {
            if depth == storage.table_count() {
                return false;
            }
            let definition = storage.table_def(table, txid);
            if definition
                .partition
                .attachment
                .is_some_and(|attachment| usize::from(attachment.parent) == ancestor)
                || definition.inheritance.contains(ancestor)
            {
                return true;
            }
            if let Some(attachment) = definition.partition.attachment
                && visit(
                    storage,
                    usize::from(attachment.parent),
                    ancestor,
                    txid,
                    depth + 1,
                )
            {
                return true;
            }
            definition
                .inheritance
                .parents_ref()
                .iter()
                .copied()
                .any(|parent| visit(storage, usize::from(parent), ancestor, txid, depth + 1))
        }
        table != ancestor
            && self.relation_visible_to_current_session(table, txid)
            && visit(self, table, ancestor, txid, 0)
    }

    /// Finds the physical owner of a row identity emitted while scanning a
    /// logical partitioned relation. Row identifiers are cluster-wide, so the
    /// search cannot confuse identically numbered rows from two leaves.
    pub fn partition_row_owner(
        &self,
        root: usize,
        rowid: u64,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        for candidate in 0..self.table_count() {
            if !self.table(candidate).visible_to(txid)
                || self.table_def(candidate, txid).partition.is_partitioned()
                || self.row_state(candidate, rowid)?.is_none()
            {
                continue;
            }
            let mut current = candidate;
            loop {
                if current == root {
                    return Ok(Some(candidate));
                }
                let Some(PartitionAttachment { parent, state, .. }) =
                    self.table_def(current, txid).partition.attachment
                else {
                    break;
                };
                if !state.routable() {
                    break;
                }
                current = usize::from(parent);
            }
        }
        Ok(None)
    }

    /// Clears only table images captured by a published checkpoint.
    pub fn clear_dirty_through(&mut self, generations: &[u64]) {
        for (slot, t) in self.tables.iter_mut().enumerate() {
            if generations.get(slot).copied() == Some(t.generation) {
                t.dirty = false;
                for (_, state) in t.rows.iter_mut() {
                    state.checkpoint_change_lsn = 0;
                }
            }
            t.statistics_dirty = false;
            t.statistics_wal_dirty = false;
        }
    }

    /// Rewrites the row heap so it contains only live row images
    /// (committed and pending alike), in ascending offset order, repointing
    /// every table's map. Reclaims the garbage left by updates and deletes;
    /// runs at checkpoint. `scratch` must hold every live image.
    pub(crate) fn compact_heap(
        &mut self,
        scratch: &mut FixedVec<(u32, u64, RowHeapImage, RowLoc)>,
    ) -> Result<(), SqlError> {
        scratch.clear();
        let row_versions = self.row_versions.exclusive();
        for (index, table) in self.tables.iter().enumerate() {
            // A transaction may have inserted rows into its pending CREATE
            // before a concurrent checkpoint. Those bytes are private, not
            // garbage: preserve them even though the committed table image is
            // not live yet. A genuinely dead slot has neither committed nor
            // pending existence.
            if !table.live && table.pending_ddl.is_none() {
                continue;
            }
            for (rowid, state) in table.rows.iter() {
                let overflow = |e| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "heap compaction scratch overflow: {}",
                        e
                    )
                };
                if let Some(RowHome::Heap(loc)) = state.committed {
                    scratch
                        .push((index as u32, rowid, RowHeapImage::Committed, loc))
                        .map_err(overflow)?;
                }
                let mut history_slot = state.history.tail;
                while let Some(slot) = history_slot {
                    let entry = &row_versions.committed_row_versions[slot];
                    if let Some(RowHome::Heap(loc)) = entry.version.home {
                        scratch
                            .push((index as u32, rowid, RowHeapImage::History(slot), loc))
                            .map_err(overflow)?;
                    }
                    history_slot = entry.previous;
                }
                let mut pending_slot = state.pending.tail;
                while let Some(slot) = pending_slot {
                    let entry = &row_versions.pending_row_versions[slot];
                    if let Some(loc) = entry.change.loc {
                        scratch
                            .push((index as u32, rowid, RowHeapImage::Pending(slot), loc))
                            .map_err(overflow)?;
                    }
                    pending_slot = entry.previous;
                }
            }
        }
        // Moving rows in ascending source order means every copy target is
        // at or below its source — copy_within stays safe.
        scratch
            .as_mut_slice()
            .sort_unstable_by_key(|(_, _, _, loc)| loc.offset);
        let mut write_at = 0usize;
        let mut prior_alias: Option<(RowLoc, RowLoc)> = None;
        for i in 0..scratch.len() {
            let (table_index, rowid, image, loc) = scratch[i];
            let len = loc.len as usize;
            let src = loc.offset as usize;
            let new_loc = if let Some((prior, relocated)) = prior_alias
                && prior == loc
            {
                relocated
            } else {
                debug_assert!(write_at <= src, "targets never overtake sources");
                if src != write_at {
                    self.heap.buffer.copy_within(src..src + len, write_at);
                }
                let relocated = RowLoc {
                    offset: write_at as u32,
                    len: loc.len,
                };
                write_at += len;
                prior_alias = Some((loc, relocated));
                relocated
            };
            match image {
                RowHeapImage::Committed => {
                    self.tables[table_index as usize]
                        .rows
                        .get_mut(&rowid)
                        .expect("scratch entries come from the maps")
                        .committed = Some(RowHome::Heap(new_loc));
                }
                RowHeapImage::History(slot) => {
                    row_versions.committed_row_versions[slot].version.home =
                        Some(RowHome::Heap(new_loc));
                }
                RowHeapImage::Pending(slot) => {
                    row_versions.pending_row_versions[slot].change.loc = Some(new_loc);
                }
            }
        }
        self.heap.used = write_at;
        Ok(())
    }

    /// Records an uncommitted change to a row. Returns whether this is the
    /// transaction's first touch of the row (the caller then remembers it
    /// for commit/rollback). A conflicting transaction becomes a wait-graph
    /// edge; the protocol parks and retries after the owner ends.
    pub fn write_pending(
        &mut self,
        table_index: usize,
        rowid: u64,
        txid: u32,
        cid: u32,
        loc: Option<RowLoc>,
    ) -> Result<Option<Option<RowLoc>>, SqlError> {
        self.write_pending_inner(table_index, rowid, txid, cid, loc, true)
    }

    /// Row rewrites and WAL reconstruction use the same MVCC transition but
    /// are not executor INSERT/UPDATE/DELETE operations.
    pub(crate) fn write_pending_untracked(
        &mut self,
        table_index: usize,
        rowid: u64,
        txid: u32,
        cid: u32,
        loc: Option<RowLoc>,
    ) -> Result<Option<Option<RowLoc>>, SqlError> {
        self.write_pending_inner(table_index, rowid, txid, cid, loc, false)
    }

    fn write_pending_inner(
        &mut self,
        table_index: usize,
        rowid: u64,
        txid: u32,
        cid: u32,
        loc: Option<RowLoc>,
        track_statistics: bool,
    ) -> Result<Option<Option<RowLoc>>, SqlError> {
        if let Some(owner) = self.tables[table_index]
            .pending_def_txid
            .filter(|owner| *owner != txid)
        {
            self.wait_for_transaction(txid, owner)?;
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for a concurrent table definition change"
            ));
        }
        let oldest_snapshot = self.oldest_snapshot();
        let conflicting_owner = self.resident_row_state(table_index, rowid)
            .and_then(|state| state.locked_by_other(txid));
        if let Some(owner) = conflicting_owner {
            self.wait_for_transaction(txid, owner)?;
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for a concurrent row update"
            ));
        }
        let existed = match self.resident_row_state(table_index, rowid) {
            Some(state) => state.visible_at(txid, SNAPSHOT_ALL, u64::MAX).flatten().is_some(),
            None => self
                .spill_probe_at(table_index, rowid, u64::MAX)?
                .is_some_and(|version| version.len.is_some()),
        };
        if let Some(state) = self.tables[table_index].rows.get(&rowid) {
            let (changed_columns, changes_existence) = self.pending_change_footprint(
                table_index,
                rowid,
                state.committed,
                loc,
                txid,
                track_statistics,
            )?;
            {
                let row_versions = self.row_versions.exclusive();
                if let Some(slot) = state.pending.tail
                    && row_versions.pending_row_versions[slot].change.cid == cid
                {
                    let last = &mut row_versions.pending_row_versions[slot].change;
                    let prior = Some(last.loc);
                    last.loc = loc;
                    // Same-command undo retains only the prior location. Keep a
                    // conservative union of every attempted image so restoring a
                    // prior location can over-invalidate but can never lose an
                    // index dependency that the restored image changed.
                    last.changed_columns |= changed_columns;
                    last.changes_existence |= changes_existence;
                    if track_statistics {
                        self.record_relation_write(txid, table_index, existed, loc.is_some())?;
                    }
                    return Ok(prior);
                }
            }
            {
                let row_versions = self.row_versions.exclusive();
                let (tables, versions) =
                    (&mut self.tables, &mut row_versions.committed_row_versions);
                let state = tables[table_index]
                    .rows
                    .get_mut(&rowid)
                    .expect("row state was just observed");
                prune_committed_history(versions, &mut state.history, oldest_snapshot);
            }
            let state = self.tables[table_index]
                .rows
                .get(&rowid)
                .expect("row state was just observed");
            if oldest_snapshot.is_some()
                && state.pending.is_none()
                && (state.committed.is_some() || state.committed_lsn != 0)
                && state.history.len() == self.max_row_versions_per_row
            {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "active snapshot history for row {} reached max_row_versions_per_row ({})",
                    rowid,
                    self.max_row_versions_per_row
                ));
            }
            let row_versions = self.row_versions.exclusive();
            let (tables, versions) = (&mut self.tables, &mut row_versions.pending_row_versions);
            let state = tables[table_index]
                .rows
                .get_mut(&rowid)
                .expect("row state was just observed");
            push_pending_version(
                versions,
                &mut state.pending,
                self.max_row_versions_per_row,
                PendingChange {
                    txid,
                    cid,
                    loc,
                    changed_columns,
                    changes_existence,
                },
            )?;
            if track_statistics {
                self.record_relation_write(txid, table_index, existed, loc.is_some())?;
            }
            return Ok(None);
        }
        // An absent entry no longer means an absent row: the spill list may
        // hold its committed image, and that image must ride into the entry
        // — a pending change with `committed: None` would hide the old
        // value from uniqueness scans and resurrect wrongly on rollback.
        let committed = self
            .spill_probe_at(table_index, rowid, u64::MAX)?
            .and_then(|version| {
                version.len.map(|len| RowHome::Spilled {
                    len,
                    sst: version.member,
                    commit_lsn: version.commit_lsn,
                })
            });
        let committed_lsn = committed.map_or(0, |home| match home {
            RowHome::Heap(_) => 0,
            RowHome::Spilled { commit_lsn, .. } => commit_lsn,
        });
        let (changed_columns, changes_existence) = self.pending_change_footprint(
            table_index,
            rowid,
            committed,
            loc,
            txid,
            track_statistics,
        )?;
        let table = &mut self.tables[table_index];
        if table.rows.len() == table.rows.capacity() {
            // Entries the spill lists reproduce are droppable on demand.
            self.evict_redundant_entries(table_index);
            if self.tables[table_index].rows.len() == self.tables[table_index].rows.capacity() {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "table row limit reached ({} rows in memtable)",
                    self.tables[table_index].rows.capacity()
                ));
            }
        }
        let mut pending = PendingVersions::empty();
        let row_versions = self.row_versions.exclusive();
        push_pending_version(
            &mut row_versions.pending_row_versions,
            &mut pending,
            self.max_row_versions_per_row,
            PendingChange {
                txid,
                cid,
                loc,
                changed_columns,
                changes_existence,
            },
        )?;
        self.tables[table_index]
            .rows
            .insert(
                rowid,
                RowState {
                    committed,
                    committed_lsn,
                    checkpoint_change_lsn: 0,
                    history: CommittedHistory::empty(),
                    pending,
                },
            )
            .expect("capacity checked above");
        if track_statistics {
            self.record_relation_write(txid, table_index, existed, loc.is_some())?;
        }
        Ok(None)
    }

    /// Compares canonical physical column payloads without allocating or
    /// decoding variable-width values. The comparison happens on the
    /// fallible, pre-commit write path: commit itself must never discover that
    /// an object-resident prior row needs I/O after its WAL is durable.
    fn pending_change_footprint(
        &self,
        table_index: usize,
        rowid: u64,
        committed: Option<RowHome>,
        pending: Option<RowLoc>,
        txid: u32,
        track_statistics: bool,
    ) -> Result<(ColumnSet, bool), SqlError> {
        let columns = self.tables[table_index].def.n_columns;
        let all_columns = ColumnSet::all(columns);
        // Row rewrites and changes under a transaction-private definition can
        // use a different physical schema. Their enforcers are rebuilt at the
        // DDL boundary, so conservative invalidation is both sufficient and
        // avoids comparing unlike encodings.
        if !track_statistics || self.tables[table_index].pending_def_txid == Some(txid) {
            return Ok((all_columns, committed.is_some() != pending.is_some()));
        }
        let (Some(committed), Some(pending)) = (committed, pending) else {
            return Ok((all_columns, committed.is_some() != pending.is_some()));
        };
        let mut schema = [ColType::Bool; MAX_COLUMNS];
        self.tables[table_index].def.schema(&mut schema);
        let pending_bytes = self.heap.get(pending);
        let mut pending_payloads = [&[][..]; MAX_COLUMNS];
        let mut pending_nulls = [false; MAX_COLUMNS];
        rowenc::encoded_columns(
            pending_bytes,
            &schema[..columns],
            &mut pending_payloads,
            &mut pending_nulls,
        )?;
        self.with_row_bytes(table_index, rowid, committed, |committed_bytes| {
            let mut committed_payloads = [&[][..]; MAX_COLUMNS];
            let mut committed_nulls = [false; MAX_COLUMNS];
            rowenc::encoded_columns(
                committed_bytes,
                &schema[..columns],
                &mut committed_payloads,
                &mut committed_nulls,
            )?;
            let mut changed = ColumnSet::EMPTY;
            for column in 0..columns {
                if committed_nulls[column] != pending_nulls[column]
                    || committed_payloads[column] != pending_payloads[column]
                {
                    changed.insert(column);
                }
            }
            Ok((changed, false))
        })
    }

    /// Drops map entries the spill lists reproduce exactly — committed,
    /// spilled, no pending change. A `Spilled` entry's member is the list's
    /// newest mention of its rowid (installs are the only thing that moves
    /// one, and they run at publish), so the merged walk and the point
    /// probe synthesize the identical state after the entry is gone. This
    /// is what unbinds a table's row count from `table_rows`: the map holds
    /// the working set, the bucket holds the rest.
    pub fn evict_redundant_entries(&mut self, slot: usize) {
        let table = &mut self.tables[slot];
        if table.n_spill_ssts == 0 {
            return;
        }
        loop {
            let mut batch = [0u64; 512];
            let mut n = 0usize;
            for (rowid, state) in table.rows.iter() {
                if Self::redundant_spilled_row_state(&state) {
                    batch[n] = rowid;
                    n += 1;
                    if n == batch.len() {
                        break;
                    }
                }
            }
            if n == 0 {
                return;
            }
            for &rowid in &batch[..n] {
                table.rows.remove(&rowid);
            }
        }
    }

    /// Whether any live table's overlay is at least half full — the map's
    /// analogue of heap pressure. Rows are counted against entries, not
    /// bytes: a table of tiny rows fills its map long before its heap.
    pub fn map_pressure(&self) -> bool {
        self.tables
            .iter()
            .any(|t| t.live && t.n_spill_ssts > 0 && t.rows.len() * 100 >= t.rows.capacity() * 50)
    }

    pub(crate) fn temporary_map_pressure(&self) -> bool {
        self.tables.iter().any(|table| {
            table.live
                && table.def.persistence == RelationPersistence::Temporary
                && table.dirty
                && table.rows.len() * 100 >= table.rows.capacity() * 50
        })
    }

    /// Starts an object flush before the resident safety window can fill.
    /// Published versions are then read through the immutable SST forest and
    /// the resident side chain is released.
    pub fn history_pressure(&self) -> bool {
        let maximum = self.max_row_versions_per_row;
        self.tables.iter().any(|table| {
            table.live
                && table
                    .rows
                    .iter()
                    .any(|(_, state)| state.history.len().saturating_add(2) >= maximum)
        })
    }

    /// A successful manifest publish made every resident historical image
    /// reachable through the table's installed versioned SST list.
    pub fn release_durable_histories(&mut self) {
        let row_versions = self.row_versions.exclusive();
        let (tables, versions) = (&mut self.tables, &mut row_versions.committed_row_versions);
        for table in tables
            .iter_mut()
            .filter(|table| table.live && table.def.persistence != RelationPersistence::Temporary)
        {
            for (_, state) in table.rows.iter_mut() {
                prune_committed_history(versions, &mut state.history, None);
            }
        }
    }

    /// The map-occupancy pass after a publish: any table whose overlay is
    /// half full sheds its redundant entries.
    pub fn evict_entries(&mut self) {
        for i in 0..self.tables.len() {
            let table = &self.tables[i];
            if !table.live
                || table.n_spill_ssts == 0
                || table.rows.len() * 100 < table.rows.capacity() * 50
            {
                continue;
            }
            self.evict_redundant_entries(i);
        }
    }

    /// Restores a row's pending change to a prior image (for `ROLLBACK TO
    /// SAVEPOINT` and error unwinding). `prior` is what `write_pending`
    /// returned: `None` clears the pending entirely (removing the row if it
    /// was never committed); `Some(loc)` reinstates a pending change.
    pub fn restore_pending(
        &mut self,
        table_index: usize,
        rowid: u64,
        txid: u32,
        prior: Option<Option<RowLoc>>,
    ) {
        let Some(state) = self.tables[table_index].rows.get(&rowid) else {
            return;
        };
        // Only touch a pending change this transaction owns (or an empty slot).
        if let Some(p) = pending_last(
            &self.row_versions.read().pending_row_versions,
            state.pending,
        ) && p.txid != txid
        {
            return;
        }
        match prior {
            None => {
                let row_versions = self.row_versions.exclusive();
                let (tables, versions) = (&mut self.tables, &mut row_versions.pending_row_versions);
                let state = tables[table_index]
                    .rows
                    .get_mut(&rowid)
                    .expect("row state was just observed");
                pop_pending_version(versions, &mut state.pending);
                if (state.committed.is_none()
                    && state.history.is_empty()
                    && state.pending.is_none())
                    || Self::redundant_spilled_row_state(state)
                {
                    tables[table_index].rows.remove(&rowid);
                }
            }
            Some(loc) => {
                if let Some(slot) = state.pending.tail {
                    self.row_versions.exclusive().pending_row_versions[slot]
                        .change
                        .loc = loc;
                }
            }
        }
    }

    /// Removes a committed row outright (journal replay of a DELETE), retaining
    /// the shadowing marker a later delta checkpoint emits as a tombstone.
    pub fn remove_committed(
        &mut self,
        table_index: usize,
        rowid: u64,
        commit_lsn: u64,
    ) -> Result<(), SqlError> {
        if self.tables[table_index].n_spill_ssts == 0 {
            if self.remove_row_state(table_index, rowid).is_some() {
                self.mark_value_bindings_changed_at(table_index, commit_lsn);
                self.tables[table_index].mark_dirty();
            }
            return Ok(());
        }
        // The spill list may hold this row, so the delete must both
        // tombstone (for the next flush) and leave a shadowing marker (for
        // reads until then) — same discipline as a committed DELETE.
        self.remove_row_state(table_index, rowid);
        let table = &mut self.tables[table_index];
        table
            .rows
            .insert(
                rowid,
                RowState {
                    committed: None,
                    committed_lsn: commit_lsn,
                    checkpoint_change_lsn: commit_lsn,
                    history: CommittedHistory::empty(),
                    pending: PendingVersions::empty(),
                },
            )
            .map_err(|error| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "journal replay overflows {}",
                    error.what
                )
            })?;
        self.mark_value_bindings_changed_at(table_index, commit_lsn);
        let table = &mut self.tables[table_index];
        table.mark_dirty();
        Ok(())
    }

    /// Promotes a row's pending change to committed. The WAL record must
    /// already be durable.
    pub fn commit_row(&mut self, table_index: usize, rowid: u64, txid: u32, commit_lsn: u64) {
        // Read the transition without holding a mutable borrow.
        let (old_committed, old_lsn, pending) = {
            let Some(state) = self.tables[table_index].rows.get(&rowid) else {
                return;
            };
            match pending_last(
                &self.row_versions.read().pending_row_versions,
                state.pending,
            ) {
                Some(p) if p.txid == txid => (state.committed, state.committed_lsn, p),
                _ => return,
            }
        };
        let new_loc = pending.loc;
        // Maintain the value indexes: drop the old committed value's key, add
        // the new one. The row images are still readable (committed not yet
        // repointed, new bytes already in the heap).
        self.maintain_indexes_on_commit(table_index, rowid, new_loc);
        let n_enforcers = self.tables[table_index].n_enforcers;
        for enforcer in self.tables[table_index].enforcers[..n_enforcers]
            .iter_mut()
            .flatten()
        {
            if pending.changes_existence
                || enforcer.dependency_mask.intersects(pending.changed_columns)
            {
                enforcer.durable_dirty = true;
                enforcer.durable_dirty_lsn = commit_lsn;
            }
        }

        let retain_history = !self.snapshot_state().active.is_empty();
        {
            let row_versions = self.row_versions.exclusive();
            let (tables, committed_versions, pending_versions) = (
                &mut self.tables,
                &mut row_versions.committed_row_versions,
                &mut row_versions.pending_row_versions,
            );
            let state = tables[table_index]
                .rows
                .get_mut(&rowid)
                .expect("row present after read");
            if retain_history && (old_committed.is_some() || old_lsn != 0) {
                push_committed_version(
                    committed_versions,
                    &mut state.history,
                    self.max_row_versions_per_row,
                    CommittedVersion {
                        home: old_committed,
                        lsn: old_lsn,
                    },
                )
                .expect("write_pending reserved historical-version capacity");
            } else if !retain_history {
                prune_committed_history(committed_versions, &mut state.history, None);
            }
            state.committed = new_loc.map(RowHome::Heap);
            state.committed_lsn = commit_lsn;
            state.checkpoint_change_lsn = commit_lsn;
            clear_pending_versions(pending_versions, &mut state.pending);
        }
        let table = &mut self.tables[table_index];
        let state = table.rows.get(&rowid).expect("row present after commit");
        if state.committed.is_none() {
            // A rowid that ever reached an SST — even if its latest version was
            // heap-resident — must tombstone, or a cold start resurrects the
            // SST's version. And until that tombstone is *flushed*, the entry
            // itself stays behind as a marker (`committed: None, pending:
            // None`): the merged walk treats any entry as shadowing the spill
            // list, so the marker is what keeps the deleted row invisible right
            // now. `clear_tombstones` purges the markers once an install has
            // made the SSTs themselves say deleted.
            if table.n_spill_ssts == 0 && state.history.is_empty() {
                table.rows.remove(&rowid);
            }
        }
        table.mark_dirty();
    }

    /// Promotes a row rewritten under a pending table definition. Value
    /// indexes are rebuilt once after every row and the definition are
    /// promoted, because the old and new encodings cannot share an index
    /// decoder.
    pub fn commit_rewritten_row(
        &mut self,
        table_index: usize,
        rowid: u64,
        txid: u32,
        commit_lsn: u64,
    ) {
        let new_loc = {
            let Some(state) = self.tables[table_index].rows.get(&rowid) else {
                return;
            };
            match pending_last(
                &self.row_versions.read().pending_row_versions,
                state.pending,
            ) {
                Some(pending) if pending.txid == txid => pending.loc,
                _ => return,
            }
        };
        {
            let row_versions = self.row_versions.exclusive();
            let (tables, committed_versions, pending_versions) = (
                &mut self.tables,
                &mut row_versions.committed_row_versions,
                &mut row_versions.pending_row_versions,
            );
            let state = tables[table_index]
                .rows
                .get_mut(&rowid)
                .expect("row present after read");
            // Definition rewrites are rejected while a historical snapshot
            // is active, so no old-schema row image can be retained here.
            prune_committed_history(committed_versions, &mut state.history, None);
            state.committed = new_loc.map(RowHome::Heap);
            state.committed_lsn = commit_lsn;
            state.checkpoint_change_lsn = commit_lsn;
            clear_pending_versions(pending_versions, &mut state.pending);
        }
        let table = &mut self.tables[table_index];
        let state = table.rows.get(&rowid).expect("row present after rewrite");
        if state.committed.is_none() && table.n_spill_ssts == 0 {
            table.rows.remove(&rowid);
        }
        self.mark_value_bindings_rebuild_at(table_index, commit_lsn);
        let table = &mut self.tables[table_index];
        table.mark_dirty();
    }

    /// Decodes the row at `home` and hashes every enforcer key whose values are
    /// all non-NULL, writing `(enforcer_index, hash)` for each into `out`.
    /// NULL keys remain in durable ordered generations but cannot satisfy an
    /// equality probe, so the resident exact map deliberately omits them.
    fn row_enforcer_hashes(
        &self,
        table_index: usize,
        rowid: u64,
        home: RowHome,
        out: &mut [(usize, u64); MAX_VALUE_ENFORCERS],
    ) -> Result<usize, SqlError> {
        let mut schema = [ColType::Bool; MAX_COLUMNS];
        let n_columns = self.tables[table_index].def.schema(&mut schema);
        let arena = self
            .index_arena
            .lock()
            .expect("index expression arena lock poisoned");
        let mark = arena.mark();
        let result = self.with_row_bytes(table_index, rowid, home, |bytes| {
            let mut values = [Datum::Null; MAX_COLUMNS];
            rowenc::decode(bytes, &schema[..n_columns], &mut values)?;
            self.values_enforcer_hashes(&arena, table_index, &values[..n_columns], out)
        });
        // SAFETY: callers receive only hashes and binding ordinals; expression
        // evaluation cannot retain values allocated above this row-local mark.
        unsafe { arena.rewind_to(mark) };
        result
    }

    fn values_enforcer_hashes(
        &self,
        arena: &Arena,
        table_index: usize,
        values: &[Datum],
        out: &mut [(usize, u64); MAX_VALUE_ENFORCERS],
    ) -> Result<usize, SqlError> {
        let n_enforcers = self.tables[table_index].n_enforcers;
        let mut n_out = 0;
        for binding in 0..n_enforcers {
            self.with_value_binding_values(
                arena,
                table_index,
                binding,
                values,
                |key, _, enforcer| {
                    let Some(key) = key else { return Ok(()) };
                    if key.iter().any(Datum::is_null) {
                        return Ok(());
                    }
                    let compact =
                        core::array::from_fn::<u16, MAX_INDEX_COLS, _>(|index| index as u16);
                    out[n_out] = (
                        binding,
                        hash_key_collated(
                            key,
                            &compact[..enforcer.n_cols],
                            &enforcer.collations[..enforcer.n_cols],
                        ),
                    );
                    n_out += 1;
                    Ok(())
                },
            )?;
        }
        Ok(n_out)
    }

    fn with_value_binding_key<R>(
        &self,
        table_index: usize,
        binding: usize,
        rowid: u64,
        home: RowHome,
        visit: impl FnOnce(Option<&[Datum]>, &[Datum], &Enforcer) -> Result<R, SqlError>,
    ) -> Result<R, SqlError> {
        let table = &self.tables[table_index];
        let mut schema = [ColType::Bool; MAX_COLUMNS];
        let n_columns = table.def.schema(&mut schema);
        let arena = self
            .index_arena
            .lock()
            .expect("index expression arena lock poisoned");
        let mark = arena.mark();
        let result = self.with_row_bytes(table_index, rowid, home, |bytes| {
            let mut values = [Datum::Null; MAX_COLUMNS];
            rowenc::decode(bytes, &schema[..n_columns], &mut values)?;
            self.with_value_binding_values(
                &arena,
                table_index,
                binding,
                &values[..n_columns],
                visit,
            )
        });
        // SAFETY: `visit` cannot return a borrowed key, and all expression
        // values have been encoded or hashed before this row-local rewind.
        unsafe { arena.rewind_to(mark) };
        result
    }

    fn with_value_binding_values<R>(
        &self,
        arena: &Arena,
        table_index: usize,
        binding: usize,
        values: &[Datum],
        visit: impl FnOnce(Option<&[Datum]>, &[Datum], &Enforcer) -> Result<R, SqlError>,
    ) -> Result<R, SqlError> {
        let table = &self.tables[table_index];
        let enforcer = table.enforcers[binding].expect("binding");
        let mut key = [Datum::Null; MAX_INDEX_COLS];
        let index;
        if let Some(created_at) = enforcer.index_created_at {
            index = self
                .index_catalog()
                .iter()
                .find(|index| {
                    index.ddl_state != CatalogDdlState::Absent
                        && index.created_at == created_at
                        && index.database == table.database
                })
                .copied()
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::INTERNAL_ERROR,
                        "physical index binding has no catalog definition"
                    )
                })?;
            if let Some(source) = index.predicate {
                let predicate = crate::sql::parser::parse_expr(source.as_str(), arena)?;
                if !crate::sql::exec::constraints::index_predicate_matches(
                    self,
                    enforcer.evaluation_txid,
                    &table.def,
                    values,
                    predicate,
                    arena,
                )? {
                    return visit(None, values, &enforcer);
                }
            }
            let mut expressions = [None; MAX_INDEX_COLS];
            for (position, source) in index.expressions.iter().enumerate().take(index.n_cols) {
                if let Some(source) = source {
                    expressions[position] =
                        Some(crate::sql::parser::parse_expr(source.as_str(), arena)?);
                }
            }
            key = crate::sql::exec::constraints::index_key_values(
                self,
                enforcer.evaluation_txid,
                &table.def,
                values,
                &index.columns[..index.n_cols],
                &expressions[..index.n_cols],
                arena,
            )?;
        } else {
            for (position, column) in enforcer.columns().iter().enumerate() {
                key[position] = values[*column as usize];
            }
        }
        visit(Some(&key[..enforcer.n_cols]), values, &enforcer)
    }

    /// The value-index maintenance for one committed row transition: remove the
    /// old entry by row identity, then insert the new value's key. Removing by
    /// identity keeps publication independent of object-store availability:
    /// the old row may be object-resident, while the new encoded bytes are
    /// already in the heap. Physical headroom guarantees the insert fits.
    fn maintain_indexes_on_commit(
        &mut self,
        table_index: usize,
        rowid: u64,
        new_loc: Option<RowLoc>,
    ) {
        if self.tables[table_index].n_enforcers == 0 {
            return;
        }
        let mut inserts = [(0usize, 0u64); MAX_VALUE_ENFORCERS];
        let n_inserts = match new_loc {
            Some(loc) => self
                .row_enforcer_hashes(table_index, rowid, RowHome::Heap(loc), &mut inserts)
                .expect("new row decodes"),
            None => 0,
        };
        let mut slots = [u32::MAX; MAX_VALUE_ENFORCERS];
        for (i, s) in slots
            .iter_mut()
            .enumerate()
            .take(self.tables[table_index].n_enforcers)
        {
            *s = self.tables[table_index].enforcers[i]
                .expect("enforcer")
                .slot;
        }
        let pool = self
            .value_indexes
            .as_mut()
            .expect("value index pool present");
        for &slot in &slots[..self.tables[table_index].n_enforcers] {
            pool.get_mut(slot).remove_rowid(rowid);
        }
        for &(ei, hash) in &inserts[..n_inserts] {
            let index = pool.get_mut(slots[ei]);
            if index.insert(hash, rowid).is_err() {
                // This structure is an acceleration cache, not durable state.
                // Once it cannot represent the complete committed image, a
                // negative probe must fall through to the authoritative rows.
                index.mark_incomplete();
            }
        }
    }

    /// Probes the value cache for the indexed tuple covering exactly `columns`,
    /// visiting every candidate rowid whose key hashes to `hash`. Durable and
    /// overlay candidates carry their encoded key; hash-only resident-cache
    /// block-stack borrow and must use that key instead of reentering storage.
    /// Returns true only when the cache is complete, so a caller may trust a
    /// negative answer; false means the authoritative row store must be scanned.
    pub fn probe_value(
        &self,
        table_index: usize,
        columns: &[u16],
        hash: u64,
        visit: impl FnMut(u64, Option<&[u8]>) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some(i) = (0..table.n_enforcers).find(|index| {
            let enforcer = table.enforcers[*index].expect("enforcer present");
            enforcer.index_created_at.is_none() && enforcer.columns() == columns
        }) else {
            return Ok(false);
        };
        self.probe_value_binding(table_index, i, hash, visit)
    }

    pub(crate) fn probe_value_binding(
        &self,
        table_index: usize,
        i: usize,
        hash: u64,
        mut visit: impl FnMut(u64, Option<&[u8]>) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        if i < table.n_enforcers {
            let e = table.enforcers[i].expect("enforcer present");
            let index = self
                .value_indexes
                .as_ref()
                .expect("value index pool present")
                .get(e.slot);
            if index.is_complete() {
                let mut callback_error = None;
                index.probe(hash, |rowid| {
                    if callback_error.is_none()
                        && let Err(error) = visit(rowid, None)
                    {
                        callback_error = Some(error);
                    }
                });
                if let Some(error) = callback_error {
                    return Err(error);
                }
                return Ok(true);
            }
            let Some(handle) = e.durable else {
                return Ok(false);
            };
            if self.commit_snapshot() < handle.published_lsn {
                return Ok(false);
            }
            let Some(spill) = &self.spill else {
                return Ok(false);
            };
            let Some(mut scratch) = try_mutex_pool(
                spill
                    .value_scratch
                    .as_ref()
                    .expect("durable value indexes have reader scratch"),
                "persistent value scratch",
            ) else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "persistent value probes nested deeper than reader scratch"
                ));
            };
            let scratch = &mut *scratch;
            {
                let ValueIndexScratch { roster, data } = scratch;
                let mut callback_error = None;
                crate::store::ValueIndexReader::over(roster, data)
                    .probe(
                        &mut *spill
                            .blocks
                            .as_ref()
                            .expect("value-index generations are durable")
                            .lock()
                            .expect("block store lock poisoned"),
                        &handle,
                        hash,
                        |rowid, _, key| {
                            if callback_error.is_none()
                                && let Err(error) = visit(rowid, Some(key))
                            {
                                callback_error = Some(error);
                            }
                        },
                    )
                    .map_err(value_index_read_error)?;
                if let Some(error) = callback_error {
                    return Err(error);
                }
            }
            // The published generation is a complete base. Every later
            // committed change remains in the bounded resident overlay
            // until its replacement generation publishes.
            let mut hashes = [(0usize, 0u64); MAX_VALUE_ENFORCERS];
            for (rowid, state) in self.tables[table_index].rows.iter() {
                if state.committed_lsn <= handle.published_lsn {
                    continue;
                }
                let Some(home) = state.committed else {
                    continue;
                };
                let n = self.row_enforcer_hashes(table_index, rowid, home, &mut hashes)?;
                if hashes[..n]
                    .iter()
                    .any(|(binding, candidate)| *binding == i && *candidate == hash)
                {
                    let key_buffer = &mut scratch.roster;
                    let Some((key_len, _, _)) =
                        self.encode_value_binding_entry(table_index, i, rowid, home, key_buffer)?
                    else {
                        continue;
                    };
                    visit(rowid, Some(&key_buffer[..key_len]))?;
                }
            }
            return Ok(true);
        }
        Ok(false)
    }

    pub fn value_cache_complete(&self, table_index: usize, columns: &[u16]) -> bool {
        let table = &self.tables[table_index];
        (0..table.n_enforcers).any(|index| {
            let enforcer = table.enforcers[index].expect("enforcer present");
            enforcer.index_created_at.is_none()
                && enforcer.columns() == columns
                && self
                    .value_indexes
                    .as_ref()
                    .expect("value index pool present")
                    .get(enforcer.slot)
                    .is_complete()
        })
    }

    pub fn value_probe_complete(&self, table_index: usize, columns: &[u16]) -> bool {
        let table = &self.tables[table_index];
        (0..table.n_enforcers).any(|index| {
            let enforcer = table.enforcers[index].expect("enforcer present");
            enforcer.index_created_at.is_none()
                && enforcer.columns() == columns
                && (self
                    .value_indexes
                    .as_ref()
                    .expect("value index pool present")
                    .get(enforcer.slot)
                    .is_complete()
                    || enforcer
                        .durable
                        .is_some_and(|handle| self.commit_snapshot() >= handle.published_lsn))
        })
    }

    pub fn value_durable_complete(&self, table_index: usize, columns: &[u16]) -> bool {
        let table = &self.tables[table_index];
        (0..table.n_enforcers).any(|index| {
            let enforcer = table.enforcers[index].expect("enforcer present");
            enforcer.index_created_at.is_none()
                && enforcer.columns() == columns
                && enforcer
                    .durable
                    .is_some_and(|handle| self.commit_snapshot() >= handle.published_lsn)
        })
    }

    pub(crate) fn value_binding_for_index(
        &self,
        table_index: usize,
        created_at: u64,
    ) -> Option<usize> {
        let table = &self.tables[table_index];
        (0..table.n_enforcers).find(|binding| {
            table.enforcers[*binding]
                .is_some_and(|enforcer| enforcer.index_created_at == Some(created_at))
        })
    }

    fn brin_geometry(&self, index_slot: usize, txid: u32) -> Result<(u64, u64, u32), SqlError> {
        let index = self
            .index_visible_to(index_slot, txid)
            .ok_or_else(|| sql_err!(sqlstate::UNDEFINED_OBJECT, "index does not exist"))?;
        if index.method != crate::sql::ast::IndexAccessMethod::Brin
            || !matches!(index.mutable_for(txid).kind, IndexKind::Ordinary)
        {
            return Err(sql_err!(
                sqlstate::WRONG_OBJECT_TYPE,
                "\"{}\" is not a BRIN index",
                index.name_for(txid).as_str()
            ));
        }
        let created_at = index.created_at;
        let pages_per_range = index
            .mutable_for(txid)
            .options
            .pages_per_range
            .unwrap_or(128);
        let table = self
            .index_table_slot_to(index_slot, txid)
            .ok_or_else(|| sql_err!(sqlstate::UNDEFINED_OBJECT, "index table does not exist"))?;
        let rows = self.visible_row_count(table, txid)?;
        Ok(((rows as u64).div_ceil(128), created_at, pages_per_range))
    }

    fn brin_maintenance(&self) -> std::sync::MutexGuard<'_, BrinMaintenance> {
        self.brin_maintenance
            .lock()
            .expect("BRIN maintenance lock poisoned")
    }

    fn brin_entry_mut(
        maintenance: &mut BrinMaintenance,
        index_slot: usize,
        ranges_per_index: usize,
    ) -> (&mut BrinMaintenanceState, &mut [u64]) {
        let start = index_slot * ranges_per_index;
        let BrinMaintenance {
            states,
            unsummarized_ranges,
        } = maintenance;
        (
            &mut states[index_slot],
            &mut unsummarized_ranges[start..start + ranges_per_index],
        )
    }

    fn discover_brin_ranges(
        state: &mut BrinMaintenanceState,
        ranges: &mut [u64],
        pages: u64,
        created_at: u64,
        configured_pages_per_range: u32,
    ) -> Result<(), SqlError> {
        if state.index_created_at != created_at {
            let pages_per_range = u64::from(configured_pages_per_range);
            let covered_end = pages.max(1).div_ceil(pages_per_range) * pages_per_range;
            *state = BrinMaintenanceState {
                index_created_at: created_at,
                pages_per_range: configured_pages_per_range,
                summarized_until_page: covered_end,
                ..BrinMaintenanceState::EMPTY
            };
            ranges.fill(0);
            return Ok(());
        }
        let pages_per_range = u64::from(state.pages_per_range);
        debug_assert_ne!(pages_per_range, 0, "visible BRIN has build geometry");
        let covered_end = pages.max(1).div_ceil(pages_per_range) * pages_per_range;
        if covered_end <= state.summarized_until_page {
            return Ok(());
        }
        let additional = ((covered_end - state.summarized_until_page) / pages_per_range) as usize;
        if usize::from(state.count) + additional > ranges.len() {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "BRIN unsummarized ranges exceed the startup-bound limit ({})",
                ranges.len()
            ));
        }
        let mut range = state.summarized_until_page;
        while range < covered_end {
            ranges[usize::from(state.count)] = range;
            state.count += 1;
            range += pages_per_range;
        }
        state.summarized_until_page = covered_end;
        state.wal_dirty = true;
        Ok(())
    }

    pub(crate) fn brin_desummarize_range(
        &self,
        index_slot: usize,
        block: u64,
        txid: u32,
    ) -> Result<(), SqlError> {
        let (pages, created_at, pages_per_range) = self.brin_geometry(index_slot, txid)?;
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) = Self::brin_entry_mut(
            &mut maintenance,
            index_slot,
            self.brin_unsummarized_ranges_per_index,
        );
        Self::discover_brin_ranges(state, ranges, pages, created_at, pages_per_range)?;
        if block >= pages {
            return Ok(());
        }
        let pages_per_range = u64::from(state.pages_per_range);
        debug_assert_ne!(pages_per_range, 0, "visible BRIN has build geometry");
        let range = block / pages_per_range * pages_per_range;
        if ranges[..usize::from(state.count)].contains(&range) {
            return Ok(());
        }
        if usize::from(state.count) == ranges.len() {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "BRIN unsummarized ranges exceed the startup-bound limit ({})",
                ranges.len()
            ));
        }
        ranges[usize::from(state.count)] = range;
        state.count += 1;
        state.wal_dirty = true;
        Ok(())
    }

    pub(crate) fn brin_summarize_range(
        &self,
        index_slot: usize,
        block: u64,
        txid: u32,
    ) -> Result<i32, SqlError> {
        let (pages, created_at, pages_per_range) = self.brin_geometry(index_slot, txid)?;
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) = Self::brin_entry_mut(
            &mut maintenance,
            index_slot,
            self.brin_unsummarized_ranges_per_index,
        );
        Self::discover_brin_ranges(state, ranges, pages, created_at, pages_per_range)?;
        if block >= pages {
            return Ok(0);
        }
        let pages_per_range = u64::from(state.pages_per_range);
        debug_assert_ne!(pages_per_range, 0, "visible BRIN has build geometry");
        let range = block / pages_per_range * pages_per_range;
        let Some(position) = ranges[..usize::from(state.count)]
            .iter()
            .position(|candidate| *candidate == range)
        else {
            return Ok(0);
        };
        let last = usize::from(state.count) - 1;
        ranges[position] = ranges[last];
        ranges[last] = 0;
        state.count -= 1;
        state.wal_dirty = true;
        Ok(1)
    }

    pub(crate) fn brin_summarize_new_values(
        &self,
        index_slot: usize,
        txid: u32,
    ) -> Result<i32, SqlError> {
        let (pages, created_at, pages_per_range) = self.brin_geometry(index_slot, txid)?;
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) = Self::brin_entry_mut(
            &mut maintenance,
            index_slot,
            self.brin_unsummarized_ranges_per_index,
        );
        Self::discover_brin_ranges(state, ranges, pages, created_at, pages_per_range)?;
        let count = i32::from(state.count);
        if count != 0 {
            ranges.fill(0);
            state.count = 0;
            state.wal_dirty = true;
        }
        Ok(count)
    }

    pub(crate) fn brin_maintenance_state(&self, index_slot: usize) -> BrinMaintenanceState {
        self.brin_maintenance().states[index_slot]
    }

    pub(crate) fn brin_maintenance_image(
        &self,
        index_slot: usize,
    ) -> (BrinMaintenanceState, [u64; MAX_BRIN_UNSUMMARIZED_RANGES]) {
        let maintenance = self.brin_maintenance();
        let state = maintenance.states[index_slot];
        let start = index_slot * self.brin_unsummarized_ranges_per_index;
        let count = usize::from(state.count);
        let mut ranges = [0; MAX_BRIN_UNSUMMARIZED_RANGES];
        ranges[..count].copy_from_slice(&maintenance.unsummarized_ranges[start..start + count]);
        (state, ranges)
    }

    pub(crate) fn rebuild_brin_maintenance(
        &self,
        index_slot: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        let (pages, created_at, pages_per_range) = self.brin_geometry(index_slot, txid)?;
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) = Self::brin_entry_mut(
            &mut maintenance,
            index_slot,
            self.brin_unsummarized_ranges_per_index,
        );
        *state = BrinMaintenanceState {
            index_created_at: created_at,
            pages_per_range,
            summarized_until_page: pages.max(1).div_ceil(u64::from(pages_per_range))
                * u64::from(pages_per_range),
            wal_dirty: true,
            ..BrinMaintenanceState::EMPTY
        };
        ranges.fill(0);
        Ok(())
    }

    pub(crate) fn clear_brin_maintenance_dirty(&self, index_slot: usize) {
        self.brin_maintenance().states[index_slot].wal_dirty = false;
    }

    pub(crate) fn restore_brin_maintenance(
        &self,
        index_slot: usize,
        pages_per_range: u32,
        summarized_until_page: u64,
        ranges: &[u64],
    ) -> Result<(), SqlError> {
        let indexes = self.index_catalog();
        let index = indexes[index_slot];
        if index.method != crate::sql::ast::IndexAccessMethod::Brin
            || !(1..=131_072).contains(&pages_per_range)
            || summarized_until_page == 0
            || !summarized_until_page.is_multiple_of(u64::from(pages_per_range))
            || ranges.len() > self.brin_unsummarized_ranges_per_index
            || ranges.iter().enumerate().any(|(position, range)| {
                *range >= summarized_until_page
                    || !range.is_multiple_of(u64::from(pages_per_range))
                    || ranges[..position].contains(range)
            })
        {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "invalid BRIN maintenance state"
            ));
        }
        let created_at = index.created_at;
        let mut maintenance = self.brin_maintenance();
        let (state, stored_ranges) = Self::brin_entry_mut(
            &mut maintenance,
            index_slot,
            self.brin_unsummarized_ranges_per_index,
        );
        state.index_created_at = created_at;
        state.pages_per_range = pages_per_range;
        state.summarized_until_page = summarized_until_page;
        stored_ranges.fill(0);
        stored_ranges[..ranges.len()].copy_from_slice(ranges);
        state.count = ranges.len() as u8;
        state.wal_dirty = false;
        Ok(())
    }

    pub(crate) fn value_binding_cache_complete(&self, table_index: usize, binding: usize) -> bool {
        self.tables[table_index].enforcers[binding].is_some_and(|enforcer| {
            self.value_indexes
                .as_ref()
                .expect("value index pool present")
                .get(enforcer.slot)
                .is_complete()
        })
    }

    pub(crate) fn value_binding_probe_complete(&self, table_index: usize, binding: usize) -> bool {
        self.tables[table_index].enforcers[binding].is_some_and(|enforcer| {
            self.value_indexes
                .as_ref()
                .expect("value index pool present")
                .get(enforcer.slot)
                .is_complete()
                || enforcer
                    .durable
                    .is_some_and(|handle| self.commit_snapshot() >= handle.published_lsn)
        })
    }

    pub(crate) fn value_binding_durable_complete(
        &self,
        table_index: usize,
        binding: usize,
    ) -> bool {
        self.spill
            .as_ref()
            .is_some_and(|spill| spill.blocks.is_some())
            && self.tables[table_index].enforcers[binding].is_some_and(|enforcer| {
                enforcer
                    .durable
                    .is_some_and(|handle| self.commit_snapshot() >= handle.published_lsn)
            })
    }

    pub(crate) fn value_binding_key_types(
        &self,
        table_index: usize,
        binding: usize,
    ) -> ([ColType; MAX_INDEX_COLS], usize) {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        (enforcer.key_types, enforcer.n_cols)
    }

    pub(crate) fn value_binding_navigation(
        &self,
        table_index: usize,
        binding: usize,
    ) -> Option<crate::store::NavigationSpec> {
        use crate::sql::types::{GinOperatorClass, GistOperatorClass, SpGistOperatorClass};
        use crate::store::{NavigationKind, NavigationSpec};
        let enforcer = self.tables[table_index].enforcers[binding]?;
        let created_at = enforcer.index_created_at?;
        let index = self
            .index_catalog()
            .iter()
            .find(|index| {
                index.created_at == created_at
                    && index.database == self.tables[table_index].database
                    && index.ddl_state != CatalogDdlState::Absent
            })
            .copied()?;
        let classify = |class: Option<IndexOperatorClass>| -> Option<NavigationKind> {
            Some(match class {
                Some(IndexOperatorClass::Gist(
                    GistOperatorClass::Point
                    | GistOperatorClass::Box
                    | GistOperatorClass::Polygon
                    | GistOperatorClass::Circle,
                ))
                | Some(IndexOperatorClass::SpGist(
                    SpGistOperatorClass::QuadPoint
                    | SpGistOperatorClass::KdPoint
                    | SpGistOperatorClass::Box
                    | SpGistOperatorClass::Polygon,
                )) => NavigationKind::Spatial,
                Some(IndexOperatorClass::Gist(
                    GistOperatorClass::Inet
                    | GistOperatorClass::Range
                    | GistOperatorClass::Multirange,
                ))
                | Some(IndexOperatorClass::SpGist(
                    SpGistOperatorClass::Inet | SpGistOperatorClass::Range,
                )) => NavigationKind::Interval,
                Some(IndexOperatorClass::Gist(GistOperatorClass::TsVector)) => {
                    NavigationKind::Signature
                }
                Some(IndexOperatorClass::Gin(
                    GinOperatorClass::Array
                    | GinOperatorClass::TsVector
                    | GinOperatorClass::Jsonb
                    | GinOperatorClass::JsonbPath,
                )) => NavigationKind::Posting,
                _ => return None,
            })
        };
        // A generation has one summary position. Preserve whichever spatial,
        // signature, or posting column the established position-order rule
        // selected; otherwise adding an earlier interval de-optimizes it.
        let classes = &index.resolved_operator_classes[..index.n_cols];
        if let Some((position, kind)) = classes.iter().enumerate().find_map(|(position, class)| {
            classify(*class)
                .filter(|kind| *kind != NavigationKind::Interval)
                .map(|kind| (position, kind))
        }) {
            return Some(NavigationSpec {
                position: position as u8,
                kind,
            });
        }
        if let Some(position) = classes
            .iter()
            .position(|class| classify(*class) == Some(NavigationKind::Interval))
        {
            return Some(NavigationSpec {
                position: position as u8,
                kind: NavigationKind::Interval,
            });
        }
        None
    }

    pub(crate) fn value_binding_navigation_summary(
        &self,
        table_index: usize,
        binding: usize,
        navigation: crate::store::NavigationSpec,
        key: &[u8],
    ) -> Result<crate::store::NavigationSummary, SqlError> {
        if navigation.kind == crate::store::NavigationKind::Posting {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "posting summaries require an encoded token"
            ));
        }
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        if usize::from(navigation.position) >= enforcer.n_cols {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "navigation key position exceeds binding"
            ));
        }
        let mut values = [Datum::Null; MAX_INDEX_COLS];
        rowenc::decode(
            key,
            &enforcer.key_types[..enforcer.n_cols],
            &mut values[..enforcer.n_cols],
        )?;
        match navigation.kind {
            crate::store::NavigationKind::Spatial => {
                crate::sql::geometry::index_bounds(values[usize::from(navigation.position)])
            }
            crate::store::NavigationKind::Signature => Ok(crate::sql::index_signature::summary(
                values[usize::from(navigation.position)],
            )),
            crate::store::NavigationKind::Interval => {
                crate::sql::index_interval::summary(values[usize::from(navigation.position)])
            }
            crate::store::NavigationKind::Posting => unreachable!("handled above"),
        }
    }

    pub(crate) fn for_each_value_binding_posting_token(
        &self,
        table_index: usize,
        binding: usize,
        key: &[u8],
        emit: impl FnMut(crate::sql::index_signature::PostingToken),
    ) -> Result<(), SqlError> {
        let navigation = self
            .value_binding_navigation(table_index, binding)
            .filter(|navigation| navigation.kind == crate::store::NavigationKind::Posting)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "posting token extraction requires a GIN binding"
                )
            })?;
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        let position = usize::from(navigation.position);
        let mut values = [Datum::Null; MAX_INDEX_COLS];
        rowenc::decode(
            key,
            &enforcer.key_types[..enforcer.n_cols],
            &mut values[..enforcer.n_cols],
        )?;
        crate::sql::index_signature::for_each_value_token(values[position], emit);
        Ok(())
    }

    pub(crate) fn value_binding_collations(
        &self,
        table_index: usize,
        binding: usize,
    ) -> ([Collation; MAX_INDEX_COLS], usize) {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        (enforcer.collations, enforcer.n_cols)
    }

    pub(crate) fn value_binding_created_at(
        &self,
        table_index: usize,
        binding: usize,
    ) -> Option<u64> {
        self.tables[table_index].enforcers[binding]
            .expect("binding")
            .index_created_at
    }

    /// Walks a manifest-published key generation and the resident changes
    /// newer than it. Encoded keys borrow reader scratch only for the callback.
    pub fn walk_value_index(
        &self,
        table_index: usize,
        columns: &[u16],
        mut visit: impl FnMut(u64, &[u8]) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some((binding, handle)) = (0..table.n_enforcers).find_map(|binding| {
            let enforcer = table.enforcers[binding].expect("enforcer");
            (enforcer.index_created_at.is_none() && enforcer.columns() == columns)
                .then_some((binding, enforcer.durable?))
        }) else {
            return Ok(false);
        };
        if self.commit_snapshot() < handle.published_lsn {
            return Ok(false);
        }
        let Some(spill) = &self.spill else {
            return Ok(false);
        };
        let Some(mut scratch) = try_mutex_pool(
            spill
                .value_scratch
                .as_ref()
                .expect("durable value indexes have reader scratch"),
            "persistent value scratch",
        ) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "persistent value scans nested deeper than reader scratch"
            ));
        };
        {
            let ValueIndexScratch { roster, data, .. } = &mut *scratch;
            let mut callback_error = Ok(());
            crate::store::ValueIndexReader::over(roster, data)
                .walk(
                    &mut *spill
                        .blocks
                        .as_ref()
                        .expect("value-index generations are durable")
                        .lock()
                        .expect("block store lock poisoned"),
                    &handle,
                    |_, rowid, _, key| {
                        if callback_error.is_ok()
                            && let Err(error) = visit(rowid, key)
                        {
                            callback_error = Err(error);
                        }
                    },
                )
                .map_err(value_index_read_error)?;
            callback_error?;
        }
        // Overlay entries supersede or extend the published base. Duplicate
        // rowids are harmless because the ordinary WHERE/MVCC path rechecks
        // them; callers sort and deduplicate candidates before execution.
        for (rowid, state) in table.rows.iter() {
            if state.committed_lsn <= handle.published_lsn {
                continue;
            }
            let Some(home) = state.committed else {
                continue;
            };
            let key_buffer = &mut scratch.roster;
            let Some((key_len, _, _)) =
                self.encode_value_binding_entry(table_index, binding, rowid, home, key_buffer)?
            else {
                continue;
            };
            visit(rowid, &key_buffer[..key_len])?;
        }
        Ok(true)
    }

    /// Scans only the durable key blocks intersecting a typed btree interval,
    /// then applies the same interval to the committed resident overlay.
    /// `classify` describes a key relative to that interval; the value-index
    /// format uses it for block pruning without taking SQL types into storage.
    #[cfg(test)]
    pub(crate) fn range_value_index(
        &self,
        table_index: usize,
        columns: &[u16],
        classify: impl FnMut(&[u8]) -> Result<crate::store::ValueIndexPosition, SqlError>,
        visit: impl FnMut(u64, u64, &[u8], &[u8]) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some(binding) = (0..table.n_enforcers).find(|binding| {
            let enforcer = table.enforcers[*binding].expect("enforcer");
            enforcer.index_created_at.is_none() && enforcer.columns() == columns
        }) else {
            return Ok(false);
        };
        self.range_value_index_binding(table_index, binding, classify, visit)
    }

    #[cfg(test)]
    pub(crate) fn range_value_index_binding(
        &self,
        table_index: usize,
        binding: usize,
        classify: impl FnMut(&[u8]) -> Result<crate::store::ValueIndexPosition, SqlError>,
        visit: impl FnMut(u64, u64, &[u8], &[u8]) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        self.range_value_index_binding_with_bounds(
            table_index,
            binding,
            |_, _| true,
            classify,
            visit,
        )
    }

    pub(crate) fn range_value_index_binding_with_bounds(
        &self,
        table_index: usize,
        binding: usize,
        intersects: impl FnMut(u8, crate::store::SpatialBounds) -> bool,
        mut classify: impl FnMut(&[u8]) -> Result<crate::store::ValueIndexPosition, SqlError>,
        mut visit: impl FnMut(u64, u64, &[u8], &[u8]) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some(handle) = table.enforcers[binding].and_then(|enforcer| enforcer.durable) else {
            return Ok(false);
        };
        if self.commit_snapshot() < handle.published_lsn {
            return Ok(false);
        }
        let Some(spill) = &self.spill else {
            return Ok(false);
        };
        let Some(mut scratch) = try_mutex_pool(
            spill
                .value_scratch
                .as_ref()
                .expect("durable value indexes have reader scratch"),
            "persistent value scratch",
        ) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "persistent value scans nested deeper than reader scratch"
            ));
        };
        {
            let ValueIndexScratch { roster, data, .. } = &mut *scratch;
            let callback_error = std::cell::RefCell::new(None);
            crate::store::ValueIndexReader::over(roster, data)
                .range_covering_with_bounds(
                    &mut *spill
                        .blocks
                        .as_ref()
                        .expect("value-index generations are durable")
                        .lock()
                        .expect("block store lock poisoned"),
                    &handle,
                    intersects,
                    |key| match classify(key) {
                        Ok(position) => position,
                        Err(error) => {
                            *callback_error.borrow_mut() = Some(error);
                            crate::store::ValueIndexPosition::Match
                        }
                    },
                    |_, rowid, lsn, key, payload| {
                        let ready = callback_error.borrow().is_none();
                        if ready && let Err(error) = visit(rowid, lsn, key, payload) {
                            *callback_error.borrow_mut() = Some(error);
                        }
                    },
                )
                .map_err(value_index_read_error)?;
            if let Some(error) = callback_error.into_inner() {
                return Err(error);
            }
        }
        for (rowid, state) in table.rows.iter() {
            if state.committed_lsn <= handle.published_lsn {
                continue;
            }
            let Some(home) = state.committed else {
                continue;
            };
            let key_buffer = &mut scratch.roster;
            let Some((key_len, payload_len, _)) =
                self.encode_value_binding_entry(table_index, binding, rowid, home, key_buffer)?
            else {
                continue;
            };
            if classify(&key_buffer[..key_len])? == crate::store::ValueIndexPosition::Match {
                visit(
                    rowid,
                    state.committed_lsn,
                    &key_buffer[..key_len],
                    &key_buffer[key_len..key_len + payload_len],
                )?;
            }
        }
        Ok(true)
    }

    /// Visits a spatial navigation generation in lower-bound sibling order.
    /// The committed resident overlay is offered first so a caller can tighten
    /// its top-k radius before reading immutable objects. The bound predicate
    /// is re-evaluated by the cursor as that radius changes.
    pub(crate) fn rank_value_index_binding(
        &self,
        table_index: usize,
        binding: usize,
        intersects: impl FnMut(u8, crate::store::SpatialBounds) -> bool,
        priority: impl FnMut(u8, crate::store::SpatialBounds) -> f64,
        mut visit: impl FnMut(
            Option<(crate::store::BlockId, bool)>,
            u64,
            u64,
            &[u8],
            &[u8],
        ) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some(handle) = table.enforcers[binding].and_then(|enforcer| enforcer.durable) else {
            return Ok(false);
        };
        if self.commit_snapshot() < handle.published_lsn {
            return Ok(false);
        }
        let Some(spill) = &self.spill else {
            return Ok(false);
        };
        let Some(mut scratch) = try_mutex_pool(
            spill
                .value_scratch
                .as_ref()
                .expect("durable value indexes have reader scratch"),
            "persistent value scratch",
        ) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "persistent value scans nested deeper than reader scratch"
            ));
        };

        // New committed keys are not in the immutable generation. Rank them
        // before opening the tree so they participate in the initial cutoff.
        for (rowid, state) in table.rows.iter() {
            if state.committed_lsn <= handle.published_lsn {
                continue;
            }
            let Some(home) = state.committed else {
                continue;
            };
            let key_buffer = &mut scratch.roster;
            let Some((key_len, payload_len, _)) =
                self.encode_value_binding_entry(table_index, binding, rowid, home, key_buffer)?
            else {
                continue;
            };
            visit(
                None,
                rowid,
                state.committed_lsn,
                &key_buffer[..key_len],
                &key_buffer[key_len..key_len + payload_len],
            )?;
        }

        let callback_error = std::cell::RefCell::new(None);
        let complete = {
            let ValueIndexScratch { roster, data, .. } = &mut *scratch;
            crate::store::ValueIndexReader::over(roster, data)
                .ranked_covering(
                    &mut *spill
                        .blocks
                        .as_ref()
                        .expect("value-index generations are durable")
                        .lock()
                        .expect("block store lock poisoned"),
                    &handle,
                    intersects,
                    priority,
                    |id, covering, _, rowid, lsn, key, payload| {
                        if callback_error.borrow().is_none()
                            && let Err(error) =
                                visit(Some((id, covering)), rowid, lsn, key, payload)
                        {
                            *callback_error.borrow_mut() = Some(error);
                        }
                    },
                )
                .map_err(value_index_read_error)?
        };
        if let Some(error) = callback_error.into_inner() {
            return Err(error);
        }
        Ok(complete)
    }

    /// Supplies the exact key and INCLUDE payload retained by a ranked
    /// candidate. Immutable candidates are found in their remembered leaf;
    /// resident candidates are regenerated from their committed row image.
    pub(crate) fn read_ranked_value_binding_entry(
        &self,
        table_index: usize,
        binding: usize,
        source: Option<(crate::store::BlockId, bool)>,
        rowid: u64,
        lsn: u64,
        mut visit: impl FnMut(&[u8], &[u8]),
    ) -> Result<bool, SqlError> {
        let Some(spill) = &self.spill else {
            return Ok(false);
        };
        let Some(mut scratch) = try_mutex_pool(
            spill
                .value_scratch
                .as_ref()
                .expect("durable value indexes have reader scratch"),
            "persistent value scratch",
        ) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "persistent value scans nested deeper than reader scratch"
            ));
        };
        if let Some((id, covering)) = source {
            let ValueIndexScratch { roster, data, .. } = &mut *scratch;
            return crate::store::ValueIndexReader::over(roster, data)
                .leaf_entry(
                    &mut *spill
                        .blocks
                        .as_ref()
                        .expect("value-index generations are durable")
                        .lock()
                        .expect("block store lock poisoned"),
                    id,
                    covering,
                    rowid,
                    lsn,
                    visit,
                )
                .map_err(value_index_read_error);
        }
        let table = &self.tables[table_index];
        let Some(state) = table.rows.get(&rowid) else {
            return Ok(false);
        };
        if state.committed_lsn != lsn {
            return Ok(false);
        }
        let Some(home) = state.committed else {
            return Ok(false);
        };
        let key_buffer = &mut scratch.roster;
        let Some((key_len, payload_len, _)) =
            self.encode_value_binding_entry(table_index, binding, rowid, home, key_buffer)?
        else {
            return Ok(false);
        };
        visit(
            &key_buffer[..key_len],
            &key_buffer[key_len..key_len + payload_len],
        );
        Ok(true)
    }

    /// Probes one exact lossy token in an immutable GIN posting generation,
    /// then scans the committed resident overlay for the same token. Returned
    /// row identities remain subject to the ordinary SQL and MVCC rechecks.
    pub(crate) fn probe_value_binding_posting(
        &self,
        table_index: usize,
        binding: usize,
        token: crate::sql::index_signature::PostingToken,
        mut visit: impl FnMut(u64, u64) -> Result<(), SqlError>,
    ) -> Result<bool, SqlError> {
        let table = &self.tables[table_index];
        let Some(navigation) = self
            .value_binding_navigation(table_index, binding)
            .filter(|navigation| navigation.kind == crate::store::NavigationKind::Posting)
        else {
            return Ok(false);
        };
        let Some(handle) = table.enforcers[binding].and_then(|enforcer| enforcer.durable) else {
            return Ok(false);
        };
        if self.commit_snapshot() < handle.published_lsn {
            return Ok(false);
        }
        let Some(spill) = &self.spill else {
            return Ok(false);
        };
        let Some(mut scratch) = try_mutex_pool(
            spill
                .value_scratch
                .as_ref()
                .expect("durable value indexes have reader scratch"),
            "persistent value scratch",
        ) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "persistent value scans nested deeper than reader scratch"
            ));
        };
        let (_, root_kind) = spill
            .blocks
            .as_ref()
            .expect("value-index generations are durable")
            .lock()
            .expect("block store lock poisoned")
            .get(&handle.roster, &mut scratch.roster)
            .map_err(|error| value_index_read_error(crate::store::ValueIndexError::Store(error)))?;
        match root_kind {
            crate::store::BlockType::ValueIndexPostingV1 => {}
            crate::store::BlockType::ValueIndexNavigationV1
            | crate::store::BlockType::ValueIndexRoster => return Ok(false),
            _ => {
                return Err(sql_err!(
                    sqlstate::IO_ERROR,
                    "persistent GIN posting root is corrupt"
                ));
            }
        }
        let encoded = token.encode();
        let mut interval_key = [0; crate::store::INTERVAL_KEY_BYTES];
        interval_key[..crate::sql::index_signature::PostingToken::KEY_BYTES]
            .copy_from_slice(&encoded);
        {
            let ValueIndexScratch { roster, data, .. } = &mut *scratch;
            let callback_error = std::cell::RefCell::new(None);
            crate::store::ValueIndexReader::over(roster, data)
                .range_covering_with_bounds(
                    &mut *spill
                        .blocks
                        .as_ref()
                        .expect("value-index generations are durable")
                        .lock()
                        .expect("block store lock poisoned"),
                    &handle,
                    |position, summary| {
                        if position != navigation.position {
                            return true;
                        }
                        match summary {
                            crate::store::NavigationSummary::Empty => false,
                            crate::store::NavigationSummary::Interval(interval) => {
                                interval.intersects(interval_key, interval_key)
                            }
                            _ => true,
                        }
                    },
                    |key| {
                        if key.len() != crate::sql::index_signature::PostingToken::KEY_BYTES {
                            *callback_error.borrow_mut() = Some(sql_err!(
                                sqlstate::IO_ERROR,
                                "persistent GIN posting key is corrupt"
                            ));
                            return crate::store::ValueIndexPosition::Match;
                        }
                        match key.cmp(&encoded) {
                            core::cmp::Ordering::Less => crate::store::ValueIndexPosition::Before,
                            core::cmp::Ordering::Equal => crate::store::ValueIndexPosition::Match,
                            core::cmp::Ordering::Greater => crate::store::ValueIndexPosition::After,
                        }
                    },
                    |_, rowid, lsn, _, _| {
                        if callback_error.borrow().is_none()
                            && let Err(error) = visit(rowid, lsn)
                        {
                            *callback_error.borrow_mut() = Some(error);
                        }
                    },
                )
                .map_err(value_index_read_error)?;
            if let Some(error) = callback_error.into_inner() {
                return Err(error);
            }
        }
        for (rowid, state) in table.rows.iter() {
            if state.committed_lsn <= handle.published_lsn {
                continue;
            }
            let Some(home) = state.committed else {
                continue;
            };
            let key_buffer = &mut scratch.roster;
            let Some((key_len, _, _)) =
                self.encode_value_binding_entry(table_index, binding, rowid, home, key_buffer)?
            else {
                continue;
            };
            let mut matches = false;
            self.for_each_value_binding_posting_token(
                table_index,
                binding,
                &key_buffer[..key_len],
                |candidate| matches |= candidate == token,
            )?;
            if matches {
                visit(rowid, state.committed_lsn)?;
            }
        }
        Ok(true)
    }

    pub(crate) fn value_binding_count(&self, table_index: usize) -> usize {
        self.tables[table_index].n_enforcers
    }

    pub(crate) fn value_binding_columns(
        &self,
        table_index: usize,
        binding: usize,
    ) -> ([u16; MAX_INDEX_COLS], usize) {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        (enforcer.columns, enforcer.n_cols)
    }

    pub(crate) fn value_binding_include_mask(
        &self,
        table_index: usize,
        binding: usize,
    ) -> ColumnSet {
        self.tables[table_index].enforcers[binding]
            .expect("binding")
            .include_mask
    }

    pub(crate) fn value_binding_handle(
        &self,
        table_index: usize,
        binding: usize,
    ) -> Option<crate::store::ValueIndexHandle> {
        self.tables[table_index].enforcers[binding]
            .expect("binding")
            .durable
    }

    pub(crate) fn value_binding_needs_publish(&self, table_index: usize, binding: usize) -> bool {
        self.tables[table_index].enforcers[binding]
            .expect("binding")
            .durable_dirty
    }

    pub(crate) fn value_binding_dirty_lsn(
        &self,
        table_index: usize,
        binding: usize,
    ) -> Option<u64> {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        enforcer.durable_dirty.then_some(enforcer.durable_dirty_lsn)
    }

    pub(crate) fn value_binding_requires_rebuild(
        &self,
        table_index: usize,
        binding: usize,
    ) -> bool {
        self.tables[table_index].enforcers[binding]
            .expect("binding")
            .durable_rebuild
    }

    /// Invalidates every durable value generation after a committed row-set
    /// replacement that bypasses [`Self::commit_row`] (replay, rewrite,
    /// truncation, or explicit REINDEX maintenance).
    pub(crate) fn mark_value_bindings_dirty(&mut self, table_index: usize) {
        let dirty_lsn = self.lsn.saturating_add(1);
        self.mark_value_bindings_rebuild_at(table_index, dirty_lsn);
    }

    pub(crate) fn mark_value_bindings_changed_at(&mut self, table_index: usize, dirty_lsn: u64) {
        let n_enforcers = self.tables[table_index].n_enforcers;
        for enforcer in self.tables[table_index].enforcers[..n_enforcers]
            .iter_mut()
            .flatten()
        {
            enforcer.durable_dirty = true;
            enforcer.durable_dirty_lsn = dirty_lsn;
        }
    }

    fn mark_value_bindings_rebuild_at(&mut self, table_index: usize, dirty_lsn: u64) {
        self.mark_value_bindings_changed_at(table_index, dirty_lsn);
        let n_enforcers = self.tables[table_index].n_enforcers;
        for enforcer in self.tables[table_index].enforcers[..n_enforcers]
            .iter_mut()
            .flatten()
        {
            enforcer.durable_rebuild = true;
        }
    }

    pub(crate) fn value_binding_is_committed(&self, table_index: usize, binding: usize) -> bool {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        if let Some(created_at) = enforcer.index_created_at {
            let table = &self.tables[table_index];
            return self.index_catalog().iter().any(|index| {
                index.ddl_state == CatalogDdlState::Present
                    && index.database == table.database
                    && index.schema == table.def.schema
                    && index.table == table.def.name
                    && index.created_at == created_at
            });
        }
        let columns = enforcer.columns();
        let table = &self.tables[table_index];
        let definition = &table.def;
        definition
            .columns()
            .iter()
            .enumerate()
            .any(|(column, metadata)| metadata.unique && columns == [column as u16])
            || definition
                .uniques()
                .iter()
                .any(|unique| unique.columns() == columns)
            || self.index_catalog().iter().any(|index| {
                index.ddl_state == CatalogDdlState::Present
                    && index.database == table.database
                    && index.schema == definition.schema
                    && index.table == definition.name
                    && &index.columns[..index.n_cols] == columns
                    && index.predicate.is_none()
                    && index.expressions[..index.n_cols]
                        .iter()
                        .all(Option::is_none)
                    && index.resolved_operator_classes[..index.n_cols]
                        .iter()
                        .all(|class| !matches!(class, Some(IndexOperatorClass::Catalog(_))))
                    && columns.iter().enumerate().all(|(position, column)| {
                        index.collations[position] == definition.columns[*column as usize].collation
                    })
            })
    }

    pub(crate) fn install_value_binding(
        &mut self,
        table_index: usize,
        columns: &[u16],
        index_created_at: Option<u64>,
        include_mask: ColumnSet,
        handle: Option<crate::store::ValueIndexHandle>,
    ) -> Result<(), SqlError> {
        let n_enforcers = self.tables[table_index].n_enforcers;
        let Some(enforcer) = self.tables[table_index].enforcers[..n_enforcers]
            .iter_mut()
            .flatten()
            .find(|enforcer| {
                enforcer.columns() == columns
                    && enforcer.index_created_at == index_created_at
                    && enforcer.include_mask == include_mask
            })
        else {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "manifest value index has no catalog binding"
            ));
        };
        enforcer.durable = handle;
        enforcer.durable_dirty = false;
        enforcer.durable_rebuild = false;
        Ok(())
    }

    /// Encodes one binding's key followed by its included-column payload into
    /// caller-owned scratch. The returned lengths are the sole split point.
    pub(crate) fn encode_value_binding_entry(
        &self,
        table_index: usize,
        binding: usize,
        rowid: u64,
        home: RowHome,
        output: &mut [u8],
    ) -> Result<Option<(usize, usize, u64)>, SqlError> {
        self.with_value_binding_key(
            table_index,
            binding,
            rowid,
            home,
            |key, values, enforcer| Self::encode_value_binding_parts(key, values, enforcer, output),
        )
    }

    fn encode_value_binding_values(
        &self,
        table_index: usize,
        binding: usize,
        values: &[Datum],
        output: &mut [u8],
    ) -> Result<Option<(usize, usize, u64)>, SqlError> {
        let arena = self
            .index_arena
            .lock()
            .expect("index expression arena lock poisoned");
        let mark = arena.mark();
        let result = self.with_value_binding_values(
            &arena,
            table_index,
            binding,
            values,
            |key, values, enforcer| Self::encode_value_binding_parts(key, values, enforcer, output),
        );
        // SAFETY: the encoded key and payload own their bytes in `output`.
        unsafe { arena.rewind_to(mark) };
        result
    }

    fn encode_value_binding_parts(
        key: Option<&[Datum]>,
        values: &[Datum],
        enforcer: &Enforcer,
        output: &mut [u8],
    ) -> Result<Option<(usize, usize, u64)>, SqlError> {
        let Some(key) = key else { return Ok(None) };
        let key_len = rowenc::encoded_len(key);
        let mut payload = [Datum::Null; MAX_COLUMNS];
        let mut n_payload = 0usize;
        for (column, value) in values.iter().enumerate() {
            if enforcer.include_mask.contains(column) {
                payload[n_payload] = *value;
                n_payload += 1;
            }
        }
        let payload_len = if n_payload == 0 {
            0
        } else {
            rowenc::encoded_len(&payload[..n_payload])
        };
        if key_len > crate::store::VALUE_INDEX_KEY_MAX
            || (n_payload != 0
                && key_len.saturating_add(payload_len) > crate::store::VALUE_INDEX_TUPLE_MAX)
            || key_len.saturating_add(payload_len) > output.len()
        {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "index tuple exceeds the persistent block limit"
            ));
        }
        rowenc::encode(key, &mut output[..key_len]);
        if n_payload != 0 {
            rowenc::encode(
                &payload[..n_payload],
                &mut output[key_len..key_len + payload_len],
            );
        }
        let compact = core::array::from_fn::<u16, MAX_INDEX_COLS, _>(|index| index as u16);
        Ok(Some((
            key_len,
            payload_len,
            hash_key_collated(
                key,
                &compact[..enforcer.n_cols],
                &enforcer.collations[..enforcer.n_cols],
            ),
        )))
    }

    /// Compares two encoded keys with the indexed columns' PostgreSQL types
    /// and collations. Checkpoint sorting and range navigation share this
    /// boundary so byte encoding can never accidentally become SQL order.
    pub(crate) fn compare_value_binding_keys(
        &self,
        table_index: usize,
        binding: usize,
        navigation: Option<crate::store::NavigationSpec>,
        left: &[u8],
        right: &[u8],
    ) -> Result<core::cmp::Ordering, SqlError> {
        let enforcer = self.tables[table_index].enforcers[binding].expect("binding");
        if navigation
            .is_some_and(|navigation| navigation.kind == crate::store::NavigationKind::Posting)
        {
            return Ok(left.cmp(right));
        }
        if let Some(
            navigation @ crate::store::NavigationSpec {
                kind: crate::store::NavigationKind::Spatial,
                ..
            },
        ) = navigation
        {
            let left_bounds =
                self.value_binding_navigation_summary(table_index, binding, navigation, left)?;
            let right_bounds =
                self.value_binding_navigation_summary(table_index, binding, navigation, right)?;
            use crate::store::SpatialBounds;
            let order_key = |bounds| match bounds {
                SpatialBounds::Empty => (0u8, 0.0f64, 0.0f64),
                SpatialBounds::Finite(bounds) => {
                    let [minimum_x, minimum_y, maximum_x, maximum_y] = bounds.coordinates();
                    (
                        1,
                        minimum_x * 0.5 + maximum_x * 0.5,
                        minimum_y * 0.5 + maximum_y * 0.5,
                    )
                }
                SpatialBounds::Unbounded => (2, 0.0, 0.0),
                SpatialBounds::Signature(_) => (2, 0.0, 0.0),
                SpatialBounds::Interval(_) => (2, 0.0, 0.0),
            };
            let left_key = order_key(left_bounds);
            let right_key = order_key(right_bounds);
            return Ok(left_key
                .0
                .cmp(&right_key.0)
                .then_with(|| left_key.1.total_cmp(&right_key.1))
                .then_with(|| left_key.2.total_cmp(&right_key.2))
                .then_with(|| left.cmp(right)));
        }
        if let Some(
            navigation @ crate::store::NavigationSpec {
                kind: crate::store::NavigationKind::Interval,
                ..
            },
        ) = navigation
        {
            let left_summary =
                self.value_binding_navigation_summary(table_index, binding, navigation, left)?;
            let right_summary =
                self.value_binding_navigation_summary(table_index, binding, navigation, right)?;
            let order_key = |summary| match summary {
                crate::store::NavigationSummary::Empty => (0, [0; 15], [0; 15], false),
                crate::store::NavigationSummary::Interval(interval) => {
                    let (lower, upper) = interval.bounds();
                    (1, lower, upper, interval.has_empty())
                }
                _ => (2, [0; 15], [0; 15], false),
            };
            return Ok(order_key(left_summary)
                .cmp(&order_key(right_summary))
                .then_with(|| left.cmp(right)));
        }
        if !enforcer.ordered {
            return Ok(left.cmp(right));
        }
        let mut types = [ColType::Bool; MAX_INDEX_COLS];
        let mut collations = [crate::sql::ast::Collation::None; MAX_INDEX_COLS];
        types[..enforcer.n_cols].copy_from_slice(&enforcer.key_types[..enforcer.n_cols]);
        collations[..enforcer.n_cols].copy_from_slice(&enforcer.collations[..enforcer.n_cols]);
        let mut left_values = [Datum::Null; MAX_INDEX_COLS];
        let mut right_values = [Datum::Null; MAX_INDEX_COLS];
        rowenc::decode(
            left,
            &types[..enforcer.n_cols],
            &mut left_values[..enforcer.n_cols],
        )?;
        rowenc::decode(
            right,
            &types[..enforcer.n_cols],
            &mut right_values[..enforcer.n_cols],
        )?;
        for position in 0..enforcer.n_cols {
            // The internal generation order is NULLS FIRST regardless of an
            // index's display ordering. Range classifiers likewise place a
            // NULL before every comparable search key, so this explicit total
            // order keeps navigation monotonic without asking SQL to compare
            // two values of the unknown type.
            let ordering = match (left_values[position], right_values[position]) {
                (Datum::Null, Datum::Null) => core::cmp::Ordering::Equal,
                (Datum::Null, _) => core::cmp::Ordering::Less,
                (_, Datum::Null) => core::cmp::Ordering::Greater,
                (left, right) => crate::sql::eval::compare_datums_collated(
                    self,
                    collations[position],
                    &left,
                    &right,
                )?,
            };
            if !ordering.is_eq() {
                return Ok(ordering);
            }
        }
        Ok(core::cmp::Ordering::Equal)
    }

    /// Whether the current command can see one of `txid`'s pending images.
    /// Other transactions' pending images do not invalidate the committed
    /// value cache: row visibility ignores them and the committed key remains
    /// installed until their transaction commits.
    pub(crate) fn has_visible_pending_rows(&self, table_index: usize, txid: u32) -> bool {
        self.resident_rows(table_index).iter().any(|(_, state)| {
            state.has_visible_pending(txid, self.read_snapshot())
        })
    }

    /// Releases a table's enforcer index slots back to the pool and clears its
    /// enforcer list. Called before a slot is reused and when a table is
    /// dropped.
    fn release_enforcers(&mut self, table_index: usize) {
        let n = self.tables[table_index].n_enforcers;
        if n == 0 {
            return;
        }
        let mut slots = [u32::MAX; MAX_VALUE_ENFORCERS];
        for (i, s) in slots.iter_mut().enumerate().take(n) {
            if let Some(e) = self.tables[table_index].enforcers[i] {
                *s = e.slot;
            }
        }
        if let Some(pool) = self.value_indexes.as_mut() {
            for &slot in slots.iter().take(n) {
                if slot != u32::MAX {
                    pool.release(slot);
                }
            }
        }
        self.tables[table_index].enforcers = [None; MAX_VALUE_ENFORCERS];
        self.tables[table_index].n_enforcers = 0;
    }

    /// Rebuilds every live table's value-index enforcers from its committed
    /// rows. Called once at startup after journal replay (whose row installs
    /// bypass the per-row commit maintenance), so the indexes reflect the
    /// recovered committed state before any query runs.
    pub fn rebuild_all_enforcers(&mut self) -> Result<(), SqlError> {
        for i in 0..self.tables.len() {
            if self.tables[i].live {
                self.refresh_enforcers(i)?;
            }
        }
        Ok(())
    }

    /// Rebuilds a table's value-cache enforcers from its current definition and
    /// named indexes, then repopulates them from the committed rows. Idempotent
    /// — call it whenever the definition, the index set, or the committed rows
    /// change outside the per-row [`Self::commit_row`] maintenance (ALTER, a
    /// committed CREATE, CREATE/DROP INDEX, cold-start replay).
    pub fn refresh_enforcers(&mut self, table_index: usize) -> Result<(), SqlError> {
        self.refresh_enforcers_visible(table_index, None)
    }

    /// Builds the cache shape visible to the owner of a pending CREATE INDEX
    /// before its WAL record becomes durable. Pool exhaustion is therefore a
    /// pre-commit DDL error, never a committed index followed by an error.
    pub fn prepare_index_enforcers(
        &mut self,
        table_index: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        self.refresh_enforcers_visible(table_index, Some(txid))
    }

    fn refresh_enforcers_visible(
        &mut self,
        table_index: usize,
        txid: Option<u32>,
    ) -> Result<(), SqlError> {
        let new_dirty_lsn = self.lsn.saturating_add(1);
        // DDL reshapes the cache slots, but an unchanged column tuple keeps
        // its manifest-published object generation.
        let mut published = [None; MAX_VALUE_ENFORCERS];
        let n_published = self.tables[table_index].n_enforcers;
        for (index, entry) in published.iter_mut().enumerate().take(n_published) {
            let enforcer = self.tables[table_index].enforcers[index].expect("enforcer");
            *entry = Some(enforcer);
        }
        self.release_enforcers(table_index);
        #[derive(Clone, Copy)]
        struct WantedBinding {
            columns: [u16; MAX_INDEX_COLS],
            n_columns: usize,
            index_created_at: Option<u64>,
            key_types: [ColType; MAX_INDEX_COLS],
            collations: [Collation; MAX_INDEX_COLS],
            ordered: bool,
            include_mask: ColumnSet,
            dependency_mask: ColumnSet,
        }
        const EMPTY_BINDING: WantedBinding = WantedBinding {
            columns: [0; MAX_INDEX_COLS],
            n_columns: 0,
            index_created_at: None,
            key_types: [ColType::Bool; MAX_INDEX_COLS],
            collations: [Collation::None; MAX_INDEX_COLS],
            ordered: true,
            include_mask: ColumnSet::EMPTY,
            dependency_mask: ColumnSet::EMPTY,
        };
        let mut want = [EMPTY_BINDING; MAX_VALUE_ENFORCERS];
        let mut n_want = 0usize;
        let too_many = || {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "a table can have at most {} distinct value-indexed column tuples",
                MAX_VALUE_ENFORCERS
            )
        };
        {
            let def = &self.tables[table_index].def;
            for (i, col) in def.columns().iter().enumerate() {
                if col.unique {
                    if n_want == MAX_VALUE_ENFORCERS {
                        return Err(too_many());
                    }
                    want[n_want].columns[0] = i as u16;
                    want[n_want].n_columns = 1;
                    want[n_want].key_types[0] = col.ctype;
                    want[n_want].collations[0] = col.collation;
                    want[n_want].dependency_mask.insert(i);
                    n_want += 1;
                }
            }
            for uk in def.uniques() {
                if n_want == MAX_VALUE_ENFORCERS {
                    return Err(too_many());
                }
                let cols = uk.columns();
                want[n_want].columns[..cols.len()].copy_from_slice(cols);
                want[n_want].n_columns = cols.len();
                for (position, column) in cols.iter().enumerate() {
                    want[n_want].key_types[position] = def.columns[*column as usize].ctype;
                    want[n_want].collations[position] = def.columns[*column as usize].collation;
                    want[n_want].dependency_mask.insert(usize::from(*column));
                }
                n_want += 1;
            }
        }
        // Named indexes use the same cache. Identical column tuples
        // share one enforcer: PostgreSQL permits redundant indexes, but a
        // second copy cannot improve the equality probe and would waste a
        // startup-reserved pool slot.
        let table_schema = self.tables[table_index].def.schema;
        let table_name = self.tables[table_index].def.name;
        let table_database = self.tables[table_index].database;
        let table_definition = self.tables[table_index].def;
        for index in self
            .matching_indexes(|index| {
                txid.map_or(index.ddl_state == CatalogDdlState::Present, |owner| {
                    index.visible_to(owner)
                }) && index.database == table_database
                    && index.schema == table_schema
                    && index.table == table_name
                    && !index.mutable_for(txid.unwrap_or(0)).kind.is_partitioned()
            })
            .map(|(_, index)| index)
        {
            let uses_catalog_comparison = index.resolved_operator_classes[..index.n_cols]
                .iter()
                .any(|class| matches!(class, Some(IndexOperatorClass::Catalog(_))));
            if uses_catalog_comparison {
                continue;
            }
            let columns = &index.columns[..index.n_cols];
            // BRIN must retain its concrete catalog identity even for plain
            // columns: inclusion operator classes and summary maintenance
            // have semantics a generic equality/range binding cannot infer.
            let special = matches!(
                index.method,
                crate::sql::ast::IndexAccessMethod::Brin
                    | crate::sql::ast::IndexAccessMethod::Gist
                    | crate::sql::ast::IndexAccessMethod::Gin
                    | crate::sql::ast::IndexAccessMethod::SpGist
            ) || index.predicate.is_some()
                || index.expressions[..index.n_cols]
                    .iter()
                    .any(Option::is_some)
                || columns.iter().enumerate().any(|(position, column)| {
                    index.collations[position]
                        != table_definition.columns[*column as usize].collation
                });
            let mut key_mask = ColumnSet::EMPTY;
            for (position, column) in columns.iter().copied().enumerate() {
                if index.expressions[position].is_none() {
                    key_mask.insert(usize::from(column));
                }
            }
            let mut include_mask = ColumnSet::EMPTY;
            for column in index.include_columns[..index.n_include_cols]
                .iter()
                .copied()
            {
                include_mask.insert(usize::from(column));
            }
            include_mask = include_mask.difference(key_mask);
            if !special
                && let Some(cached) = want[..n_want].iter_mut().find(|cached| {
                    cached.index_created_at.is_none()
                        && &cached.columns[..cached.n_columns] == columns
                })
            {
                cached.include_mask |= include_mask;
                cached.dependency_mask |= include_mask;
                continue;
            }
            if n_want == MAX_VALUE_ENFORCERS {
                return Err(too_many());
            }
            want[n_want].columns[..columns.len()].copy_from_slice(columns);
            want[n_want].n_columns = columns.len();
            want[n_want].index_created_at = special.then_some(index.created_at);
            want[n_want].ordered = !matches!(
                index.method,
                crate::sql::ast::IndexAccessMethod::Gist
                    | crate::sql::ast::IndexAccessMethod::Gin
                    | crate::sql::ast::IndexAccessMethod::SpGist
            );
            want[n_want].collations[..columns.len()]
                .copy_from_slice(&index.collations[..columns.len()]);
            want[n_want].dependency_mask = key_mask | include_mask;
            let arena = self
                .index_arena
                .lock()
                .expect("index expression arena lock poisoned");
            let mark = arena.mark();
            let type_result = (|| {
                for (position, expression) in index.expressions[..index.n_cols].iter().enumerate() {
                    want[n_want].key_types[position] = match expression {
                        None => table_definition.columns[columns[position] as usize].ctype,
                        Some(source) => {
                            let expression =
                                crate::sql::parser::parse_expr(source.as_str(), &arena)?;
                            want[n_want].dependency_mask |=
                                crate::sql::exec::check_referenced_columns(
                                    expression,
                                    &table_definition,
                                )?;
                            let (type_oid, _) = crate::sql::exec::infer_type_catalog(
                                expression,
                                Some(&table_definition),
                                self,
                                txid.unwrap_or(0),
                            )?;
                            self.routine_result_for_oid(type_oid, txid.unwrap_or(0))
                                .map(|result| result.ctype)
                                .ok_or_else(|| {
                                    sql_err!(
                                        sqlstate::UNDEFINED_OBJECT,
                                        "index expression data type does not exist"
                                    )
                                })?
                        }
                    };
                }
                if let Some(source) = index.predicate {
                    let predicate = crate::sql::parser::parse_expr(source.as_str(), &arena)?;
                    want[n_want].dependency_mask |=
                        crate::sql::exec::check_referenced_columns(predicate, &table_definition)?;
                }
                Ok(())
            })();
            // SAFETY: inferred expression metadata does not retain parser
            // nodes or values allocated above this row-local mark.
            unsafe { arena.rewind_to(mark) };
            drop(arena);
            type_result?;
            want[n_want].include_mask = include_mask;
            n_want += 1;
        }
        for (w, wanted) in want.iter().take(n_want).enumerate() {
            let slot = match self.value_indexes.as_mut().expect("pool present").acquire() {
                Some(s) => s,
                None => {
                    // Give back what this call already took, then fail loudly.
                    self.release_enforcers(table_index);
                    return Err(sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "value index pool exhausted (raise max_value_indexes)"
                    ));
                }
            };
            let prior = published[..n_published]
                .iter()
                .flatten()
                .find(|enforcer| {
                    enforcer.n_cols == wanted.n_columns
                        && enforcer.index_created_at == wanted.index_created_at
                        && enforcer.include_mask == wanted.include_mask
                        && enforcer.dependency_mask == wanted.dependency_mask
                        && enforcer.ordered == wanted.ordered
                        && enforcer.key_types[..enforcer.n_cols]
                            == wanted.key_types[..wanted.n_columns]
                        && enforcer.collations[..enforcer.n_cols]
                            == wanted.collations[..wanted.n_columns]
                        && enforcer.columns[..enforcer.n_cols] == wanted.columns[..wanted.n_columns]
                })
                .copied();
            self.tables[table_index].enforcers[w] = Some(Enforcer {
                slot,
                columns: wanted.columns,
                n_cols: wanted.n_columns,
                index_created_at: wanted.index_created_at,
                evaluation_txid: txid.unwrap_or(0),
                key_types: wanted.key_types,
                collations: wanted.collations,
                ordered: wanted.ordered,
                include_mask: wanted.include_mask,
                dependency_mask: wanted.dependency_mask,
                durable: prior.and_then(|enforcer| enforcer.durable),
                durable_dirty: prior.is_none_or(|enforcer| enforcer.durable_dirty),
                durable_rebuild: prior.is_none_or(|enforcer| enforcer.durable_rebuild),
                durable_dirty_lsn: prior
                    .map_or(new_dirty_lsn, |enforcer| enforcer.durable_dirty_lsn),
            });
            // Keep the installed prefix visible to `release_enforcers`, so an
            // acquire failure later in this loop returns every slot already
            // taken by this rebuild.
            self.tables[table_index].n_enforcers = w + 1;
        }
        self.populate_enforcers(table_index)?;
        Ok(())
    }

    /// Populates a table's enforcer indexes from its committed rows. Takes the
    /// pool out of `self` so the row walk (which borrows the rest of `self`) and
    /// the index inserts do not overlap.
    fn populate_enforcers(&mut self, table_index: usize) -> Result<(), SqlError> {
        if self.tables[table_index].n_enforcers == 0 {
            return Ok(());
        }
        let mut pool = self.value_indexes.take().expect("pool present");
        let result = self.populate_into(table_index, &mut pool);
        self.value_indexes = Some(pool);
        result
    }

    fn populate_into(&self, table_index: usize, pool: &mut ValueIndexPool) -> Result<(), SqlError> {
        let n_enf = self.tables[table_index].n_enforcers;
        let mut slots = [u32::MAX; MAX_VALUE_ENFORCERS];
        for (i, s) in slots.iter_mut().enumerate().take(n_enf) {
            *s = self.tables[table_index].enforcers[i]
                .expect("enforcer")
                .slot;
        }
        let mut incomplete = false;
        let mut buf = [(0usize, 0u64); MAX_VALUE_ENFORCERS];
        let mut insert_hashes = |rowid: u64, hashes: &[(usize, u64)]| {
            for &(binding, hash) in hashes {
                let index = pool.get_mut(slots[binding]);
                if index.insert(hash, rowid).is_err() {
                    incomplete = true;
                    return core::ops::ControlFlow::Break(());
                }
            }
            core::ops::ControlFlow::Continue(())
        };
        let overlay = self.for_each_scan_overlay_row_state(table_index, &mut |rowid, state| {
            let Some(home) = state.committed else {
                return Ok(core::ops::ControlFlow::Continue(()));
            };
            let count = self.row_enforcer_hashes(table_index, rowid, home, &mut buf)?;
            Ok(insert_hashes(rowid, &buf[..count]))
        })?;
        if overlay.is_continue() {
            let mut schema = [ColType::Bool; MAX_COLUMNS];
            let n_columns = self.tables[table_index].def.schema(&mut schema);
            let dependency_mask = self.tables[table_index].enforcers[..n_enf]
                .iter()
                .flatten()
                .fold(ColumnSet::EMPTY, |mask, enforcer| {
                    mask | enforcer.dependency_mask
                });
            let demanded = core::array::from_fn(|column| {
                column < n_columns && dependency_mask.contains(column)
            });
            let demanded_count = demanded[..n_columns].iter().filter(|&&set| set).count();
            let arena = self
                .index_arena
                .lock()
                .expect("index expression arena lock poisoned");
            self.spill_merged_walk_bytes(
                table_index,
                &arena,
                true,
                Some(&demanded),
                demanded_count.saturating_mul(2) >= n_columns,
                SpillOverlayMode::VisibleScan,
                None,
                &mut |rowid, _commit_lsn, representation| {
                    let mark = arena.mark();
                    let mut decoded = [Datum::Null; MAX_COLUMNS];
                    let values = match representation {
                        SpilledRowRepresentation::Encoded(bytes) => {
                            rowenc::decode(bytes, &schema[..n_columns], &mut decoded)?;
                            &decoded[..n_columns]
                        }
                        SpilledRowRepresentation::Values(values) => values,
                    };
                    let hashes = self.values_enforcer_hashes(&arena, table_index, values, &mut buf);
                    // SAFETY: `hashes` retains only fixed hash values and
                    // binding ordinals from expression evaluation.
                    unsafe { arena.rewind_to(mark) };
                    let count = hashes?;
                    Ok(insert_hashes(rowid, &buf[..count]))
                },
            )?;
        }
        if incomplete {
            // A stopped walk can leave any cache without later rows, including
            // one that still had room when another binding filled.
            for &slot in &slots[..n_enf] {
                pool.get_mut(slot).mark_incomplete();
            }
        }
        Ok(())
    }

    /// Committed-catalog lookup (ignores uncommitted DDL): used by journal
    /// replay and any context that operates on the durable image.
    pub fn find_table(&self, schema: &str, name: &str) -> Option<usize> {
        self.tables.iter().take(self.table_count()).position(|t| {
            t.database == current_database()
                && t.live
                && t.def.schema.as_str() == schema
                && t.def.name.as_str() == name
        })
    }

    /// Transaction-scoped lookup: `txid` sees its own uncommitted CREATE/DROP
    /// and every committed table, but not another transaction's uncommitted
    /// DDL.
    pub fn find_visible(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        self.tables
            .iter()
            .take(self.table_count())
            .enumerate()
            .position(|(index, table)| {
                table.database == current_database()
                    && table.visible_to(txid)
                    && self.table_def(index, txid).schema.as_str() == schema
                    && self.table_def(index, txid).name.as_str() == name
            })
    }

    pub fn table(&self, index: usize) -> &Table {
        &self.tables[index]
    }

    pub(crate) fn table_slot_visible_to(&self, index: usize, txid: u32) -> bool {
        self.tables[index].database == current_database() && self.tables[index].visible_to(txid)
    }

    pub fn table_mut(&mut self, index: usize) -> &mut Table {
        &mut self.tables[index]
    }

    pub(crate) fn table_serial_value(&self, index: usize, column: usize) -> i64 {
        self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned")
            .values[column]
    }

    pub(crate) fn table_serial_values(&self, index: usize) -> [i64; MAX_COLUMNS] {
        self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned")
            .values
    }

    pub(crate) fn set_table_serial_value(&self, index: usize, column: usize, value: i64) {
        self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned")
            .set(column, value);
    }

    pub(crate) fn next_table_serial_value(
        &self,
        index: usize,
        column: usize,
        step: i64,
        ctype: ColType,
    ) -> Result<i64, SqlError> {
        let (minimum, maximum, type_name) = match ctype {
            ColType::Int2 => (i64::from(i16::MIN), i64::from(i16::MAX), "smallint"),
            ColType::Int4 => (i64::from(i32::MIN), i64::from(i32::MAX), "integer"),
            ColType::Int8 => (i64::MIN, i64::MAX, "bigint"),
            _ => {
                return Err(sql_err!(
                    sqlstate::DATATYPE_MISMATCH,
                    "table serial counter requires an integer column"
                ));
            }
        };
        let mut serial = self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned");
        let next = serial.values[column]
            .checked_add(step)
            .filter(|value| (minimum..=maximum).contains(value))
            .ok_or_else(|| {
                sql_err!(sqlstate::NUMERIC_OUT_OF_RANGE, "{} out of range", type_name)
            })?;
        serial.set(column, next);
        Ok(next)
    }

    pub(crate) fn stage_table_serial_values(
        &self,
        index: usize,
        txid: u32,
    ) -> Option<[i64; MAX_COLUMNS]> {
        let mut serial = self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned");
        if !serial.dirty {
            return None;
        }
        serial.staged_by = Some(txid);
        Some(serial.values)
    }

    pub(crate) fn acknowledge_table_serial_values(&self, index: usize, txid: u32) {
        let mut serial = self.tables[index]
            .serial
            .lock()
            .expect("table serial state lock poisoned");
        if serial.staged_by == Some(txid) {
            serial.dirty = false;
            serial.staged_by = None;
        }
    }

    pub(crate) fn replay_table_serial_value(
        &mut self,
        index: usize,
        column: usize,
        value: i64,
        txid: u32,
    ) -> Result<(), SqlError> {
        if column >= self.table_def(index, txid).n_columns {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "journal serial column {} is outside the table definition",
                column
            ));
        }
        let serial = self.tables[index]
            .serial
            .get_mut()
            .expect("table serial state lock poisoned");
        serial.values[column] = value;
        serial.staged_by = None;
        Ok(())
    }

    pub(crate) fn install_table_serial_values(&mut self, index: usize, values: [i64; MAX_COLUMNS]) {
        *self.tables[index]
            .serial
            .get_mut()
            .expect("table serial state lock poisoned") = TableSerialState {
            values,
            ..TableSerialState::EMPTY
        };
    }

    pub fn table_def(&self, index: usize, txid: u32) -> &TableDef {
        match self.pending_table_def(index) {
            Some(pending) if pending.txid == txid => &pending.def,
            _ => &self.tables[index].def,
        }
    }

    pub(crate) fn table_definition_images(&self) -> TableDefinitionImages {
        TableDefinitionImages::new(&self.table_definition_images)
    }

    pub fn has_pending_table_def(&self, index: usize, txid: u32) -> bool {
        self.tables[index].pending_def_txid == Some(txid)
    }

    fn pending_table_def(&self, index: usize) -> Option<&PendingTableDef> {
        let table = &self.tables[index];
        let slot = table.pending_def_tail? as usize;
        Some(&self.pending_table_defs[slot].version)
    }

    fn clear_pending_table_defs(&mut self, index: usize) {
        let mut tail = self.tables[index].pending_def_tail.take();
        while let Some(slot) = tail {
            let entry = &mut self.pending_table_defs[slot as usize];
            tail = entry.previous;
            entry.used = false;
        }
        self.tables[index].pending_def_txid = None;
    }

    /// Installs the next transaction-owned table shape. `column_mapping`
    /// describes the transition from the previously visible definition to
    /// `def`; the stored mapping is composed back to the committed definition.
    pub fn write_table_def(
        &mut self,
        index: usize,
        txid: u32,
        mut def: TableDef,
        column_mapping: &[Option<SqlName>; MAX_COLUMNS],
        rewrites_rows: bool,
    ) -> Result<(), SqlError> {
        if let Some(other) = self.tables[index].ddl_locked_by_other(txid) {
            self.wait_for_transaction(txid, other)?;
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on \"{}\"",
                self.tables[index].def.name.as_str()
            ));
        }
        let current = *self.table_def(index, txid);
        def.has_toast |= current.has_toast
            || def
                .columns()
                .iter()
                .any(|column| column.ctype.typlen() == -1);
        def.has_rules |= current.has_rules;
        let prior = self.pending_table_def(index).copied();
        let mut composed = [None; MAX_COLUMNS];
        for (committed_column, target) in composed
            .iter_mut()
            .enumerate()
            .take(self.tables[index].def.n_columns)
        {
            let current_name = match prior {
                Some(version) if version.txid == txid => version.column_mapping[committed_column],
                _ => Some(self.tables[index].def.columns()[committed_column].name),
            };
            let Some(current_name) = current_name else {
                continue;
            };
            let Some(current_column) = current.column_index(current_name.as_str()) else {
                continue;
            };
            *target = column_mapping[current_column];
        }
        let version = PendingTableDef {
            txid,
            def,
            column_mapping: composed,
            rewrites_rows: rewrites_rows
                || prior.is_some_and(|version| version.txid == txid && version.rewrites_rows),
        };
        let previous = self.tables[index].pending_def_tail;
        if previous.is_some_and(|slot| {
            self.pending_table_defs[slot as usize].depth >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "relation \"{}\" exceeds max_catalog_versions_per_object ({})",
                self.tables[index].def.name.as_str(),
                self.max_catalog_versions_per_object
            ));
        }
        let depth = previous.map_or(1, |slot| self.pending_table_defs[slot as usize].depth + 1);
        let slot = match self.pending_table_defs.iter().position(|entry| !entry.used) {
            Some(slot) => {
                self.pending_table_defs[slot] = PendingTableDefSlot {
                    used: true,
                    previous,
                    depth,
                    version,
                };
                slot
            }
            None => {
                let slot = self.pending_table_defs.len();
                self.pending_table_defs
                    .push(PendingTableDefSlot {
                        used: true,
                        previous,
                        depth,
                        version,
                    })
                    .map_err(|_| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "pending table-definition pool is exhausted"
                        )
                    })?;
                slot
            }
        };
        self.tables[index].pending_def_tail = Some(slot as u32);
        self.tables[index].pending_def_txid = Some(txid);
        self.refresh_table_comment_identity(index, txid);
        Ok(())
    }

    pub fn rollback_table_def(&mut self, index: usize, txid: u32) {
        if self.tables[index].pending_def_txid != Some(txid) {
            return;
        }
        let Some(slot) = self.tables[index].pending_def_tail else {
            return;
        };
        let previous = self.pending_table_defs[slot as usize].previous;
        self.pending_table_defs[slot as usize].used = false;
        self.tables[index].pending_def_tail = previous;
        if previous.is_none() {
            self.tables[index].pending_def_txid = None;
        }
        self.refresh_table_comment_identity(index, txid);
    }

    fn refresh_table_comment_identity(&mut self, index: usize, txid: u32) {
        let database = Some(self.tables[index].database);
        let committed = self.tables[index].def;
        let visible = *self.table_def(index, txid);
        let changed = committed.schema != visible.schema || committed.name != visible.name;
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.database == database
                && matches!(comment.class, CommentClass::Relation | CommentClass::Type)
                && comment.schema == committed.schema
                && comment.name == committed.name
            {
                comment.pending_identity = changed.then_some(PendingCommentIdentity {
                    txid,
                    schema: visible.schema,
                    name: visible.name,
                });
            }
            if comment.used
                && comment.database == database
                && comment.class == CommentClass::Constraint
                && comment.subid == index as u32
                && comment.schema == committed.schema
                && changed
            {
                let name = comment
                    .pending_identity
                    .filter(|identity| identity.txid == txid)
                    .map_or(comment.name, |identity| identity.name);
                comment.pending_identity = Some(PendingCommentIdentity {
                    txid,
                    schema: visible.schema,
                    name,
                });
            }
        }
    }

    /// Promotes the latest pending definition after its WAL batch is durable.
    /// Row images are promoted separately by the transaction coordinator.
    pub fn commit_table_def(&mut self, index: usize, txid: u32) -> bool {
        let Some(pending) = self.pending_table_def(index).copied() else {
            return false;
        };
        if pending.txid != txid {
            return false;
        }
        let mut definition = pending.def;
        definition.has_toast |= self.tables[index].def.has_toast;
        definition.has_rules |= self.tables[index].def.has_rules;
        self.set_table_def(index, definition, &pending.column_mapping);
        self.clear_pending_table_defs(index);
        self.commit_constraint_comment_identities(index, txid);
        pending.rewrites_rows
    }

    fn commit_constraint_comment_identities(&mut self, table: usize, txid: u32) {
        for comment in self.comment_catalog().entries.iter_mut().filter(|comment| {
            comment.used
                && comment.database == Some(current_database())
                && comment.class == CommentClass::Constraint
                && comment.subid == table as u32
                && comment
                    .pending_identity
                    .is_some_and(|identity| identity.txid == txid)
        }) {
            let identity = comment
                .pending_identity
                .take()
                .expect("filtered pending constraint comment identity");
            comment.schema = identity.schema;
            comment.name = identity.name;
        }
    }

    pub fn finish_table_def_commit(&mut self, index: usize, rewrote_rows: bool) {
        if rewrote_rows {
            self.set_spill_list(index, &[]);
        }
    }

    /// Allocates a slot for a fresh table. Shared by replay (committed) and
    /// the executor (pending); `pending` overlays the uncommitted-CREATE
    /// state so the table is invisible to other transactions until commit.
    fn alloc_table(
        &mut self,
        def: TableDef,
        pending: Option<PendingDdl>,
    ) -> Result<usize, SqlError> {
        let Some(slot) = self.tables.iter().position(Table::is_free) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many tables (limit {})",
                self.tables.len()
            ));
        };
        // A reused slot must not keep the dropped table's value indexes.
        self.release_enforcers(slot);
        self.clear_pending_table_defs(slot);
        self.clear_pending_table_statistics(slot);
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Table,
            slot: slot as u16,
        });
        let ownership = self.initial_ownership(pending.map_or(0, |pending| pending.txid));
        let created_at = self.catalog_sequence.next();
        let stamp = created_at;
        self.cumulative_statistics().relations[slot] = RelationCumulativeStatistics::EMPTY;
        self.reset_implicit_index_statistics(slot);
        self.clear_table_rows(slot);
        let table = &mut self.tables[slot];
        table.database = current_database();
        table.def = def;
        table.ownership = ownership;
        table.created_at = stamp;
        table.live = pending.is_none();
        table.pending_ddl = pending;
        table.pending_has_rules_txid = None;
        table.mark_dirty();
        table.statistics = TableStatistics::EMPTY;
        table.statistics_dirty = false;
        table.statistics_wal_dirty = false;
        // A reused slot must not inherit the dropped table's sequences or
        // spilled rows.
        *table
            .serial
            .get_mut()
            .expect("table serial state lock poisoned") = TableSerialState::EMPTY;
        table.spill_ssts.fill(None);
        table.spill_through_lsn.fill(0);
        table.n_spill_ssts = 0;
        let schema = table.def.schema;
        let name = table.def.name;
        if let Err(error) = self.refresh_enforcers(slot) {
            self.rollback_create(slot);
            let table = &mut self.tables[slot];
            table.def = TableDef::empty();
            table.ownership = Ownership::BOOTSTRAP;
            table.created_at = 0;
            return Err(error);
        }
        self.rename_stored_query_dependency(DependencyClass::Table, slot, None, schema, name);
        Ok(slot)
    }

    /// Committed create (journal replay): the table is immediately part of the
    /// durable image.
    /// Rebinds every persisted user-defined column type from its stable name to
    /// the current catalog slot. Slots are runtime identities and may change
    /// across restart; scalar enums and enum/domain arrays therefore never
    /// trust the slot encoded in the table definition.
    fn bind_user_type_columns_to(&self, def: &mut TableDef, txid: u32) -> Result<(), SqlError> {
        for i in 0..def.n_columns {
            let col = &def.columns[i];
            match col.ctype {
                ColType::Enum(_) | ColType::Array(ArrElem::Enum(_)) => {
                    let UserTypeName { schema, name } = col.user_type.ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "reloaded enum column has no type identity"
                        )
                    })?;
                    let slot = self
                        .enum_slot(schema.as_str(), name.as_str(), txid)
                        .ok_or_else(|| {
                            sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "enum type \"{}.{}\" for a reloaded column does not exist",
                                schema.as_str(),
                                name.as_str()
                            )
                        })?;
                    def.columns[i].ctype = if matches!(col.ctype, ColType::Array(_)) {
                        ColType::Array(ArrElem::Enum(slot as u16))
                    } else {
                        ColType::Enum(slot as u16)
                    };
                }
                ColType::Array(ArrElem::Domain { .. }) => {
                    let UserTypeName { schema, name } = col.user_type.ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "reloaded domain-array column has no type identity"
                        )
                    })?;
                    let slot = self
                        .domain_slot(schema.as_str(), name.as_str(), txid)
                        .ok_or_else(|| {
                            sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "domain type \"{}.{}\" for a reloaded column does not exist",
                                schema.as_str(),
                                name.as_str()
                            )
                        })?;
                    let domain = self.domain(slot);
                    let element = ArrElem::domain(slot as u16, domain.base).ok_or_else(|| {
                        sql_err!(
                            sqlstate::FEATURE_NOT_SUPPORTED,
                            "arrays of domain {} require a scalar base type",
                            name.as_str()
                        )
                    })?;
                    def.columns[i].ctype = ColType::Array(element);
                }
                _ if col.user_type.is_some_and(|identity| {
                    self.domain_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                        .is_some()
                }) =>
                {
                    let identity = col.user_type.expect("domain identity checked above");
                    let slot = self
                        .domain_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                        .expect("domain identity checked above");
                    // Scalar domains execute as their base representation, but
                    // their durable identity is the domain.  Resolve it before
                    // the `Composite`/`Enum` cases below so a domain named
                    // independently from its composite base cannot be
                    // mistaken for that base during replay.
                    def.columns[i].ctype = self.domain(slot).base;
                }
                ColType::Composite(_) | ColType::Array(ArrElem::Composite(_)) => {
                    let UserTypeName { schema, name } = col.user_type.ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "reloaded composite column has no type identity"
                        )
                    })?;
                    let slot = self
                        .composite_slot(schema.as_str(), name.as_str(), txid)
                        .ok_or_else(|| {
                            sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "composite type \"{}.{}\" for a reloaded column does not exist",
                                schema.as_str(),
                                name.as_str()
                            )
                        })?;
                    def.columns[i].ctype = if matches!(col.ctype, ColType::Array(_)) {
                        ColType::Array(ArrElem::Composite(slot as u16))
                    } else {
                        ColType::Composite(slot as u16)
                    };
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn bind_user_type_columns(&self, def: &mut TableDef) -> Result<(), SqlError> {
        self.bind_user_type_columns_to(def, 0)
    }

    pub fn create_table(&mut self, mut def: TableDef) -> Result<usize, SqlError> {
        if def.n_columns > MAX_RELATION_COLUMNS {
            return Err(sql_err!(
                sqlstate::TOO_MANY_COLUMNS,
                "tables can have at most {} columns",
                MAX_RELATION_COLUMNS
            ));
        }
        def.has_toast |= def
            .columns()
            .iter()
            .any(|column| column.ctype.typlen() == -1);
        if self
            .find_table(def.schema.as_str(), def.name.as_str())
            .is_some()
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                def.name.as_str()
            ));
        }
        // A reloaded enum column decodes as `Enum(ENUM_SLOT_UNRESOLVED)` plus the
        // enum's name (in `domain`); bind it to the live catalog slot now that
        // the enum has itself been loaded (WAL/checkpoint order guarantees it).
        self.bind_user_type_columns(&mut def)?;
        let slot = self.alloc_table(def, None)?;
        Ok(slot)
    }

    /// Starts replaying ALTER TABLE's two-record in-place rewrite.
    pub fn begin_replay_table_rewrite(
        &mut self,
        previous_schema: &str,
        previous_name: &str,
        preserve_rows: bool,
        column_mapping: [u16; MAX_COLUMNS],
    ) -> Result<(), SqlError> {
        if self.replay_table_rewrite.is_some() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "corrupt journal contains nested table rewrite markers"
            ));
        }
        let Some(index) = self.find_table(previous_schema, previous_name) else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "journal rewrites unknown table \"{}\"",
                previous_name
            ));
        };
        self.replay_table_rewrite = Some(ReplayTableRewrite {
            table: index,
            preserve_rows,
            column_mapping,
        });
        Ok(())
    }

    /// Completes a pending ALTER TABLE replay when its final definition arrives.
    /// Returns false when the definition is an ordinary CREATE TABLE.
    pub fn complete_replay_table_rewrite(&mut self, mut def: TableDef) -> Result<bool, SqlError> {
        let Some(rewrite) = self.replay_table_rewrite.take() else {
            return Ok(false);
        };
        self.bind_user_type_columns(&mut def)?;
        let mut column_mapping = [None; MAX_COLUMNS];
        for (old_column, &target_column) in rewrite.column_mapping.iter().enumerate() {
            if target_column == u16::MAX {
                continue;
            }
            let Some(target) = def.columns().get(target_column as usize) else {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "corrupt journal maps table column {} past the rewritten definition",
                    target_column
                ));
            };
            column_mapping[old_column] = Some(target.name);
        }
        let index = rewrite.table;
        def.has_toast |= self.tables[index].def.has_toast
            || def
                .columns()
                .iter()
                .any(|column| column.ctype.typlen() == -1);
        def.has_rules |= self.tables[index].def.has_rules;
        self.set_table_def(index, def, &column_mapping);
        if !rewrite.preserve_rows {
            self.clear_table_rows(index);
            self.tables[index].statistics = TableStatistics::EMPTY;
            self.tables[index].statistics_wal_dirty = false;
            self.set_spill_list(index, &[]);
        }
        self.mark_value_bindings_dirty(index);
        Ok(true)
    }

    pub fn ensure_no_pending_replay_table_rewrite(&self) -> Result<(), SqlError> {
        if self.replay_table_rewrite.is_some() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "corrupt journal ends during a table rewrite"
            ));
        }
        Ok(())
    }

    /// Transactional create: the table exists only for `txid` until commit.
    /// A name already visible to `txid` is a duplicate (42P07); a name held by
    /// another transaction's uncommitted DDL joins the shared wait graph.
    pub fn create_table_in(&mut self, mut def: TableDef, txid: u32) -> Result<usize, SqlError> {
        def.has_toast |= def
            .columns()
            .iter()
            .any(|column| column.ctype.typlen() == -1);
        self.require_schema_create(def.schema.as_str(), txid)?;
        if self
            .find_visible(def.schema.as_str(), def.name.as_str(), txid)
            .is_some()
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                def.name.as_str()
            ));
        }
        if let Some(other) =
            self.ddl_name_locked_by_other(def.schema.as_str(), def.name.as_str(), txid)
        {
            self.wait_for_transaction(txid, other)?;
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on \"{}\"",
                def.name.as_str()
            ));
        }
        let slot = self.alloc_table(
            def,
            Some(PendingDdl {
                txid,
                creating: true,
            }),
        )?;
        if def.persistence == RelationPersistence::Temporary {
            self.mark_temporary_transaction(txid);
        }
        Ok(slot)
    }

    /// The txid of another transaction holding uncommitted DDL for `name`.
    fn ddl_name_locked_by_other(&self, schema: &str, name: &str, txid: u32) -> Option<u32> {
        self.tables
            .iter()
            .enumerate()
            .filter(|(_, table)| table.database == current_database())
            .filter(|(index, table)| {
                (table.def.schema.as_str() == schema && table.def.name.as_str() == name)
                    || self.pending_table_def(*index).is_some_and(|pending| {
                        pending.def.schema.as_str() == schema && pending.def.name.as_str() == name
                    })
            })
            .find_map(|(_, table)| table.ddl_locked_by_other(txid))
    }

    /// Committed drop (journal replay): rows are retained; the slot is freed at
    /// checkpoint.
    pub fn drop_table(&mut self, index: usize) {
        let (schema, name) = (self.tables[index].def.schema, self.tables[index].def.name);
        self.drop_object_comments(CommentClass::Relation, schema.as_str(), name.as_str());
        self.drop_object_comments(CommentClass::Type, schema.as_str(), name.as_str());
        self.drop_comments_by_subid(CommentClass::Constraint, index as u32);
        self.release_enforcers(index);
        self.clear_pending_table_defs(index);
        self.clear_pending_table_statistics(index);
        self.tables[index].live = false;
        self.tables[index].pending_ddl = None;
        self.tables[index].mark_dirty();
        self.commit_triggers_for_table(index);
        self.commit_policies_for_table(index);
        self.commit_extended_statistics_for_table(index);
    }

    /// Transactional drop: the table stays visible to every other transaction
    /// (committed baseline) until `txid` commits.
    pub fn drop_table_in(&mut self, index: usize, txid: u32) {
        self.tables[index].pending_ddl = Some(PendingDdl {
            txid,
            creating: false,
        });
        for rule in self.view_rule_catalog().rules.iter_mut().filter(|rule| {
            rule.database == current_database()
                && rule.visible_to(txid)
                && rule.definition_for(txid).target == RuleTarget::Table(index as u16)
        }) {
            rule.ddl_state = rule.ddl_state.drop_by(txid);
        }
        self.tables[index].mark_dirty();
    }

    /// Promotes an uncommitted CREATE to the committed image.
    pub fn commit_create(&mut self, index: usize) {
        self.tables[index].live = true;
        self.tables[index].pending_ddl = None;
    }

    /// Applies a committed DROP: the table leaves the image and its rows are
    /// reclaimed.
    pub fn commit_drop(&mut self, index: usize) {
        let (schema, name) = (self.tables[index].def.schema, self.tables[index].def.name);
        self.drop_object_comments(CommentClass::Relation, schema.as_str(), name.as_str());
        self.drop_object_comments(CommentClass::Type, schema.as_str(), name.as_str());
        self.drop_comments_by_subid(CommentClass::Constraint, index as u32);
        self.release_enforcers(index);
        self.reset_relation_statistics(index);
        self.reset_implicit_index_statistics(index);
        self.clear_pending_table_defs(index);
        self.clear_pending_table_statistics(index);
        self.tables[index].live = false;
        self.tables[index].pending_ddl = None;
        self.clear_table_rows(index);
        self.tables[index].statistics_wal_dirty = false;
        self.commit_triggers_for_table(index);
        self.commit_policies_for_table(index);
        self.commit_extended_statistics_for_table(index);
        self.commit_rules_for_table(index);
    }

    /// Rolls back an uncommitted CREATE, freeing the slot.
    pub fn rollback_create(&mut self, index: usize) {
        self.release_enforcers(index);
        self.clear_pending_table_defs(index);
        self.clear_pending_table_statistics(index);
        self.tables[index].live = false;
        self.tables[index].pending_ddl = None;
        self.clear_table_rows(index);
        self.tables[index].statistics_wal_dirty = false;
    }

    /// Rolls back an uncommitted DROP: the table returns to the committed
    /// image unchanged.
    pub fn rollback_drop(&mut self, index: usize) {
        self.tables[index].pending_ddl = None;
        for rule in self.view_rule_catalog().rules.iter_mut().filter(|rule| {
            rule.database == current_database()
                && rule.definition.target == RuleTarget::Table(index as u16)
                && matches!(rule.ddl_state, CatalogDdlState::PendingDrop { .. })
        }) {
            rule.ddl_state = CatalogDdlState::Present;
        }
    }

    /// Whether any live view exists (lets the executor skip view expansion).
    pub fn has_any_view(&self) -> bool {
        self.view_rule_catalog().views.iter().any(|view| {
            view.database == current_database() && view.ddl_state != CatalogDdlState::Absent
        })
    }

    /// Owned committed view images for nested catalog reads.
    pub fn live_views(&self) -> impl Iterator<Item = ViewDef> + '_ {
        self.views_with_slots().map(|(_, view)| view)
    }

    /// Committed views with their slot indices, for OID assignment.
    pub fn views_with_slots(&self) -> impl Iterator<Item = (usize, ViewDef)> + '_ {
        self.view_entries().accepting(0, |view, _| {
            view.database == current_database() && view.ddl_state == CatalogDdlState::Present
        })
    }

    /// Views visible to `txid`, including the transaction's own DDL.
    pub(crate) fn views_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ViewDef)> + '_ {
        self.view_entries().accepting(txid, |view, txid| {
            view.database == current_database() && view.visible_to(txid)
        })
    }

    fn view_rule_catalog(&self) -> std::sync::MutexGuard<'_, ViewRuleCatalog> {
        self.view_rule_catalog
            .lock()
            .expect("view and rule catalog lock poisoned")
    }

    fn view_entries(&self) -> ViewRuleIter<'_, ViewDef> {
        ViewRuleIter {
            catalog: &self.view_rule_catalog,
            entries: |catalog| &catalog.views,
            next_slot: 0,
            txid: 0,
            accept: |_, _| true,
        }
    }

    fn rule_entries(&self) -> ViewRuleIter<'_, RuleDef> {
        ViewRuleIter {
            catalog: &self.view_rule_catalog,
            entries: |catalog| &catalog.rules,
            next_slot: 0,
            txid: 0,
            accept: |_, _| true,
        }
    }

    pub(crate) fn view(&self, slot: usize) -> ViewDef {
        self.view_rule_catalog().views[slot]
    }

    pub(crate) fn view_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let view = self.view(slot);
        view.database == current_database() && view.visible_to(txid)
    }

    pub(crate) fn view_dependencies(&self, slot: usize) -> StoredQueryDependencyImage<'_> {
        self.committed_dependencies(StoredQueryDependencyOwner::Rule(
            self.view(slot).return_rule,
        ))
    }

    pub(crate) fn view_return_rule(&self, slot: usize) -> usize {
        usize::from(self.view(slot).return_rule)
    }

    pub(crate) fn snapshot_view_query(
        &self,
        slot: usize,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDefinition, SqlError> {
        let catalog = self.view_rule_catalog();
        let rule_slot = catalog.views[slot].return_rule;
        let definition = &catalog.rules[usize::from(rule_slot)].definition;
        let dependencies = self.snapshot_dependency_image(
            self.committed_dependency_image(StoredQueryDependencyOwner::Rule(rule_slot)),
            arena,
        )?;
        Ok(StoredQueryDefinition {
            sql: StackStr::from_str(
                definition
                    .action_sql()
                    .next()
                    .expect("every view has one _RETURN action"),
            ),
            creation_path: definition.creation_path,
            dependencies,
        })
    }

    pub(crate) fn view_sql(&self, slot: usize) -> StackStr<VIEW_SQL_MAX> {
        let catalog = self.view_rule_catalog();
        let rule = &catalog.rules[usize::from(catalog.views[slot].return_rule)];
        StackStr::from_str(
            rule.definition
                .action_sql()
                .next()
                .expect("every view has one _RETURN action"),
        )
    }

    pub(crate) fn view_sql_for(&self, view: &ViewDef) -> StackStr<VIEW_SQL_MAX> {
        let definition = self.rule(usize::from(view.return_rule)).definition;
        StackStr::from_str(
            definition
                .action_sql()
                .next()
                .expect("every view has one _RETURN action"),
        )
    }

    pub(crate) fn view_creation_path(&self, slot: usize) -> StackStr<128> {
        let catalog = self.view_rule_catalog();
        catalog.rules[usize::from(catalog.views[slot].return_rule)]
            .definition
            .creation_path
    }

    pub(crate) fn view_count(&self) -> usize {
        self.view_catalog_capacity
    }

    pub(crate) fn publication_count(&self) -> usize {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")
            .len()
    }

    /// Committed publications for catalog visibility and replication setup.
    pub fn live_publications(&self) -> impl Iterator<Item = PublicationDef> + '_ {
        PublicationIter {
            catalog: &self.publications,
            next_slot: 0,
        }
        .map(|(_, publication)| publication)
        .filter(|publication| {
            publication.database == current_database()
                && publication.ddl_state == CatalogDdlState::Present
        })
    }

    pub fn publications_with_slots(&self) -> impl Iterator<Item = (usize, PublicationDef)> + '_ {
        PublicationIter {
            catalog: &self.publications,
            next_slot: 0,
        }
        .filter(|(_, publication)| {
            publication.database == current_database()
                && publication.ddl_state == CatalogDdlState::Present
        })
    }

    pub(crate) fn publication_for_event_trigger(&self, slot: usize) -> PublicationDef {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")[slot]
    }

    pub(crate) fn publications_with_slots_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, PublicationDef)> + '_ {
        PublicationIter {
            catalog: &self.publications,
            next_slot: 0,
        }
        .filter(move |(_, publication)| {
            publication.database == current_database() && publication.visible_to(txid)
        })
    }

    /// Committed publication lookup for replication protocol setup.
    pub(crate) fn publication(&self, name: &str) -> Option<PublicationDef> {
        self.live_publications()
            .find(|publication| publication.name.as_str() == name)
    }

    pub(crate) fn publication_definition(
        &self,
        name: &str,
        txid: u32,
    ) -> Option<(usize, PublicationDefinition)> {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")
            .iter()
            .enumerate()
            .find_map(|(slot, publication)| {
                (publication.database == current_database()
                    && publication.visible_to(txid)
                    && publication.name_for(txid).as_str() == name)
                    .then_some((slot, publication.definition_for(txid)))
            })
    }

    pub(crate) fn publication_owner(&self, slot: usize, txid: u32) -> u16 {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")[slot]
            .ownership
            .owner_to(txid)
    }

    pub(crate) fn restore_publication_owner(&mut self, slot: usize, owner: u16) {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")[slot]
            .ownership = Ownership {
            owner,
            pending: None,
        };
    }

    pub(crate) fn set_publication_owner(
        &mut self,
        slot: usize,
        owner: usize,
        txid: u32,
    ) -> Result<Option<PendingOwnership>, SqlError> {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let publication = &mut publications[slot];
        if let Some(blocker) = publication.pending_owner_other_than(txid) {
            let name = publication.name;
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let ownership = &mut publication.ownership;
        let prior = ownership.pending;
        ownership.pending = Some(PendingOwnership {
            txid,
            owner: owner as u16,
        });
        Ok(prior)
    }

    pub(crate) fn restore_publication_owner_pending(
        &mut self,
        slot: usize,
        prior: Option<PendingOwnership>,
    ) {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")[slot]
            .ownership
            .pending = prior;
    }

    pub(crate) fn rename_publication(
        &mut self,
        slot: usize,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingPublicationName>, SqlError> {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        if let Some(blocker) = publications[slot].pending_owner_other_than(txid) {
            let current_name = publications[slot].name;
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, current_name.as_str()));
        }
        if publications
            .iter()
            .enumerate()
            .any(|(other_slot, publication)| {
                other_slot != slot
                    && publication.database == current_database()
                    && publication.visible_to(txid)
                    && publication.name_for(txid) == name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "publication \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(blocker) =
            publications
                .iter()
                .enumerate()
                .find_map(|(other_slot, publication)| {
                    (other_slot != slot
                        && publication.database == current_database()
                        && publication.identity_matches(name))
                    .then(|| publication.pending_owner_other_than(txid))
                    .flatten()
                })
        {
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let publication = &mut publications[slot];
        if let Some(pending) = publication.pending_name
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "publication \"{}\" is being renamed by another transaction",
                publication.name.as_str()
            ));
        }
        let prior = publication.pending_name;
        publication.pending_name = Some(PendingPublicationName { txid, name });
        Ok(prior)
    }

    pub(crate) fn commit_publication_rename(&mut self, slot: usize, txid: u32) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let publication = &mut publications[slot];
        if let Some(pending) = publication.pending_name
            && pending.txid == txid
        {
            publication.name = pending.name;
            publication.pending_name = None;
        }
    }

    pub(crate) fn rollback_publication_rename(
        &mut self,
        slot: usize,
        prior: Option<PendingPublicationName>,
    ) {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")[slot]
            .pending_name = prior;
    }

    pub(crate) fn publication_selecting_schema(
        &self,
        schema: u8,
        txid: u32,
    ) -> Option<(SqlName, PublicationDefinition)> {
        self.publications
            .lock()
            .expect("publication catalog lock poisoned")
            .iter()
            .find_map(|publication| {
                let definition = publication.definition_for(txid);
                (publication.database == current_database()
                    && publication.visible_to(txid)
                    && definition.schemas[..definition.schema_count].contains(&schema))
                .then_some((publication.name_for(txid), definition))
            })
    }

    pub(crate) fn require_publication_owner(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        if txid == 0 {
            return Ok(());
        }
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let (owner, name) = {
            let publications = self
                .publications
                .lock()
                .expect("publication catalog lock poisoned");
            (
                publications[slot].ownership.owner_to(txid) as usize,
                publications[slot].name,
            )
        };
        if self.role(role).attributes_to(txid).superuser
            || owner == role
            || self.role_can_set(role, owner, txid)
        {
            return Ok(());
        }
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of publication {}",
            name.as_str()
        ))
    }

    fn insert_replication_slot(
        &self,
        name: ReplicationSlotName,
        restart_lsn: u64,
        confirmed_flush_lsn: u64,
        behavior: ReplicationSlotBehavior,
    ) -> Result<usize, SqlError> {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        if replication_slots.iter().any(|slot| {
            slot.database == current_database() && slot.live && slot.name.as_str() == name.as_str()
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "replication slot \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(index) = replication_slots.iter().position(|slot| !slot.live) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many replication slots (limit {})",
                replication_slots.len()
            ));
        };
        replication_slots[index] = ReplicationSlotDef {
            database: current_database(),
            name: name.sql_name(),
            restart_lsn,
            confirmed_flush_lsn,
            behavior,
            active: false,
            active_pid: None,
            sent_lsn: confirmed_flush_lsn,
            total_txns: 0,
            total_bytes: 0,
            stats_reset: None,
            live: true,
        };
        Ok(index)
    }

    pub(crate) fn create_replication_slot(
        &mut self,
        name: ReplicationSlotName,
        restart_lsn: u64,
        behavior: ReplicationSlotBehavior,
    ) -> Result<usize, SqlError> {
        self.insert_replication_slot(name, restart_lsn, restart_lsn, behavior)
    }

    pub(crate) fn replication_slot(&self, name: &str) -> Option<ReplicationSlotDef> {
        self.replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned")
            .iter()
            .copied()
            .find(|slot| {
                slot.database == current_database() && slot.live && slot.name.as_str() == name
            })
    }

    pub(crate) fn alter_replication_slot(
        &mut self,
        name: ReplicationSlotName,
        behavior: ReplicationSlotBehavior,
    ) -> Result<(), SqlError> {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let slot = replication_slots
            .iter_mut()
            .find(|slot| {
                slot.database == current_database() && slot.live && slot.name == name.sql_name()
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "replication slot \"{}\" does not exist",
                    name.as_str()
                )
            })?;
        if slot.active {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "replication slot \"{}\" is active",
                name.as_str()
            ));
        }
        slot.behavior = behavior;
        Ok(())
    }

    pub(crate) fn replication_slots_with_slots(
        &self,
    ) -> impl Iterator<Item = (usize, ReplicationSlotDef)> + '_ {
        ReplicationSlotIter {
            catalog: &self.replication_slots,
            next_slot: 0,
        }
        .filter(|(_, slot)| slot.database == current_database() && slot.live)
    }

    pub(crate) fn replication_slot_capacity(&self) -> usize {
        self.replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned")
            .len()
    }

    /// The oldest durable point any logical consumer may still request.
    /// WAL segment collection must retain the segment straddling this LSN.
    pub(crate) fn oldest_replication_restart_lsn(&self) -> Option<u64> {
        self.replication_slots_with_slots()
            .map(|(_, slot)| slot.restart_lsn)
            .min()
    }

    pub(crate) fn restore_replication_slot(
        &mut self,
        name: ReplicationSlotName,
        restart_lsn: u64,
        confirmed_flush_lsn: u64,
        behavior: ReplicationSlotBehavior,
    ) -> Result<(), SqlError> {
        if confirmed_flush_lsn < restart_lsn {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "replication slot confirmed LSN precedes restart LSN"
            ));
        }
        self.insert_replication_slot(name, restart_lsn, confirmed_flush_lsn, behavior)
            .map(|_| ())
    }

    pub(crate) fn drop_replication_slot(&mut self, name: &str) -> Result<(), SqlError> {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let Some(slot) = replication_slots.iter_mut().find(|slot| {
            slot.database == current_database() && slot.live && slot.name.as_str() == name
        }) else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "replication slot \"{}\" does not exist",
                name
            ));
        };
        if slot.active {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "replication slot \"{}\" is active",
                name
            ));
        }
        *slot = ReplicationSlotDef::EMPTY;
        Ok(())
    }

    pub(crate) fn prepare_replication_slot_advance(
        &self,
        name: &str,
        confirmed_flush_lsn: u64,
    ) -> Result<ReplicationSlotAdvance, SqlError> {
        let replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let (index, slot) = replication_slots
            .iter()
            .enumerate()
            .find(|(_, slot)| {
                slot.database == current_database() && slot.live && slot.name.as_str() == name
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "replication slot \"{}\" does not exist",
                    name
                )
            })?;
        if confirmed_flush_lsn < slot.confirmed_flush_lsn {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "replication slot confirmed LSN cannot move backwards"
            ));
        }
        Ok(ReplicationSlotAdvance {
            slot: index,
            database: slot.database,
            name: slot.name,
            confirmed_flush_lsn,
        })
    }

    pub(crate) fn apply_replication_slot_advance(&mut self, advance: ReplicationSlotAdvance) {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let slot = replication_slots
            .get_mut(advance.slot)
            .filter(|slot| {
                slot.database == advance.database && slot.live && slot.name == advance.name
            })
            .expect("validated replication slot must remain live until its WAL commit");
        slot.confirmed_flush_lsn = advance.confirmed_flush_lsn;
        slot.restart_lsn = advance.confirmed_flush_lsn;
    }

    pub(crate) fn activate_replication_slot(
        &mut self,
        name: &str,
        backend_pid: i32,
    ) -> Result<u64, SqlError> {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let slot = replication_slots
            .iter_mut()
            .find(|slot| {
                slot.database == current_database() && slot.live && slot.name.as_str() == name
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::UNDEFINED_OBJECT,
                    "replication slot \"{}\" does not exist",
                    name
                )
            })?;
        if slot.active {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "replication slot \"{}\" is active",
                name
            ));
        }
        slot.active = true;
        slot.active_pid = Some(backend_pid);
        slot.sent_lsn = slot.confirmed_flush_lsn;
        Ok(slot.confirmed_flush_lsn)
    }

    pub(crate) fn record_replication_slot_transaction(
        &mut self,
        name: &str,
        sent_lsn: u64,
        bytes: usize,
    ) {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        let Some(slot) = replication_slots.iter_mut().find(|slot| {
            slot.database == current_database() && slot.live && slot.name.as_str() == name
        }) else {
            return;
        };
        slot.sent_lsn = slot.sent_lsn.max(sent_lsn);
        slot.total_txns = slot.total_txns.saturating_add(1);
        slot.total_bytes = slot
            .total_bytes
            .saturating_add(i64::try_from(bytes).unwrap_or(i64::MAX));
    }

    pub(crate) fn reset_replication_slot_statistics(
        &mut self,
        name: Option<&str>,
        reset_at: i64,
    ) -> Result<(), SqlError> {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        if let Some(name) = name
            && !replication_slots.iter().any(|slot| {
                slot.database == current_database() && slot.live && slot.name.as_str() == name
            })
        {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "replication slot \"{}\" does not exist",
                name
            ));
        }
        for slot in replication_slots.iter_mut().filter(|slot| {
            slot.database == current_database()
                && slot.live
                && name.is_none_or(|name| slot.name.as_str() == name)
        }) {
            slot.total_txns = 0;
            slot.total_bytes = 0;
            slot.stats_reset = Some(reset_at);
        }
        Ok(())
    }

    pub(crate) fn deactivate_replication_slot(&mut self, name: &str) {
        let mut replication_slots = self
            .replication_slots
            .lock()
            .expect("replication slot catalog lock poisoned");
        if let Some(slot) = replication_slots.iter_mut().find(|slot| {
            slot.database == current_database() && slot.live && slot.name.as_str() == name
        }) {
            slot.active = false;
            slot.active_pid = None;
        }
    }

    pub(crate) fn subscriptions_with_slots_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, SubscriptionDef)> + '_ {
        SubscriptionIter {
            catalog: &self.subscription_catalog,
            next_slot: 0,
        }
        .filter(move |(_, subscription)| {
            subscription.database == current_database() && subscription.visible_to(txid)
        })
    }

    pub(crate) fn reset_subscription_statistics(
        &mut self,
        slot: Option<usize>,
        txid: u32,
        reset_at: i64,
    ) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        for (index, subscription) in catalog.definitions.iter_mut().enumerate() {
            if subscription.database == current_database()
                && subscription.visible_to(txid)
                && slot.is_none_or(|slot| slot == index)
            {
                subscription.apply_error_count = 0;
                subscription.sync_error_count = 0;
                subscription.stats_reset = Some(reset_at);
            }
        }
    }

    pub(crate) fn subscription_for_event_trigger(&self, slot: usize) -> SubscriptionDef {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
    }

    pub(crate) fn subscriptions_with_slots_durable(
        &self,
    ) -> impl Iterator<Item = (usize, SubscriptionDef)> + '_ {
        SubscriptionIter {
            catalog: &self.subscription_catalog,
            next_slot: 0,
        }
        .filter(|(_, subscription)| {
            subscription.database == current_database()
                && (subscription.ddl_state == CatalogDdlState::Present
                    || subscription.cleanup != SubscriptionCleanup::None)
        })
    }

    pub(crate) fn subscription(&self, name: &str, txid: u32) -> Option<(usize, SubscriptionDef)> {
        self.subscriptions_with_slots_visible_to(txid)
            .find(|(_, subscription)| subscription.name_for(txid).as_str() == name)
    }

    pub(crate) fn create_subscription(
        &mut self,
        spec: SubscriptionSpec<'_>,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let owner = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        if spec.publications.is_empty() {
            return Err(sql_err!(
                sqlstate::SYNTAX_ERROR,
                "CREATE SUBSCRIPTION requires at least one publication"
            ));
        }
        if spec.publications.len() > MAX_SUBSCRIPTION_PUBLICATIONS {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many publications in subscription (limit {})",
                MAX_SUBSCRIPTION_PUBLICATIONS
            ));
        }
        if !matches!(
            (spec.slot, spec.bootstrap),
            (
                SubscriptionSlot::Absent,
                SubscriptionBootstrap::Deferred
                    | SubscriptionBootstrap::CopyWithoutSlot
                    | SubscriptionBootstrap::Ready
            ) | (
                SubscriptionSlot::External(_),
                SubscriptionBootstrap::Deferred
                    | SubscriptionBootstrap::CopyExternalSlot
                    | SubscriptionBootstrap::Refresh { .. }
                    | SubscriptionBootstrap::Ready
            ) | (
                SubscriptionSlot::Managed(_),
                SubscriptionBootstrap::CreateManagedSlot { .. }
                    | SubscriptionBootstrap::Refresh { .. }
                    | SubscriptionBootstrap::Ready
            )
        ) {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "subscription slot ownership does not match its bootstrap state"
            ));
        }
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some((existing_slot, subscription)) =
            catalog
                .definitions
                .iter()
                .enumerate()
                .find(|(_, subscription)| {
                    subscription.database == current_database()
                        && subscription.ddl_state != CatalogDdlState::Absent
                        && (subscription.name == spec.name
                            || subscription
                                .pending_name
                                .is_some_and(|pending| pending.name == spec.name))
                })
        {
            if let Some(blocker) = Self::subscription_change_blocker(&catalog, existing_slot, txid)
            {
                let name = subscription.name;
                drop(catalog);
                return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
            }
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "subscription \"{}\" already exists",
                spec.name.as_str()
            ));
        }
        let Some(slot) = catalog.definitions.iter().position(|subscription| {
            subscription.ddl_state == CatalogDdlState::Absent
                && subscription.cleanup == SubscriptionCleanup::None
        }) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many subscriptions (limit {})",
                catalog.definitions.len()
            ));
        };
        let mut publications = [SqlName::EMPTY; MAX_SUBSCRIPTION_PUBLICATIONS];
        publications[..spec.publications.len()].copy_from_slice(spec.publications);
        let created_at = self.catalog_sequence.next();
        catalog.definitions[slot] = SubscriptionDef {
            database: current_database(),
            created_at,
            definition_generation: 1,
            name: spec.name,
            pending_name: None,
            connection: spec.connection,
            publications,
            publication_count: spec.publications.len(),
            pending_definition: None,
            enabled: spec.enabled,
            pending_enabled: None,
            slot: spec.slot,
            behavior: spec.behavior,
            bootstrap: spec.bootstrap,
            pending_bootstrap: None,
            pending_relation_refresh: None,
            cleanup: SubscriptionCleanup::None,
            failure: None,
            apply_error_count: 0,
            sync_error_count: 0,
            stats_reset: None,
            confirmed_lsn: 0,
            origin_lsn: 0,
            ownership: Ownership {
                owner: owner as u16,
                pending: None,
            },
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn drop_subscription(
        &mut self,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let Some(slot) = catalog.definitions.iter().position(|subscription| {
            subscription.database == current_database()
                && subscription.visible_to(txid)
                && subscription.name_for(txid).as_str() == name
        }) else {
            return Ok(None);
        };
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.drop_by(txid);
        Ok(Some(slot))
    }

    pub(crate) fn require_subscription_owner(
        &self,
        slot: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        let role = self.current_role_slot(txid).ok_or_else(|| {
            sql_err!(
                sqlstate::INSUFFICIENT_PRIVILEGE,
                "current role is not present in the role catalog"
            )
        })?;
        let (owner, name) = {
            let catalog = self
                .subscription_catalog
                .lock()
                .expect("subscription catalog lock poisoned");
            let subscription = catalog.definitions[slot];
            (
                subscription.ownership.owner_to(txid) as usize,
                subscription.name,
            )
        };
        if self.role(role).attributes_to(txid).superuser || role == owner {
            return Ok(());
        }
        Err(sql_err!(
            sqlstate::INSUFFICIENT_PRIVILEGE,
            "must be owner of subscription {}",
            name.as_str()
        ))
    }

    pub(crate) fn commit_subscription_create(&mut self, slot: usize) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_create();
    }

    pub(crate) fn restore_subscription_stream_identity(
        &mut self,
        slot: usize,
        created_at: u64,
        definition_generation: u64,
    ) -> Result<(), SqlError> {
        if created_at == 0 || definition_generation == 0 {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "subscription stream identity must be nonzero"
            ));
        }
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = &mut catalog.definitions[slot];
        subscription.created_at = created_at;
        subscription.definition_generation = definition_generation;
        self.catalog_sequence.observe(created_at);
        Ok(())
    }

    pub(crate) fn restore_subscription_owner(&mut self, slot: usize, owner: u16) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .ownership = Ownership {
            owner,
            pending: None,
        };
    }

    pub(crate) fn set_subscription_owner(
        &mut self,
        slot: usize,
        owner: usize,
        txid: u32,
    ) -> Result<Option<PendingOwnership>, SqlError> {
        self.require_subscription_owner(slot, txid)?;
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let prior = catalog.definitions[slot].ownership.pending;
        catalog.definitions[slot].ownership.pending = Some(PendingOwnership {
            txid,
            owner: owner as u16,
        });
        Ok(prior)
    }

    pub(crate) fn restore_subscription_owner_pending(
        &mut self,
        slot: usize,
        prior: Option<PendingOwnership>,
    ) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .ownership
            .pending = prior;
    }

    pub(crate) fn commit_subscription_owner(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let ownership = &mut catalog.definitions[slot].ownership;
        if let Some(pending) = ownership.pending
            && pending.txid == txid
        {
            ownership.owner = pending.owner;
            ownership.pending = None;
        }
    }

    pub(crate) fn rename_subscription(
        &mut self,
        slot: usize,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingSubscriptionName>, SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let current_name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, current_name.as_str()));
        }
        if let Some(subscription) =
            catalog
                .definitions
                .iter()
                .enumerate()
                .find_map(|(other, subscription)| {
                    (other != slot
                        && subscription.database == current_database()
                        && subscription.ddl_state != CatalogDdlState::Absent
                        && (subscription.name == name
                            || subscription
                                .pending_name
                                .is_some_and(|pending| pending.name == name)))
                    .then_some((other, subscription))
                })
        {
            let (other, subscription) = subscription;
            if let Some(blocker) = Self::subscription_change_blocker(&catalog, other, txid) {
                let current_name = subscription.name;
                drop(catalog);
                return Err(self.catalog_ddl_wait_error(txid, blocker, current_name.as_str()));
            }
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "subscription \"{}\" already exists",
                name.as_str()
            ));
        }
        let subscription = &mut catalog.definitions[slot];
        if let Some(pending) = subscription.pending_name
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "subscription \"{}\" is being renamed by another transaction",
                subscription.name.as_str()
            ));
        }
        let prior = subscription.pending_name;
        subscription.pending_name = Some(PendingSubscriptionName { txid, name });
        Ok(prior)
    }

    pub(crate) fn commit_subscription_rename(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let (created_at, definition_generation) = {
            let subscription = &mut catalog.definitions[slot];
            let Some(pending) = subscription
                .pending_name
                .filter(|pending| pending.txid == txid)
            else {
                return;
            };
            subscription.name = pending.name;
            subscription.pending_name = None;
            subscription.definition_generation = subscription
                .definition_generation
                .checked_add(1)
                .expect("subscription definition generation exhausted");
            (subscription.created_at, subscription.definition_generation)
        };
        for relation in catalog.relations.iter_mut() {
            if relation.ddl_state != CatalogDdlState::Absent
                && relation.subscription_created_at == created_at
            {
                relation.definition_generation = definition_generation;
            }
        }
    }

    pub(crate) fn rollback_subscription_rename(
        &mut self,
        slot: usize,
        prior: Option<PendingSubscriptionName>,
    ) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .pending_name = prior;
    }

    pub(crate) fn commit_subscription_drop(&mut self, slot: usize) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let created_at = catalog.definitions[slot].created_at;
        for relation in catalog.relations.iter_mut() {
            if relation.subscription_created_at == created_at {
                *relation = SubscriptionRelation::EMPTY;
            }
        }
        let cleanup = match catalog.definitions[slot].slot {
            SubscriptionSlot::Managed(_) => SubscriptionCleanup::DropManagedSlot,
            SubscriptionSlot::Absent | SubscriptionSlot::External(_) => SubscriptionCleanup::None,
        };
        if cleanup == SubscriptionCleanup::None {
            catalog.definitions[slot] = SubscriptionDef::EMPTY;
        } else {
            catalog.definitions[slot].cleanup = cleanup;
            catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_drop();
        }
        drop(catalog);
        self.drop_comments_by_subid(CommentClass::Subscription, created_at as u32);
    }

    pub(crate) fn subscription_cleanup(
        &self,
        slot: usize,
    ) -> Option<(u64, SqlName, SubscriptionConnInfo, SqlName)> {
        let catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = catalog.definitions.get(slot)?;
        let SubscriptionCleanup::DropManagedSlot = subscription.cleanup else {
            return None;
        };
        let SubscriptionSlot::Managed(remote_slot) = subscription.slot else {
            unreachable!("managed cleanup retains a managed slot")
        };
        Some((
            subscription.created_at,
            subscription.name,
            subscription.connection,
            remote_slot.sql_name(),
        ))
    }

    pub(crate) fn complete_subscription_cleanup(
        &mut self,
        slot: usize,
        created_at: u64,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = catalog.definitions.get_mut(slot).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "subscription cleanup slot is invalid"
            )
        })?;
        if subscription.ddl_state != CatalogDdlState::Absent
            || subscription.created_at != created_at
            || subscription.cleanup != SubscriptionCleanup::DropManagedSlot
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "subscription cleanup identity changed"
            ));
        }
        *subscription = SubscriptionDef::EMPTY;
        Ok(())
    }

    pub(crate) fn rollback_subscription_create(&mut self, slot: usize) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        debug_assert_eq!(
            catalog.definitions[slot].ddl_state.rollback_create(),
            CatalogDdlState::Absent
        );
        catalog.definitions[slot] = SubscriptionDef::EMPTY;
    }

    pub(crate) fn rollback_subscription_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        catalog.definitions[slot].ddl_state =
            catalog.definitions[slot].ddl_state.rollback_drop(txid);
    }

    /// Stages an enablement change only after proving no concurrent catalog
    /// operation owns this subscription.  `None` is a real no-op, not an
    /// alternative execution path: the requested visible state already holds.
    pub(crate) fn set_subscription_enabled(
        &mut self,
        slot: usize,
        enabled: bool,
        txid: u32,
    ) -> Result<SubscriptionEnabledChange, SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let subscription = &mut catalog.definitions[slot];
        if subscription.enabled_to(txid) == enabled {
            return Ok(SubscriptionEnabledChange::Unchanged);
        }
        let prior = subscription.pending_enabled;
        subscription.pending_enabled = Some(PendingSubscriptionEnabled { txid, enabled });
        Ok(SubscriptionEnabledChange::Changed { prior })
    }

    fn subscription_change_blocker(
        catalog: &SubscriptionCatalog,
        slot: usize,
        txid: u32,
    ) -> Option<u32> {
        let subscription = &catalog.definitions[slot];
        [
            subscription.ddl_state.pending_txid(),
            subscription.pending_name.map(|pending| pending.txid),
            subscription.pending_enabled.map(|pending| pending.txid),
            subscription.pending_bootstrap.map(|pending| pending.txid),
            subscription.pending_relation_refresh,
            subscription.pending_definition.map(|pending| pending.txid),
            subscription.ownership.pending.map(|pending| pending.txid),
        ]
        .into_iter()
        .flatten()
        .find(|owner| *owner != txid)
        .or_else(|| {
            catalog.relations.iter().find_map(|relation| {
                if relation.subscription_created_at != subscription.created_at {
                    return None;
                }
                relation
                    .ddl_state
                    .pending_txid()
                    .filter(|owner| *owner != txid)
            })
        })
    }

    pub(crate) fn commit_subscription_enabled(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = &mut catalog.definitions[slot];
        if let Some(pending) = subscription.pending_enabled
            && pending.txid == txid
        {
            subscription.enabled = pending.enabled;
            subscription.pending_enabled = None;
            if pending.enabled {
                subscription.failure = None;
            }
        }
    }

    pub(crate) fn restore_subscription_enabled(
        &mut self,
        slot: usize,
        prior: Option<PendingSubscriptionEnabled>,
    ) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .pending_enabled = prior;
    }

    pub(crate) fn set_subscription_bootstrap(
        &mut self,
        slot: usize,
        bootstrap: SubscriptionBootstrap,
        txid: u32,
    ) -> Result<SubscriptionBootstrapChange, SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let subscription = &mut catalog.definitions[slot];
        if subscription.bootstrap_to(txid) == bootstrap {
            return Ok(SubscriptionBootstrapChange::Unchanged);
        }
        let prior = subscription.pending_bootstrap;
        subscription.pending_bootstrap = Some(PendingSubscriptionBootstrap { txid, bootstrap });
        Ok(SubscriptionBootstrapChange::Changed { prior })
    }

    pub(crate) fn commit_subscription_bootstrap(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = &mut catalog.definitions[slot];
        if let Some(pending) = subscription.pending_bootstrap
            && pending.txid == txid
        {
            subscription.bootstrap = pending.bootstrap;
            subscription.pending_bootstrap = None;
            subscription.failure = None;
        }
    }

    pub(crate) fn restore_subscription_bootstrap(
        &mut self,
        slot: usize,
        prior: Option<PendingSubscriptionBootstrap>,
    ) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .pending_bootstrap = prior;
    }

    pub(crate) fn set_subscription_definition(
        &mut self,
        slot: usize,
        definition: SubscriptionDefinition,
        txid: u32,
    ) -> Result<SubscriptionDefinitionChange, SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, slot, txid) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let subscription = &mut catalog.definitions[slot];
        let current = subscription.definition_to(txid);
        if current.connection.as_str() == definition.connection.as_str()
            && current.publications() == definition.publications()
            && current.slot == definition.slot
            && current.behavior == definition.behavior
        {
            return Ok(SubscriptionDefinitionChange {
                changed: false,
                prior: subscription.pending_definition,
            });
        }
        let prior = subscription.pending_definition;
        subscription.pending_definition = Some(PendingSubscriptionDefinition {
            txid,
            connection: definition.connection,
            publications: definition.publication_array(),
            publication_count: definition.publication_count(),
            slot: definition.slot,
            behavior: definition.behavior,
        });
        Ok(SubscriptionDefinitionChange {
            changed: true,
            prior,
        })
    }

    /// Returns the definition visible to `txid`. A definition change is one
    /// atomic catalog value: callers cannot combine a staged connection with
    /// committed publication membership.
    pub(crate) fn subscription_definition_to(
        &self,
        slot: usize,
        txid: u32,
    ) -> SubscriptionDefinition {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .definition_to(txid)
    }

    pub(crate) fn commit_subscription_definition(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let Some((created_at, definition_generation)) = ({
            let subscription = &mut catalog.definitions[slot];
            let Some(pending) = subscription
                .pending_definition
                .filter(|pending| pending.txid == txid)
            else {
                return;
            };
            let replaces_stream = subscription.connection.as_str() != pending.connection.as_str()
                || subscription.publication_count != pending.publication_count
                || subscription.publications[..subscription.publication_count]
                    != pending.publications[..pending.publication_count]
                || subscription.slot != pending.slot
                || !subscription
                    .behavior
                    .same_publisher_stream(pending.behavior);
            subscription.connection = pending.connection;
            subscription.publications = pending.publications;
            subscription.publication_count = pending.publication_count;
            subscription.slot = pending.slot;
            subscription.behavior = pending.behavior;
            if replaces_stream {
                subscription.definition_generation = subscription
                    .definition_generation
                    .checked_add(1)
                    .expect("subscription definition generation exhausted");
            }
            subscription.pending_definition = None;
            subscription.failure = None;
            replaces_stream.then_some((subscription.created_at, subscription.definition_generation))
        }) else {
            return;
        };
        for relation in catalog.relations.iter_mut() {
            if relation.ddl_state != CatalogDdlState::Absent
                && relation.subscription_created_at == created_at
            {
                relation.definition_generation = definition_generation;
            }
        }
    }

    pub(crate) fn fail_subscription(
        &mut self,
        stream: SubscriptionStream,
        failure: SubscriptionFailure,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = catalog.definitions.get_mut(stream.slot()).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "subscription worker slot is invalid"
            )
        })?;
        if subscription.database != current_database()
            || stream.database != current_database()
            || !subscription.visible_to(0)
            || subscription.created_at != stream.created_at()
            || subscription.definition_generation != stream.definition_generation()
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "subscription failure targets a replaced stream definition"
            ));
        }
        subscription.failure = Some(failure);
        if matches!(subscription.bootstrap, SubscriptionBootstrap::Ready) {
            subscription.apply_error_count = subscription.apply_error_count.saturating_add(1);
        } else {
            subscription.sync_error_count = subscription.sync_error_count.saturating_add(1);
        }
        if subscription.behavior.disable_on_error {
            subscription.enabled = false;
        }
        Ok(())
    }

    pub(crate) fn restore_subscription_definition(
        &mut self,
        slot: usize,
        prior: Option<PendingSubscriptionDefinition>,
    ) {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions[slot]
            .pending_definition = prior;
    }

    /// Validates one monotonically advancing, committed publisher position.
    /// Returning `None` makes re-delivery after a lost acknowledgement
    /// explicitly idempotent; callers must not apply that remote transaction
    /// again.
    pub(crate) fn subscription_stream(&self, slot: usize, txid: u32) -> Option<SubscriptionStream> {
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .definitions
            .get(slot)
            .filter(|subscription| {
                subscription.database == current_database() && subscription.visible_to(txid)
            })
            .map(|subscription| SubscriptionStream {
                database: subscription.database,
                slot,
                created_at: subscription.created_at,
                definition_generation: subscription.definition_generation,
                name: subscription.name,
            })
    }

    pub(crate) fn subscription_advance(
        &self,
        stream: SubscriptionStream,
        confirmed_lsn: u64,
        txid: u32,
    ) -> Result<Option<SubscriptionAdvance>, SqlError> {
        let catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let subscription = catalog
            .definitions
            .get(stream.slot)
            .filter(|subscription| {
                stream.database == current_database()
                    && subscription.database == current_database()
                    && subscription.visible_to(txid)
                    && subscription.created_at == stream.created_at
                    && subscription.definition_generation == stream.definition_generation
                    && subscription.name == stream.name
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "subscription stream definition changed before its remote transaction committed"
                )
            })?;
        if confirmed_lsn <= subscription.confirmed_lsn {
            return Ok(None);
        }
        Ok(Some(SubscriptionAdvance {
            stream,
            confirmed_lsn,
        }))
    }

    pub(crate) fn apply_subscription_advance(
        &mut self,
        advance: SubscriptionAdvance,
        origin_lsn: u64,
    ) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        {
            let subscription = catalog
                .definitions
                .get_mut(advance.stream.slot)
                .filter(|subscription| {
                    subscription.ddl_state == CatalogDdlState::Present
                        && subscription.database == current_database()
                        && advance.stream.database == current_database()
                        && subscription.created_at == advance.stream.created_at
                        && subscription.definition_generation
                            == advance.stream.definition_generation
                        && subscription.name == advance.stream.name
                })
                .expect("validated subscription must remain live until its WAL commit");
            subscription.confirmed_lsn = advance.confirmed_lsn;
            subscription.origin_lsn = origin_lsn;
            subscription.bootstrap = SubscriptionBootstrap::Ready;
        }
        for relation in catalog.relations.iter_mut() {
            if relation.ddl_state == CatalogDdlState::Present
                && relation.subscription_created_at == advance.stream.created_at
                && relation.definition_generation == advance.stream.definition_generation
            {
                relation.state = SubscriptionRelationState::Ready;
                relation.synchronization_lsn = advance.confirmed_lsn;
            }
        }
    }

    pub(crate) fn begin_subscription_relation_refresh(
        &mut self,
        stream: SubscriptionStream,
        txid: u32,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        let valid = catalog
            .definitions
            .get(stream.slot)
            .is_some_and(|subscription| {
                stream.database == current_database()
                    && subscription.database == current_database()
                    && subscription.visible_to(txid)
                    && subscription.created_at == stream.created_at
                    && subscription.definition_generation == stream.definition_generation
                    && subscription.name == stream.name
            });
        if !valid {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "subscription stream definition changed before relation refresh"
            ));
        }
        if let Some(blocker) = Self::subscription_change_blocker(&catalog, stream.slot, txid) {
            let name = catalog.definitions[stream.slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        catalog.definitions[stream.slot].pending_relation_refresh = Some(txid);
        for relation in catalog.relations.iter_mut() {
            if relation.ddl_state == CatalogDdlState::Present
                && relation.subscription_created_at == stream.created_at
            {
                relation.ddl_state = relation.ddl_state.drop_by(txid);
            }
        }
        Ok(())
    }

    pub(crate) fn stage_subscription_relation(
        &mut self,
        stream: SubscriptionStream,
        schema: &str,
        table: &str,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let table_slot = self.find_visible(schema, table, txid).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "subscription relation \"{}.{}\" does not exist locally",
                schema,
                table
            )
        })?;
        if table_slot > usize::from(u16::MAX) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "subscription relation table identity exceeds its fixed range"
            ));
        }
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        Self::stage_subscription_relation_in(&mut catalog, stream, table_slot, txid)
    }

    fn stage_subscription_relation_in(
        catalog: &mut SubscriptionCatalog,
        stream: SubscriptionStream,
        table_slot: usize,
        txid: u32,
    ) -> Result<usize, SqlError> {
        catalog
            .definitions
            .get(stream.slot)
            .filter(|subscription| {
                stream.database == current_database()
                    && subscription.database == current_database()
                    && subscription.visible_to(txid)
                    && subscription.created_at == stream.created_at
                    && subscription.definition_generation == stream.definition_generation
                    && subscription.name == stream.name
                    && (txid == 0 || subscription.pending_relation_refresh == Some(txid))
            })
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                    "subscription stream definition changed before relation refresh"
                )
            })?;
        if catalog.relations.iter().any(|relation| {
            relation.ddl_state.visible_to(txid)
                && relation.subscription_created_at == stream.created_at
                && relation.definition_generation == stream.definition_generation
                && relation.table_slot() == table_slot
        }) {
            return Ok(table_slot);
        }
        let relation = catalog
            .relations
            .iter_mut()
            .find(|relation| relation.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "subscription relation catalog exhausted its startup capacity"
                )
            })?;
        *relation = SubscriptionRelation {
            subscription_created_at: stream.created_at,
            definition_generation: stream.definition_generation,
            table_slot: table_slot as u16,
            state: SubscriptionRelationState::DataCopy,
            synchronization_lsn: 0,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(table_slot)
    }

    pub(crate) fn restore_subscription_relation(
        &mut self,
        stream: SubscriptionStream,
        schema: &str,
        table: &str,
        state: SubscriptionRelationState,
        synchronization_lsn: u64,
    ) -> Result<(), SqlError> {
        let table_slot = self.find_visible(schema, table, 0).ok_or_else(|| {
            sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "subscription relation \"{}.{}\" does not exist locally",
                schema,
                table
            )
        })?;
        if table_slot > usize::from(u16::MAX) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "subscription relation table identity exceeds its fixed range"
            ));
        }
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        catalog.definitions[stream.slot].pending_relation_refresh = Some(0);
        if let Err(error) =
            Self::stage_subscription_relation_in(&mut catalog, stream, table_slot, 0)
        {
            catalog.definitions[stream.slot].pending_relation_refresh = None;
            return Err(error);
        }
        let relation = catalog
            .relations
            .iter_mut()
            .find(|relation| {
                relation.subscription_created_at == stream.created_at
                    && relation.definition_generation == stream.definition_generation
                    && relation.table_slot() == table_slot
            })
            .expect("staged subscription relation is present");
        relation.state = state;
        relation.synchronization_lsn = synchronization_lsn;
        for relation in catalog.relations.iter_mut() {
            if matches!(
                relation.ddl_state,
                CatalogDdlState::PendingCreate { txid: 0 }
            ) {
                relation.ddl_state = CatalogDdlState::Present;
            }
        }
        catalog.definitions[stream.slot].pending_relation_refresh = None;
        Ok(())
    }

    pub(crate) fn commit_subscription_relation_refresh(&mut self, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        for relation in catalog.relations.iter_mut() {
            match relation.ddl_state {
                CatalogDdlState::PendingCreate { txid: owner } if owner == txid => {
                    relation.ddl_state = CatalogDdlState::Present;
                }
                CatalogDdlState::PendingDrop { txid: owner } if owner == txid => {
                    *relation = SubscriptionRelation::EMPTY;
                }
                _ => {}
            }
        }
        for subscription in catalog.definitions.iter_mut() {
            if subscription.pending_relation_refresh == Some(txid) {
                subscription.pending_relation_refresh = None;
            }
        }
    }

    pub(crate) fn rollback_subscription_relation_refresh(&mut self, txid: u32) {
        let mut catalog = self
            .subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned");
        for relation in catalog.relations.iter_mut() {
            match relation.ddl_state {
                CatalogDdlState::PendingCreate { txid: owner } if owner == txid => {
                    *relation = SubscriptionRelation::EMPTY;
                }
                CatalogDdlState::PendingDrop { txid: owner } if owner == txid => {
                    relation.ddl_state = CatalogDdlState::Present;
                }
                _ => {}
            }
        }
        for subscription in catalog.definitions.iter_mut() {
            if subscription.pending_relation_refresh == Some(txid) {
                subscription.pending_relation_refresh = None;
            }
        }
    }

    pub(crate) fn subscription_relations_visible_to(
        &self,
        subscription: &SubscriptionDef,
        txid: u32,
    ) -> impl Iterator<Item = SubscriptionRelation> + '_ {
        let created_at = subscription.created_at;
        let definition_generation = subscription.definition_generation;
        SubscriptionRelationIter {
            catalog: &self.subscription_catalog,
            next_slot: 0,
        }
        .filter(move |relation| {
            relation.ddl_state.visible_to(txid)
                && relation.subscription_created_at == created_at
                && relation.definition_generation == definition_generation
        })
    }

    pub(crate) fn subscription_relation_is_ready(
        &self,
        stream: SubscriptionStream,
        schema: &str,
        table: &str,
    ) -> bool {
        let Some(table_slot) = self.find_visible(schema, table, 0) else {
            return false;
        };
        self.subscription_catalog
            .lock()
            .expect("subscription catalog lock poisoned")
            .relations
            .iter()
            .any(|relation| {
                relation.ddl_state == CatalogDdlState::Present
                    && relation.subscription_created_at == stream.created_at
                    && relation.definition_generation == stream.definition_generation
                    && relation.table_slot() == table_slot
                    && relation.state == SubscriptionRelationState::Ready
            })
    }

    pub fn create_publication(
        &mut self,
        spec: PublicationSpec<'_>,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if spec.tables.len() > MAX_PUBLICATION_TABLES {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many tables in publication (limit {})",
                MAX_PUBLICATION_TABLES
            ));
        }
        if spec.table_column_masks.len() != spec.tables.len() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "publication table projections do not match publication members"
            ));
        }
        if spec.table_include_descendants.len() != spec.tables.len() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "publication descendant selections do not match publication members"
            ));
        }
        if spec.table_filter_sql.len() != spec.tables.len() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "publication row filters do not match publication members"
            ));
        }
        if spec.schemas.len() > MAX_PUBLICATION_SCHEMAS {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many schemas in publication (limit {})",
                MAX_PUBLICATION_SCHEMAS
            ));
        }
        let mut members = [u16::MAX; MAX_PUBLICATION_TABLES];
        members[..spec.tables.len()].copy_from_slice(spec.tables);
        let mut table_column_masks = [ColumnSet::EMPTY; MAX_PUBLICATION_TABLES];
        table_column_masks[..spec.table_column_masks.len()]
            .copy_from_slice(spec.table_column_masks);
        let mut table_include_descendants = [false; MAX_PUBLICATION_TABLES];
        table_include_descendants[..spec.table_include_descendants.len()]
            .copy_from_slice(spec.table_include_descendants);
        let table_filters = PublicationFilters::from_sql(spec.table_filter_sql)?;
        let mut schemas = [u8::MAX; MAX_PUBLICATION_SCHEMAS];
        schemas[..spec.schemas.len()].copy_from_slice(spec.schemas);
        let ownership = self.initial_ownership(txid);
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        if let Some(blocker) = publications.iter().find_map(|publication| {
            (publication.database == current_database() && publication.identity_matches(spec.name))
                .then(|| publication.pending_owner_other_than(txid))
                .flatten()
        }) {
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, spec.name.as_str()));
        }
        if publications.iter().any(|publication| {
            publication.database == current_database()
                && publication.visible_to(txid)
                && publication.name_for(txid) == spec.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "publication \"{}\" already exists",
                spec.name.as_str()
            ));
        }
        let Some(slot) = publications
            .iter()
            .position(|publication| publication.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many publications (limit {})",
                publications.len()
            ));
        };
        publications[slot] = PublicationDef {
            database: current_database(),
            created_at: self.catalog_sequence.next(),
            name: spec.name,
            pending_name: None,
            all_tables: spec.all_tables,
            tables: members,
            table_column_masks,
            table_include_descendants,
            table_filters,
            table_count: spec.tables.len(),
            schemas,
            schema_count: spec.schemas.len(),
            publish_insert: spec.publish_insert,
            publish_update: spec.publish_update,
            publish_delete: spec.publish_delete,
            publish_truncate: spec.publish_truncate,
            publish_via_partition_root: spec.publish_via_partition_root,
            publish_generated_columns: spec.publish_generated_columns,
            pending_definition: None,
            ownership,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub fn drop_publication(&mut self, name: &str, txid: u32) -> Result<Option<usize>, SqlError> {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let Some(slot) = publications.iter().position(|publication| {
            publication.database == current_database()
                && publication.visible_to(txid)
                && publication.name_for(txid).as_str() == name
        }) else {
            return Ok(None);
        };
        let publication = &mut publications[slot];
        if let Some(blocker) = publication.pending_owner_other_than(txid) {
            let publication_name = publication.name;
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, publication_name.as_str()));
        }
        publication.ddl_state = publication.ddl_state.drop_by(txid);
        Ok(Some(slot))
    }

    pub fn commit_publication_create(&mut self, slot: usize) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        publications[slot].ddl_state = publications[slot].ddl_state.commit_create();
    }
    pub(crate) fn commit_publication_owner(&mut self, slot: usize, txid: u32) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let ownership = &mut publications[slot].ownership;
        if let Some(pending) = ownership.pending
            && pending.txid == txid
        {
            ownership.owner = pending.owner;
            ownership.pending = None;
        }
    }
    pub fn commit_publication_drop(&mut self, slot: usize) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        if publications[slot].ddl_state.commit_drop() == CatalogDdlState::Absent {
            publications[slot] = PublicationDef::EMPTY;
        }
        drop(publications);
        self.drop_comments_by_subid(CommentClass::Publication, slot as u32);
    }

    pub(crate) fn alter_publication(
        &mut self,
        name: &str,
        definition: PublicationDefinition,
        txid: u32,
    ) -> Result<(usize, PublicationAlteration), SqlError> {
        if definition.table_count > MAX_PUBLICATION_TABLES {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many tables in publication (limit {})",
                MAX_PUBLICATION_TABLES
            ));
        }
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let Some(slot) = publications.iter().position(|publication| {
            publication.database == current_database()
                && publication.visible_to(txid)
                && publication.name_for(txid).as_str() == name
        }) else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "publication \"{}\" does not exist",
                name
            ));
        };
        let publication = &mut publications[slot];
        if let Some(blocker) = publication.pending_owner_other_than(txid) {
            let publication_name = publication.name;
            drop(publications);
            return Err(self.catalog_ddl_wait_error(txid, blocker, publication_name.as_str()));
        }
        if matches!(publication.ddl_state, CatalogDdlState::PendingCreate { txid: owner } if owner == txid)
        {
            let prior = publication.definition();
            publication.set_definition(definition);
            return Ok((slot, PublicationAlteration::Created(prior)));
        }
        let prior = publication.pending_definition;
        publication.pending_definition = Some(PendingPublicationDefinition { txid, definition });
        Ok((slot, PublicationAlteration::Committed(prior)))
    }

    pub(crate) fn commit_publication_alter(&mut self, slot: usize, txid: u32) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let publication = &mut publications[slot];
        if let Some(pending) = publication
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            publication.set_definition(pending.definition);
            publication.pending_definition = None;
        }
    }

    pub(crate) fn rollback_publication_alter(&mut self, slot: usize, prior: PublicationAlteration) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let publication = &mut publications[slot];
        match prior {
            PublicationAlteration::Committed(prior) => publication.pending_definition = prior,
            PublicationAlteration::Created(prior) => publication.set_definition(prior),
        }
    }
    pub fn rollback_publication_create(&mut self, slot: usize) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        if publications[slot].ddl_state.rollback_create() == CatalogDdlState::Absent {
            publications[slot] = PublicationDef::EMPTY;
        }
    }
    pub fn rollback_publication_drop(&mut self, slot: usize, txid: u32) {
        let mut publications = self
            .publications
            .lock()
            .expect("publication catalog lock poisoned");
        let publication = &mut publications[slot];
        publication.ddl_state = publication.ddl_state.rollback_drop(txid);
    }

    /// The stored SELECT text of a view visible to `txid`, if `name` names one
    /// (own uncommitted CREATE/DROP included; another transaction's excluded).
    pub fn find_view(&self, schema: &str, name: &str, txid: u32) -> Option<ViewDef> {
        self.view_rule_catalog()
            .views
            .iter()
            .find(|v| {
                v.database == current_database()
                    && v.visible_to(txid)
                    && v.schema_for(txid).as_str() == schema
                    && v.name_for(txid).as_str() == name
            })
            .copied()
    }

    // --- Materialized-view catalog (parallel to views; data lives in a
    // same-named backing Table, so these hold only the defining query). ---

    /// Committed materialized views, for checkpoint serialization.
    fn matview_catalog(&self) -> std::sync::MutexGuard<'_, FixedVec<MatviewDef>> {
        self.matviews
            .lock()
            .expect("materialized-view catalog lock poisoned")
    }

    pub fn live_matviews(&self) -> impl Iterator<Item = MatviewDef> + '_ {
        self.matviews_with_slots().map(|(_, definition)| definition)
    }

    pub fn matviews_with_slots(&self) -> impl Iterator<Item = (usize, MatviewDef)> + '_ {
        MatviewIter {
            catalog: &self.matviews,
            next_slot: 0,
            database: Some(current_database()),
            txid: 0,
            checkpoint: true,
        }
    }

    /// Materialized views visible to `txid`, including the transaction's own DDL.
    pub(crate) fn matviews_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, MatviewDef)> + '_ {
        MatviewIter {
            catalog: &self.matviews,
            next_slot: 0,
            database: Some(current_database()),
            txid,
            checkpoint: false,
        }
    }

    pub(crate) fn matview(&self, slot: usize) -> MatviewDef {
        self.matview_catalog()[slot]
    }

    pub(crate) fn matview_dependencies(&self, slot: usize) -> StoredQueryDependencyImage<'_> {
        let image = self.matview_dependency_image(slot);
        let catalog = self
            .stored_query_dependencies
            .lock()
            .expect("stored-query dependency catalog lock poisoned");
        let count = catalog.counts[image];
        StoredQueryDependencyImage {
            catalog,
            image,
            count,
            entries_per_image: self.stored_query_dependencies_per_image,
        }
    }

    pub(crate) fn matview_count(&self) -> usize {
        self.matview_catalog().len()
    }

    pub fn find_matview(&self, schema: &str, name: &str, txid: u32) -> Option<MatviewDef> {
        self.matviews_visible_to(txid).find_map(|(_, definition)| {
            (self.table_slot_visible_to(usize::from(definition.backing_table), txid) && {
                let table = self.table_def(usize::from(definition.backing_table), txid);
                table.schema.as_str() == schema && table.name.as_str() == name
            })
            .then_some(definition)
        })
    }

    /// The slot of a materialized view visible to `txid`, for later mutation
    /// (REFRESH marks it populated).
    pub fn matview_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        self.matviews_visible_to(txid)
            .find_map(|(slot, definition)| {
                (self.table_slot_visible_to(usize::from(definition.backing_table), txid) && {
                    let table = self.table_def(usize::from(definition.backing_table), txid);
                    table.schema.as_str() == schema && table.name.as_str() == name
                })
                .then_some(slot)
            })
    }

    pub(crate) fn matview_table(&self, slot: usize) -> usize {
        usize::from(self.matview(slot).backing_table)
    }

    pub(crate) fn matview_slot_for_table(&self, table: usize, txid: u32) -> Option<usize> {
        self.matviews_visible_to(txid).find_map(|(slot, matview)| {
            (usize::from(matview.backing_table) == table).then_some(slot)
        })
    }

    pub fn set_matview_populated(&self, slot: usize, populated: bool) {
        self.matview_catalog()[slot].populated = populated;
    }

    /// Registers a materialized view as an uncommitted CREATE owned by `txid`.
    /// Unlike `create_view`, the name-vs-table collision is owned by the backing
    /// table's own creation, so no `find_table`/`or_replace` handling is needed.
    pub fn create_matview(
        &mut self,
        backing_table: usize,
        query: StoredQueryDefinition,
        populated: bool,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let definition = *self.table_def(backing_table, txid);
        if !self.table_slot_visible_to(backing_table, txid) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "materialized view backing relation does not exist"
            ));
        }
        let blocker = self.matview_catalog().iter().find_map(|m| {
            (m.database == current_database()
                && m.ddl_state != CatalogDdlState::Absent
                && m.backing_table == backing_table as u16)
                .then_some(m.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        });
        if let Some(blocker) = blocker {
            return Err(self.catalog_ddl_wait_error(txid, blocker, definition.name.as_str()));
        }
        let new = {
            let matviews = self.matview_catalog();
            matviews
                .iter()
                .position(|m| m.ddl_state == CatalogDdlState::Absent)
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "too many materialized views (limit {})",
                        matviews.len()
                    )
                })?
        };
        let ownership = self.initial_ownership(txid);
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::MaterializedView,
            slot: new as u16,
        });
        let image = self.matview_dependency_image(new);
        self.write_dependency_image(image, query.dependencies.view())?;
        let created_at = self.catalog_sequence.next();
        self.matview_catalog()[new] = MatviewDef {
            database: current_database(),
            created_at,
            backing_table: backing_table as u16,
            sql: query.sql,
            creation_path: query.creation_path,
            ownership,
            populated,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(new)
    }

    pub fn drop_matview(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let blocker = self.matview_catalog().iter().find_map(|m| {
            (m.database == current_database() && m.ddl_state != CatalogDdlState::Absent && {
                let table = self.table_def(usize::from(m.backing_table), txid);
                table.schema.as_str() == schema && table.name.as_str() == name
            })
            .then_some(m.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        });
        if let Some(blocker) = blocker {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = self.matview_catalog().iter().position(|m| {
            m.database == current_database() && m.visible_to(txid) && {
                let table = self.table_def(usize::from(m.backing_table), txid);
                table.schema.as_str() == schema && table.name.as_str() == name
            }
        }) else {
            return Ok(None);
        };
        self.pending_drop_matview(i, txid);
        Ok(Some(i))
    }

    fn pending_drop_matview(&mut self, slot: usize, txid: u32) {
        let mut matviews = self.matview_catalog();
        let m = &mut matviews[slot];
        m.ddl_state = m.ddl_state.drop_by(txid);
    }

    pub fn commit_matview_create(&mut self, slot: usize) {
        let mut matviews = self.matview_catalog();
        matviews[slot].ddl_state = matviews[slot].ddl_state.commit_create();
    }

    pub fn commit_matview_drop(&mut self, slot: usize) {
        let definition = self.tables[usize::from(self.matview(slot).backing_table)].def;
        let (schema, name) = (definition.schema, definition.name);
        self.drop_object_comments(CommentClass::Relation, schema.as_str(), name.as_str());
        self.matview_catalog()[slot] = MatviewDef::EMPTY;
        let image = self.matview_dependency_image(slot);
        self.clear_dependency_image(image);
        self.clear_extension_dependencies_for_object(AccessObject {
            class: AccessClass::MaterializedView,
            slot: slot as u16,
        });
    }

    pub fn rollback_matview_create(&mut self, slot: usize) {
        self.matview_catalog()[slot] = MatviewDef::EMPTY;
        let image = self.matview_dependency_image(slot);
        self.clear_dependency_image(image);
    }

    pub fn rollback_matview_drop(&mut self, slot: usize, txid: u32) {
        let mut matviews = self.matview_catalog();
        let m = &mut matviews[slot];
        m.ddl_state = m.ddl_state.rollback_drop(txid);
    }

    // --- Sequences -------------------------------------------------------

    pub fn live_sequences(&self) -> impl Iterator<Item = SequenceDef> + '_ {
        SequenceIter {
            catalog: &self.sequence_catalog,
            next_slot: 0,
        }
        .map(|(_, definition)| definition)
        .filter(|sequence| {
            sequence.database == current_database()
                && sequence.ddl_state == CatalogDdlState::Present
        })
    }

    pub fn sequences_with_slots(&self) -> impl Iterator<Item = (usize, SequenceDef)> + '_ {
        SequenceIter {
            catalog: &self.sequence_catalog,
            next_slot: 0,
        }
        .filter(|(_, sequence)| {
            sequence.database == current_database()
                && sequence.ddl_state == CatalogDdlState::Present
        })
    }

    pub(crate) fn sequence(&self, slot: usize) -> SequenceDef {
        self.sequence_catalog
            .lock()
            .expect("sequence catalog lock poisoned")
            .definitions[slot]
    }

    fn sequence_catalog(&self) -> std::sync::MutexGuard<'_, SequenceCatalog> {
        self.sequence_catalog
            .lock()
            .expect("sequence catalog lock poisoned")
    }

    pub(crate) fn sequence_count(&self) -> usize {
        self.sequence_catalog().definitions.len()
    }

    pub(crate) fn sequence_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let catalog = self.sequence_catalog();
        catalog.definitions[slot].database == current_database()
            && catalog.definitions[slot].visible_to(txid)
    }

    pub fn find_sequence(&self, schema: &str, name: &str, txid: u32) -> Option<SequenceDef> {
        self.sequence_catalog()
            .definitions
            .iter()
            .copied()
            .find(|s| {
                let definition = s.definition_for(txid);
                s.database == current_database()
                    && s.visible_to(txid)
                    && definition.schema.as_str() == schema
                    && definition.name.as_str() == name
            })
    }

    pub fn sequence_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        let slot = self.sequence_catalog().definitions.iter().position(|s| {
            let definition = s.definition_for(txid);
            s.database == current_database()
                && s.visible_to(txid)
                && definition.schema.as_str() == schema
                && definition.name.as_str() == name
        });
        if slot.is_some_and(|slot| {
            self.sequence_for(slot, txid).persistence == RelationPersistence::Temporary
        }) {
            self.mark_temporary_transaction(txid);
        }
        slot
    }

    pub fn generated_sequence_slot(
        &self,
        table_schema: &str,
        table: &str,
        column: &str,
        txid: u32,
    ) -> Option<usize> {
        let direct = self
            .sequence_catalog()
            .definitions
            .iter()
            .position(|sequence| {
                sequence.database == current_database()
                    && sequence.visible_to(txid)
                    && matches!(
                        sequence.definition_for(txid).generator_for,
                        Some(owner)
                            if owner.table_schema.as_str() == table_schema
                                && owner.table.as_str() == table
                                && owner.column.as_str() == column
                    )
            });
        if direct.is_some() {
            return direct;
        }

        // Sequence dependencies are stored against the committed table
        // identity and rebound when its staged definition commits. Translate
        // the transaction-visible name back through the composed column map so
        // successive ALTER TABLE statements can still use serial defaults.
        let table_slot = (0..self.tables.len()).find(|slot| {
            self.table_slot_visible_to(*slot, txid)
                && self.table_def(*slot, txid).schema.as_str() == table_schema
                && self.table_def(*slot, txid).name.as_str() == table
        })?;
        let pending = self
            .pending_table_def(table_slot)
            .filter(|pending| pending.txid == txid)?;
        let committed = self.tables[table_slot].def;
        let committed_column = pending
            .column_mapping
            .iter()
            .enumerate()
            .take(committed.n_columns)
            .find_map(|(index, mapped)| {
                mapped
                    .is_some_and(|mapped| mapped.as_str() == column)
                    .then_some(committed.columns()[index].name)
            })?;
        self.sequence_catalog()
            .definitions
            .iter()
            .position(|sequence| {
                sequence.database == current_database()
                    && sequence.visible_to(txid)
                    && matches!(
                        sequence.definition_for(txid).generator_for,
                        Some(owner)
                            if owner.table_schema == committed.schema
                                && owner.table == committed.name
                                && owner.column == committed_column
                    )
            })
    }

    /// Resolves a (possibly unqualified) sequence name to its slot: a qualifier
    /// names the schema directly, otherwise the search path is walked, matching
    /// [`Self::resolve_relation`].
    pub fn sequence_on_path(
        &self,
        qualifier: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        if let Some(schema) = qualifier {
            if schema == "pg_temp" {
                return self
                    .temporary_schema()
                    .ok()
                    .and_then(|schema| self.sequence_slot(schema.as_str(), name, txid));
            }
            if schema.starts_with("pg_temp_") && !self.is_current_temporary_schema(schema) {
                return None;
            }
            return self.sequence_slot(schema, name, txid);
        }
        if let Ok(schema) = self.temporary_schema()
            && let Some(found) = self.sequence_slot(schema.as_str(), name, txid)
        {
            return Some(found);
        }
        for entry in self.path().entries() {
            if let PathEntry::Schema(slot) = entry {
                let schema_name = self.schema_def(*slot as usize).name;
                if let Some(found) = self.sequence_slot(schema_name.as_str(), name, txid) {
                    return Some(found);
                }
            }
        }
        None
    }

    /// Whether PostgreSQL's shared relation namespace already contains this
    /// name, including indexes and sequences.
    pub fn relation_name_taken(&self, schema: &str, name: &str, txid: u32) -> bool {
        self.relation_kind_in(schema, name, txid).is_some()
    }

    /// Registers a sequence as an uncommitted CREATE owned by `txid`. The caller
    /// has already validated options and checked the name is free.
    pub(crate) fn create_sequence(
        &mut self,
        create: SequenceCreateSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let SequenceCreateSpec {
            schema,
            name,
            spec,
            owner,
            generator_for,
            persistence,
        } = create;
        self.require_schema_create(schema.as_str(), txid)?;
        let ownership = self.initial_ownership(txid);
        let created_at = self.catalog_sequence.next();
        let mut catalog = self.sequence_catalog();
        if let Some(blocker) = catalog.definitions.iter().find_map(|s| {
            (s.database == current_database()
                && s.schema.as_str() == schema.as_str()
                && s.name.as_str() == name.as_str())
            .then_some(s.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let Some(new) = catalog
            .definitions
            .iter()
            .position(|sequence| sequence.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many sequences (limit {})",
                catalog.definitions.len()
            ));
        };
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Sequence,
            slot: new as u16,
        });
        catalog.definitions[new] = SequenceDef {
            database: current_database(),
            created_at,
            cache_generation: 0,
            schema,
            name,
            ownership,
            data_type: spec.data_type,
            increment: spec.increment,
            min_value: spec.min_value,
            max_value: spec.max_value,
            start_value: spec.start_value,
            cache: spec.cache,
            cycle: spec.cycle,
            persistence,
            owner,
            generator_for,
            pending_definition: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        catalog.values[new] = SequenceValues::initial(spec.start_value);
        drop(catalog);
        if persistence == RelationPersistence::Temporary {
            self.mark_temporary_transaction(txid);
        }
        Ok(new)
    }

    pub(crate) fn sequence_for(&self, slot: usize, txid: u32) -> SequenceDef {
        self.sequence_catalog().definitions[slot].definition_for(txid)
    }

    pub(crate) fn stage_sequence_alter(
        &mut self,
        slot: usize,
        alteration: SequenceAlteration,
        txid: u32,
    ) -> Result<Option<PendingSequenceDefinition>, SqlError> {
        let mut catalog = self.sequence_catalog();
        let current_identity = catalog.definitions[slot].definition_for(txid);
        let pending = catalog.definitions[slot].pending_definition;
        if let Some(pending) = pending
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "sequence \"{}\" is being altered by another transaction",
                catalog.definitions[slot].name.as_str()
            ));
        }
        let sequence_values = &mut catalog.values[slot];
        let prior = pending.map(|pending| PendingSequenceDefinition {
            last_value: sequence_values.pending.last_value,
            is_called: sequence_values.pending.is_called,
            log_count: sequence_values.pending.log_count,
            ..pending
        });
        let active = if pending.is_some_and(|pending| pending.txid == txid) {
            sequence_values.pending
        } else {
            sequence_values.committed
        };
        let (last_value, is_called) = alteration
            .restart
            .map_or((active.last_value, active.is_called), |value| {
                (value, false)
            });
        let restarted = pending.is_some_and(|pending| pending.txid == txid && pending.restarted)
            || alteration.restart.is_some();
        sequence_values.pending = SequenceValue {
            last_value,
            is_called,
            log_count: 0,
            dirty: alteration.restart.is_some(),
            generation: sequence_values.pending.generation.wrapping_add(1),
            staged_generation: 0,
        };
        catalog.definitions[slot].pending_definition = Some(PendingSequenceDefinition {
            txid,
            schema: alteration.schema,
            name: alteration.name,
            spec: alteration.spec,
            owner: alteration.owner,
            generator_for: alteration.generator_for,
            persistence: alteration.persistence,
            last_value,
            is_called,
            log_count: 0,
            restarted,
        });
        drop(catalog);
        if current_identity.schema != alteration.schema || current_identity.name != alteration.name
        {
            self.stage_object_comment_identity(
                CommentClass::Relation,
                current_identity.schema,
                current_identity.name,
                alteration.schema,
                alteration.name,
                txid,
            );
        }
        Ok(prior)
    }

    pub(crate) fn commit_sequence_alter(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.sequence_catalog();
        if catalog.definitions[slot]
            .pending_definition
            .filter(|pending| pending.txid == txid)
            .is_some()
        {
            let old_schema = catalog.definitions[slot].schema;
            let old_name = catalog.definitions[slot].name;
            let definition = catalog.definitions[slot].definition_for(txid);
            catalog.definitions[slot] = definition;
            let values = &mut catalog.values[slot];
            values.committed = values.pending;
            values.committed.dirty = false;
            values.committed.staged_generation = 0;
            values.pending.dirty = false;
            values.pending.staged_generation = 0;
            if old_schema != catalog.definitions[slot].schema
                || old_name != catalog.definitions[slot].name
            {
                let new_schema = catalog.definitions[slot].schema;
                let new_name = catalog.definitions[slot].name;
                drop(catalog);
                self.commit_object_comment_identity(
                    CommentClass::Relation,
                    old_schema,
                    old_name,
                    txid,
                );
                self.rename_stored_query_dependency(
                    DependencyClass::Sequence,
                    slot,
                    None,
                    new_schema,
                    new_name,
                );
            }
        }
    }

    pub(crate) fn rollback_sequence_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingSequenceDefinition>,
    ) {
        let mut catalog = self.sequence_catalog();
        let current = catalog.definitions[slot].pending_definition;
        let txid = current.map(|pending| pending.txid);
        let old_identity = current.map(|pending| (pending.schema, pending.name));
        // ALTER SEQUENCE's definition is transactional, but an advance made
        // under an ordinary staged definition is not.  Only RESTART owns a
        // temporary value image that rollback may discard.
        catalog.definitions[slot].pending_definition = prior;
        let values = &mut catalog.values[slot];
        if current.is_some_and(|pending| !pending.restarted) {
            values.committed = values.pending;
        }
        if let Some(prior) = prior {
            values.pending = SequenceValue {
                last_value: prior.last_value,
                is_called: prior.is_called,
                log_count: prior.log_count,
                dirty: false,
                generation: values.pending.generation.wrapping_add(1),
                staged_generation: 0,
            };
        } else {
            values.pending.dirty = false;
        }
        if let (Some(txid), Some((old_schema, old_name))) = (txid, old_identity) {
            let visible = catalog.definitions[slot].definition_for(txid);
            if old_schema != visible.schema || old_name != visible.name {
                drop(catalog);
                self.stage_object_comment_identity(
                    CommentClass::Relation,
                    old_schema,
                    old_name,
                    visible.schema,
                    visible.name,
                    txid,
                );
            }
        }
    }

    pub(crate) fn reserve_sequence_values(
        &self,
        slot: usize,
        txid: u32,
        requested: i64,
    ) -> Result<(i64, i64, bool), SqlError> {
        let mut catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let definition = pending.then(|| sequence.definition_for(txid));
        if let Some(definition) = definition {
            return definition.reserve_values_with(&mut catalog.values[slot].pending, requested);
        }
        sequence.reserve_values_with(&mut catalog.values[slot].committed, requested)
    }

    pub(crate) fn set_sequence_value(
        &self,
        slot: usize,
        txid: u32,
        value: i64,
        is_called: bool,
    ) -> Result<i64, SqlError> {
        let mut catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let definition = pending.then(|| sequence.definition_for(txid));
        if let Some(definition) = definition {
            return definition.set_value_with(value, is_called, &mut catalog.values[slot].pending);
        }
        sequence.set_value_with(value, is_called, &mut catalog.values[slot].committed)
    }

    pub(crate) fn check_sequence_value(
        &self,
        slot: usize,
        txid: u32,
        value: i64,
    ) -> Result<(), SqlError> {
        self.sequence_for(slot, txid).check_setval(value)
    }

    pub(crate) fn sequence_value_image_for(
        &self,
        slot: usize,
        txid: u32,
    ) -> (i64, bool, i64, bool, u64) {
        let catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let value = if pending {
            catalog.values[slot].pending
        } else {
            catalog.values[slot].committed
        };
        (
            value.last_value,
            value.is_called,
            value.log_count,
            value.dirty,
            value.generation,
        )
    }

    pub(crate) fn sequence_catalog_image_for(
        &self,
        slot: usize,
        txid: u32,
    ) -> Option<(SequenceDef, i64, bool, i64, bool, u64)> {
        let catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        if sequence.database != current_database() || !sequence.visible_to(txid) {
            return None;
        }
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let definition = sequence.definition_for(txid);
        let value = if pending {
            catalog.values[slot].pending
        } else {
            catalog.values[slot].committed
        };
        Some((
            definition,
            value.last_value,
            value.is_called,
            value.log_count,
            value.dirty,
            value.generation,
        ))
    }

    pub(crate) fn sequence_value_for(&self, slot: usize, txid: u32) -> (i64, bool) {
        let (last_value, is_called, _, _, _) = self.sequence_value_image_for(slot, txid);
        (last_value, is_called)
    }

    pub(crate) fn sequence_log_count_for(&self, slot: usize, txid: u32) -> i64 {
        self.sequence_value_image_for(slot, txid).2
    }

    pub(crate) fn mark_sequence_value_staged(&self, slot: usize, txid: u32, generation: u64) {
        let mut catalog = self.sequence_catalog();
        let pending = catalog.definitions[slot]
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let value = if pending {
            &mut catalog.values[slot].pending
        } else {
            &mut catalog.values[slot].committed
        };
        if value.generation == generation {
            value.staged_generation = generation;
        }
    }

    pub(crate) fn clear_sequence_value_dirty(&self, slot: usize, txid: u32) {
        let mut catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        if sequence.database != current_database() || !sequence.visible_to(txid) {
            return;
        }
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        let temporary = sequence.definition_for(txid).persistence == RelationPersistence::Temporary;
        let value = if pending {
            &mut catalog.values[slot].pending
        } else {
            &mut catalog.values[slot].committed
        };
        if temporary || value.generation == value.staged_generation {
            value.dirty = false;
            value.staged_generation = 0;
        }
    }

    pub(crate) fn reset_sequence_value(
        &self,
        slot: usize,
        txid: u32,
        value: i64,
    ) -> SequenceValueState {
        let mut catalog = self.sequence_catalog();
        let sequence = catalog.definitions[slot];
        let pending = sequence
            .pending_definition
            .is_some_and(|pending| pending.txid == txid);
        if pending {
            let state = &mut catalog.values[slot].pending;
            let prior = SequenceValueState::Pending {
                last_value: state.last_value,
                is_called: state.is_called,
                log_count: state.log_count,
                dirty: state.dirty,
                generation: state.generation,
                staged_generation: state.staged_generation,
            };
            *state = SequenceValue {
                last_value: value,
                is_called: false,
                log_count: 0,
                dirty: true,
                generation: state.generation.wrapping_add(1),
                staged_generation: state.staged_generation,
            };
            return prior;
        }
        let state = &mut catalog.values[slot].committed;
        let prior = SequenceValueState::Committed {
            last_value: state.last_value,
            is_called: state.is_called,
            log_count: state.log_count,
            dirty: state.dirty,
            generation: state.generation,
            staged_generation: state.staged_generation,
        };
        *state = SequenceValue {
            last_value: value,
            is_called: false,
            log_count: 0,
            dirty: true,
            generation: state.generation.wrapping_add(1),
            staged_generation: state.staged_generation,
        };
        prior
    }

    pub(crate) fn restore_sequence_value(&self, slot: usize, prior: SequenceValueState) {
        let mut catalog = self.sequence_catalog();
        match prior {
            SequenceValueState::Committed {
                last_value,
                is_called,
                log_count,
                dirty,
                generation,
                staged_generation,
            } => {
                catalog.values[slot].committed = SequenceValue {
                    last_value,
                    is_called,
                    log_count,
                    dirty,
                    generation,
                    staged_generation,
                };
            }
            SequenceValueState::Pending {
                last_value,
                is_called,
                log_count,
                dirty,
                generation,
                staged_generation,
            } => {
                catalog.values[slot].pending = SequenceValue {
                    last_value,
                    is_called,
                    log_count,
                    dirty,
                    generation,
                    staged_generation,
                };
            }
        }
    }

    pub fn drop_sequence(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self.sequence_catalog();
        if let Some(blocker) = catalog.definitions.iter().find_map(|s| {
            let definition = s.definition_for(txid);
            (s.database == current_database()
                && definition.schema.as_str() == schema
                && definition.name.as_str() == name)
                .then_some(s.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = catalog.definitions.iter().position(|s| {
            let definition = s.definition_for(txid);
            s.database == current_database()
                && s.visible_to(txid)
                && definition.schema.as_str() == schema
                && definition.name.as_str() == name
        }) else {
            return Ok(None);
        };
        let sequence = &mut catalog.definitions[i];
        sequence.ddl_state = sequence.ddl_state.drop_by(txid);
        Ok(Some(i))
    }

    pub fn commit_sequence_create(&mut self, slot: usize) {
        let mut catalog = self.sequence_catalog();
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_create();
    }

    pub fn commit_sequence_drop(&mut self, slot: usize) {
        let mut catalog = self.sequence_catalog();
        let (schema, name) = (
            catalog.definitions[slot].schema,
            catalog.definitions[slot].name,
        );
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_drop();
        catalog.definitions[slot] = SequenceDef::EMPTY;
        catalog.values[slot] = SequenceValues::initial(1);
        drop(catalog);
        self.drop_object_comments(CommentClass::Relation, schema.as_str(), name.as_str());
    }

    pub fn rollback_sequence_create(&mut self, slot: usize) {
        let mut catalog = self.sequence_catalog();
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.rollback_create();
        catalog.definitions[slot] = SequenceDef::EMPTY;
        catalog.values[slot] = SequenceValues::initial(1);
    }

    pub fn rollback_sequence_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.sequence_catalog();
        let sequence = &mut catalog.definitions[slot];
        sequence.ddl_state = sequence.ddl_state.rollback_drop(txid);
    }

    pub(crate) fn restore_sequence_value_image(
        &mut self,
        slot: usize,
        last_value: i64,
        is_called: bool,
        log_count: i64,
    ) {
        let catalog = self
            .sequence_catalog
            .get_mut()
            .expect("sequence catalog lock poisoned");
        catalog.values[slot].committed = SequenceValue {
            last_value,
            is_called,
            log_count,
            dirty: false,
            generation: 0,
            staged_generation: 0,
        };
    }

    /// Applies a replayed/absolute `SequenceAdvance`: set value state directly,
    /// without marking dirty (replay must not re-journal).
    pub fn apply_sequence_advance(&mut self, schema: &str, name: &str, last: i64, is_called: bool) {
        let catalog = self
            .sequence_catalog
            .get_mut()
            .expect("sequence catalog lock poisoned");
        if let Some(i) = catalog.definitions.iter().position(|s| {
            s.database == current_database()
                && s.ddl_state != CatalogDdlState::Absent
                && s.schema.as_str() == schema
                && s.name.as_str() == name
        }) {
            catalog.values[i].committed = SequenceValue {
                last_value: last,
                is_called,
                log_count: 0,
                dirty: false,
                generation: 0,
                staged_generation: 0,
            };
        }
    }

    // --- Domains (`CREATE DOMAIN`) ---------------------------------------

    /// Resolves a (possibly schema-qualified) domain type name to its
    /// definition, visible to `txid`, searching the current path when
    /// unqualified.
    pub fn find_domain(&self, type_name: &str, txid: u32) -> Option<DomainDef> {
        let (qualifier, name) = match type_name.split_once('.') {
            Some((q, n)) => (Some(q), n),
            None => (None, type_name),
        };
        self.find_domain_slot(qualifier, name, txid)
            .map(|slot| self.domain_for(slot, txid))
    }

    fn find_domain_slot(&self, qualifier: Option<&str>, name: &str, txid: u32) -> Option<usize> {
        if let Some(schema) = qualifier {
            return DomainIter {
                catalog: &self.type_catalog,
                next_slot: 0,
            }
            .find_map(|(slot, d)| {
                let definition = d.definition_for(txid);
                (d.database == current_database()
                    && d.visible_to(txid)
                    && definition.schema.as_str() == schema
                    && definition.name.as_str() == name)
                    .then_some(slot)
            });
        }
        for entry in self.path().entries() {
            if let PathEntry::Schema(slot) = entry {
                let schema = self.schema_def(*slot as usize).name;
                if let Some(i) = (DomainIter {
                    catalog: &self.type_catalog,
                    next_slot: 0,
                })
                .find_map(|(slot, d)| {
                    let definition = d.definition_for(txid);
                    (d.database == current_database()
                        && d.visible_to(txid)
                        && definition.schema.as_str() == schema.as_str()
                        && definition.name.as_str() == name)
                        .then_some(slot)
                }) {
                    return Some(i);
                }
            }
        }
        None
    }

    /// Resolves a (possibly qualified) domain type name to its slot on the
    /// current path, visible to `txid`.
    pub fn resolve_domain_slot(&self, type_name: &str, txid: u32) -> Option<usize> {
        let (qualifier, name) = match type_name.split_once('.') {
            Some((q, n)) => (Some(q), n),
            None => (None, type_name),
        };
        self.find_domain_slot(qualifier, name, txid)
    }

    /// The definition of a domain named `name` (any schema) visible to `txid` —
    /// for enforcing a column's domain constraints, where the column stores
    /// only the domain's name.
    pub fn domain_by_name(&self, name: &str, txid: u32) -> Option<DomainDef> {
        DomainIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .find_map(|(_, domain)| {
            (domain.database == current_database()
                && domain.visible_to(txid)
                && domain.definition_for(txid).name.as_str() == name)
                .then(|| domain.definition_for(txid))
        })
    }

    /// The domain named `(schema, name)` visible to `txid`, by slot.
    pub fn domain_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        DomainIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .find_map(|(slot, d)| {
            let definition = d.definition_for(txid);
            (d.database == current_database()
                && d.visible_to(txid)
                && definition.schema.as_str() == schema
                && definition.name.as_str() == name)
                .then_some(slot)
        })
    }

    /// Resolves a durable reference held by a column or a child domain. SQL
    /// name lookup deliberately uses [`Self::domain_slot`] instead: an owning
    /// transaction must not keep resolving a domain's retired public name.
    pub(crate) fn domain_identity_slot(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        self.domain_slot(schema, name, txid).or_else(|| {
            DomainIter {
                catalog: &self.type_catalog,
                next_slot: 0,
            }
            .find_map(|(slot, domain)| {
                (domain.database == current_database()
                    && domain.visible_to(txid)
                    && domain.schema.as_str() == schema
                    && domain.name.as_str() == name
                    && domain
                        .pending_definition
                        .is_some_and(|pending| pending.txid == txid && pending.identity.is_some()))
                .then_some(slot)
            })
        })
    }

    /// Resolves a table column's declared type for schema metadata.
    ///
    /// Domains keep their base [`ColType`] for execution, so schema metadata
    /// cannot derive its OID from `column.ctype.oid()`.
    /// Its context-specific accessors intentionally do not expose a generic
    /// OID conversion: result metadata follows the base-type contract for
    /// domains, while parameters, catalogs, and replication use this identity.
    pub fn declared_column_type(
        &self,
        column: &ColumnMeta,
        txid: u32,
    ) -> Result<DeclaredColumnType, SqlError> {
        use crate::sql::types::oid;

        match column.ctype {
            ColType::Array(ArrElem::Domain { slot, .. }) => {
                let UserTypeName { schema, name } = column.user_type.ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "domain-array column type lacks its durable identity"
                    )
                })?;
                if self.domain_identity_slot(schema.as_str(), name.as_str(), txid)
                    != Some(slot as usize)
                {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "domain-array column type does not match its durable identity"
                    ));
                }
                return Ok(DeclaredColumnType::Builtin {
                    oid: oid::domain_array_oid(slot),
                });
            }
            _ if column.user_type.is_some_and(|identity| {
                self.domain_identity_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .is_some()
            }) =>
            {
                let UserTypeName { schema, name } = column.user_type.expect("domain checked above");
                let slot = self
                    .domain_identity_slot(schema.as_str(), name.as_str(), txid)
                    .expect("domain checked above");
                return Ok(DeclaredColumnType::UserDefined {
                    oid: oid::domain_oid(slot as u16),
                    schema,
                    name,
                });
            }
            ColType::Enum(slot) => {
                let UserTypeName { schema, name } = column.user_type.ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "enum column type lacks its durable identity"
                    )
                })?;
                if self.enum_slot(schema.as_str(), name.as_str(), txid) != Some(slot as usize) {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "enum column type does not match its durable identity"
                    ));
                }
                return Ok(DeclaredColumnType::UserDefined {
                    oid: oid::enum_oid(slot),
                    schema,
                    name,
                });
            }
            ColType::Array(ArrElem::Enum(slot)) => {
                let UserTypeName { schema, name } = column.user_type.ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "enum-array column type lacks its durable identity"
                    )
                })?;
                if self.enum_slot(schema.as_str(), name.as_str(), txid) != Some(slot as usize) {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "enum-array column type does not match its durable identity"
                    ));
                }
                return Ok(DeclaredColumnType::Builtin {
                    oid: oid::enum_array_oid(slot),
                });
            }
            ColType::Composite(slot) => {
                let UserTypeName { schema, name } = column.user_type.ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "composite column type lacks its durable identity"
                    )
                })?;
                if self.composite_slot(schema.as_str(), name.as_str(), txid) != Some(slot as usize)
                {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "composite column type does not match its durable identity"
                    ));
                }
                return Ok(DeclaredColumnType::UserDefined {
                    oid: oid::composite_oid(slot),
                    schema,
                    name,
                });
            }
            ColType::Array(ArrElem::Composite(slot)) => {
                let UserTypeName { schema, name } = column.user_type.ok_or_else(|| {
                    sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "composite-array column type lacks its durable identity"
                    )
                })?;
                if self.composite_slot(schema.as_str(), name.as_str(), txid) != Some(slot as usize)
                {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "composite-array column type does not match its durable identity"
                    ));
                }
                return Ok(DeclaredColumnType::Builtin {
                    oid: oid::composite_array_oid(slot),
                });
            }
            _ => {}
        }

        let Some(UserTypeName { schema, name }) = column.user_type else {
            return Ok(DeclaredColumnType::Builtin {
                oid: column.ctype.oid(),
            });
        };
        if let Some(slot) = self.domain_identity_slot(schema.as_str(), name.as_str(), txid) {
            return Ok(DeclaredColumnType::UserDefined {
                oid: oid::domain_oid(slot as u16),
                schema,
                name,
            });
        }
        if let Some(slot) = self.enum_slot(schema.as_str(), name.as_str(), txid) {
            return Ok(DeclaredColumnType::UserDefined {
                oid: oid::enum_oid(slot as u16),
                schema,
                name,
            });
        }
        if let Some(slot) = self.composite_slot(schema.as_str(), name.as_str(), txid) {
            return Ok(DeclaredColumnType::UserDefined {
                oid: oid::composite_oid(slot as u16),
                schema,
                name,
            });
        }
        Err(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "declared column type \"{}.{}\" does not exist",
            schema.as_str(),
            name.as_str()
        ))
    }

    pub fn domain(&self, slot: usize) -> DomainDef {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .domains[slot]
    }

    pub(crate) fn domain_count(&self) -> usize {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .domains
            .len()
    }

    pub(crate) fn domain_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let domain = self.domain(slot);
        domain.database == current_database() && domain.visible_to(txid)
    }

    /// Committed domains carrying their slot indices, for the checkpoint and
    /// `pg_type`.
    pub fn live_domains(&self) -> impl Iterator<Item = (usize, DomainDef)> + '_ {
        DomainIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .filter(|(_, d)| {
            d.database == current_database() && d.ddl_state == CatalogDdlState::Present
        })
    }

    /// Whether any table column (in any table) is declared with this domain —
    /// the dependency that makes `DROP DOMAIN ... RESTRICT` fail.
    pub fn domain_in_use(&self, schema: &str, name: &str) -> Option<(SqlName, SqlName)> {
        for table in self
            .tables
            .iter()
            .filter(|t| t.database == current_database() && t.live)
        {
            for col in table.def.columns() {
                if col.user_type.is_some_and(|identity| {
                    identity.name.as_str() == name && identity.schema.as_str() == schema
                }) {
                    return Some((table.def.name, col.name));
                }
            }
        }
        None
    }

    /// Registers a domain as an uncommitted CREATE owned by `txid` (or, for
    /// replay/checkpoint with `txid == 0`, committed directly). The caller has
    /// validated the base type and constraints and checked the name is free.
    pub fn create_domain(
        &mut self,
        schema: SqlName,
        name: SqlName,
        spec: DomainSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.create_domain_with_binding(schema, name, spec, txid, false)
    }

    /// Manifest loading is the sole phase allowed to defer a named base-type
    /// slot until every catalog record has been parsed.
    pub(crate) fn create_domain_from_manifest(
        &mut self,
        schema: SqlName,
        name: SqlName,
        spec: DomainSpec,
    ) -> Result<usize, SqlError> {
        self.create_domain_with_binding(schema, name, spec, 0, true)
    }

    fn create_domain_with_binding(
        &mut self,
        schema: SqlName,
        name: SqlName,
        mut spec: DomainSpec,
        txid: u32,
        defer_manifest_binding: bool,
    ) -> Result<usize, SqlError> {
        if let Some(identity) = spec.base_user_type {
            spec.base = match spec.base {
                ColType::Enum(slot)
                    if slot != ColType::ENUM_SLOT_UNRESOLVED
                        && (slot as usize) < self.enum_count()
                        && self.enum_for(slot as usize, txid).database == current_database()
                        && self.enum_for(slot as usize, txid).visible_to(txid) =>
                {
                    // WAL preserves the catalog slot. Its spelling can be stale
                    // after an older domain image is replayed over a moved type.
                    let definition = self.enum_for(slot as usize, txid);
                    spec.base_user_type = Some(UserTypeName {
                        schema: definition.schema,
                        name: definition.name,
                    });
                    ColType::Enum(slot)
                }
                ColType::Enum(_) => {
                    match self.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid) {
                        Some(slot) => ColType::Enum(slot as u16),
                        None if defer_manifest_binding => {
                            ColType::Enum(ColType::ENUM_SLOT_UNRESOLVED)
                        }
                        None => {
                            return Err(sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "domain base enum \"{}.{}\" does not exist",
                                identity.schema.as_str(),
                                identity.name.as_str()
                            ));
                        }
                    }
                }
                ColType::Composite(slot)
                    if slot != ColType::COMPOSITE_SLOT_UNRESOLVED
                        && (slot as usize) < self.composite_count()
                        && self.composite_for(slot as usize, txid).database
                            == current_database()
                        && self.composite_for(slot as usize, txid).visible_to(txid) =>
                {
                    // See the enum case: slot identity is durable; names are a
                    // rebindable catalog projection.
                    let definition = self.composite_for(slot as usize, txid);
                    spec.base_user_type = Some(UserTypeName {
                        schema: definition.schema,
                        name: definition.name,
                    });
                    ColType::Composite(slot)
                }
                ColType::Composite(_) => match self.composite_slot(
                    identity.schema.as_str(),
                    identity.name.as_str(),
                    txid,
                ) {
                    Some(slot) => ColType::Composite(slot as u16),
                    None if defer_manifest_binding => {
                        ColType::Composite(ColType::COMPOSITE_SLOT_UNRESOLVED)
                    }
                    None => {
                        return Err(sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "domain base composite \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        ));
                    }
                },
                _ => {
                    return Err(sql_err!(
                        sqlstate::PROTOCOL_VIOLATION,
                        "domain base identity names a non-user-defined type"
                    ));
                }
            };
        }
        self.require_schema_create(schema.as_str(), txid)?;
        let created_at = self.catalog_sequence.next();
        let ownership = self.initial_ownership(txid);
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.domains.iter().find_map(|d| {
            (d.database == current_database()
                && (d.schema == schema && d.name == name
                    || d.pending_definition
                        .and_then(|pending| pending.identity)
                        .is_some_and(|identity| {
                            identity.schema == schema && identity.name == name
                        })))
            .then(|| {
                d.pending_definition
                    .map(|pending| pending.txid)
                    .or_else(|| d.ddl_state.pending_txid())
            })
            .flatten()
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if let Some(blocker) = catalog.enums.iter().find_map(|e| {
            (e.database == current_database()
                && (e.schema == schema && e.name == name
                    || e.pending_definition
                        .is_some_and(|pending| pending.schema == schema && pending.name == name)))
            .then(|| {
                e.pending_definition
                    .map(|pending| pending.txid)
                    .or_else(|| e.ddl_state.pending_txid())
            })
            .flatten()
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if let Some(blocker) = catalog.composites.iter().find_map(|composite| {
            (composite.database == current_database()
                && (composite.schema == schema && composite.name == name
                    || composite
                        .pending_definition
                        .is_some_and(|pending| pending.schema == schema && pending.name == name)))
            .then(|| {
                composite
                    .pending_definition
                    .map(|pending| pending.txid)
                    .or_else(|| composite.ddl_state.pending_txid())
            })
            .flatten()
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog.domains.iter().any(|domain| {
            domain.database == current_database()
                && domain.visible_to(txid)
                && domain.definition_for(txid).schema == schema
                && domain.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        if catalog.enums.iter().any(|e| {
            e.database == current_database()
                && e.visible_to(txid)
                && e.definition_for(txid).schema == schema
                && e.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        if catalog.composites.iter().any(|composite| {
            composite.database == current_database()
                && composite.visible_to(txid)
                && composite.definition_for(txid).schema == schema
                && composite.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(new) = catalog
            .domains
            .iter()
            .position(|d| d.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many domains (limit {})",
                catalog.domains.len()
            ));
        };
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Domain,
            slot: new as u16,
        });
        catalog.domains[new] = DomainDef {
            database: current_database(),
            created_at,
            schema,
            name,
            ownership,
            base_domain: spec.base_domain,
            base_user_type: spec.base_user_type,
            base: spec.base,
            base_type_mod: spec.base_type_mod,
            not_null: spec.not_null,
            default_expr: spec.default_expr,
            checks: spec.checks,
            n_checks: spec.n_checks,
            pending_definition: None,
            ddl_state: if txid == 0 {
                CatalogDdlState::Present
            } else {
                CatalogDdlState::PendingCreate { txid }
            },
        };
        Ok(new)
    }

    pub(crate) fn domain_for(&self, slot: usize, txid: u32) -> DomainDef {
        self.domain(slot).definition_for(txid)
    }

    /// Finishes manifest-time user-type binding once every catalog definition
    /// has been installed. Startup never exposes the interim unresolved slot.
    pub(crate) fn rebind_domain_base_types(&mut self) -> Result<(), SqlError> {
        self.rebind_domain_base_types_to(0)
    }

    fn rebind_domain_base_types_to(&mut self, txid: u32) -> Result<(), SqlError> {
        let current_database = current_database();
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let TypeCatalog {
            domains,
            enums,
            composites,
            ..
        } = &mut *catalog;
        let mut state = self
            .domain_graph_scratch
            .lock()
            .expect("domain graph scratch lock poisoned");
        let mut remaining = 0usize;
        for (slot, marker) in state.iter_mut().enumerate() {
            let domain = domains[slot];
            if domain.database == current_database && domain.visible_to(txid) {
                *marker = 0;
                remaining += 1;
            } else {
                *marker = 2;
            }
        }

        while remaining != 0 {
            let before = remaining;
            for slot in 0..domains.len() {
                if state[slot] != 0 {
                    continue;
                }
                let domain = domains[slot].definition_for(txid);
                let rebound = if let Some(parent) = domain.base_domain {
                    let parent_slot = domains
                        .iter()
                        .position(|candidate| {
                            let candidate = candidate.definition_for(txid);
                            candidate.database == current_database
                                && candidate.visible_to(txid)
                                && candidate.schema == parent.schema
                                && candidate.name == parent.name
                        })
                        .ok_or_else(|| {
                            sql_err!(
                                sqlstate::UNDEFINED_OBJECT,
                                "domain base \"{}.{}\" does not exist",
                                parent.schema.as_str(),
                                parent.name.as_str()
                            )
                        })?;
                    if state[parent_slot] == 0 {
                        continue;
                    }
                    domains[parent_slot].definition_for(txid).base
                } else if let Some(identity) = domain.base_user_type {
                    match domain.base {
                        ColType::Enum(_) => ColType::Enum(
                            enums
                                .iter()
                                .position(|candidate| {
                                    let candidate = candidate.definition_for(txid);
                                    candidate.database == current_database
                                        && candidate.visible_to(txid)
                                        && candidate.schema == identity.schema
                                        && candidate.name == identity.name
                                })
                                .ok_or_else(|| {
                                    sql_err!(
                                        sqlstate::UNDEFINED_OBJECT,
                                        "domain base enum \"{}.{}\" does not exist",
                                        identity.schema.as_str(),
                                        identity.name.as_str()
                                    )
                                })? as u16,
                        ),
                        ColType::Composite(_) => ColType::Composite(
                            composites
                                .iter()
                                .position(|candidate| {
                                    let candidate = candidate.definition_for(txid);
                                    candidate.database == current_database
                                        && candidate.visible_to(txid)
                                        && candidate.schema == identity.schema
                                        && candidate.name == identity.name
                                })
                                .ok_or_else(|| {
                                    sql_err!(
                                        sqlstate::UNDEFINED_OBJECT,
                                        "domain base composite \"{}.{}\" does not exist",
                                        identity.schema.as_str(),
                                        identity.name.as_str()
                                    )
                                })? as u16,
                        ),
                        _ => {
                            return Err(sql_err!(
                                sqlstate::PROTOCOL_VIOLATION,
                                "domain base identity names a non-user-defined type"
                            ));
                        }
                    }
                } else {
                    domain.base
                };
                domains[slot].base = rebound;
                state[slot] = 2;
                remaining -= 1;
            }
            if remaining == before {
                return Err(sql_err!(
                    sqlstate::PROTOCOL_VIOLATION,
                    "recovered domain base chain contains a cycle"
                ));
            }
        }
        Ok(())
    }

    /// Rebind persisted declarations after their complete catalog exists.
    /// Checkpoint type codes deliberately omit runtime slots; a user-type name
    /// is the durable witness that selects the current enum, composite, or
    /// domain representation.
    fn rebind_declared_user_type(
        &self,
        ctype: ColType,
        identity: UserTypeName,
        txid: u32,
    ) -> Result<ColType, SqlError> {
        if let Some(slot) = self.domain_slot(identity.schema.as_str(), identity.name.as_str(), txid)
        {
            let domain = self.domain_for(slot, txid);
            return match ctype {
                ColType::Array(ArrElem::Domain { .. }) => ArrElem::domain(slot as u16, domain.base)
                    .map(ColType::Array)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::FEATURE_NOT_SUPPORTED,
                            "arrays of domain {} require a scalar base type",
                            identity.name.as_str()
                        )
                    }),
                _ => Ok(domain.base),
            };
        }
        if let Some(slot) = self.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid) {
            return Ok(if matches!(ctype, ColType::Array(_)) {
                ColType::Array(ArrElem::Enum(slot as u16))
            } else {
                ColType::Enum(slot as u16)
            });
        }
        if let Some(slot) =
            self.composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
        {
            return Ok(if matches!(ctype, ColType::Array(_)) {
                ColType::Array(ArrElem::Composite(slot as u16))
            } else {
                ColType::Composite(slot as u16)
            });
        }
        Err(sql_err!(
            sqlstate::UNDEFINED_OBJECT,
            "declared type \"{}.{}\" does not exist",
            identity.schema.as_str(),
            identity.name.as_str()
        ))
    }

    /// Completes checkpoint-time binding for every table and composite field.
    /// No recovered declaration is exposed with an unresolved user-type slot.
    pub(crate) fn rebind_user_type_declarations(&mut self) -> Result<(), SqlError> {
        self.rebind_user_type_declarations_to(0)
    }

    fn rebind_user_type_declarations_to(&mut self, txid: u32) -> Result<(), SqlError> {
        for table in 0..self.tables.len() {
            if self.tables[table].database != current_database()
                || !self.tables[table].visible_to(txid)
            {
                continue;
            }
            let mut definition = self.tables[table].def;
            self.bind_user_type_columns_to(&mut definition, txid)?;
            self.tables[table].def = definition;
        }
        for composite in 0..self.composite_count() {
            let definition = self.composite_for(composite, txid);
            if definition.database != current_database() || !definition.visible_to(txid) {
                continue;
            }
            let n_fields = definition.n_fields;
            for field in 0..n_fields {
                let field_definition = definition.fields[field];
                if field_definition.dropped {
                    continue;
                }
                let Some(identity) = field_definition.user_type else {
                    continue;
                };
                let rebound =
                    self.rebind_declared_user_type(field_definition.ctype, identity, txid)?;
                self.type_catalog
                    .lock()
                    .expect("type catalog lock poisoned")
                    .composites[composite]
                    .fields[field]
                    .ctype = rebound;
            }
        }
        Ok(())
    }

    /// Rebind routine declaration representations from their durable type
    /// names after a manifest rebuild.  Routine slots are deliberately never
    /// used as identities: a dropped type may free its slot before recovery.
    pub(crate) fn rebind_routine_types(&mut self) -> Result<(), SqlError> {
        self.rebind_routine_types_to(0)
    }

    fn rebind_routine_types_to(&mut self, txid: u32) -> Result<(), SqlError> {
        fn rebind(
            storage: &Storage,
            ctype: ColType,
            identity: UserTypeName,
            txid: u32,
        ) -> Result<ColType, SqlError> {
            if polymorphic_type(ctype, Some(identity)).is_some() {
                return Ok(ctype);
            }
            if let Some(slot) =
                storage.domain_slot(identity.schema.as_str(), identity.name.as_str(), txid)
            {
                let domain = storage.domain_for(slot, txid);
                return match ctype {
                    ColType::Array(_) => {
                        crate::sql::types::ArrElem::domain(slot as u16, domain.base)
                            .map(ColType::Array)
                            .ok_or_else(|| {
                                sql_err!(
                                    sqlstate::PROTOCOL_VIOLATION,
                                    "routine domain array has invalid element type"
                                )
                            })
                    }
                    _ => Ok(domain.base),
                };
            }
            if let Some(slot) =
                storage.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid)
            {
                return Ok(match ctype {
                    ColType::Array(_) => {
                        ColType::Array(crate::sql::types::ArrElem::Enum(slot as u16))
                    }
                    _ => ColType::Enum(slot as u16),
                });
            }
            if let Some(slot) =
                storage.composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
            {
                return Ok(match ctype {
                    ColType::Array(_) => {
                        ColType::Array(crate::sql::types::ArrElem::Composite(slot as u16))
                    }
                    _ => ColType::Composite(slot as u16),
                });
            }
            Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "routine type \"{}.{}\" does not exist",
                identity.schema.as_str(),
                identity.name.as_str()
            ))
        }
        for slot in 0..self.routine_count() {
            let mut routine = self.routine(slot);
            if routine.database != current_database() || !routine.visible_to(txid) {
                continue;
            }
            for argument in &mut routine.arguments[..routine.argument_count] {
                if let Some(identity) = argument.user_type {
                    argument.ctype = rebind(self, argument.ctype, identity, txid)?;
                }
            }
            for parameter in &mut routine.parameters[..routine.parameter_count] {
                if let Some(identity) = parameter.user_type {
                    parameter.ctype = rebind(self, parameter.ctype, identity, txid)?;
                }
            }
            for column in &mut routine.result_columns[..routine.result_column_count] {
                if let Some(identity) = column.user_type {
                    column.ctype = rebind(self, column.ctype, identity, txid)?;
                }
            }
            match &mut routine.kind {
                RoutineKind::Function { result } | RoutineKind::SetFunction { result } => {
                    if let Some(identity) = result.user_type {
                        result.ctype = rebind(self, result.ctype, identity, txid)?;
                    }
                }
                RoutineKind::Aggregate(aggregate) => {
                    for result in [&mut aggregate.state_type, &mut aggregate.result_type] {
                        if let Some(identity) = result.user_type {
                            result.ctype = rebind(self, result.ctype, identity, txid)?;
                        }
                    }
                    if let Some(moving) = &mut aggregate.moving
                        && let Some(identity) = moving.state_type.user_type
                    {
                        moving.state_type.ctype =
                            rebind(self, moving.state_type.ctype, identity, txid)?;
                    }
                }
                RoutineKind::RecordFunction { .. }
                | RoutineKind::TableFunction
                | RoutineKind::Trigger
                | RoutineKind::EventTrigger
                | RoutineKind::Procedure => {}
            }
            self.routines.lock().expect("routine catalog lock poisoned")[slot] = routine;
        }
        Ok(())
    }

    pub(crate) fn stage_domain_alter(
        &mut self,
        slot: usize,
        spec: DomainSpec,
        txid: u32,
    ) -> Result<Option<PendingDomainDefinition>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let domain = &mut catalog.domains[slot];
        if let Some(pending) = domain.pending_definition
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "domain \"{}\" is being altered by another transaction",
                domain.name.as_str()
            ));
        }
        let prior = domain.pending_definition;
        domain.pending_definition = Some(PendingDomainDefinition {
            txid,
            spec,
            identity: prior.and_then(|pending| pending.identity),
        });
        Ok(prior)
    }

    pub(crate) fn stage_domain_identity(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingDomainDefinition>, SqlError> {
        let current = self.domain_for(slot, txid);
        if current.schema == schema && current.name == name {
            return Ok(self.domain(slot).pending_definition);
        }
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) =
            catalog
                .domains
                .iter()
                .enumerate()
                .find_map(|(other_slot, domain)| {
                    let definition = domain.definition_for(txid);
                    (other_slot != slot
                        && domain.database == current_database()
                        && definition.schema == schema
                        && definition.name == name)
                        .then(|| {
                            domain
                                .pending_definition
                                .map(|pending| pending.txid)
                                .or_else(|| domain.ddl_state.pending_txid())
                        })
                        .flatten()
                        .filter(|&owner| owner != txid)
                })
        {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog
            .domains
            .iter()
            .enumerate()
            .any(|(other_slot, domain)| {
                other_slot != slot
                    && domain.database == current_database()
                    && domain.visible_to(txid)
                    && domain.definition_for(txid).schema == schema
                    && domain.definition_for(txid).name == name
            })
            || catalog.enums.iter().any(|enumeration| {
                enumeration.database == current_database()
                    && enumeration.visible_to(txid)
                    && enumeration.schema == schema
                    && enumeration.definition_for(txid).name == name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        let domain = &mut catalog.domains[slot];
        if let Some(pending) = domain.pending_definition
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "domain \"{}\" is being altered by another transaction",
                domain.name.as_str()
            ));
        }
        let prior = domain.pending_definition;
        let spec = prior.map_or(
            DomainSpec {
                base_domain: domain.base_domain,
                base_user_type: domain.base_user_type,
                base: domain.base,
                base_type_mod: domain.base_type_mod,
                not_null: domain.not_null,
                default_expr: domain.default_expr,
                checks: domain.checks,
                n_checks: domain.n_checks,
            },
            |pending| pending.spec,
        );
        domain.pending_definition = Some(PendingDomainDefinition {
            txid,
            spec,
            identity: Some(PendingDomainIdentity { schema, name }),
        });
        Ok(prior)
    }

    pub(crate) fn commit_domain_alter(&mut self, slot: usize, txid: u32) {
        let rename = {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let domain = catalog.domains[slot];
            if domain
                .pending_definition
                .filter(|pending| pending.txid == txid)
                .is_none()
            {
                return;
            }
            let definition = domain.definition_for(txid);
            catalog.domains[slot] = definition;
            (definition.schema != domain.schema || definition.name != domain.name).then_some((
                domain.schema,
                domain.name,
                definition.schema,
                definition.name,
            ))
        };
        if let Some((old_schema, old_name, schema, name)) = rename {
            self.rename_domain_references(slot, old_schema, old_name, schema, name);
        }
    }

    pub(crate) fn rollback_domain_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingDomainDefinition>,
    ) {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .domains[slot]
            .pending_definition = prior;
    }

    pub fn restore_domain(&mut self, slot: usize, prior: DomainDef) {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .domains[slot] = prior;
    }

    fn rename_domain_references(
        &mut self,
        slot: usize,
        old_schema: SqlName,
        old_name: SqlName,
        schema: SqlName,
        name: SqlName,
    ) {
        for table in self
            .tables
            .iter_mut()
            .filter(|table| table.live || table.pending_ddl.is_some())
        {
            let mut changed = false;
            for column in table.def.columns[..table.def.n_columns].iter_mut() {
                let uses_domain = column.user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
                    || matches!(
                        column.ctype,
                        ColType::Array(ArrElem::Domain { slot: domain_slot, .. })
                            if domain_slot as usize == slot
                    );
                if uses_domain {
                    column.user_type = Some(UserTypeName { schema, name });
                    changed = true;
                }
            }
            if changed {
                table.mark_dirty();
            }
        }
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        for domain in catalog.domains.iter_mut() {
            if domain.base_domain
                == Some(UserTypeName {
                    schema: old_schema,
                    name: old_name,
                })
            {
                domain.base_domain = Some(UserTypeName { schema, name });
            }
        }
        drop(catalog);
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.class == CommentClass::Type
                && comment.schema == old_schema
                && comment.name == old_name
            {
                comment.schema = schema;
                comment.name = name;
            }
        }
        self.move_routine_type_references(old_schema, old_name, schema, name, |_| true);
        self.rename_stored_query_dependency(DependencyClass::Domain, slot, None, schema, name);
    }

    pub fn drop_domain(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.domains.iter().find_map(|d| {
            (d.database == current_database()
                && d.schema.as_str() == schema
                && d.name.as_str() == name)
                .then_some(d.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = catalog.domains.iter().position(|d| {
            d.database == current_database()
                && d.visible_to(txid)
                && d.schema.as_str() == schema
                && d.name.as_str() == name
        }) else {
            return Ok(None);
        };
        let d = &mut catalog.domains[i];
        d.ddl_state = d.ddl_state.drop_by(txid);
        Ok(Some(i))
    }

    pub fn commit_domain_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.domains[slot].ddl_state = catalog.domains[slot].ddl_state.commit_create();
    }

    pub fn commit_domain_drop(&mut self, slot: usize) {
        let (schema, name) = {
            let catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            (catalog.domains[slot].schema, catalog.domains[slot].name)
        };
        self.drop_object_comments(CommentClass::Type, schema.as_str(), name.as_str());
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.domains[slot].ddl_state = catalog.domains[slot].ddl_state.commit_drop();
    }

    pub fn rollback_domain_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.domains[slot].ddl_state = catalog.domains[slot].ddl_state.rollback_create();
    }

    pub fn rollback_domain_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let d = &mut catalog.domains[slot];
        d.ddl_state = d.ddl_state.rollback_drop(txid);
    }

    // --- Enum types (CREATE TYPE ... AS ENUM) ---

    /// The slot of a (possibly schema-qualified) enum type name, visible to
    /// `txid`, searching the current path when unqualified.
    fn find_enum_slot(&self, qualifier: Option<&str>, name: &str, txid: u32) -> Option<usize> {
        if let Some(schema) = qualifier {
            return EnumIter {
                catalog: &self.type_catalog,
                next_slot: 0,
            }
            .find_map(|(slot, e)| {
                (e.database == current_database()
                    && e.visible_to(txid)
                    && e.definition_for(txid).schema.as_str() == schema
                    && e.definition_for(txid).name.as_str() == name)
                    .then_some(slot)
            });
        }
        for entry in self.path().entries() {
            if let PathEntry::Schema(slot) = entry {
                let schema = self.schema_def(*slot as usize).name;
                if let Some(i) = (EnumIter {
                    catalog: &self.type_catalog,
                    next_slot: 0,
                })
                .find_map(|(slot, e)| {
                    (e.database == current_database()
                        && e.visible_to(txid)
                        && e.definition_for(txid).schema.as_str() == schema.as_str()
                        && e.definition_for(txid).name.as_str() == name)
                        .then_some(slot)
                }) {
                    return Some(i);
                }
            }
        }
        None
    }

    /// Resolves a (possibly qualified) enum type name to its slot on the current
    /// path, visible to `txid`.
    pub fn resolve_enum_slot(&self, type_name: &str, txid: u32) -> Option<usize> {
        let (qualifier, name) = match type_name.split_once('.') {
            Some((q, n)) => (Some(q), n),
            None => (None, type_name),
        };
        self.find_enum_slot(qualifier, name, txid)
    }

    /// The definition of an enum named `name` (any schema) visible to `txid` —
    /// for resolving a column whose stored type identity is only the enum name.
    pub fn enum_by_name(&self, name: &str, txid: u32) -> Option<EnumDefinition<'_>> {
        self.enum_slot_by_name(name, txid)
            .map(|slot| self.enum_for(slot, txid))
    }

    /// The slot of an enum named `name` (any schema) visible to `txid`.
    pub fn enum_slot_by_name(&self, name: &str, txid: u32) -> Option<usize> {
        EnumIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .find_map(|(slot, e)| {
            (e.database == current_database()
                && e.visible_to(txid)
                && e.definition_for(txid).name.as_str() == name)
                .then_some(slot)
        })
    }

    /// The enum named `(schema, name)` visible to `txid`, by slot.
    pub fn enum_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        EnumIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .find_map(|(slot, e)| {
            (e.database == current_database()
                && e.visible_to(txid)
                && e.definition_for(txid).schema.as_str() == schema
                && e.definition_for(txid).name.as_str() == name)
                .then_some(slot)
        })
    }

    pub(crate) fn enum_for(&self, slot: usize, txid: u32) -> EnumDefinition<'_> {
        let (definition, member_image, member_count) = {
            let catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let enumeration = catalog.enums[slot];
            let definition = enumeration.definition_for(txid);
            let (image, count) = enumeration
                .pending_definition
                .filter(|pending| pending.txid == txid)
                .map_or((slot, enumeration.member_count), |pending| {
                    (
                        self.enum_member_pending_base + pending.member_slot as usize,
                        pending.member_count,
                    )
                });
            (
                definition,
                image * self.enum_members_per_image,
                count as usize,
            )
        };
        EnumDefinition {
            catalog: &self.type_catalog,
            member_image,
            member_count,
            database: definition.database,
            created_at: definition.created_at,
            schema: definition.schema,
            name: definition.name,
            ownership: definition.ownership,
            ddl_state: definition.ddl_state,
        }
    }

    pub(crate) fn enum_count(&self) -> usize {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .enums
            .len()
    }

    pub(crate) fn enum_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let enumeration = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .enums[slot];
        enumeration.database == current_database() && enumeration.visible_to(txid)
    }

    /// Whether `label` was added to a pre-existing enum by this transaction.
    /// PostgreSQL makes such labels visible in the catalog but rejects their
    /// use until commit; labels of a type created in the same transaction and
    /// renamed committed labels are immediately safe.
    pub(crate) fn enum_label_is_uncommitted(&self, slot: usize, label: &str, txid: u32) -> bool {
        let catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let enumeration = &catalog.enums[slot];
        if enumeration.ddl_state == (CatalogDdlState::PendingCreate { txid }) {
            return false;
        }
        let Some(pending) = enumeration
            .pending_definition
            .filter(|pending| pending.txid == txid)
        else {
            return false;
        };
        let start = (self.enum_member_pending_base + pending.member_slot as usize)
            * self.enum_members_per_image;
        catalog.enum_members[start..start + pending.member_count as usize]
            .iter()
            .position(|member| member.label.as_str() == label)
            .is_some_and(|index| index >= pending.safe_member_count as usize)
    }

    /// Committed enums carrying their slot indices, for the checkpoint,
    /// `pg_type` and `pg_enum`.
    pub fn live_enums(&self) -> impl Iterator<Item = (usize, EnumDef)> + '_ {
        EnumIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .filter(|(_, e)| {
            e.database == current_database() && e.ddl_state == CatalogDdlState::Present
        })
    }

    /// Whether any table column (in any table) is declared with this enum —
    /// the dependency that makes `DROP TYPE ... RESTRICT` fail.
    pub fn enum_in_use(&self, slot: usize) -> Option<(SqlName, SqlName)> {
        for table in self
            .tables
            .iter()
            .filter(|t| t.database == current_database() && t.live)
        {
            for col in table.def.columns() {
                if matches!(col.ctype, ColType::Enum(s) if s as usize == slot)
                    || matches!(
                        col.ctype,
                        ColType::Array(ArrElem::Enum(s)) if s as usize == slot
                    )
                {
                    return Some((table.def.name, col.name));
                }
            }
        }
        None
    }

    fn write_enum_member_image(
        catalog: &mut TypeCatalog,
        enum_members_per_image: usize,
        image: usize,
        members: &[EnumMember],
    ) -> Result<u32, SqlError> {
        if members.len() > enum_members_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "an enum type may have at most {} labels",
                enum_members_per_image
            ));
        }
        let count = u32::try_from(members.len()).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "enum label count exceeds durable representation"
            )
        })?;
        let start = image * enum_members_per_image;
        catalog.enum_members[start..start + members.len()].copy_from_slice(members);
        Ok(count)
    }

    pub(crate) fn enum_label_capacity(&self) -> usize {
        self.enum_members_per_image
    }

    pub(crate) fn enum_replay_members(
        &self,
        count: usize,
    ) -> Result<EnumReplayMembers<'_>, SqlError> {
        if count > self.enum_members_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "an enum type may have at most {} labels",
                self.enum_members_per_image
            ));
        }
        let start = self.enum_member_replay_image * self.enum_members_per_image;
        Ok(EnumReplayMembers {
            catalog: self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned"),
            start,
            count,
        })
    }

    pub(crate) fn finish_enum_replay(
        &mut self,
        schema: SqlName,
        name: SqlName,
        count: usize,
    ) -> Result<usize, SqlError> {
        if count > self.enum_members_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "an enum type may have at most {} labels",
                self.enum_members_per_image
            ));
        }
        let slot = if let Some(slot) = self.enum_slot(schema.as_str(), name.as_str(), 0) {
            slot
        } else {
            self.create_enum(schema, name, EnumSpec { members: &[] }, 0)?
        };
        let source = self.enum_member_replay_image * self.enum_members_per_image;
        let target = slot * self.enum_members_per_image;
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog
            .enum_members
            .copy_within(source..source + count, target);
        catalog.enums[slot].member_count = u32::try_from(count).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "enum label count exceeds durable representation"
            )
        })?;
        Ok(slot)
    }

    /// Registers an enum as an uncommitted CREATE owned by `txid` (or, for
    /// replay/checkpoint with `txid == 0`, committed directly). The caller has
    /// validated the labels and checked the name is free.
    pub fn create_enum(
        &mut self,
        schema: SqlName,
        name: SqlName,
        spec: EnumSpec<'_>,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.require_schema_create(schema.as_str(), txid)?;
        let created_at = self.catalog_sequence.next();
        let ownership = self.initial_ownership(txid);
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.enums.iter().find_map(|e| {
            let same_name = e.database == current_database()
                && (e.schema == schema && e.name == name
                    || e.pending_definition
                        .is_some_and(|pending| pending.schema == schema && pending.name == name));
            same_name
                .then(|| {
                    e.pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| e.ddl_state.pending_txid())
                })
                .flatten()
                .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog.enums.iter().any(|e| {
            e.database == current_database()
                && e.visible_to(txid)
                && e.definition_for(txid).schema == schema
                && e.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(blocker) = catalog.domains.iter().find_map(|d| {
            (d.database == current_database()
                && (d.schema == schema && d.name == name
                    || d.pending_definition
                        .and_then(|pending| pending.identity)
                        .is_some_and(|identity| {
                            identity.schema == schema && identity.name == name
                        })))
            .then_some(d.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog.domains.iter().any(|d| {
            d.database == current_database()
                && d.visible_to(txid)
                && d.definition_for(txid).schema == schema
                && d.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        if catalog.composites.iter().any(|composite| {
            composite.database == current_database()
                && composite.visible_to(txid)
                && composite.definition_for(txid).schema == schema
                && composite.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(new) = catalog
            .enums
            .iter()
            .position(|e| e.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many enum types (limit {})",
                catalog.enums.len()
            ));
        };
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Enum,
            slot: new as u16,
        });
        let member_count = Self::write_enum_member_image(
            &mut catalog,
            self.enum_members_per_image,
            new,
            spec.members,
        )?;
        catalog.enums[new] = EnumDef {
            database: current_database(),
            created_at,
            schema,
            name,
            ownership,
            member_count,
            pending_definition: None,
            ddl_state: if txid == 0 {
                CatalogDdlState::Present
            } else {
                CatalogDdlState::PendingCreate { txid }
            },
        };
        Ok(new)
    }

    pub(crate) fn stage_enum_alter(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
        members: &[EnumMember],
        txid: u32,
    ) -> Result<Option<PendingEnumDefinition>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog
            .enums
            .iter()
            .enumerate()
            .find_map(|(other_slot, other)| {
                (other_slot != slot
                    && other.database == current_database()
                    && (other.schema == schema && other.name == name
                        || other.pending_definition.is_some_and(|pending| {
                            pending.schema == schema && pending.name == name
                        })))
                .then(|| {
                    other
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| other.ddl_state.pending_txid())
                })
                .flatten()
                .filter(|&owner| owner != txid)
            })
        {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if let Some(blocker) = catalog.domains.iter().find_map(|domain| {
            (domain.database == current_database()
                && (domain.schema == schema && domain.name == name
                    || domain
                        .pending_definition
                        .and_then(|pending| pending.identity)
                        .is_some_and(|identity| {
                            identity.schema == schema && identity.name == name
                        })))
            .then_some(domain.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog.enums.iter().enumerate().any(|(other_slot, other)| {
            other_slot != slot
                && other.database == current_database()
                && other.visible_to(txid)
                && other.definition_for(txid).schema == schema
                && other.definition_for(txid).name == name
        }) || catalog.domains.iter().any(|domain| {
            domain.database == current_database()
                && domain.visible_to(txid)
                && domain.definition_for(txid).schema == schema
                && domain.definition_for(txid).name == name
        }) || catalog.composites.iter().any(|composite| {
            composite.database == current_database()
                && composite.visible_to(txid)
                && composite.definition_for(txid).schema == schema
                && composite.definition_for(txid).name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(pending) = catalog.enums[slot].pending_definition
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "type \"{}\" is being altered by another transaction",
                catalog.enums[slot].name.as_str()
            ));
        }
        let prior = catalog.enums[slot].pending_definition;
        let previous = prior.map(|pending| pending.member_slot);
        if previous.is_some_and(|previous| {
            catalog.pending_enum_members[previous as usize].depth
                >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "enum type exceeds max_catalog_versions_per_object ({})",
                self.max_catalog_versions_per_object
            ));
        }
        let Some(member_slot) = catalog
            .pending_enum_members
            .iter()
            .position(|entry| !entry.used)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "pending enum-definition pool is exhausted"
            ));
        };
        let depth = previous.map_or(1, |previous| {
            catalog.pending_enum_members[previous as usize].depth + 1
        });
        let member_count = Self::write_enum_member_image(
            &mut catalog,
            self.enum_members_per_image,
            self.enum_member_pending_base + member_slot,
            members,
        )?;
        catalog.pending_enum_members[member_slot] = PendingEnumMemberSlot {
            used: true,
            previous,
            depth,
        };
        let safe_member_count = prior.map_or(catalog.enums[slot].member_count, |pending| {
            pending.safe_member_count
        });
        catalog.enums[slot].pending_definition = Some(PendingEnumDefinition {
            txid,
            schema,
            name,
            member_count,
            safe_member_count,
            member_slot: member_slot as u32,
        });
        Ok(prior)
    }

    pub(crate) fn mark_enum_label_uncommitted(
        &mut self,
        slot: usize,
        label: SqlName,
        txid: u32,
    ) -> Result<(), SqlError> {
        let catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if catalog.enums[slot].ddl_state == (CatalogDdlState::PendingCreate { txid }) {
            return Ok(());
        }
        let pending = catalog.enums[slot]
            .pending_definition
            .filter(|pending| pending.txid == txid)
            .ok_or_else(|| sql_err!(sqlstate::INTERNAL_ERROR, "enum alteration is not staged"))?;
        let start = (self.enum_member_pending_base + pending.member_slot as usize)
            * self.enum_members_per_image;
        catalog.enum_members[start..start + pending.member_count as usize]
            .iter()
            .position(|member| member.label == label)
            .ok_or_else(|| sql_err!(sqlstate::INTERNAL_ERROR, "new enum label is not staged"))?;
        Ok(())
    }

    fn release_pending_enum_members(catalog: &mut TypeCatalog, slot: u32) -> Option<u32> {
        let pending = catalog.pending_enum_members[slot as usize];
        catalog.pending_enum_members[slot as usize] = PendingEnumMemberSlot::EMPTY;
        pending.previous
    }

    fn clear_pending_enum_member_chain(catalog: &mut TypeCatalog, mut tail: Option<u32>) {
        while let Some(slot) = tail {
            tail = Self::release_pending_enum_members(catalog, slot);
        }
    }

    pub(crate) fn commit_enum_alter(&mut self, slot: usize, txid: u32) {
        let rename = {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let Some(pending) = catalog.enums[slot]
                .pending_definition
                .filter(|pending| pending.txid == txid)
            else {
                return;
            };
            let definition = catalog.enums[slot].definition_for(txid);
            let previous = catalog.enums[slot];
            let source = (self.enum_member_pending_base + pending.member_slot as usize)
                * self.enum_members_per_image;
            let target = slot * self.enum_members_per_image;
            let count = pending.member_count as usize;
            catalog
                .enum_members
                .copy_within(source..source + count, target);
            catalog.enums[slot] = definition;
            Self::clear_pending_enum_member_chain(&mut catalog, Some(pending.member_slot));
            (definition.schema != previous.schema || definition.name != previous.name).then_some((
                previous.schema,
                previous.name,
                definition.schema,
                definition.name,
            ))
        };
        if let Some((old_schema, old_name, schema, name)) = rename {
            self.move_enum_references(slot, old_schema, old_name, schema, name);
        }
    }

    pub(crate) fn replay_enum_identity(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if catalog.enums.iter().enumerate().any(|(other_slot, other)| {
            other_slot != slot
                && other.database == current_database()
                && other.visible_to(0)
                && other.schema == schema
                && other.name == name
        }) || catalog.domains.iter().any(|domain| {
            domain.database == current_database()
                && domain.visible_to(0)
                && domain.schema == schema
                && domain.name == name
        }) || catalog.composites.iter().any(|composite| {
            composite.database == current_database()
                && composite.visible_to(0)
                && composite.schema == schema
                && composite.name == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        let previous = catalog.enums[slot];
        if schema != previous.schema || name != previous.name {
            catalog.enums[slot].schema = schema;
            catalog.enums[slot].name = name;
            drop(catalog);
            self.move_enum_references(slot, previous.schema, previous.name, schema, name);
        }
        Ok(())
    }

    pub(crate) fn rollback_enum_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingEnumDefinition>,
    ) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(current) = catalog.enums[slot].pending_definition {
            Self::release_pending_enum_members(&mut catalog, current.member_slot);
        }
        catalog.enums[slot].pending_definition = prior;
    }

    /// Moves an enum and every persisted reference to its type identity. Runtime
    /// slots and value sort keys stay stable; comments are name-keyed and move
    /// with the type just as PostgreSQL keeps the same `pg_type` OID.
    fn move_enum_references(
        &mut self,
        slot: usize,
        old_schema: SqlName,
        old_name: SqlName,
        new_schema: SqlName,
        new_name: SqlName,
    ) {
        for table in self
            .tables
            .iter_mut()
            .filter(|table| table.live || table.pending_ddl.is_some())
        {
            let mut changed = false;
            for column in table.def.columns[..table.def.n_columns].iter_mut() {
                let uses_enum = matches!(column.ctype, ColType::Enum(s) if s as usize == slot)
                    || matches!(
                        column.ctype,
                        ColType::Array(ArrElem::Enum(s)) if s as usize == slot
                    );
                if uses_enum {
                    if let Some(identity) = &mut column.user_type {
                        identity.schema = new_schema;
                        identity.name = new_name;
                    }
                    changed = true;
                }
            }
            if changed {
                table.mark_dirty();
            }
        }
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        for composite in catalog
            .composites
            .iter_mut()
            .filter(|composite| composite.ddl_state != CatalogDdlState::Absent)
        {
            for field in composite.fields.iter_mut().take(composite.n_fields) {
                if matches!(field.ctype, ColType::Enum(candidate) | ColType::Array(ArrElem::Enum(candidate)) if candidate as usize == slot)
                    && let Some(identity) = &mut field.user_type
                {
                    identity.schema = new_schema;
                    identity.name = new_name;
                }
            }
            if let Some(pending) = &mut composite.pending_definition {
                for field in pending.fields.iter_mut().take(pending.n_fields) {
                    if matches!(field.ctype, ColType::Enum(candidate) | ColType::Array(ArrElem::Enum(candidate)) if candidate as usize == slot)
                        && let Some(identity) = &mut field.user_type
                    {
                        identity.schema = new_schema;
                        identity.name = new_name;
                    }
                }
            }
        }
        for domain in catalog
            .domains
            .iter_mut()
            .filter(|domain| domain.ddl_state != CatalogDdlState::Absent)
        {
            if matches!(domain.base, ColType::Enum(candidate) if candidate as usize == slot)
                && domain.base_user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
            {
                domain.base_user_type = Some(UserTypeName {
                    schema: new_schema,
                    name: new_name,
                });
            }
        }
        drop(catalog);
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.class == CommentClass::Type
                && comment.schema == old_schema
                && comment.name == old_name
            {
                comment.schema = new_schema;
                comment.name = new_name;
            }
        }
        self.move_routine_type_references(old_schema, old_name, new_schema, new_name, |ctype| {
            matches!(ctype, ColType::Enum(candidate) | ColType::Array(ArrElem::Enum(candidate)) if candidate as usize == slot)
        });
        self.rename_stored_query_dependency(
            DependencyClass::Enum,
            slot,
            None,
            new_schema,
            new_name,
        );
    }

    pub fn drop_enum(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.enums.iter().find_map(|e| {
            let same_name = e.schema.as_str() == schema
                && (e.name.as_str() == name
                    || e.pending_definition
                        .is_some_and(|pending| pending.name.as_str() == name));
            same_name
                .then(|| {
                    e.pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| e.ddl_state.pending_txid())
                })
                .flatten()
                .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = catalog.enums.iter().position(|e| {
            e.visible_to(txid)
                && e.schema.as_str() == schema
                && e.definition_for(txid).name.as_str() == name
        }) else {
            return Ok(None);
        };
        let e = &mut catalog.enums[i];
        e.ddl_state = e.ddl_state.drop_by(txid);
        Ok(Some(i))
    }

    pub fn commit_enum_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.enums[slot].ddl_state = catalog.enums[slot].ddl_state.commit_create();
    }

    pub fn commit_enum_drop(&mut self, slot: usize) {
        let (schema, name) = {
            let catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            (catalog.enums[slot].schema, catalog.enums[slot].name)
        };
        self.drop_object_comments(CommentClass::Type, schema.as_str(), name.as_str());
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let pending = catalog.enums[slot]
            .pending_definition
            .take()
            .map(|pending| pending.member_slot);
        Self::clear_pending_enum_member_chain(&mut catalog, pending);
        catalog.enums[slot].ddl_state = catalog.enums[slot].ddl_state.commit_drop();
    }

    pub fn rollback_enum_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.enums[slot].ddl_state = catalog.enums[slot].ddl_state.rollback_create();
    }

    pub fn rollback_enum_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let e = &mut catalog.enums[slot];
        e.ddl_state = e.ddl_state.rollback_drop(txid);
    }

    // --- Named composite types (CREATE TYPE ... AS (...)) ---

    pub fn resolve_composite_slot(&self, type_name: &str, txid: u32) -> Option<usize> {
        let (qualifier, name) = type_name
            .split_once('.')
            .map_or((None, type_name), |(s, n)| (Some(s), n));
        self.find_composite_slot(qualifier, name, txid)
    }

    fn find_composite_slot(&self, qualifier: Option<&str>, name: &str, txid: u32) -> Option<usize> {
        if let Some(schema) = qualifier {
            return self.composite_slot(schema, name, txid);
        }
        for entry in self.path().entries() {
            let PathEntry::Schema(schema_slot) = entry else {
                continue;
            };
            let schema = self.schema_def(*schema_slot as usize).name;
            if let Some(slot) = self.composite_slot(schema.as_str(), name, txid) {
                return Some(slot);
            }
        }
        None
    }

    pub fn composite_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        CompositeIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .find_map(|(slot, definition)| {
            (definition.database == current_database()
                && definition.visible_to(txid)
                && definition.definition_for(txid).schema.as_str() == schema
                && definition.definition_for(txid).name.as_str() == name)
                .then_some(slot)
        })
    }

    /// Resolve the closed PostgreSQL `ALTER TYPE ... OWNER` target set.
    ///
    /// Search-path resolution is performed once across the shared named-type
    /// namespace, so an enum in a later schema cannot shadow a composite in an
    /// earlier schema (or vice versa).
    pub(crate) fn resolve_alter_type_target(
        &self,
        qualifier: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<AlterTypeTarget> {
        if let Some(schema) = qualifier {
            return self.alter_type_target_in_schema(schema, name, txid);
        }
        for entry in self.path().entries() {
            let PathEntry::Schema(schema_slot) = entry else {
                continue;
            };
            let schema = self.schema_def(*schema_slot as usize).name;
            if let Some(target) = self.alter_type_target_in_schema(schema.as_str(), name, txid) {
                return Some(target);
            }
        }
        None
    }

    fn alter_type_target_in_schema(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Option<AlterTypeTarget> {
        match (
            self.enum_slot(schema, name, txid),
            self.composite_slot(schema, name, txid),
        ) {
            (Some(enum_slot), None) => Some(AlterTypeTarget::Enum(enum_slot as u16)),
            (None, Some(composite_slot)) => Some(AlterTypeTarget::Composite(composite_slot as u16)),
            (None, None) => None,
            (Some(_), Some(_)) => {
                unreachable!("the shared named-type namespace admitted a duplicate")
            }
        }
    }

    pub fn composite(&self, slot: usize) -> CompositeDef {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .composites[slot]
    }

    pub(crate) fn composite_for(&self, slot: usize, txid: u32) -> CompositeDef {
        self.composite(slot).definition_for(txid)
    }

    pub fn live_composites(&self) -> impl Iterator<Item = (usize, CompositeDef)> + '_ {
        CompositeIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .filter(|(_, definition)| {
            definition.database == current_database()
                && definition.ddl_state == CatalogDdlState::Present
        })
    }

    pub(crate) fn composite_count(&self) -> usize {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .composites
            .len()
    }

    pub(crate) fn composites_with_slots_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, CompositeDef)> + '_ {
        CompositeIter {
            catalog: &self.type_catalog,
            next_slot: 0,
        }
        .filter(move |(_, definition)| {
            definition.database == current_database() && definition.visible_to(txid)
        })
        .map(move |(slot, definition)| (slot, definition.definition_for(txid)))
    }

    pub(crate) fn composite_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let composite = self.composite(slot);
        composite.database == current_database() && composite.visible_to(txid)
    }

    pub(crate) fn stage_composite_alter(
        &mut self,
        slot: usize,
        definition: CompositeDef,
        txid: u32,
    ) -> Result<Option<PendingCompositeDefinition>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.enums.iter().find_map(|enumeration| {
            (enumeration.database == current_database()
                && (enumeration.schema == definition.schema && enumeration.name == definition.name
                    || enumeration.pending_definition.is_some_and(|pending| {
                        pending.schema == definition.schema && pending.name == definition.name
                    })))
            .then(|| {
                enumeration
                    .pending_definition
                    .map(|pending| pending.txid)
                    .or_else(|| enumeration.ddl_state.pending_txid())
            })
            .flatten()
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, definition.name.as_str()));
        }
        if let Some(blocker) = catalog.domains.iter().find_map(|domain| {
            (domain.database == current_database()
                && (domain.schema == definition.schema && domain.name == definition.name
                    || domain
                        .pending_definition
                        .and_then(|pending| pending.identity)
                        .is_some_and(|identity| {
                            identity.schema == definition.schema && identity.name == definition.name
                        })))
            .then_some(domain.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, definition.name.as_str()));
        }
        if let Some(blocker) =
            catalog
                .composites
                .iter()
                .enumerate()
                .find_map(|(other_slot, other)| {
                    (other_slot != slot
                        && other.database == current_database()
                        && (other.schema == definition.schema && other.name == definition.name
                            || other.pending_definition.is_some_and(|pending| {
                                pending.schema == definition.schema
                                    && pending.name == definition.name
                            })))
                    .then(|| {
                        other
                            .pending_definition
                            .map(|pending| pending.txid)
                            .or_else(|| other.ddl_state.pending_txid())
                    })
                    .flatten()
                    .filter(|&owner| owner != txid)
                })
        {
            return Err(self.catalog_ddl_wait_error(txid, blocker, definition.name.as_str()));
        }
        if catalog.enums.iter().any(|enumeration| {
            enumeration.database == current_database()
                && enumeration.visible_to(txid)
                && enumeration.definition_for(txid).schema == definition.schema
                && enumeration.definition_for(txid).name == definition.name
        }) || catalog.domains.iter().any(|domain| {
            domain.database == current_database()
                && domain.visible_to(txid)
                && domain.definition_for(txid).schema == definition.schema
                && domain.definition_for(txid).name == definition.name
        }) || catalog
            .composites
            .iter()
            .enumerate()
            .any(|(other_slot, other)| {
                other_slot != slot
                    && other.database == current_database()
                    && other.visible_to(txid)
                    && other.definition_for(txid).schema == definition.schema
                    && other.definition_for(txid).name == definition.name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        let name = catalog.composites[slot].name;
        let composite = &mut catalog.composites[slot];
        if let Some(pending) = composite.pending_definition
            && pending.txid != txid
        {
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, name.as_str()));
        }
        let prior = composite.pending_definition;
        composite.pending_definition = Some(PendingCompositeDefinition {
            txid,
            schema: definition.schema,
            name: definition.name,
            fields: definition.fields,
            n_fields: definition.n_fields,
        });
        Ok(prior)
    }

    pub(crate) fn commit_composite_alter(&mut self, slot: usize, txid: u32) {
        let renamed = {
            let mut catalog = self
                .type_catalog
                .lock()
                .expect("type catalog lock poisoned");
            let composite = &mut catalog.composites[slot];
            if let Some(pending) = composite.pending_definition
                && pending.txid == txid
            {
                let prior_schema = composite.schema;
                let prior_name = composite.name;
                composite.schema = pending.schema;
                composite.name = pending.name;
                composite.fields = pending.fields;
                composite.n_fields = pending.n_fields;
                composite.pending_definition = None;
                (prior_schema != composite.schema || prior_name != composite.name).then_some((
                    prior_schema,
                    prior_name,
                    composite.schema,
                    composite.name,
                ))
            } else {
                None
            }
        };
        if let Some((prior_schema, prior_name, new_schema, new_name)) = renamed {
            self.move_composite_references(slot, prior_schema, prior_name, new_schema, new_name);
        }
    }

    /// A composite slot is durable identity, while persisted definitions retain
    /// the SQL identity needed to rebind that slot after recovery. Move every
    /// such identity in the same catalog commit that changes its schema or name.
    fn move_composite_references(
        &mut self,
        slot: usize,
        old_schema: SqlName,
        old_name: SqlName,
        new_schema: SqlName,
        new_name: SqlName,
    ) {
        for table in self
            .tables
            .iter_mut()
            .filter(|table| table.live || table.pending_ddl.is_some())
        {
            let mut changed = false;
            for column in table.def.columns[..table.def.n_columns].iter_mut() {
                if matches!(
                    column.ctype,
                    ColType::Composite(candidate)
                        | ColType::Array(ArrElem::Composite(candidate))
                        if candidate as usize == slot
                ) && column.user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
                {
                    column.user_type = Some(UserTypeName {
                        schema: new_schema,
                        name: new_name,
                    });
                    changed = true;
                }
            }
            if changed {
                table.mark_dirty();
            }
        }
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        for composite in catalog
            .composites
            .iter_mut()
            .filter(|composite| composite.ddl_state != CatalogDdlState::Absent)
        {
            for field in composite.fields.iter_mut().take(composite.n_fields) {
                if matches!(
                    field.ctype,
                    ColType::Composite(candidate)
                        | ColType::Array(ArrElem::Composite(candidate))
                        if candidate as usize == slot
                ) && field.user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
                {
                    field.user_type = Some(UserTypeName {
                        schema: new_schema,
                        name: new_name,
                    });
                }
            }
            if let Some(pending) = &mut composite.pending_definition {
                for field in pending.fields.iter_mut().take(pending.n_fields) {
                    if matches!(
                        field.ctype,
                        ColType::Composite(candidate)
                            | ColType::Array(ArrElem::Composite(candidate))
                            if candidate as usize == slot
                    ) && field.user_type
                        == Some(UserTypeName {
                            schema: old_schema,
                            name: old_name,
                        })
                    {
                        field.user_type = Some(UserTypeName {
                            schema: new_schema,
                            name: new_name,
                        });
                    }
                }
            }
        }
        for domain in catalog
            .domains
            .iter_mut()
            .filter(|domain| domain.ddl_state != CatalogDdlState::Absent)
        {
            if matches!(domain.base, ColType::Composite(candidate) if candidate as usize == slot)
                && domain.base_user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
            {
                domain.base_user_type = Some(UserTypeName {
                    schema: new_schema,
                    name: new_name,
                });
            }
        }
        drop(catalog);
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.class == CommentClass::Type
                && comment.schema == old_schema
                && comment.name == old_name
            {
                comment.schema = new_schema;
                comment.name = new_name;
            }
        }
        self.move_routine_type_references(old_schema, old_name, new_schema, new_name, |ctype| {
            matches!(ctype, ColType::Composite(candidate) | ColType::Array(ArrElem::Composite(candidate)) if candidate as usize == slot)
        });
        self.rename_stored_query_dependency(
            DependencyClass::Composite,
            slot,
            None,
            new_schema,
            new_name,
        );
    }

    fn move_routine_type_references(
        &mut self,
        old_schema: SqlName,
        old_name: SqlName,
        new_schema: SqlName,
        new_name: SqlName,
        uses: impl Fn(ColType) -> bool,
    ) {
        let move_argument = |argument: &mut RoutineArgumentDef| {
            if uses(argument.ctype)
                && argument.user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
            {
                argument.user_type = Some(UserTypeName {
                    schema: new_schema,
                    name: new_name,
                });
            }
        };
        let move_result = |result: &mut RoutineResult| {
            if uses(result.ctype)
                && result.user_type
                    == Some(UserTypeName {
                        schema: old_schema,
                        name: old_name,
                    })
            {
                result.user_type = Some(UserTypeName {
                    schema: new_schema,
                    name: new_name,
                });
            }
        };
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        for routine in routines.iter_mut() {
            for argument in routine.arguments.iter_mut().take(routine.argument_count) {
                move_argument(argument);
            }
            for column in routine
                .result_columns
                .iter_mut()
                .take(routine.result_column_count)
            {
                move_argument(column);
            }
            for parameter in routine.parameters.iter_mut().take(routine.parameter_count) {
                let mut argument = RoutineArgumentDef {
                    name: parameter.name,
                    ctype: parameter.ctype,
                    user_type: parameter.user_type,
                };
                move_argument(&mut argument);
                parameter.user_type = argument.user_type;
            }
            match &mut routine.kind {
                RoutineKind::Function { result } | RoutineKind::SetFunction { result } => {
                    move_result(result)
                }
                RoutineKind::Aggregate(aggregate) => {
                    move_result(&mut aggregate.state_type);
                    move_result(&mut aggregate.result_type);
                    if let Some(moving) = &mut aggregate.moving {
                        move_result(&mut moving.state_type);
                    }
                }
                _ => {}
            }
            if let Some(pending) = &mut routine.pending_definition {
                for argument in pending.arguments.iter_mut().take(pending.argument_count) {
                    move_argument(argument);
                }
                for column in pending
                    .result_columns
                    .iter_mut()
                    .take(pending.result_column_count)
                {
                    move_argument(column);
                }
                for parameter in pending.parameters.iter_mut().take(pending.parameter_count) {
                    let mut argument = RoutineArgumentDef {
                        name: parameter.name,
                        ctype: parameter.ctype,
                        user_type: parameter.user_type,
                    };
                    move_argument(&mut argument);
                    parameter.user_type = argument.user_type;
                }
                match &mut pending.kind {
                    RoutineKind::Function { result } | RoutineKind::SetFunction { result } => {
                        move_result(result)
                    }
                    RoutineKind::Aggregate(aggregate) => {
                        move_result(&mut aggregate.state_type);
                        move_result(&mut aggregate.result_type);
                        if let Some(moving) = &mut aggregate.moving {
                            move_result(&mut moving.state_type);
                        }
                    }
                    _ => {}
                }
            }
        }
    }

    pub(crate) fn rollback_composite_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingCompositeDefinition>,
    ) {
        self.type_catalog
            .lock()
            .expect("type catalog lock poisoned")
            .composites[slot]
            .pending_definition = prior;
    }

    pub fn create_composite(
        &mut self,
        schema: SqlName,
        name: SqlName,
        mut spec: CompositeSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.require_schema_create(schema.as_str(), txid)?;
        for field in spec.fields.iter_mut().take(spec.n_fields) {
            let Some(identity) = field.user_type else {
                continue;
            };
            let rebound = match field.ctype {
                ColType::Enum(_) | ColType::Array(ArrElem::Enum(_)) => self
                    .enum_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .map(|slot| {
                        if matches!(field.ctype, ColType::Array(_)) {
                            ColType::Array(ArrElem::Enum(slot as u16))
                        } else {
                            ColType::Enum(slot as u16)
                        }
                    }),
                ColType::Composite(_) | ColType::Array(ArrElem::Composite(_)) => self
                    .composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .map(|slot| {
                        if matches!(field.ctype, ColType::Array(_)) {
                            ColType::Array(ArrElem::Composite(slot as u16))
                        } else {
                            ColType::Composite(slot as u16)
                        }
                    }),
                _ => None,
            };
            if let Some(ctype) = rebound {
                field.ctype = ctype;
            }
        }
        let created_at = self.catalog_sequence.next();
        let ownership = self.initial_ownership(txid);
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        let blocker = catalog
            .domains
            .iter()
            .filter_map(|domain| {
                (domain.database == current_database()
                    && (domain.schema == schema && domain.name == name
                        || domain
                            .pending_definition
                            .and_then(|pending| pending.identity)
                            .is_some_and(|identity| {
                                identity.schema == schema && identity.name == name
                            })))
                .then(|| {
                    domain
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| domain.ddl_state.pending_txid())
                })
                .flatten()
            })
            .chain(catalog.enums.iter().filter_map(|enumeration| {
                (enumeration.database == current_database()
                    && (enumeration.schema == schema && enumeration.name == name
                        || enumeration.pending_definition.is_some_and(|pending| {
                            pending.schema == schema && pending.name == name
                        })))
                .then(|| {
                    enumeration
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| enumeration.ddl_state.pending_txid())
                })
                .flatten()
            }))
            .chain(catalog.composites.iter().filter_map(|composite| {
                (composite.database == current_database()
                    && (composite.schema == schema && composite.name == name
                        || composite.pending_definition.is_some_and(|pending| {
                            pending.schema == schema && pending.name == name
                        })))
                .then(|| {
                    composite
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| composite.ddl_state.pending_txid())
                })
                .flatten()
            }))
            .find(|&owner| owner != txid);
        if let Some(blocker) = blocker {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let exists = catalog.domains.iter().any(|domain| {
            domain.database == current_database()
                && domain.visible_to(txid)
                && domain.definition_for(txid).schema == schema
                && domain.definition_for(txid).name == name
        }) || catalog.enums.iter().any(|enumeration| {
            enumeration.database == current_database()
                && enumeration.visible_to(txid)
                && enumeration.definition_for(txid).schema == schema
                && enumeration.definition_for(txid).name == name
        }) || catalog.composites.iter().any(|composite| {
            composite.database == current_database()
                && composite.visible_to(txid)
                && composite.definition_for(txid).schema == schema
                && composite.definition_for(txid).name == name
        });
        if exists {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "type \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(slot) = catalog
            .composites
            .iter()
            .position(|definition| definition.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many composite types (limit {})",
                catalog.composites.len()
            ));
        };
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Composite,
            slot: slot as u16,
        });
        catalog.composites[slot] = CompositeDef {
            database: current_database(),
            created_at,
            schema,
            name,
            ownership,
            fields: spec.fields,
            n_fields: spec.n_fields,
            pending_definition: None,
            ddl_state: if txid == 0 {
                CatalogDdlState::Present
            } else {
                CatalogDdlState::PendingCreate { txid }
            },
        };
        Ok(slot)
    }

    /// Replays a durable composite catalog identity. A WAL record names the
    /// slot explicitly, so restart cannot rebind existing rows to whichever
    /// free slot happens to be allocated first.
    pub(crate) fn create_composite_at(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
        mut spec: CompositeSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        for field in spec.fields.iter_mut().take(spec.n_fields) {
            let Some(identity) = field.user_type else {
                continue;
            };
            if let Some(ctype) = match field.ctype {
                ColType::Enum(_) | ColType::Array(ArrElem::Enum(_)) => self
                    .enum_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .map(|type_slot| {
                        if matches!(field.ctype, ColType::Array(_)) {
                            ColType::Array(ArrElem::Enum(type_slot as u16))
                        } else {
                            ColType::Enum(type_slot as u16)
                        }
                    }),
                ColType::Composite(_) | ColType::Array(ArrElem::Composite(_)) => self
                    .composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .map(|type_slot| {
                        if matches!(field.ctype, ColType::Array(_)) {
                            ColType::Array(ArrElem::Composite(type_slot as u16))
                        } else {
                            ColType::Composite(type_slot as u16)
                        }
                    }),
                _ => None,
            } {
                field.ctype = ctype;
            }
        }
        let created_at = self.catalog_sequence.next();
        let ownership = self.initial_ownership(txid);
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if slot >= catalog.composites.len()
            || catalog.composites[slot].ddl_state != CatalogDdlState::Absent
        {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "journal composite catalog identity is unavailable"
            ));
        }
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Composite,
            slot: slot as u16,
        });
        catalog.composites[slot] = CompositeDef {
            database: current_database(),
            created_at,
            schema,
            name,
            ownership,
            fields: spec.fields,
            n_fields: spec.n_fields,
            pending_definition: None,
            ddl_state: if txid == 0 {
                CatalogDdlState::Present
            } else {
                CatalogDdlState::PendingCreate { txid }
            },
        };
        Ok(slot)
    }

    pub fn commit_composite_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.composites[slot].ddl_state = catalog.composites[slot].ddl_state.commit_create();
    }

    pub fn drop_composite(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        if let Some(blocker) = catalog.composites.iter().find_map(|definition| {
            (definition.database == current_database()
                && definition.schema.as_str() == schema
                && (definition.name.as_str() == name
                    || definition
                        .pending_definition
                        .is_some_and(|pending| pending.name.as_str() == name)))
            .then(|| {
                definition
                    .pending_definition
                    .map(|pending| pending.txid)
                    .or_else(|| definition.ddl_state.pending_txid())
            })
            .flatten()
            .filter(|&owner| owner != txid)
        }) {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(slot) = catalog.composites.iter().position(|definition| {
            definition.database == current_database()
                && definition.visible_to(txid)
                && definition.schema.as_str() == schema
                && definition.definition_for(txid).name.as_str() == name
        }) else {
            return Ok(None);
        };
        catalog.composites[slot].ddl_state = catalog.composites[slot].ddl_state.drop_by(txid);
        Ok(Some(slot))
    }

    pub fn commit_composite_drop(&mut self, slot: usize) {
        let definition = self.composite(slot);
        self.drop_object_comments(
            CommentClass::Type,
            definition.schema.as_str(),
            definition.name.as_str(),
        );
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.composites[slot].ddl_state = catalog.composites[slot].ddl_state.commit_drop();
    }

    pub fn rollback_composite_create(&mut self, slot: usize) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.composites[slot].ddl_state = catalog.composites[slot].ddl_state.rollback_create();
    }

    pub fn rollback_composite_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .type_catalog
            .lock()
            .expect("type catalog lock poisoned");
        catalog.composites[slot].ddl_state = catalog.composites[slot].ddl_state.rollback_drop(txid);
    }

    /// Registers a view as an uncommitted CREATE owned by `txid` (other
    /// transactions keep seeing the committed catalog until commit).
    /// `or_replace` marks an existing visible view pending-dropped. Returns
    /// `(new_slot, replaced_old_slot)`. Errors if the name is taken by a
    /// table, by a view visible to `txid` (without `or_replace`), or by
    /// another transaction's uncommitted view DDL.
    pub fn create_view(
        &self,
        schema: SqlName,
        name: SqlName,
        definition: ViewDefinition,
        or_replace: bool,
        txid: u32,
    ) -> Result<(usize, Option<usize>), SqlError> {
        self.require_schema_create(schema.as_str(), txid)?;
        if self.find_table(schema.as_str(), name.as_str()).is_some() {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                name.as_str()
            ));
        }
        let ownership = self.initial_ownership(txid);
        let mut catalog = self.view_rule_catalog();
        if let Some(blocker) = catalog.views.iter().find_map(|v| {
            (v.database == current_database()
                && v.schema_for(txid).as_str() == schema.as_str()
                && v.name.as_str() == name.as_str())
            .then_some(v.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let existing = catalog.views.iter().position(|v| {
            v.database == current_database()
                && v.visible_to(txid)
                && v.schema_for(txid).as_str() == schema.as_str()
                && v.name_for(txid).as_str() == name.as_str()
        });
        if existing.is_some() && !or_replace {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(new) = catalog
            .views
            .iter()
            .position(|v| v.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many views (limit {})",
                self.view_count()
            ));
        };
        let rule_definition = RuleDefinition {
            name: SqlName::parse("_RETURN").expect("fixed name fits"),
            target: RuleTarget::View(new as u16),
            event: RewriteEvent::Select,
            mode: RewriteMode::Instead,
            enabled: RuleEnabled::Origin,
            source: definition.query.sql,
            condition: None,
            actions: {
                let mut actions = [RuleTextSpan::EMPTY; MAX_RULE_ACTIONS];
                actions[0] = RuleTextSpan {
                    start: 0,
                    len: definition.query.sql.as_str().len() as u16,
                };
                actions
            },
            action_count: 1,
            returning_action: None,
            creation_path: definition.query.creation_path,
        };
        // Reserve and populate the return rule before changing either view.
        // Capacity errors must leave an existing replacement target untouched.
        let rule = self.create_new_rule_in(
            &mut catalog,
            rule_definition,
            definition.query.dependencies.view(),
            txid,
        )?;
        if let Some(old) = existing {
            Self::pending_replace_view_in(&mut catalog, old, txid);
        }
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::View,
            slot: new as u16,
        });
        catalog.views[new] = ViewDef {
            database: current_database(),
            created_at: self.catalog_sequence.next(),
            schema,
            name,
            persistence: definition.persistence,
            return_rule: rule as u16,
            options: definition.options,
            columns: definition.columns,
            ownership,
            pending_schema: None,
            pending_name: None,
            pending_options: None,
            pending_columns: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        drop(catalog);
        if definition.persistence == RelationPersistence::Temporary {
            self.mark_temporary_transaction(txid);
        }
        Ok((new, existing))
    }

    /// Restores a checkpointed view at its durable catalog slot. View OIDs and
    /// relation-target comment identities are slot-derived, so compacting a
    /// replacement-created hole during recovery would corrupt both.
    pub(crate) fn restore_view_at(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
        definition: ViewDefinition,
    ) -> Result<(), SqlError> {
        if slot >= self.view_count() || self.view(slot).ddl_state != CatalogDdlState::Absent {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "checkpoint view slot is unavailable"
            ));
        }
        if self.find_view(schema.as_str(), name.as_str(), 0).is_some() {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "checkpoint contains a duplicate view"
            ));
        }
        let (created, replaced) = self.create_view(schema, name, definition, false, 0)?;
        debug_assert!(replaced.is_none());
        if created != slot {
            let mut catalog = self.view_rule_catalog();
            catalog.views[slot] = catalog.views[created];
            catalog.views[created] = ViewDef::EMPTY;
            let return_rule = usize::from(catalog.views[slot].return_rule);
            catalog.rules[return_rule].definition.target = RuleTarget::View(slot as u16);
            if let Some(pending) = &mut catalog.rules[return_rule].pending {
                pending.definition.target = RuleTarget::View(slot as u16);
            }
        }
        self.commit_view_create(slot);
        Ok(())
    }

    /// Marks the view visible to `txid` pending-dropped; returns its slot (for
    /// undo). None if absent. Errors if another transaction's uncommitted DDL
    /// holds the name.
    pub fn drop_view(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let blocker = self.view_rule_catalog().views.iter().find_map(|v| {
            (v.database == current_database()
                && v.schema_for(txid).as_str() == schema
                && v.name.as_str() == name)
                .then_some(v.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        });
        if let Some(blocker) = blocker {
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = self.view_rule_catalog().views.iter().position(|v| {
            v.database == current_database()
                && v.visible_to(txid)
                && v.schema_for(txid).as_str() == schema
                && v.name_for(txid).as_str() == name
        }) else {
            return Ok(None);
        };
        self.pending_drop_view(i, txid);
        Ok(Some(i))
    }

    /// Overlays a pending DROP on a slot: the owner's own pending-create
    /// simply evaporates (never committed, nothing to keep).
    fn pending_drop_view(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.view_rule_catalog();
        catalog.views[slot].ddl_state = catalog.views[slot].ddl_state.drop_by(txid);
        for rule in catalog.rules.iter_mut().filter(|rule| {
            rule.database == current_database()
                && rule.visible_to(txid)
                && rule.definition_for(txid).target == RuleTarget::View(slot as u16)
        }) {
            rule.ddl_state = rule.ddl_state.drop_by(txid);
        }
    }

    /// A replacement retires only the old view and its SELECT rule. User
    /// rules, triggers, extension membership, and stored-query references
    /// belong to the logical view and are retargeted to the new catalog slot.
    fn pending_replace_view_in(catalog: &mut ViewRuleCatalog, slot: usize, txid: u32) {
        catalog.views[slot].ddl_state = catalog.views[slot].ddl_state.drop_by(txid);
        let return_rule = usize::from(catalog.views[slot].return_rule);
        catalog.rules[return_rule].ddl_state = catalog.rules[return_rule].ddl_state.drop_by(txid);
    }

    /// Moves the internal identity of a replaced view between physical catalog
    /// slots. The same operation in the opposite direction is the rollback.
    pub(crate) fn retarget_view_dependents(&mut self, from: usize, to: usize) {
        let schema = self.view(to).schema;
        let name = self.view(to).name;
        self.replace_stored_query_dependency_slot(DependencyClass::View, from, to, schema, name);

        let old_rule_subid = RuleTarget::View(from as u16).comment_subid();
        let new_rule_subid = RuleTarget::View(to as u16).comment_subid();
        let excluded_return_rule = usize::from(self.view(from).return_rule);
        let mut moved_rule = false;
        for (slot, rule) in self.view_rule_catalog().rules.iter_mut().enumerate() {
            if slot == excluded_return_rule || rule.ddl_state == CatalogDdlState::Absent {
                continue;
            }
            let mut changed = false;
            if rule.definition.target == RuleTarget::View(from as u16) {
                rule.definition.target = RuleTarget::View(to as u16);
                changed = true;
            }
            if let Some(pending) = &mut rule.pending
                && pending.definition.target == RuleTarget::View(from as u16)
            {
                pending.definition.target = RuleTarget::View(to as u16);
                changed = true;
            }
            moved_rule |= changed;
        }
        if moved_rule {
            for comment in self.comment_catalog().entries.iter_mut().filter(|comment| {
                comment.used
                    && comment.database == Some(current_database())
                    && comment.class == CommentClass::Rule
                    && comment.subid == old_rule_subid
            }) {
                comment.subid = new_rule_subid;
            }
        }

        let old_trigger_target = TriggerTarget::View(from as u16);
        let new_trigger_target = TriggerTarget::View(to as u16);
        let mut moved_trigger = false;
        {
            let mut catalog = self
                .trigger_catalog
                .lock()
                .expect("trigger catalog lock poisoned");
            for trigger in catalog.definitions.iter_mut().filter(|trigger| {
                trigger.database == current_database()
                    && trigger.ddl_state != CatalogDdlState::Absent
                    && trigger.target == old_trigger_target
            }) {
                trigger.target = new_trigger_target;
                moved_trigger = true;
            }
        }
        if moved_trigger {
            let old_subid = old_trigger_target.comment_subid();
            let new_subid = new_trigger_target.comment_subid();
            for comment in self.comment_catalog().entries.iter_mut().filter(|comment| {
                comment.used
                    && comment.database == Some(current_database())
                    && comment.class == CommentClass::Trigger
                    && comment.subid == old_subid
            }) {
                comment.subid = new_subid;
            }
        }

        let old_object = AccessObject {
            class: AccessClass::View,
            slot: from as u16,
        };
        let new_object = AccessObject {
            class: AccessClass::View,
            slot: to as u16,
        };
        for dependency in self.extension_catalog().dependencies.iter_mut() {
            if dependency.object == old_object {
                dependency.object = new_object;
            }
        }
    }

    /// Promotes an uncommitted CREATE VIEW into the committed catalog.
    pub fn commit_view_create(&self, slot: usize) {
        let mut catalog = self.view_rule_catalog();
        catalog.views[slot].ddl_state = catalog.views[slot].ddl_state.commit_create();
        let rule = usize::from(catalog.views[slot].return_rule);
        catalog.rules[rule].ddl_state = catalog.rules[rule].ddl_state.commit_create();
    }

    pub(crate) fn stage_view_schema(
        &mut self,
        slot: usize,
        schema: SqlName,
        txid: u32,
    ) -> Result<Option<PendingObjectSchema>, SqlError> {
        let prior = self.view(slot).pending_schema;
        if prior.is_some_and(|pending| pending.txid != txid) {
            return Err(self.catalog_ddl_wait_error(
                txid,
                prior.expect("checked Some").txid,
                self.view(slot).name.as_str(),
            ));
        }
        let (old_schema, old_name) = {
            let view = &self.view(slot);
            (view.schema_for(txid), view.name_for(txid))
        };
        self.view_rule_catalog().views[slot].pending_schema =
            Some(PendingObjectSchema { txid, schema });
        let visible_schema = self.view(slot).schema_for(txid);
        let name = self.view(slot).name_for(txid);
        self.stage_object_comment_identity(
            CommentClass::Relation,
            old_schema,
            old_name,
            visible_schema,
            name,
            txid,
        );
        self.stage_object_comment_identity(
            CommentClass::Type,
            old_schema,
            old_name,
            visible_schema,
            name,
            txid,
        );
        Ok(prior)
    }

    pub(crate) fn commit_view_schema(&mut self, slot: usize, txid: u32) {
        let Some(pending) = self
            .view(slot)
            .pending_schema
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        let old_schema = self.view(slot).schema;
        let name = self.view(slot).name;
        {
            let mut catalog = self.view_rule_catalog();
            catalog.views[slot].schema = pending.schema;
            catalog.views[slot].pending_schema = None;
        }
        self.commit_object_comment_identity(CommentClass::Relation, old_schema, name, txid);
        self.commit_object_comment_identity(CommentClass::Type, old_schema, name, txid);
    }

    pub(crate) fn rollback_view_schema(&mut self, slot: usize, prior: Option<PendingObjectSchema>) {
        let txid = self.view(slot).pending_schema.map(|pending| pending.txid);
        let (old_schema, old_name) = txid.map_or((SqlName::EMPTY, SqlName::EMPTY), |txid| {
            let view = &self.view(slot);
            (view.schema_for(txid), view.name_for(txid))
        });
        self.view_rule_catalog().views[slot].pending_schema = prior;
        if let Some(txid) = txid {
            let (visible_schema, name) = {
                let view = &self.view(slot);
                (view.schema_for(txid), view.name_for(txid))
            };
            self.stage_object_comment_identity(
                CommentClass::Relation,
                old_schema,
                old_name,
                visible_schema,
                name,
                txid,
            );
            self.stage_object_comment_identity(
                CommentClass::Type,
                old_schema,
                old_name,
                visible_schema,
                name,
                txid,
            );
        }
    }

    pub(crate) fn stage_view_rename(
        &mut self,
        slot: usize,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingViewName>, SqlError> {
        let prior = self.view(slot).pending_name;
        if prior.is_some_and(|pending| pending.txid != txid) {
            return Err(self.catalog_ddl_wait_error(
                txid,
                prior.expect("checked Some").txid,
                self.view(slot).name.as_str(),
            ));
        }
        let (old_schema, old_name) = {
            let view = &self.view(slot);
            (view.schema_for(txid), view.name_for(txid))
        };
        self.view_rule_catalog().views[slot].pending_name = Some(PendingViewName { txid, name });
        let new_schema = self.view(slot).schema_for(txid);
        let new_name = self.view(slot).name_for(txid);
        self.stage_object_comment_identity(
            CommentClass::Relation,
            old_schema,
            old_name,
            new_schema,
            new_name,
            txid,
        );
        self.stage_object_comment_identity(
            CommentClass::Type,
            old_schema,
            old_name,
            new_schema,
            new_name,
            txid,
        );
        Ok(prior)
    }

    pub(crate) fn commit_view_rename(&mut self, slot: usize, txid: u32) {
        let Some(pending) = self
            .view(slot)
            .pending_name
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        let old_schema = self.view(slot).schema;
        let old_name = self.view(slot).name;
        {
            let mut catalog = self.view_rule_catalog();
            catalog.views[slot].name = pending.name;
            catalog.views[slot].pending_name = None;
        }
        self.commit_object_comment_identity(CommentClass::Relation, old_schema, old_name, txid);
        self.commit_object_comment_identity(CommentClass::Type, old_schema, old_name, txid);
    }

    pub(crate) fn rollback_view_rename(&mut self, slot: usize, prior: Option<PendingViewName>) {
        let txid = self.view(slot).pending_name.map(|pending| pending.txid);
        let (old_schema, old_name) = txid.map_or((SqlName::EMPTY, SqlName::EMPTY), |txid| {
            let view = &self.view(slot);
            (view.schema_for(txid), view.name_for(txid))
        });
        self.view_rule_catalog().views[slot].pending_name = prior;
        if let Some(txid) = txid {
            let view = &self.view(slot);
            let new_schema = view.schema_for(txid);
            let new_name = view.name_for(txid);
            self.stage_object_comment_identity(
                CommentClass::Relation,
                old_schema,
                old_name,
                new_schema,
                new_name,
                txid,
            );
            self.stage_object_comment_identity(
                CommentClass::Type,
                old_schema,
                old_name,
                new_schema,
                new_name,
                txid,
            );
        }
    }

    pub(crate) fn stage_view_options(
        &mut self,
        slot: usize,
        options: ViewOptions,
        txid: u32,
    ) -> Result<Option<PendingViewOptions>, SqlError> {
        let prior = self.view(slot).pending_options;
        if prior.is_some_and(|pending| pending.txid != txid) {
            return Err(self.catalog_ddl_wait_error(
                txid,
                prior.expect("checked Some").txid,
                self.view(slot).name.as_str(),
            ));
        }
        self.view_rule_catalog().views[slot].pending_options =
            Some(PendingViewOptions { txid, options });
        Ok(prior)
    }

    pub(crate) fn commit_view_options(&mut self, slot: usize, txid: u32) {
        let Some(pending) = self
            .view(slot)
            .pending_options
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        {
            let mut catalog = self.view_rule_catalog();
            catalog.views[slot].options = pending.options;
            catalog.views[slot].pending_options = None;
        }
    }

    pub(crate) fn rollback_view_options(&mut self, slot: usize, prior: Option<PendingViewOptions>) {
        self.view_rule_catalog().views[slot].pending_options = prior;
    }

    pub(crate) fn stage_view_columns(
        &mut self,
        slot: usize,
        columns: ViewColumns,
        txid: u32,
    ) -> Result<Option<PendingViewColumns>, SqlError> {
        let prior = self.view(slot).pending_columns;
        if prior.is_some_and(|pending| pending.txid != txid) {
            return Err(self.catalog_ddl_wait_error(
                txid,
                prior.expect("checked Some").txid,
                self.view(slot).name.as_str(),
            ));
        }
        self.view_rule_catalog().views[slot].pending_columns =
            Some(PendingViewColumns { txid, columns });
        Ok(prior)
    }

    pub(crate) fn commit_view_columns(&mut self, slot: usize, txid: u32) {
        let Some(pending) = self
            .view(slot)
            .pending_columns
            .filter(|pending| pending.txid == txid)
        else {
            return;
        };
        {
            let mut catalog = self.view_rule_catalog();
            catalog.views[slot].columns = pending.columns;
            catalog.views[slot].pending_columns = None;
        }
    }

    pub(crate) fn rollback_view_columns(&mut self, slot: usize, prior: Option<PendingViewColumns>) {
        self.view_rule_catalog().views[slot].pending_columns = prior;
    }

    /// Promotes an uncommitted DROP VIEW into the committed catalog.
    pub fn commit_view_drop(&mut self, slot: usize) {
        let database = self.view(slot).database;
        let (schema, name) = (self.view(slot).schema, self.view(slot).name);
        // CREATE OR REPLACE installs the replacement before retiring this
        // slot. Comments belong to the logical same-named object and survive;
        // an ordinary DROP has no replacement and removes them.
        let replaced = self
            .view_rule_catalog()
            .views
            .iter()
            .enumerate()
            .any(|(other, view)| {
                other != slot
                    && view.database == database
                    && view.ddl_state == CatalogDdlState::Present
                    && view.schema == schema
                    && view.name == name
            });
        if !replaced {
            self.drop_object_comments(CommentClass::Relation, schema.as_str(), name.as_str());
            self.drop_object_comments(CommentClass::Type, schema.as_str(), name.as_str());
        }
        for rule_slot in 0..self.rule_count() {
            if self.rule(rule_slot).database == database
                && self.rule(rule_slot).definition.target == RuleTarget::View(slot as u16)
                && matches!(
                    self.rule(rule_slot).ddl_state,
                    CatalogDdlState::PendingDrop { .. }
                )
            {
                self.clear_rule_comments(self.rule(rule_slot).definition);
            }
        }
        self.commit_triggers_for_view(slot);
        self.clear_extension_dependencies_for_object(AccessObject {
            class: AccessClass::View,
            slot: slot as u16,
        });
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::View,
            slot: slot as u16,
        });
        let mut catalog = self.view_rule_catalog();
        let _ = catalog.views[slot].ddl_state.commit_drop();
        for rule in 0..catalog.rules.len() {
            if catalog.rules[rule].database == database
                && catalog.rules[rule].definition.target == RuleTarget::View(slot as u16)
                && matches!(
                    catalog.rules[rule].ddl_state,
                    CatalogDdlState::PendingDrop { .. }
                )
            {
                self.clear_rule_slot_in(&mut catalog, rule);
            }
        }
        catalog.views[slot] = ViewDef::EMPTY;
    }

    /// Discards an uncommitted CREATE VIEW (rollback): the slot is freed.
    pub fn rollback_view_create(&self, slot: usize) {
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::View,
            slot: slot as u16,
        });
        let mut catalog = self.view_rule_catalog();
        let _ = catalog.views[slot].ddl_state.rollback_create();
        let rule = usize::from(catalog.views[slot].return_rule);
        let _ = catalog.rules[rule].ddl_state.rollback_create();
        self.clear_rule_slot_in(&mut catalog, rule);
        catalog.views[slot] = ViewDef::EMPTY;
    }

    /// Discards an uncommitted DROP VIEW (rollback). A committed view becomes
    /// visible again; a same-transaction pending-create (create + drop, then
    /// the drop rolled back to a savepoint) reverts to pending-create.
    pub fn rollback_view_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.view_rule_catalog();
        for rule in catalog.rules.iter_mut().filter(|rule| {
            rule.database == current_database()
                && rule.definition.target == RuleTarget::View(slot as u16)
                && matches!(rule.ddl_state, CatalogDdlState::PendingDrop { txid: owner } if owner == txid)
        }) {
            rule.ddl_state = rule.ddl_state.rollback_drop(txid);
        }
        let view = &mut catalog.views[slot];
        view.ddl_state = view.ddl_state.rollback_drop(txid);
    }

    pub(crate) fn routine_count(&self) -> usize {
        self.routines
            .lock()
            .expect("routine catalog lock poisoned")
            .len()
    }

    fn routine_entries(&self) -> RoutineIter<'_> {
        RoutineIter {
            catalog: &self.routines,
            next_slot: 0,
            lookup: None,
        }
    }

    fn routine_candidates<'a>(
        &'a self,
        schema: &'a str,
        name: &'a str,
        transaction: u32,
        kind: RoutineCallKind,
    ) -> RoutineIter<'a> {
        RoutineIter {
            catalog: &self.routines,
            next_slot: 0,
            lookup: Some(RoutineLookup {
                database: current_database(),
                schema,
                name,
                transaction,
                kind,
            }),
        }
    }

    pub(crate) fn routine_slot_visible_to(&self, slot: usize, txid: u32) -> bool {
        let routine = self.routine(slot);
        routine.database == current_database() && routine.visible_to(txid)
    }

    pub(crate) fn routine(&self, slot: usize) -> RoutineDef {
        self.routine_at(slot).expect("routine slot is in range")
    }

    fn routine_at(&self, slot: usize) -> Option<RoutineDef> {
        self.routines
            .lock()
            .expect("routine catalog lock poisoned")
            .get(slot)
            .copied()
    }

    /// Returns the routine definition visible to `txid`.  Replacement keeps
    /// the catalog slot and object identifier stable while its new definition
    /// is private until commit.
    pub(crate) fn routine_for(&self, slot: usize, txid: u32) -> RoutineDef {
        self.routine(slot).definition_for(txid)
    }

    pub(crate) fn routine_slot_by_oid(&self, oid: i32, txid: u32) -> Option<usize> {
        self.routine_entries().find_map(|(slot, routine)| {
            (routine.database == current_database()
                && routine.visible_to(txid)
                && routine_oid(&routine) == oid)
                .then_some(slot)
        })
    }

    /// Resolves a scalar call from its evaluated values and their SQL type
    /// identities. Domains deliberately use their base representation at
    /// runtime, so their OID belongs at this boundary rather than being
    /// inferred from an erased datum.
    pub(crate) fn routine_slot_for_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        self.routine_slot_for_call_syntax_oids(name, argument_type_oids, false, txid)
    }

    pub(crate) fn routine_slot_for_call_syntax_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        explicit_variadic: bool,
        txid: u32,
    ) -> Option<usize> {
        if argument_type_oids.len() > MAX_ROUTINE_ARGUMENTS {
            return None;
        }
        if !explicit_variadic
            && let Some(slot) = self.routine_slot_on_path_oids(
                name,
                argument_type_oids,
                txid,
                RoutineCallKind::Scalar,
            )
        {
            return Some(slot);
        }
        self.variadic_routine_slot_on_path_oids(
            name,
            argument_type_oids,
            explicit_variadic,
            txid,
            RoutineCallKind::Scalar,
        )
    }

    pub(crate) fn routine_slot_for_function_call_syntax_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        explicit_variadic: bool,
        txid: u32,
    ) -> Option<usize> {
        if !explicit_variadic
            && let Some(slot) =
                self.routine_slot_for_function_call_oids(name, argument_type_oids, txid)
        {
            return Some(slot);
        }
        self.routine_slot_for_call_syntax_oids(name, argument_type_oids, explicit_variadic, txid)
            .or_else(|| {
                self.variadic_routine_slot_on_path_oids(
                    name,
                    argument_type_oids,
                    explicit_variadic,
                    txid,
                    RoutineCallKind::Set,
                )
            })
    }

    fn variadic_routine_slot_on_path_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        explicit_variadic: bool,
        txid: u32,
        kind: RoutineCallKind,
    ) -> Option<usize> {
        let resolve = |schema: &str, routine_name: &str| {
            let mut candidates = self
                .routine_candidates(schema, routine_name, txid, kind)
                .filter_map(|(slot, routine)| {
                    let definition = routine.definition_for(txid);
                    if routine.database != current_database()
                        || !routine.visible_to(txid)
                        || !kind.accepts(definition.kind)
                        || definition.schema_for(txid).as_str() != schema
                        || definition.name_for(txid).as_str() != routine_name
                    {
                        return None;
                    }
                    let variadic_index = definition.arguments().len().checked_sub(1)?;
                    let variadic_parameter = definition.parameter_for_input(variadic_index)?;
                    let RoutineParameterMode::Variadic { .. } = variadic_parameter.mode else {
                        return None;
                    };
                    let ColType::Array(element) = variadic_parameter.ctype else {
                        return None;
                    };
                    let fixed = &definition.arguments()[..variadic_index];
                    if argument_type_oids.len() < fixed.len() + usize::from(!explicit_variadic)
                        || explicit_variadic && argument_type_oids.len() != fixed.len() + 1
                        || !fixed.iter().zip(argument_type_oids).all(|(argument, oid)| {
                            self.routine_argument_oid(argument, txid)
                                .is_some_and(|expected| {
                                    self.routine_implicit_cast(*oid, expected, txid)
                                })
                        })
                    {
                        return None;
                    }
                    let expected = if explicit_variadic {
                        self.routine_argument_oid(&definition.arguments()[variadic_index], txid)?
                    } else {
                        element.element_oid()
                    };
                    argument_type_oids[variadic_index..]
                        .iter()
                        .all(|oid| self.routine_implicit_cast(*oid, expected, txid))
                        .then_some(slot)
                });
            let first = candidates.next();
            if first.is_some() && candidates.next().is_none() {
                first
            } else {
                None
            }
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            resolve(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    pub(crate) fn routine_slot_for_named_call_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        if argument_type_oids.len() > MAX_ROUTINE_ARGUMENTS
            || argument_names.len() != argument_type_oids.len()
        {
            return None;
        }
        let resolve = |schema: &str, routine_name: &str| {
            self.routine_slot_in_named_oids(
                schema,
                routine_name,
                argument_names,
                argument_type_oids,
                txid,
                RoutineCallKind::Scalar,
            )
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            resolve(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    pub(crate) fn routine_slot_for_named_function_call_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        if let Some(slot) =
            self.routine_slot_for_named_call_oids(name, argument_names, argument_type_oids, txid)
        {
            return Some(slot);
        }
        let resolve = |schema: &str, routine_name: &str| {
            self.routine_slot_in_named_oids(
                schema,
                routine_name,
                argument_names,
                argument_type_oids,
                txid,
                RoutineCallKind::Set,
            )
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            resolve(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    pub(crate) fn routine_for_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<RoutineDef> {
        self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Scalar)
            .and_then(|slot| self.routine_for_bound_call(slot, argument_type_oids, txid))
    }

    pub(crate) fn aggregate_for_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<(usize, RoutineDef, AggregateRoutine)> {
        let slot = self.routine_slot_on_path_oids(
            name,
            argument_type_oids,
            txid,
            RoutineCallKind::Aggregate,
        )?;
        let routine = self.routine_for_bound_call(slot, argument_type_oids, txid)?;
        let RoutineKind::Aggregate(aggregate) = routine.kind else {
            unreachable!("aggregate call resolution returned a non-aggregate")
        };
        Some((slot, routine, aggregate))
    }

    pub(crate) fn has_aggregate_candidate(&self, name: &str, arity: usize, txid: u32) -> bool {
        self.has_routine_candidate(name, arity, txid, |kind, _| {
            matches!(kind, RoutineKind::Aggregate(_))
        })
    }

    pub(crate) fn function_for_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<RoutineDef> {
        self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Scalar)
            .or_else(|| {
                self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Set)
            })
            .and_then(|slot| self.routine_for_bound_call(slot, argument_type_oids, txid))
    }

    pub(crate) fn function_for_call_syntax_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        explicit_variadic: bool,
        txid: u32,
    ) -> Option<RoutineDef> {
        if !explicit_variadic
            && let Some(routine) = self.function_for_call_oids(name, argument_type_oids, txid)
        {
            return Some(routine);
        }
        let slot = self
            .variadic_routine_slot_on_path_oids(
                name,
                argument_type_oids,
                explicit_variadic,
                txid,
                RoutineCallKind::Scalar,
            )
            .or_else(|| {
                self.variadic_routine_slot_on_path_oids(
                    name,
                    argument_type_oids,
                    explicit_variadic,
                    txid,
                    RoutineCallKind::Set,
                )
            })?;
        let routine = self.routine_for(slot, txid);
        let mut declared_oids = [crate::sql::types::oid::UNKNOWN; MAX_ROUTINE_ARGUMENTS];
        for (index, argument) in routine.arguments().iter().enumerate() {
            declared_oids[index] = self.routine_argument_oid(argument, txid)?;
        }
        self.routine_for_bound_call(slot, &declared_oids[..routine.argument_count], txid)
    }

    pub(crate) fn function_for_named_call_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<RoutineDef> {
        let slot = self.routine_slot_for_named_function_call_oids(
            name,
            argument_names,
            argument_type_oids,
            txid,
        )?;
        let routine = self.routine_for(slot, txid);
        let mapping =
            routine.call_input_mapping(argument_names, argument_type_oids.len(), false)?;
        let mut completed = [crate::sql::types::oid::UNKNOWN; MAX_ROUTINE_ARGUMENTS];
        for (input_index, argument) in routine.arguments().iter().enumerate() {
            completed[input_index] = self.routine_argument_oid(argument, txid)?;
        }
        for (call_index, oid) in argument_type_oids.iter().enumerate() {
            completed[usize::from(mapping[call_index])] = *oid;
        }
        self.routine_for_bound_call(slot, &completed[..routine.argument_count], txid)
    }

    /// Resolves the declared input OIDs for a function call that still has
    /// untyped protocol parameters. Only a unique overload may supply the
    /// contract; an unknown argument is never guessed from one of several
    /// candidates.
    pub(crate) fn function_call_parameter_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        explicit_variadic: bool,
        actual_oids: &[i32],
        txid: u32,
    ) -> Option<[i32; MAX_ROUTINE_ARGUMENTS]> {
        if actual_oids.len() > MAX_ROUTINE_ARGUMENTS
            || (!argument_names.is_empty() && argument_names.len() != actual_oids.len())
        {
            return None;
        }
        let resolve = |schema: &str, routine_name: &str| {
            let mut found = None;
            for (slot, stored) in self.routine_entries() {
                let routine = stored.definition_for(txid);
                if stored.database != current_database()
                    || !stored.visible_to(txid)
                    || !matches!(
                        routine.kind,
                        RoutineKind::Function { .. }
                            | RoutineKind::SetFunction { .. }
                            | RoutineKind::RecordFunction { .. }
                            | RoutineKind::TableFunction
                    )
                    || routine.schema_for(txid).as_str() != schema
                    || routine.name_for(txid).as_str() != routine_name
                {
                    continue;
                }
                let Some(mapping) = routine.call_input_mapping(
                    argument_names,
                    actual_oids.len(),
                    explicit_variadic,
                ) else {
                    continue;
                };
                let variadic_input =
                    routine
                        .arguments()
                        .iter()
                        .enumerate()
                        .find_map(|(input_index, _)| {
                            matches!(
                                routine.parameter_for_input(input_index)?.mode,
                                RoutineParameterMode::Variadic { .. }
                            )
                            .then_some(input_index)
                        });
                let mut expected = [crate::sql::types::oid::UNKNOWN; MAX_ROUTINE_ARGUMENTS];
                let mut matches = true;
                for (call_index, actual_oid) in actual_oids.iter().copied().enumerate() {
                    let input_index = usize::from(mapping[call_index]);
                    let argument = routine.arguments()[input_index];
                    let expected_oid = if !explicit_variadic && variadic_input == Some(input_index)
                    {
                        match argument.ctype {
                            ColType::Array(element) => Some(element.element_oid()),
                            _ => None,
                        }
                    } else {
                        self.routine_argument_oid(&argument, txid)
                    };
                    let Some(expected_oid) = expected_oid else {
                        matches = false;
                        break;
                    };
                    expected[call_index] = if argument.polymorphic_type().is_some() {
                        actual_oid
                    } else {
                        expected_oid
                    };
                    if actual_oid != crate::sql::types::oid::UNKNOWN
                        && argument.polymorphic_type().is_none()
                        && !self.routine_implicit_cast(actual_oid, expected_oid, txid)
                    {
                        matches = false;
                        break;
                    }
                }
                if !matches {
                    continue;
                }
                if found.replace((slot, expected)).is_some() {
                    return None;
                }
            }
            found.map(|(_, expected)| expected)
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        for entry in self.path().entries() {
            let PathEntry::Schema(schema_slot) = entry else {
                continue;
            };
            let schema = self.schema_def(*schema_slot as usize).name;
            if let Some(expected) = resolve(schema.as_str(), name) {
                return Some(expected);
            }
        }
        None
    }

    pub(crate) fn routine_for_bound_call(
        &self,
        slot: usize,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<RoutineDef> {
        let mut routine = self.routine_for(slot, txid);
        if routine.accepts_input_arity(argument_type_oids.len())
            && routine.arguments()[..argument_type_oids.len()]
                .iter()
                .zip(argument_type_oids)
                .all(|(argument, oid)| {
                    self.routine_argument_oid(argument, txid)
                        .is_some_and(|expected| self.routine_implicit_cast(*oid, expected, txid))
                })
        {
            return Some(routine);
        }
        let binding = self.polymorphic_call_binding(
            &routine.arguments()[..argument_type_oids.len()],
            argument_type_oids,
            txid,
        )?;
        for argument in routine.arguments.iter_mut().take(routine.argument_count) {
            let Some(kind) = argument.polymorphic_type() else {
                continue;
            };
            let concrete = self.routine_result_for_oid(binding.concrete_oid(kind)?, txid)?;
            argument.ctype = concrete.ctype;
            argument.user_type = concrete.user_type;
        }
        for parameter in routine.parameters.iter_mut().take(routine.parameter_count) {
            let Some(kind) = polymorphic_type(parameter.ctype, parameter.user_type) else {
                continue;
            };
            let concrete = self.routine_result_for_oid(binding.concrete_oid(kind)?, txid)?;
            parameter.ctype = concrete.ctype;
            parameter.user_type = concrete.user_type;
        }
        for column in routine
            .result_columns
            .iter_mut()
            .take(routine.result_column_count)
        {
            let Some(kind) = column.polymorphic_type() else {
                continue;
            };
            let concrete = self.routine_result_for_oid(binding.concrete_oid(kind)?, txid)?;
            column.ctype = concrete.ctype;
            column.user_type = concrete.user_type;
        }
        let resolve = |result: &mut RoutineResult| -> Option<()> {
            let Some(kind) = result.polymorphic_type() else {
                return Some(());
            };
            *result = self.routine_result_for_oid(binding.concrete_oid(kind)?, txid)?;
            Some(())
        };
        match &mut routine.kind {
            RoutineKind::Function { result } | RoutineKind::SetFunction { result } => {
                resolve(result)?;
            }
            RoutineKind::Aggregate(aggregate) => {
                resolve(&mut aggregate.state_type)?;
                resolve(&mut aggregate.result_type)?;
                if let Some(moving) = &mut aggregate.moving {
                    resolve(&mut moving.state_type)?;
                }
            }
            RoutineKind::RecordFunction { .. }
            | RoutineKind::TableFunction
            | RoutineKind::Trigger
            | RoutineKind::EventTrigger
            | RoutineKind::Procedure => {}
        }
        Some(routine)
    }

    pub(crate) fn routine_slot_for_function_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Scalar)
            .or_else(|| {
                self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Set)
            })
    }

    pub(crate) fn has_set_routine_candidate(&self, name: &str, arity: usize, txid: u32) -> bool {
        self.has_routine_candidate(name, arity, txid, |kind, _| kind.is_set_returning())
    }

    pub(crate) fn has_function_routine_candidate(
        &self,
        name: &str,
        arity: usize,
        txid: u32,
    ) -> bool {
        self.has_routine_candidate(name, arity, txid, |kind, _| {
            matches!(
                kind,
                RoutineKind::Function { .. }
                    | RoutineKind::SetFunction { .. }
                    | RoutineKind::RecordFunction { .. }
                    | RoutineKind::TableFunction
            )
        })
    }

    pub(crate) fn has_volatile_function_routine_candidate(
        &self,
        name: &str,
        arity: usize,
        txid: u32,
    ) -> bool {
        self.has_routine_candidate(name, arity, txid, |kind, attributes| {
            matches!(
                kind,
                RoutineKind::Function { .. }
                    | RoutineKind::SetFunction { .. }
                    | RoutineKind::RecordFunction { .. }
                    | RoutineKind::TableFunction
            ) && attributes.volatility == RoutineVolatility::Volatile
        })
    }

    fn has_routine_candidate(
        &self,
        name: &str,
        arity: usize,
        txid: u32,
        accepts: impl Fn(RoutineKind, RoutineAttributes) -> bool,
    ) -> bool {
        let matches = |schema: &str, routine_name: &str| {
            self.routine_entries().any(|(_, routine)| {
                routine.database == current_database()
                    && routine.visible_to(txid)
                    && accepts(routine.kind_for(txid), routine.attributes_for(txid))
                    && routine.accepts_input_arity_for(arity, txid)
                    && routine.schema_for(txid).as_str() == schema
                    && routine.name_for(txid).as_str() == routine_name
            })
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return matches(schema, routine_name);
        }
        self.path().entries().iter().any(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return false;
            };
            matches(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    /// Resolves a set-returning call from declared argument identities.  This
    /// is distinct from the datum representation because a domain's runtime
    /// representation is its base type.
    pub(crate) fn routine_slot_for_table_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        if argument_type_oids.len() > MAX_ROUTINE_ARGUMENTS {
            return None;
        }
        self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Set)
    }

    pub(crate) fn routine_function_result_oid(
        &self,
        routine: &RoutineDef,
        txid: u32,
    ) -> Option<i32> {
        let result = match routine.kind {
            RoutineKind::Function { result } | RoutineKind::SetFunction { result } => result,
            RoutineKind::TableFunction if routine.result_column_count == 1 => {
                let column = routine.result_columns[0];
                return self.routine_type_oid(column.ctype, column.user_type, txid);
            }
            RoutineKind::RecordFunction { .. } | RoutineKind::TableFunction => {
                return Some(crate::sql::types::oid::RECORD);
            }
            RoutineKind::Trigger
            | RoutineKind::EventTrigger
            | RoutineKind::Procedure
            | RoutineKind::Aggregate(_) => {
                return None;
            }
        };
        self.routine_type_oid(result.ctype, result.user_type, txid)
    }

    pub(crate) fn procedure_slot_for_call_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        self.routine_slot_on_path_oids(name, argument_type_oids, txid, RoutineCallKind::Procedure)
    }

    pub(crate) fn procedure_slot_for_call_syntax_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        explicit_variadic: bool,
        txid: u32,
    ) -> Option<usize> {
        if !explicit_variadic
            && let Some(slot) = self.procedure_slot_for_call_oids(name, argument_type_oids, txid)
        {
            return Some(slot);
        }
        self.variadic_routine_slot_on_path_oids(
            name,
            argument_type_oids,
            explicit_variadic,
            txid,
            RoutineCallKind::Procedure,
        )
    }

    pub(crate) fn procedure_slot_for_named_call_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<usize> {
        let resolve = |schema: &str, routine_name: &str| {
            self.routine_slot_in_named_oids(
                schema,
                routine_name,
                argument_names,
                argument_type_oids,
                txid,
                RoutineCallKind::Procedure,
            )
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            resolve(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    pub(crate) fn procedure_slot_for_call_shape(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        argument_count: usize,
        txid: u32,
    ) -> Option<usize> {
        let resolve = |schema: &str, routine_name: &str| {
            let mut candidates = self.routine_entries().filter_map(|(slot, routine)| {
                let definition = routine.definition_for(txid);
                (routine.database == current_database()
                    && routine.visible_to(txid)
                    && definition.schema_for(txid).as_str() == schema
                    && definition.name_for(txid).as_str() == routine_name
                    && definition
                        .procedure_call_mapping(argument_names, argument_count)
                        .is_some())
                .then_some(slot)
            });
            let first = candidates.next();
            if first.is_some() && candidates.next().is_none() {
                first
            } else {
                None
            }
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            resolve(self.schema_def(*slot as usize).name.as_str(), name)
        })
    }

    /// Resolves protocol parameter OIDs for a CALL before its Bind values
    /// exist. OUT placeholders and input arguments both derive their type from
    /// the unique procedure declaration.
    pub(crate) fn procedure_call_parameter_oids(
        &self,
        name: &str,
        argument_names: &[Option<&str>],
        explicit_variadic: bool,
        actual_oids: &[i32],
        txid: u32,
    ) -> Option<[i32; MAX_ROUTINE_ARGUMENTS]> {
        if actual_oids.len() > MAX_ROUTINE_ARGUMENTS
            || (!argument_names.is_empty() && argument_names.len() != actual_oids.len())
        {
            return None;
        }
        let resolve = |schema: &str, routine_name: &str| {
            let mut found = None;
            for (_, stored) in self.routine_entries() {
                let routine = stored.definition_for(txid);
                if stored.database != current_database()
                    || !stored.visible_to(txid)
                    || !matches!(routine.kind, RoutineKind::Procedure)
                    || routine.schema_for(txid).as_str() != schema
                    || routine.name_for(txid).as_str() != routine_name
                {
                    continue;
                }
                let output_call = routine
                    .parameters()
                    .iter()
                    .any(|parameter| parameter.mode.is_output());
                let input_mapping = if output_call {
                    let Some(mapping) =
                        routine.procedure_call_mapping(argument_names, actual_oids.len())
                    else {
                        continue;
                    };
                    mapping
                } else {
                    let Some(mapping) = routine.call_input_mapping(
                        argument_names,
                        actual_oids.len(),
                        explicit_variadic,
                    ) else {
                        continue;
                    };
                    mapping
                };
                let variadic_input =
                    routine
                        .arguments()
                        .iter()
                        .enumerate()
                        .find_map(|(input_index, _)| {
                            matches!(
                                routine.parameter_for_input(input_index)?.mode,
                                RoutineParameterMode::Variadic { .. }
                            )
                            .then_some(input_index)
                        });
                let mut expected = [crate::sql::types::oid::UNKNOWN; MAX_ROUTINE_ARGUMENTS];
                let mut matches = true;
                for (call_index, actual_oid) in actual_oids.iter().copied().enumerate() {
                    let (polymorphic, expected_oid) =
                        if output_call && input_mapping[call_index] == u8::MAX {
                            let parameter_index =
                                match argument_names.get(call_index).copied().flatten() {
                                    Some(name) => {
                                        routine.parameters().iter().position(|parameter| {
                                            parameter.name.as_str().eq_ignore_ascii_case(name)
                                        })?
                                    }
                                    None => call_index,
                                };
                            let parameter = *routine.parameters().get(parameter_index)?;
                            let expected_oid =
                                self.routine_type_oid(parameter.ctype, parameter.user_type, txid)?;
                            (
                                polymorphic_type(parameter.ctype, parameter.user_type),
                                expected_oid,
                            )
                        } else {
                            let input_index = usize::from(input_mapping[call_index]);
                            let argument = routine.arguments()[input_index];
                            let expected_oid =
                                if !explicit_variadic && variadic_input == Some(input_index) {
                                    match argument.ctype {
                                        ColType::Array(element) => element.element_oid(),
                                        _ => return None,
                                    }
                                } else {
                                    self.routine_argument_oid(&argument, txid)?
                                };
                            (argument.polymorphic_type(), expected_oid)
                        };
                    expected[call_index] = if polymorphic.is_some() {
                        actual_oid
                    } else {
                        expected_oid
                    };
                    if actual_oid != crate::sql::types::oid::UNKNOWN
                        && polymorphic.is_none()
                        && !self.routine_implicit_cast(actual_oid, expected_oid, txid)
                    {
                        matches = false;
                        break;
                    }
                }
                if !matches {
                    continue;
                }
                if found.replace(expected).is_some() {
                    return None;
                }
            }
            found
        };
        if let Some((schema, routine_name)) = name.split_once('.') {
            return resolve(schema, routine_name);
        }
        for entry in self.path().entries() {
            let PathEntry::Schema(schema_slot) = entry else {
                continue;
            };
            let schema = self.schema_def(*schema_slot as usize).name;
            if let Some(expected) = resolve(schema.as_str(), name) {
                return Some(expected);
            }
        }
        None
    }

    pub(crate) fn trigger_slot_for_call(&self, name: &str, txid: u32) -> Option<usize> {
        self.routine_slot_on_path(name, &[], txid, RoutineCallKind::Trigger)
    }

    pub(crate) fn event_trigger_slot_for_call(&self, name: &str, txid: u32) -> Option<usize> {
        self.routine_slot_on_path(name, &[], txid, RoutineCallKind::EventTrigger)
    }

    fn routine_slot_on_path(
        &self,
        name: &str,
        argument_types: &[ColType],
        txid: u32,
        kind: RoutineCallKind,
    ) -> Option<usize> {
        if let Some((schema, name)) = name.split_once('.') {
            return self.routine_slot_in(schema, name, argument_types, txid, kind);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            self.routine_slot_in(
                self.schema_def(*slot as usize).name.as_str(),
                name,
                argument_types,
                txid,
                kind,
            )
        })
    }

    fn routine_slot_on_path_oids(
        &self,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
        kind: RoutineCallKind,
    ) -> Option<usize> {
        if let Some((schema, name)) = name.split_once('.') {
            return self.routine_slot_in_oids(schema, name, argument_type_oids, txid, kind);
        }
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(slot) = entry else {
                return None;
            };
            self.routine_slot_in_oids(
                self.schema_def(*slot as usize).name.as_str(),
                name,
                argument_type_oids,
                txid,
                kind,
            )
        })
    }

    fn routine_slot_in(
        &self,
        schema: &str,
        name: &str,
        argument_types: &[ColType],
        txid: u32,
        kind: RoutineCallKind,
    ) -> Option<usize> {
        self.routine_candidates(schema, name, txid, kind)
            .find_map(|(slot, routine)| {
                let definition = routine.definition_for(txid);
                (routine.database == current_database()
                    && routine.visible_to(txid)
                    && kind.accepts(definition.kind)
                    && definition.schema_for(txid).as_str() == schema
                    && definition.name_for(txid).as_str() == name
                    && definition.accepts_input_arity(argument_types.len())
                    && definition.arguments()[..argument_types.len()]
                        .iter()
                        .zip(argument_types)
                        .all(|(parameter, value)| parameter.ctype == *value))
                .then_some(slot)
            })
    }

    fn routine_slot_in_oids(
        &self,
        schema: &str,
        name: &str,
        argument_type_oids: &[i32],
        txid: u32,
        kind: RoutineCallKind,
    ) -> Option<usize> {
        let exact =
            self.routine_candidates(schema, name, txid, kind)
                .find_map(|(slot, routine)| {
                    let definition = routine.definition_for(txid);
                    (routine.database == current_database()
                        && routine.visible_to(txid)
                        && kind.accepts(definition.kind)
                        && definition.schema_for(txid).as_str() == schema
                        && definition.name_for(txid).as_str() == name
                        && definition.argument_count == argument_type_oids.len()
                        && definition.arguments().iter().zip(argument_type_oids).all(
                            |(argument, oid)| {
                                self.routine_argument_oid(argument, txid) == Some(*oid)
                            },
                        ))
                    .then_some(slot)
                });
        if exact.is_some() {
            return exact;
        }
        let concrete = self
            .routine_candidates(schema, name, txid, kind)
            .filter_map(|(slot, routine)| {
                let definition = routine.definition_for(txid);
                (routine.database == current_database()
                    && routine.visible_to(txid)
                    && kind.accepts(definition.kind)
                    && definition.schema_for(txid).as_str() == schema
                    && definition.name_for(txid).as_str() == name
                    && definition.accepts_input_arity(argument_type_oids.len())
                    && definition.arguments()[..argument_type_oids.len()]
                        .iter()
                        .zip(argument_type_oids)
                        .all(|(argument, oid)| {
                            self.routine_argument_oid(argument, txid)
                                .is_some_and(|expected| {
                                    self.routine_implicit_cast(*oid, expected, txid)
                                })
                        }))
                .then_some(slot)
            });
        let mut concrete = concrete;
        let first = concrete.next();
        if first.is_some() && concrete.next().is_none() {
            return first;
        }
        let polymorphic = self
            .routine_candidates(schema, name, txid, kind)
            .filter_map(|(slot, routine)| {
                let definition = routine.definition_for(txid);
                (routine.database == current_database()
                    && routine.visible_to(txid)
                    && kind.accepts(definition.kind)
                    && definition.schema_for(txid).as_str() == schema
                    && definition.name_for(txid).as_str() == name
                    && definition.accepts_input_arity(argument_type_oids.len())
                    && self
                        .polymorphic_call_binding(
                            &definition.arguments()[..argument_type_oids.len()],
                            argument_type_oids,
                            txid,
                        )
                        .is_some())
                .then_some(slot)
            });
        let mut polymorphic = polymorphic;
        let first = polymorphic.next();
        if first.is_some() && polymorphic.next().is_none() {
            first
        } else {
            None
        }
    }

    fn routine_slot_in_named_oids(
        &self,
        schema: &str,
        name: &str,
        argument_names: &[Option<&str>],
        argument_type_oids: &[i32],
        txid: u32,
        call_kind: RoutineCallKind,
    ) -> Option<usize> {
        let matches = |routine: &RoutineDef, implicit: bool, polymorphic: bool| {
            let definition = routine.definition_for(txid);
            if routine.database != current_database()
                || !routine.visible_to(txid)
                || !call_kind.accepts(definition.kind)
                || definition.schema_for(txid).as_str() != schema
                || definition.name_for(txid).as_str() != name
            {
                return false;
            }
            let Some(mapping) =
                definition.call_input_mapping(argument_names, argument_type_oids.len(), false)
            else {
                return false;
            };
            let mut binding = PolymorphicBinding::EMPTY;
            let mut saw_polymorphic = false;
            for (call_index, actual_oid) in argument_type_oids.iter().enumerate() {
                let argument = definition.arguments[usize::from(mapping[call_index])];
                if let Some(kind) = argument.polymorphic_type() {
                    if !polymorphic || binding.bind(kind, *actual_oid).is_none() {
                        return false;
                    }
                    saw_polymorphic = true;
                } else {
                    let Some(expected) = self.routine_argument_oid(&argument, txid) else {
                        return false;
                    };
                    if *actual_oid != expected
                        && (!implicit || !self.routine_implicit_cast(*actual_oid, expected, txid))
                    {
                        return false;
                    }
                }
            }
            polymorphic == saw_polymorphic
        };
        for (implicit, polymorphic) in [(false, false), (true, false), (true, true)] {
            let mut candidates = self
                .routine_candidates(schema, name, txid, call_kind)
                .filter_map(|(slot, routine)| {
                    matches(&routine, implicit, polymorphic).then_some(slot)
                });
            let first = candidates.next();
            if first.is_some() && candidates.next().is_none() {
                return first;
            }
        }
        None
    }

    fn polymorphic_call_binding(
        &self,
        arguments: &[RoutineArgumentDef],
        argument_type_oids: &[i32],
        txid: u32,
    ) -> Option<PolymorphicBinding> {
        let mut binding = PolymorphicBinding::EMPTY;
        let mut saw_polymorphic = false;
        for (argument, actual_oid) in arguments.iter().zip(argument_type_oids) {
            let Some(polymorphic) = argument.polymorphic_type() else {
                if !self
                    .routine_argument_oid(argument, txid)
                    .is_some_and(|expected| self.routine_implicit_cast(*actual_oid, expected, txid))
                {
                    return None;
                }
                continue;
            };
            saw_polymorphic = true;
            binding.bind(polymorphic, *actual_oid)?;
        }
        saw_polymorphic.then_some(binding)
    }

    fn routine_argument_oid(&self, argument: &RoutineArgumentDef, txid: u32) -> Option<i32> {
        if let Some(polymorphic) = argument.polymorphic_type() {
            return Some(polymorphic.oid());
        }
        self.routine_type_oid(argument.ctype, argument.user_type, txid)
    }

    pub(crate) fn routine_type_oid(
        &self,
        ctype: ColType,
        user_type: Option<UserTypeName>,
        txid: u32,
    ) -> Option<i32> {
        use crate::sql::types::{ArrElem, oid};

        if let Some(polymorphic) = polymorphic_type(ctype, user_type) {
            return Some(polymorphic.oid());
        }

        match ctype {
            ColType::Enum(slot) => return Some(oid::enum_oid(slot)),
            ColType::Composite(slot) => return Some(oid::composite_oid(slot)),
            ColType::Array(ArrElem::Enum(slot)) => return Some(oid::enum_array_oid(slot)),
            ColType::Array(ArrElem::Composite(slot)) => {
                return Some(oid::composite_array_oid(slot));
            }
            ColType::Array(ArrElem::Domain { slot, .. }) => {
                return Some(oid::domain_array_oid(slot));
            }
            _ => {}
        }
        let Some(identity) = user_type else {
            return Some(ctype.oid());
        };
        let array = matches!(ctype, ColType::Array(_));
        self.user_type_identity_oid(identity, array, txid)
    }

    /// Binds the transient representation slot in a persisted routine type to
    /// its durable schema/name identity. WAL and manifests intentionally write
    /// unresolved slots because catalog allocation order is process-local.
    pub(crate) fn bind_routine_result(
        &self,
        mut result: RoutineResult,
        txid: u32,
    ) -> Result<RoutineResult, SqlError> {
        use crate::sql::types::ArrElem;

        let Some(identity) = result.user_type else {
            return Ok(result);
        };
        result.ctype = match result.ctype {
            ColType::Enum(_) => ColType::Enum(
                self.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "persisted type \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        )
                    })? as u16,
            ),
            ColType::Composite(_) => ColType::Composite(
                self.composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "persisted type \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        )
                    })? as u16,
            ),
            ColType::Array(ArrElem::Enum(_)) => ColType::Array(ArrElem::Enum(
                self.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "persisted type \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        )
                    })? as u16,
            )),
            ColType::Array(ArrElem::Composite(_)) => ColType::Array(ArrElem::Composite(
                self.composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "persisted type \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        )
                    })? as u16,
            )),
            ColType::Array(ArrElem::Domain {
                base_code,
                base_user_slot,
                ..
            }) => ColType::Array(ArrElem::Domain {
                slot: self
                    .domain_slot(identity.schema.as_str(), identity.name.as_str(), txid)
                    .ok_or_else(|| {
                        sql_err!(
                            sqlstate::UNDEFINED_OBJECT,
                            "persisted type \"{}.{}\" does not exist",
                            identity.schema.as_str(),
                            identity.name.as_str()
                        )
                    })? as u16,
                base_code,
                base_user_slot,
            }),
            ctype => ctype,
        };
        Ok(result)
    }

    pub(crate) fn routine_result_for_oid(&self, type_oid: i32, txid: u32) -> Option<RoutineResult> {
        use crate::sql::types::{ArrElem, ColType, oid};

        let identity = |schema: SqlName, name: SqlName| Some(UserTypeName { schema, name });
        if (oid::FIRST_DOMAIN..oid::FIRST_DOMAIN + self.domain_count() as i32).contains(&type_oid) {
            let slot = usize::try_from(type_oid - oid::FIRST_DOMAIN).ok()?;
            let domain = self.domain_for(slot, txid);
            return (domain.database == current_database() && domain.visible_to(txid)).then_some(
                RoutineResult {
                    ctype: domain.base,
                    user_type: identity(domain.schema, domain.name),
                },
            );
        }
        if (oid::FIRST_DOMAIN_ARRAY..oid::FIRST_DOMAIN_ARRAY + self.domain_count() as i32)
            .contains(&type_oid)
        {
            let slot = usize::try_from(type_oid - oid::FIRST_DOMAIN_ARRAY).ok()?;
            let domain = self.domain_for(slot, txid);
            return (domain.database == current_database() && domain.visible_to(txid)).then_some(
                RoutineResult {
                    ctype: ColType::Array(ArrElem::domain(slot as u16, domain.base)?),
                    user_type: identity(domain.schema, domain.name),
                },
            );
        }
        if (oid::FIRST_ENUM..oid::FIRST_ENUM + self.enum_count() as i32).contains(&type_oid) {
            let slot = usize::try_from(type_oid - oid::FIRST_ENUM).ok()?;
            let enumeration = self.enum_for(slot, txid);
            return (enumeration.database == current_database() && enumeration.visible_to(txid))
                .then_some(RoutineResult {
                    ctype: ColType::Enum(slot as u16),
                    user_type: identity(enumeration.schema, enumeration.name),
                });
        }
        if (oid::FIRST_ENUM_ARRAY..oid::FIRST_ENUM_ARRAY + self.enum_count() as i32)
            .contains(&type_oid)
        {
            let slot = usize::try_from(type_oid - oid::FIRST_ENUM_ARRAY).ok()?;
            let enumeration = self.enum_for(slot, txid);
            return (enumeration.database == current_database() && enumeration.visible_to(txid))
                .then_some(RoutineResult {
                    ctype: ColType::Array(ArrElem::Enum(slot as u16)),
                    user_type: identity(enumeration.schema, enumeration.name),
                });
        }
        if (oid::FIRST_COMPOSITE..oid::FIRST_COMPOSITE + self.composite_count() as i32)
            .contains(&type_oid)
        {
            let slot = usize::try_from(type_oid - oid::FIRST_COMPOSITE).ok()?;
            let composite = self.composite_for(slot, txid);
            return (composite.database == current_database() && composite.visible_to(txid))
                .then_some(RoutineResult {
                    ctype: ColType::Composite(slot as u16),
                    user_type: identity(composite.schema, composite.name),
                });
        }
        if (oid::FIRST_COMPOSITE_ARRAY..oid::FIRST_COMPOSITE_ARRAY + self.composite_count() as i32)
            .contains(&type_oid)
        {
            let slot = usize::try_from(type_oid - oid::FIRST_COMPOSITE_ARRAY).ok()?;
            let composite = self.composite_for(slot, txid);
            return (composite.database == current_database() && composite.visible_to(txid))
                .then_some(RoutineResult {
                    ctype: ColType::Array(ArrElem::Composite(slot as u16)),
                    user_type: identity(composite.schema, composite.name),
                });
        }
        ColType::from_oid(type_oid).map(RoutineResult::builtin)
    }

    /// Whether PostgreSQL permits `actual_oid` to enter a routine parameter
    /// declared as `expected_oid` without an explicit cast. Routine overload
    /// resolution consumes this relation; execution then performs the cast at
    /// the declared-parameter boundary.
    pub(crate) fn routine_implicit_cast(
        &self,
        actual_oid: i32,
        expected_oid: i32,
        txid: u32,
    ) -> bool {
        use crate::sql::types::{ColType, oid};

        if actual_oid == expected_oid || actual_oid == oid::UNKNOWN {
            return true;
        }

        // A domain is implicitly treated as its base type when passed out of
        // the domain, but PostgreSQL does not implicitly manufacture a value
        // of a different domain at routine lookup.
        let expected_is_domain = (oid::FIRST_DOMAIN
            ..oid::FIRST_DOMAIN + self.domain_count() as i32)
            .contains(&expected_oid);
        if expected_is_domain {
            return false;
        }
        let actual = match self.routine_result_for_oid(actual_oid, txid) {
            Some(actual) => actual,
            None => return false,
        };
        let expected = match self.routine_result_for_oid(expected_oid, txid) {
            Some(expected) => expected,
            None => return false,
        };
        if actual.user_type.is_some() && actual.ctype == expected.ctype {
            return true;
        }
        if let (ColType::Array(actual), ColType::Array(expected)) = (actual.ctype, expected.ctype) {
            return self.routine_implicit_cast(actual.element_oid(), expected.element_oid(), txid);
        }
        if self
            .cast_for_oids(actual_oid, expected_oid, txid)
            .is_some_and(|(_, cast)| cast.context.permits_implicit())
        {
            return true;
        }

        matches!(
            (actual_oid, expected_oid),
            // Numeric widening casts from pg_cast.castcontext = 'i'.
            (oid::INT2, oid::INT4 | oid::INT8 | oid::NUMERIC | oid::FLOAT4 | oid::FLOAT8)
                | (oid::INT4, oid::INT8 | oid::NUMERIC | oid::FLOAT4 | oid::FLOAT8)
                | (oid::INT8, oid::NUMERIC | oid::FLOAT4 | oid::FLOAT8)
                | (oid::NUMERIC, oid::FLOAT4 | oid::FLOAT8)
                | (oid::FLOAT4, oid::FLOAT8)
                // PostgreSQL string-category binary and function casts.
                | (oid::BPCHAR, oid::VARCHAR | oid::NAME | oid::TEXT)
                | (oid::VARCHAR, oid::BPCHAR | oid::NAME | oid::TEXT | oid::REGCLASS)
                | (oid::TEXT, oid::BPCHAR | oid::VARCHAR | oid::NAME | oid::REGCLASS)
                | (oid::NAME, oid::TEXT)
                | (oid::BIT, oid::VARBIT)
                | (oid::VARBIT, oid::BIT)
                // Date/time and network casts accepted implicitly by PG18.
                | (oid::DATE, oid::TIMESTAMP | oid::TIMESTAMPTZ)
                | (oid::TIMESTAMP, oid::TIMESTAMPTZ)
                | (oid::TIME, oid::TIMETZ | oid::INTERVAL)
                | (oid::CIDR, oid::INET)
                | (oid::MACADDR, oid::MACADDR8)
                | (oid::MACADDR8, oid::MACADDR)
                // OID alias types are binary-coercible in both directions;
                // integer casts to OID aliases follow PostgreSQL's pg_cast.
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::OID)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGPROC)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGPROCEDURE)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGOPER)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGOPERATOR)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGCLASS)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGTYPE)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGNAMESPACE)
                | (oid::INT2 | oid::INT4 | oid::INT8, oid::REGROLE)
                | (oid::OID, oid::REGPROC | oid::REGPROCEDURE | oid::REGOPER | oid::REGOPERATOR | oid::REGCLASS | oid::REGTYPE | oid::REGNAMESPACE | oid::REGROLE)
                | (oid::REGPROC | oid::REGPROCEDURE | oid::REGOPER | oid::REGOPERATOR | oid::REGCLASS | oid::REGTYPE | oid::REGNAMESPACE | oid::REGROLE, oid::OID)
                | (oid::REGPROC, oid::REGPROCEDURE)
                | (oid::REGPROCEDURE, oid::REGPROC)
                | (oid::REGOPER, oid::REGOPERATOR)
                | (oid::REGOPERATOR, oid::REGOPER)
        )
    }

    pub(crate) fn user_type_identity_oid(
        &self,
        identity: UserTypeName,
        array: bool,
        txid: u32,
    ) -> Option<i32> {
        use crate::sql::types::oid;

        if let Some(slot) =
            self.domain_identity_slot(identity.schema.as_str(), identity.name.as_str(), txid)
        {
            return Some(if array {
                oid::domain_array_oid(slot as u16)
            } else {
                oid::domain_oid(slot as u16)
            });
        }
        if let Some(slot) = self.enum_slot(identity.schema.as_str(), identity.name.as_str(), txid) {
            return Some(if array {
                oid::enum_array_oid(slot as u16)
            } else {
                oid::enum_oid(slot as u16)
            });
        }
        self.composite_slot(identity.schema.as_str(), identity.name.as_str(), txid)
            .map(|slot| {
                if array {
                    oid::composite_array_oid(slot as u16)
                } else {
                    oid::composite_oid(slot as u16)
                }
            })
    }

    pub(crate) fn routine_slot_by_signature(
        &self,
        schema: &str,
        name: &str,
        argument_types: &[ColType],
        txid: u32,
    ) -> Option<usize> {
        self.routine_entries().find_map(|(slot, routine)| {
            let definition = routine.definition_for(txid);
            (routine.database == current_database()
                && routine.visible_to(txid)
                && definition.schema_for(txid).as_str() == schema
                && definition.name_for(txid).as_str() == name
                && definition.argument_count == argument_types.len()
                && definition
                    .arguments()
                    .iter()
                    .zip(argument_types)
                    .all(|(argument, ctype)| argument.ctype == *ctype))
            .then_some(slot)
        })
    }

    pub(crate) fn routine_slot_by_declared_signature(
        &self,
        schema: &str,
        name: &str,
        arguments: &[RoutineArgumentDef],
        txid: u32,
    ) -> Option<usize> {
        self.routine_entries().find_map(|(slot, routine)| {
            let definition = routine.definition_for(txid);
            (routine.database == current_database()
                && routine.visible_to(txid)
                && definition.schema_for(txid).as_str() == schema
                && definition.name_for(txid).as_str() == name
                && definition.argument_count == arguments.len()
                && definition
                    .arguments()
                    .iter()
                    .zip(arguments)
                    .all(|(left, right)| {
                        left.ctype == right.ctype && left.user_type == right.user_type
                    }))
            .then_some(slot)
        })
    }

    /// Resolves PostgreSQL's omitted-argument `DROP FUNCTION name` form.  It
    /// is valid only when exactly one visible routine has that identity.
    pub(crate) fn routine_slot_by_name_unambiguous(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, ()> {
        let mut found = None;
        for (slot, routine) in self.routine_entries() {
            if routine.database != current_database()
                || !routine.visible_to(txid)
                || routine.schema_for(txid).as_str() != schema
                || routine.name_for(txid).as_str() != name
            {
                continue;
            }
            if found.replace(slot).is_some() {
                return Err(());
            }
        }
        Ok(found)
    }

    pub(crate) fn alter_routine_identity(
        &mut self,
        slot: usize,
        schema: SqlName,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingRoutineIdentity>, SqlError> {
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        let routine = routines[slot];
        if let Some(pending) = routine.pending_identity
            && pending.txid != txid
        {
            drop(routines);
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, routine.name.as_str()));
        }
        if routines.iter().enumerate().any(|(other, candidate)| {
            other != slot
                && candidate.database == current_database()
                && candidate.visible_to(txid)
                && candidate.schema_for(txid) == schema
                && candidate.name_for(txid) == name
                && candidate.argument_count == routine.argument_count
                && candidate
                    .arguments()
                    .iter()
                    .zip(routine.arguments())
                    .all(|(left, right)| {
                        left.ctype == right.ctype && left.user_type == right.user_type
                    })
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_FUNCTION,
                "routine \"{}\" already exists with same argument types",
                name.as_str()
            ));
        }
        if let Some(blocker) = routines.iter().enumerate().find_map(|(other, candidate)| {
            (other != slot)
                .then_some(candidate.pending_identity)
                .flatten()
                .filter(|pending| {
                    pending.txid != txid
                        && pending.schema == schema
                        && pending.name == name
                        && candidate.argument_count == routine.argument_count
                        && candidate.arguments().iter().zip(routine.arguments()).all(
                            |(left, right)| {
                                left.ctype == right.ctype && left.user_type == right.user_type
                            },
                        )
                })
                .map(|pending| pending.txid)
        }) {
            drop(routines);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let prior = routines[slot].pending_identity;
        routines[slot].pending_identity = Some(PendingRoutineIdentity { txid, schema, name });
        Ok(prior)
    }

    pub(crate) fn commit_routine_identity(&mut self, slot: usize, txid: u32) {
        let changed = {
            let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
            let routine = &mut routines[slot];
            if let Some(pending) = routine.pending_identity
                && pending.txid == txid
            {
                routine.schema = pending.schema;
                routine.name = pending.name;
                routine.pending_identity = None;
                Some((pending.schema, pending.name))
            } else {
                None
            }
        };
        if let Some((schema, name)) = changed {
            self.rename_stored_query_dependency(DependencyClass::Routine, slot, None, schema, name);
        }
    }

    pub(crate) fn restore_routine_identity(
        &mut self,
        slot: usize,
        prior: Option<PendingRoutineIdentity>,
    ) {
        self.routines.lock().expect("routine catalog lock poisoned")[slot].pending_identity = prior;
    }

    pub(crate) const fn routine_access_object(slot: usize) -> AccessObject {
        AccessObject {
            class: AccessClass::Routine,
            slot: slot as u16,
        }
    }

    pub(crate) fn routine_dependencies_for(
        &self,
        slot: usize,
        txid: u32,
    ) -> StoredQueryDependencyImage<'_> {
        if let Some(pending) = self
            .routine(slot)
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            return self.pending_dependencies(pending.dependency_slot);
        }
        self.committed_dependencies(StoredQueryDependencyOwner::Routine(slot as u16))
    }

    pub(crate) fn snapshot_routine_dependencies_for(
        &self,
        slot: usize,
        txid: u32,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let image = if let Some(pending) = self
            .routine(slot)
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            self.stored_query_dependency_pending_base + pending.dependency_slot as usize
        } else {
            self.committed_dependency_image(StoredQueryDependencyOwner::Routine(slot as u16))
        };
        self.snapshot_dependency_image(image, arena)
    }

    pub(crate) fn create_routine(
        &mut self,
        spec: RoutineSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let RoutineSpec {
            identity,
            schema,
            name,
            arguments,
            argument_count,
            parameters,
            parameter_count,
            kind,
            result_columns,
            result_column_count,
            language,
            attributes,
            configs,
            config_count,
            body_kind,
            body,
            creation_path,
            dependencies,
        } = spec;
        if config_count > configs.len()
            || configs[..config_count]
                .iter()
                .enumerate()
                .any(|(index, config)| {
                    configs[..index]
                        .iter()
                        .any(|prior| prior.name == config.name)
                })
        {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "routine configuration contract is invalid"
            ));
        }
        if parameter_count > parameters.len()
            || parameters[..parameter_count]
                .iter()
                .filter(|parameter| parameter.mode.is_input())
                .count()
                != argument_count
        {
            return Err(sql_err!(
                sqlstate::INVALID_FUNCTION_DEFINITION,
                "routine parameter contract does not match its input signature"
            ));
        }
        let output_parameter_count = parameters[..parameter_count]
            .iter()
            .filter(|parameter| parameter.mode.is_output())
            .count();
        let mut saw_default = false;
        let mut saw_variadic = false;
        for parameter in &parameters[..parameter_count] {
            if saw_variadic && !matches!(parameter.mode, RoutineParameterMode::Out) {
                return Err(sql_err!(
                    sqlstate::INVALID_FUNCTION_DEFINITION,
                    "VARIADIC parameter must be the last input parameter"
                ));
            }
            if parameter.mode.is_input() {
                if parameter.mode.default().is_some() {
                    saw_default = true;
                } else if saw_default {
                    return Err(sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "input parameters after one with a default value must also have defaults"
                    ));
                }
            }
            saw_variadic |= matches!(parameter.mode, RoutineParameterMode::Variadic { .. });
        }
        match kind {
            RoutineKind::TableFunction => {
                if result_column_count == 0 || result_column_count > result_columns.len() {
                    return Err(sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "record-returning function must have between one and {} result columns",
                        result_columns.len()
                    ));
                }
                if result_columns[..result_column_count]
                    .iter()
                    .enumerate()
                    .any(|(index, column)| {
                        result_columns[..index]
                            .iter()
                            .any(|prior| prior.name == column.name)
                    })
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "routine result column names must be distinct"
                    ));
                }
            }
            RoutineKind::RecordFunction { .. }
                if result_column_count < 2
                    || result_column_count != output_parameter_count
                    || result_column_count > result_columns.len() =>
            {
                return Err(sql_err!(
                    sqlstate::INVALID_FUNCTION_DEFINITION,
                    "record function result contract does not match its output parameters"
                ));
            }
            RoutineKind::RecordFunction { .. } => {}
            RoutineKind::Function { .. } | RoutineKind::SetFunction { .. }
                if result_column_count != 0
                    && (result_column_count != 1 || output_parameter_count != 1) =>
            {
                return Err(sql_err!(
                    sqlstate::INVALID_FUNCTION_DEFINITION,
                    "scalar function result contract does not match its output parameter"
                ));
            }
            RoutineKind::Function { .. } | RoutineKind::SetFunction { .. } => {}
            RoutineKind::Trigger
            | RoutineKind::EventTrigger
            | RoutineKind::Procedure
            | RoutineKind::Aggregate(_)
                if result_column_count != 0 =>
            {
                return Err(sql_err!(
                    sqlstate::INVALID_FUNCTION_DEFINITION,
                    "routine kind cannot define result columns"
                ));
            }
            RoutineKind::Trigger
            | RoutineKind::EventTrigger
            | RoutineKind::Procedure
            | RoutineKind::Aggregate(_) => {}
        }
        self.require_schema_create(schema.as_str(), txid)?;
        let allocated_ownership =
            matches!(identity, RoutineIdentity::Allocate).then(|| self.initial_ownership(txid));
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        if let Some(blocker) = routines.iter().find_map(|routine| {
            (routine.database == current_database()
                && routine.schema_for(txid) == schema
                && routine.name_for(txid) == name
                && routine.argument_count == argument_count
                && routine.arguments()[..argument_count]
                    .iter()
                    .zip(&arguments[..argument_count])
                    .all(|(left, right)| {
                        left.ctype == right.ctype && left.user_type == right.user_type
                    }))
            .then_some(routine.ddl_state.pending_txid()?)
            .filter(|&owner| owner != txid)
        }) {
            drop(routines);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if routines.iter().any(|routine| {
            routine.database == current_database()
                && routine.visible_to(txid)
                && routine.schema_for(txid) == schema
                && routine.name_for(txid) == name
                && routine.argument_count == argument_count
                && routine.arguments()[..argument_count]
                    .iter()
                    .zip(&arguments[..argument_count])
                    .all(|(left, right)| {
                        left.ctype == right.ctype && left.user_type == right.user_type
                    })
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_FUNCTION,
                "function \"{}\" already exists with same argument types",
                name.as_str()
            ));
        }
        let Some(slot) = routines
            .iter()
            .position(|routine| routine.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many routines (limit {})",
                routines.len()
            ));
        };
        let (created_at, ownership) = match identity {
            RoutineIdentity::Allocate => (
                self.catalog_sequence.next(),
                allocated_ownership.expect("allocated routine ownership was prepared"),
            ),
            RoutineIdentity::Preserve {
                created_at,
                ownership,
            } => {
                self.catalog_sequence.observe(created_at);
                (created_at, ownership)
            }
        };
        routines[slot] = RoutineDef {
            database: current_database(),
            created_at,
            schema,
            name,
            pending_identity: None,
            pending_definition: None,
            arguments,
            argument_count,
            parameters,
            parameter_count,
            kind,
            result_columns,
            result_column_count,
            language,
            attributes,
            configs,
            config_count,
            body_kind,
            body,
            creation_path,
            ownership,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        drop(routines);
        self.clear_object_acl_entries(Self::routine_access_object(slot));
        if let Err(error) = self.write_committed_dependencies(
            StoredQueryDependencyOwner::Routine(slot as u16),
            dependencies.view(),
        ) {
            self.routines.lock().expect("routine catalog lock poisoned")[slot] = RoutineDef::EMPTY;
            self.clear_committed_dependencies(StoredQueryDependencyOwner::Routine(slot as u16));
            return Err(error);
        }
        Ok(slot)
    }

    pub(crate) fn commit_routine_create(&mut self, slot: usize, txid: u32) {
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        routines[slot].ddl_state = routines[slot].ddl_state.commit_create();
        let ownership = &mut routines[slot].ownership;
        if let Some(pending) = ownership.pending
            && pending.txid == txid
        {
            ownership.owner = pending.owner;
            ownership.pending = None;
        }
    }

    pub(crate) fn rollback_routine_create(&mut self, slot: usize) {
        self.routines.lock().expect("routine catalog lock poisoned")[slot] = RoutineDef::EMPTY;
        self.clear_committed_dependencies(StoredQueryDependencyOwner::Routine(slot as u16));
    }

    pub(crate) fn replace_routine(
        &mut self,
        slot: usize,
        mut definition: PendingRoutineDefinition,
        dependencies: StoredQueryDependencyView<'_>,
    ) -> Result<Option<PendingRoutineDefinition>, SqlError> {
        let routine = self.routine(slot);
        let name = routine.name;
        if let Some(pending) = routine.pending_definition
            && pending.txid != definition.txid
        {
            return Err(self.catalog_ddl_wait_error(definition.txid, pending.txid, name.as_str()));
        }
        let previous = routine
            .pending_definition
            .filter(|pending| pending.txid == definition.txid)
            .map(|pending| pending.dependency_slot);
        definition.dependency_slot = self.allocate_pending_stored_query_dependencies(
            StoredQueryDependencyOwner::Routine(slot as u16),
            definition.txid,
            previous,
            dependencies,
        )?;
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        let routine = &mut routines[slot];
        let prior = routine.pending_definition;
        routine.pending_definition = Some(definition);
        Ok(prior)
    }

    pub(crate) fn replace_routine_preserving_dependencies(
        &mut self,
        slot: usize,
        mut definition: PendingRoutineDefinition,
    ) -> Result<Option<PendingRoutineDefinition>, SqlError> {
        let routine = self.routine(slot);
        let name = routine.name;
        if let Some(pending) = routine.pending_definition
            && pending.txid != definition.txid
        {
            return Err(self.catalog_ddl_wait_error(definition.txid, pending.txid, name.as_str()));
        }
        let previous = routine
            .pending_definition
            .filter(|pending| pending.txid == definition.txid)
            .map(|pending| pending.dependency_slot);
        definition.dependency_slot = self.allocate_pending_stored_query_dependencies_from_current(
            StoredQueryDependencyOwner::Routine(slot as u16),
            previous,
        )?;
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        let routine = &mut routines[slot];
        let prior = routine.pending_definition;
        routine.pending_definition = Some(definition);
        Ok(prior)
    }

    pub(crate) fn commit_routine_replace(&mut self, slot: usize, txid: u32) {
        if let Some(pending) = self.routine(slot).pending_definition
            && pending.txid == txid
        {
            self.commit_pending_dependencies(
                StoredQueryDependencyOwner::Routine(slot as u16),
                pending.dependency_slot,
            );
            let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
            let routine = &mut routines[slot];
            routine.arguments = pending.arguments;
            routine.argument_count = pending.argument_count;
            routine.parameters = pending.parameters;
            routine.parameter_count = pending.parameter_count;
            routine.kind = pending.kind;
            routine.result_columns = pending.result_columns;
            routine.result_column_count = pending.result_column_count;
            routine.language = pending.language;
            routine.attributes = pending.attributes;
            routine.configs = pending.configs;
            routine.config_count = pending.config_count;
            routine.body_kind = pending.body_kind;
            routine.body = pending.body;
            routine.creation_path = pending.creation_path;
            routine.pending_definition = None;
        }
    }

    pub(crate) fn rollback_routine_replace(
        &mut self,
        slot: usize,
        prior: Option<PendingRoutineDefinition>,
    ) {
        if let Some(current) = self.routine(slot).pending_definition {
            self.release_pending_dependencies(current.dependency_slot);
        }
        self.routines.lock().expect("routine catalog lock poisoned")[slot].pending_definition =
            prior;
    }

    pub(crate) fn drop_routine(&mut self, slot: usize, txid: u32) {
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        routines[slot].ddl_state = routines[slot].ddl_state.drop_by(txid);
    }

    pub(crate) fn commit_routine_drop(&mut self, slot: usize) {
        let routine = self.routine(slot);
        let routine_oid = routine_oid(&routine);
        let oid = routine_oid as u32;
        let pending = routine
            .pending_definition
            .map(|pending| pending.dependency_slot);
        self.reset_function_statistics(routine_oid);
        self.routines.lock().expect("routine catalog lock poisoned")[slot] = RoutineDef::EMPTY;
        let object = Self::routine_access_object(slot);
        self.clear_object_acl_entries(object);
        self.clear_extension_dependencies_for_object(object);
        self.clear_committed_dependencies(StoredQueryDependencyOwner::Routine(slot as u16));
        self.drop_comments_by_subid(CommentClass::Routine, oid);
        self.clear_pending_dependency_chain(pending);
    }

    pub(crate) fn rollback_routine_drop(&mut self, slot: usize, txid: u32) {
        let mut routines = self.routines.lock().expect("routine catalog lock poisoned");
        routines[slot].ddl_state = routines[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn policy(&self, slot: usize) -> PolicyDef {
        self.policy_catalog
            .lock()
            .expect("policy catalog lock poisoned")
            .definitions[slot]
    }

    pub(crate) fn policy_count(&self) -> usize {
        self.policy_catalog_capacity
    }

    pub(crate) fn policy_dependencies(
        &self,
        slot: usize,
        txid: u32,
    ) -> StoredQueryDependencyImage<'_> {
        if let Some(pending) = self
            .policy(slot)
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            return self.pending_dependencies(pending.dependency_slot);
        }
        self.committed_dependencies(StoredQueryDependencyOwner::Policy(slot as u16))
    }

    pub(crate) fn snapshot_policy_dependencies(
        &self,
        slot: usize,
        txid: u32,
        arena: &crate::mem::arena::Arena,
    ) -> Result<StoredQueryDependencies, SqlError> {
        let image = if let Some(pending) = self
            .policy(slot)
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            self.stored_query_dependency_pending_base + pending.dependency_slot as usize
        } else {
            self.committed_dependency_image(StoredQueryDependencyOwner::Policy(slot as u16))
        };
        self.snapshot_dependency_image(image, arena)
    }

    fn write_policy_role_image(
        catalog: &mut PolicyCatalog,
        roles_per_image: usize,
        image: usize,
        roles: &[u16],
    ) -> Result<u32, SqlError> {
        if roles.is_empty() || roles.len() > roles_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "a policy can target between 1 and {} roles",
                roles_per_image
            ));
        }
        let count = u32::try_from(roles.len()).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "policy role count exceeds durable representation"
            )
        })?;
        let start = image * roles_per_image;
        catalog.roles[start..start + roles.len()].copy_from_slice(roles);
        Ok(count)
    }

    fn clear_policy_slot_in(catalog: &mut PolicyCatalog, roles_per_image: usize, slot: usize) {
        catalog.definitions[slot] = PolicyDef::EMPTY;
        let start = slot * roles_per_image;
        catalog.roles[start..start + roles_per_image].fill(PUBLIC_ROLE);
    }

    pub(crate) fn policy_roles(&self, slot: usize, txid: u32) -> PolicyRoleImage<'_> {
        let catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        let policy = catalog.definitions[slot];
        let (image, count) = if let Some(pending) = policy
            .pending_definition
            .filter(|pending| pending.txid == txid)
        {
            (
                self.policy_role_pending_base + pending.dependency_slot as usize,
                pending.role_count,
            )
        } else {
            (slot, policy.role_count)
        };
        PolicyRoleImage {
            catalog,
            start: image * self.policy_roles_per_image,
            count: usize::try_from(count).expect("policy role count fits usize"),
        }
    }

    pub(crate) fn policy_role_capacity(&self) -> usize {
        self.policy_roles_per_image
    }

    pub(crate) fn policy_applies_to_role(&self, slot: usize, role: usize, txid: u32) -> bool {
        self.policy_roles(slot, txid).iter().any(|target| {
            *target == PUBLIC_ROLE
                || usize::from(*target) == role
                || self.role_is_member_of(role, usize::from(*target), txid)
        })
    }

    pub(crate) fn policies_for_table(
        &self,
        table: usize,
        txid: u32,
    ) -> impl Iterator<Item = (usize, PolicyDef)> + '_ {
        PolicyIter {
            catalog: &self.policy_catalog,
            next_slot: 0,
        }
        .filter(move |(_, policy)| {
            policy.database == current_database()
                && policy.visible_to(txid)
                && usize::from(policy.table) == table
        })
    }

    pub(crate) fn policies_with_slots_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, PolicyDef)> + '_ {
        PolicyIter {
            catalog: &self.policy_catalog,
            next_slot: 0,
        }
        .filter(move |(_, policy)| policy.database == current_database() && policy.visible_to(txid))
    }

    /// Whether this role is subject to the table's row-security policies.
    /// Superusers and BYPASSRLS roles always bypass; owners bypass unless the
    /// table is forced. Disabled row security never consults policies.
    pub(crate) fn row_security_applies(&self, table: usize, role: usize, txid: u32) -> bool {
        let state = self.table_def(table, txid).row_level_security;
        if !state.enabled {
            return false;
        }
        let attributes = self.role(role).attributes_to(txid);
        if attributes.superuser || attributes.bypass_row_level_security {
            return false;
        }
        state.forced || self.object_owner(self.table_access_object(table, txid), txid) != role
    }

    pub(crate) fn policy_slot_on(&self, table: usize, name: &str, txid: u32) -> Option<usize> {
        self.policies_for_table(table, txid)
            .find_map(|(slot, policy)| (policy.name.as_str() == name).then_some(slot))
    }

    pub(crate) fn create_policy(
        &mut self,
        spec: PolicySpec<'_>,
        dependencies: &StoredQueryDependencies,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if spec.table >= self.tables.len()
            || spec.roles.is_empty()
            || (matches!(spec.command, PolicyCommandKind::Insert)
                && spec.definition.using.is_some())
            || (matches!(
                spec.command,
                PolicyCommandKind::Select | PolicyCommandKind::Delete
            ) && spec.definition.with_check.is_some())
        {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "invalid row-security policy definition"
            ));
        }
        let table = u16::try_from(spec.table).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "table slot exceeds policy catalog capacity"
            )
        })?;
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        if catalog.definitions.iter().any(|policy| {
            policy.database == current_database()
                && policy.visible_to(txid)
                && policy.table == table
                && policy.name == spec.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "policy \"{}\" for table already exists",
                spec.name.as_str()
            ));
        }
        let Some(slot) = catalog
            .definitions
            .iter()
            .position(|policy| policy.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "row-security policy catalog is full (limit {})",
                catalog.definitions.len()
            ));
        };
        let role_count = Self::write_policy_role_image(
            &mut catalog,
            self.policy_roles_per_image,
            slot,
            spec.roles,
        )?;
        self.write_committed_dependencies(
            StoredQueryDependencyOwner::Policy(slot as u16),
            dependencies.view(),
        )?;
        let created_at = self.catalog_sequence.next();
        catalog.definitions[slot] = PolicyDef {
            database: current_database(),
            created_at,
            name: spec.name,
            table,
            command: spec.command,
            permissive: spec.permissive,
            definition: spec.definition,
            role_count,
            pending_definition: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn alter_policy(
        &mut self,
        slot: usize,
        definition: PolicyDefinition,
        roles: &[u16],
        dependencies: &StoredQueryDependencies,
        txid: u32,
    ) -> Result<Option<PendingPolicyDefinition>, SqlError> {
        let policy = self.policy(slot);
        if matches!(policy.command, PolicyCommandKind::Insert) && definition.using.is_some()
            || matches!(
                policy.command,
                PolicyCommandKind::Select | PolicyCommandKind::Delete
            ) && definition.with_check.is_some()
        {
            return Err(sql_err!(
                sqlstate::SYNTAX_ERROR,
                "policy expression is not valid for its command"
            ));
        }
        if let Some(pending) = policy.pending_definition
            && pending.txid != txid
        {
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, policy.name.as_str()));
        }
        let prior = policy.pending_definition;
        let previous = prior
            .filter(|pending| pending.txid == txid)
            .map(|pending| pending.dependency_slot);
        if roles.is_empty() || roles.len() > self.policy_roles_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "a policy can target between 1 and {} roles",
                self.policy_roles_per_image
            ));
        }
        let dependency_slot = self.allocate_pending_stored_query_dependencies(
            StoredQueryDependencyOwner::Policy(slot as u16),
            txid,
            previous,
            dependencies.view(),
        )?;
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        let role_count = Self::write_policy_role_image(
            &mut catalog,
            self.policy_roles_per_image,
            self.policy_role_pending_base + dependency_slot as usize,
            roles,
        )?;
        catalog.definitions[slot].pending_definition = Some(PendingPolicyDefinition {
            txid,
            definition,
            role_count,
            dependency_slot,
        });
        Ok(prior)
    }

    pub(crate) fn drop_policy(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.drop_by(txid);
    }

    pub(crate) fn commit_policy_create(&mut self, slot: usize) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_create();
    }

    pub(crate) fn rollback_policy_create(&mut self, slot: usize) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        Self::clear_policy_slot_in(&mut catalog, self.policy_roles_per_image, slot);
        drop(catalog);
        self.clear_committed_dependencies(StoredQueryDependencyOwner::Policy(slot as u16));
    }

    pub(crate) fn commit_policy_alter(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        if let Some(pending) = catalog.definitions[slot].pending_definition
            && pending.txid == txid
        {
            let source = (self.policy_role_pending_base + pending.dependency_slot as usize)
                * self.policy_roles_per_image;
            let target = slot * self.policy_roles_per_image;
            let count = usize::try_from(pending.role_count).expect("policy role count fits usize");
            self.commit_pending_dependencies(
                StoredQueryDependencyOwner::Policy(slot as u16),
                pending.dependency_slot,
            );
            catalog.roles.copy_within(source..source + count, target);
            catalog.definitions[slot].definition = pending.definition;
            catalog.definitions[slot].role_count = pending.role_count;
            catalog.definitions[slot].pending_definition = None;
        }
    }

    pub(crate) fn rollback_policy_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingPolicyDefinition>,
    ) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        if let Some(current) = catalog.definitions[slot].pending_definition {
            catalog.definitions[slot].pending_definition = prior;
            drop(catalog);
            self.release_pending_dependencies(current.dependency_slot);
        } else {
            catalog.definitions[slot].pending_definition = prior;
        }
    }

    pub(crate) fn commit_policy_drop(&mut self, slot: usize) {
        let (oid, pending) = {
            let mut catalog = self
                .policy_catalog
                .lock()
                .expect("policy catalog lock poisoned");
            let policy = catalog.definitions[slot];
            Self::clear_policy_slot_in(&mut catalog, self.policy_roles_per_image, slot);
            (
                policy_oid(&policy) as u32,
                policy
                    .pending_definition
                    .map(|pending| pending.dependency_slot),
            )
        };
        self.clear_pending_dependency_chain(pending);
        self.clear_committed_dependencies(StoredQueryDependencyOwner::Policy(slot as u16));
        self.drop_comments_by_subid(CommentClass::Policy, oid);
    }

    pub(crate) fn rollback_policy_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        catalog.definitions[slot].ddl_state =
            catalog.definitions[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn commit_policies_for_table(&mut self, table: usize) {
        for slot in 0..self.policy_count() {
            let removed = {
                let mut catalog = self
                    .policy_catalog
                    .lock()
                    .expect("policy catalog lock poisoned");
                let policy = catalog.definitions[slot];
                (policy.ddl_state != CatalogDdlState::Absent && usize::from(policy.table) == table)
                    .then(|| {
                        Self::clear_policy_slot_in(&mut catalog, self.policy_roles_per_image, slot);
                        policy
                    })
            };
            let Some(policy) = removed else {
                continue;
            };
            let pending = policy
                .pending_definition
                .map(|pending| pending.dependency_slot);
            self.clear_pending_dependency_chain(pending);
            self.clear_committed_dependencies(StoredQueryDependencyOwner::Policy(slot as u16));
            self.drop_comments_by_subid(CommentClass::Policy, policy_oid(&policy) as u32);
        }
    }

    pub(crate) fn replay_set_policy<'a>(
        &mut self,
        spec: RecoveredPolicySpec,
        roles: impl ExactSizeIterator<Item = &'a str>,
        dependencies: StoredQueryDependencies,
    ) -> Result<usize, SqlError> {
        let role_count = roles.len();
        if role_count == 0 || role_count > self.policy_roles_per_image {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "a policy can target between 1 and {} roles",
                self.policy_roles_per_image
            ));
        }
        let durable_role_count = u32::try_from(role_count).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "policy role count exceeds durable representation"
            )
        })?;
        let scratch_start = self.policy_role_replay_image * self.policy_roles_per_image;
        let mut catalog = self
            .policy_catalog
            .lock()
            .expect("policy catalog lock poisoned");
        for (index, role) in roles.enumerate() {
            let role = if role.eq_ignore_ascii_case("public") {
                PUBLIC_ROLE
            } else {
                u16::try_from(self.find_role_visible(role, 0).ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_OBJECT,
                        "recovered policy references unknown role \"{}\"",
                        role
                    )
                })?)
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "role slot exceeds policy representation"
                    )
                })?
            };
            catalog.roles[scratch_start + index] = role;
        }
        if spec.table >= self.tables.len()
            || (matches!(spec.command, PolicyCommandKind::Insert)
                && spec.definition.using.is_some())
            || (matches!(
                spec.command,
                PolicyCommandKind::Select | PolicyCommandKind::Delete
            ) && spec.definition.with_check.is_some())
        {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "invalid recovered row-security policy definition"
            ));
        }
        let table = u16::try_from(spec.table).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "table slot exceeds policy catalog capacity"
            )
        })?;
        let existing = catalog.definitions.iter().position(|policy| {
            policy.database == current_database()
                && policy.visible_to(0)
                && policy.table == table
                && policy.name == spec.name
        });
        let slot = if let Some(slot) = existing {
            slot
        } else {
            let Some(slot) = catalog
                .definitions
                .iter()
                .position(|policy| policy.ddl_state == CatalogDdlState::Absent)
            else {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "row-security policy catalog is full (limit {})",
                    catalog.definitions.len()
                ));
            };
            let created_at = self.catalog_sequence.next();
            catalog.definitions[slot] = PolicyDef {
                database: current_database(),
                created_at,
                name: spec.name,
                table,
                command: spec.command,
                permissive: spec.permissive,
                definition: spec.definition,
                role_count: durable_role_count,
                pending_definition: None,
                ddl_state: CatalogDdlState::Present,
            };
            slot
        };
        let target = slot * self.policy_roles_per_image;
        catalog
            .roles
            .copy_within(scratch_start..scratch_start + role_count, target);
        self.write_committed_dependencies(
            StoredQueryDependencyOwner::Policy(slot as u16),
            dependencies.view(),
        )?;
        let policy = &mut catalog.definitions[slot];
        policy.command = spec.command;
        policy.permissive = spec.permissive;
        policy.definition = spec.definition;
        policy.role_count = durable_role_count;
        policy.pending_definition = None;
        Ok(slot)
    }

    pub(crate) fn replay_drop_policy(&mut self, table: usize, name: &str) {
        if let Some(slot) = self.policy_slot_on(table, name, 0) {
            self.drop_policy(slot, 0);
            self.commit_policy_drop(slot);
        }
    }

    pub(crate) fn restore_policy<'a>(
        &mut self,
        created_at: u64,
        spec: RecoveredPolicySpec,
        roles: impl ExactSizeIterator<Item = &'a str>,
        dependencies: StoredQueryDependencies,
    ) -> Result<(), SqlError> {
        let slot = self.replay_set_policy(spec, roles, dependencies)?;
        self.policy_catalog
            .lock()
            .expect("policy catalog lock poisoned")
            .definitions[slot]
            .created_at = created_at;
        self.catalog_sequence.observe(created_at);
        Ok(())
    }

    pub(crate) fn triggers_for_table(
        &self,
        table: usize,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TriggerDef)> + '_ {
        TriggerIter {
            catalog: &self.trigger_catalog,
            next_slot: 0,
        }
        .filter(move |(_, trigger)| {
            trigger.database == current_database()
                && trigger.visible_to(txid)
                && trigger.target == TriggerTarget::Table(table as u16)
        })
        .map(move |(slot, trigger)| (slot, trigger.effective_to(txid)))
    }

    pub(crate) fn triggers_for_view(
        &self,
        view: usize,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TriggerDef)> + '_ {
        TriggerIter {
            catalog: &self.trigger_catalog,
            next_slot: 0,
        }
        .filter(move |(_, trigger)| {
            trigger.database == current_database()
                && trigger.visible_to(txid)
                && trigger.target == TriggerTarget::View(view as u16)
        })
        .map(move |(slot, trigger)| (slot, trigger.effective_to(txid)))
    }

    pub(crate) fn triggers_for_target(
        &self,
        target: TriggerTarget,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TriggerDef)> + '_ {
        self.triggers_with_slots_visible_to(txid)
            .filter(move |(_, trigger)| trigger.target == target)
    }

    pub(crate) fn trigger_metadata_for_target(
        &self,
        target: TriggerTarget,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TriggerDef)> + '_ {
        TriggerIter {
            catalog: &self.trigger_catalog,
            next_slot: 0,
        }
        .filter(move |(_, trigger)| {
            trigger.database == current_database()
                && trigger.visible_to(txid)
                && trigger.target == target
        })
    }

    pub(crate) fn trigger_for_target(
        &self,
        slot: usize,
        target: TriggerTarget,
        txid: u32,
    ) -> Option<TriggerDef> {
        let trigger = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned")
            .definitions
            .get(slot)
            .copied()?;
        (trigger.database == current_database()
            && trigger.visible_to(txid)
            && trigger.target == target)
            .then(|| trigger.effective_to(txid))
    }

    pub(crate) fn triggers_with_slots_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TriggerDef)> + '_ {
        TriggerIter {
            catalog: &self.trigger_catalog,
            next_slot: 0,
        }
        .filter(move |(_, trigger)| {
            trigger.database == current_database() && trigger.visible_to(txid)
        })
        .map(move |(slot, trigger)| (slot, trigger.effective_to(txid)))
    }

    pub(crate) fn trigger(&self, slot: usize) -> TriggerDef {
        self.trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned")
            .definitions[slot]
    }

    pub(crate) fn trigger_capacity(&self) -> usize {
        self.trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned")
            .definitions
            .len()
    }

    pub(crate) fn trigger_to(&self, slot: usize, txid: u32) -> TriggerDef {
        self.trigger(slot).effective_to(txid)
    }

    pub(crate) fn trigger_slot_on(
        &self,
        target: TriggerTarget,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        self.triggers_for_target(target, txid)
            .find_map(|(slot, trigger)| (trigger.name_to(txid).as_str() == name).then_some(slot))
    }

    pub(crate) fn trigger_slot_inherited_by(
        &self,
        table: usize,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        self.triggers_with_slots_visible_to(txid)
            .find_map(|(slot, trigger)| {
                let TriggerTarget::Table(parent) = trigger.target else {
                    return None;
                };
                (matches!(trigger.level, crate::sql::ast::TriggerLevel::Row)
                    && trigger.name_to(txid).as_str() == name
                    && self.partition_descends_from(table, usize::from(parent), txid))
                .then_some(slot)
            })
    }

    pub(crate) fn partition_trigger_enabled_to(
        &self,
        trigger: usize,
        table: usize,
        txid: u32,
    ) -> TriggerEnabled {
        let override_enabled = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned")
            .partition_states
            .iter()
            .find(|state| state.trigger as usize == trigger && state.table as usize == table)
            .and_then(|state| state.enabled_to(txid));
        override_enabled.unwrap_or_else(|| self.trigger_to(trigger, txid).enabled_to(txid))
    }

    pub(crate) fn stage_partition_trigger_enabled(
        &mut self,
        trigger: usize,
        table: usize,
        enabled: TriggerEnabled,
        txid: u32,
    ) -> Result<Option<(usize, PartitionTriggerState)>, SqlError> {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let existing = catalog.partition_states.iter().position(|state| {
            state.trigger as usize == trigger
                && state.table as usize == table
                && (state.present || state.pending.is_some())
        });
        let slot = existing.or_else(|| {
            catalog
                .partition_states
                .iter()
                .position(|state| !state.present && state.pending.is_none())
        });
        let Some(slot) = slot else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "partition trigger state exceeds the startup catalog capacity"
            ));
        };
        let prior = catalog.partition_states[slot];
        if let Some(pending) = prior.pending
            && pending.txid != txid
        {
            return Err(self.catalog_ddl_wait_error(
                txid,
                pending.txid,
                catalog.definitions[trigger].name.as_str(),
            ));
        }
        if prior.enabled_to(txid) == Some(enabled) {
            return Ok(None);
        }
        catalog.partition_states[slot] = PartitionTriggerState {
            trigger: trigger as u16,
            table: table as u16,
            enabled: prior.enabled,
            present: prior.present,
            pending: Some(PendingPartitionTriggerState { txid, enabled }),
        };
        Ok(Some((slot, prior)))
    }

    pub(crate) fn commit_partition_trigger_state(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let state = &mut catalog.partition_states[slot];
        if let Some(pending) = state.pending
            && pending.txid == txid
        {
            state.enabled = pending.enabled;
            state.present = true;
            state.pending = None;
        }
    }

    pub(crate) fn rollback_partition_trigger_state(
        &mut self,
        slot: usize,
        prior: PartitionTriggerState,
    ) {
        self.trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned")
            .partition_states[slot] = prior;
    }

    pub(crate) fn restore_partition_trigger_state(
        &mut self,
        trigger: usize,
        table: usize,
        enabled: TriggerEnabled,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        if catalog.partition_states.iter().any(|state| {
            state.present && state.trigger as usize == trigger && state.table as usize == table
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "duplicate partition trigger state in checkpoint"
            ));
        }
        let Some(slot) = catalog
            .partition_states
            .iter()
            .position(|state| !state.present && state.pending.is_none())
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many partition trigger states in checkpoint"
            ));
        };
        catalog.partition_states[slot] = PartitionTriggerState {
            trigger: trigger as u16,
            table: table as u16,
            enabled,
            present: true,
            pending: None,
        };
        Ok(())
    }

    pub(crate) fn partition_trigger_states(
        &self,
    ) -> impl Iterator<Item = (usize, usize, TriggerEnabled)> + '_ {
        PartitionTriggerStateIter {
            catalog: &self.trigger_catalog,
            next_slot: 0,
        }
        .filter_map(|state| {
            (state.present
                && self.table_def(usize::from(state.table), 0).persistence
                    != RelationPersistence::Temporary)
                .then_some((
                    usize::from(state.trigger),
                    usize::from(state.table),
                    state.enabled,
                ))
        })
    }

    pub(crate) const fn trigger_access_object(slot: usize) -> AccessObject {
        AccessObject {
            class: AccessClass::Trigger,
            slot: slot as u16,
        }
    }

    pub(crate) fn create_trigger(
        &mut self,
        spec: TriggerSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if !spec.is_valid() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "invalid trigger definition"
            ));
        }
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let same_identity = |trigger: &TriggerDef| {
            trigger.database == current_database()
                && trigger.target == spec.target
                && (trigger.name == spec.name
                    || trigger
                        .pending_definition
                        .is_some_and(|pending| pending.definition.name == spec.name))
        };
        if let Some(blocker) = catalog.definitions.iter().find_map(|trigger| {
            same_identity(trigger)
                .then(|| {
                    trigger
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| trigger.ddl_state.pending_txid())
                })
                .flatten()
                .filter(|owner| *owner != txid)
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, spec.name.as_str()));
        }
        if catalog
            .definitions
            .iter()
            .any(|trigger| same_identity(trigger) && trigger.visible_to(txid))
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "trigger \"{}\" for relation already exists",
                spec.name.as_str()
            ));
        }
        let Some(slot) = catalog
            .definitions
            .iter()
            .position(|trigger| trigger.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many triggers (limit {})",
                catalog.definitions.len()
            ));
        };
        let created_at = self
            .catalog_sequence
            .next_bounded(MAX_TRIGGER_OID_GENERATION, "trigger")?;
        catalog.definitions[slot] = TriggerDef {
            database: current_database(),
            created_at,
            name: spec.name,
            target: spec.target,
            kind: spec.kind,
            function: u16::try_from(spec.function).map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "routine slot exceeds trigger capacity"
                )
            })?,
            timing: spec.timing,
            level: spec.level,
            events: spec.events,
            update_columns: spec.update_columns,
            transition_tables: spec.transition_tables,
            when: spec.when,
            arguments: spec.arguments,
            enabled: TriggerEnabled::Origin,
            pending_definition: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn drop_trigger(&mut self, slot: usize, txid: u32) -> Result<(), SqlError> {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let trigger = catalog.definitions[slot];
        let blocker = trigger
            .pending_definition
            .map(|pending| pending.txid)
            .or_else(|| trigger.ddl_state.pending_txid())
            .filter(|owner| *owner != txid);
        if let Some(blocker) = blocker {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, trigger.name_to(txid).as_str()));
        }
        catalog.definitions[slot].ddl_state = trigger.ddl_state.drop_by(txid);
        Ok(())
    }

    pub(crate) fn alter_trigger(
        &mut self,
        slot: usize,
        name: SqlName,
        enabled: TriggerEnabled,
        txid: u32,
    ) -> Result<TriggerAlter, SqlError> {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let trigger = catalog.definitions[slot];
        let target_blocker = trigger
            .pending_definition
            .map(|pending| pending.txid)
            .or_else(|| trigger.ddl_state.pending_txid())
            .filter(|owner| *owner != txid);
        let name_blocker = catalog
            .definitions
            .iter()
            .enumerate()
            .find_map(|(other, candidate)| {
                (other != slot
                    && candidate.database == current_database()
                    && candidate.target == trigger.target
                    && (candidate.name == name
                        || candidate
                            .pending_definition
                            .is_some_and(|pending| pending.definition.name == name)))
                .then(|| {
                    candidate
                        .pending_definition
                        .map(|pending| pending.txid)
                        .or_else(|| candidate.ddl_state.pending_txid())
                })
                .flatten()
                .filter(|owner| *owner != txid)
            });
        if let Some(blocker) = target_blocker.or(name_blocker) {
            let name = catalog.definitions[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog
            .definitions
            .iter()
            .enumerate()
            .any(|(other, candidate)| {
                other != slot
                    && candidate.database == current_database()
                    && candidate.target == trigger.target
                    && candidate.visible_to(txid)
                    && candidate.name_to(txid) == name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "trigger \"{}\" for relation already exists",
                name.as_str()
            ));
        }
        let trigger = &mut catalog.definitions[slot];
        let mut definition = trigger.definition_to(txid);
        if definition.name == name && definition.enabled == enabled {
            return Ok(TriggerAlter::Unchanged);
        }
        let old_name = definition.name;
        let comment_subid = trigger.target.comment_subid();
        let prior = trigger.pending_definition;
        definition.name = name;
        definition.enabled = enabled;
        trigger.pending_definition = Some(PendingTriggerDefinition { txid, definition });
        drop(catalog);
        if old_name != name {
            self.stage_trigger_comment_rename(old_name, name, comment_subid, txid);
        }
        Ok(TriggerAlter::Changed { prior })
    }

    pub(crate) fn replace_trigger(
        &mut self,
        slot: usize,
        spec: TriggerSpec,
        txid: u32,
    ) -> Result<TriggerAlter, SqlError> {
        if !spec.is_valid() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "invalid replacement trigger definition"
            ));
        }
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        let trigger = catalog.definitions[slot];
        let blocker = trigger
            .pending_definition
            .map(|pending| pending.txid)
            .or_else(|| trigger.ddl_state.pending_txid())
            .filter(|owner| *owner != txid);
        if let Some(blocker) = blocker {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, trigger.name.as_str()));
        }
        if trigger.target != spec.target || !matches!(trigger.kind, TriggerKind::Ordinary) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "trigger \"{}\" for relation is a constraint trigger",
                spec.name.as_str()
            ));
        }
        let function = u16::try_from(spec.function).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "routine slot exceeds trigger capacity"
            )
        })?;
        let prior = trigger.pending_definition;
        catalog.definitions[slot].pending_definition = Some(PendingTriggerDefinition {
            txid,
            definition: TriggerDefinition {
                name: spec.name,
                kind: spec.kind,
                function,
                timing: spec.timing,
                level: spec.level,
                events: spec.events,
                update_columns: spec.update_columns,
                transition_tables: spec.transition_tables,
                when: spec.when,
                arguments: spec.arguments,
                enabled: TriggerEnabled::Origin,
            },
        });
        Ok(TriggerAlter::Changed { prior })
    }

    pub(crate) fn commit_trigger_alter(&mut self, slot: usize, txid: u32) {
        let changed = {
            let mut catalog = self
                .trigger_catalog
                .lock()
                .expect("trigger catalog lock poisoned");
            let trigger = &mut catalog.definitions[slot];
            trigger
                .pending_definition
                .filter(|pending| pending.txid == txid)
                .map(|pending| {
                    let old_name = trigger.name;
                    let new_name = pending.definition.name;
                    let subid = trigger.target.comment_subid();
                    trigger.apply_definition(pending.definition);
                    trigger.pending_definition = None;
                    (old_name, new_name, subid)
                })
        };
        if let Some((old_name, new_name, subid)) = changed {
            for comment in self.comment_catalog().entries.iter_mut().filter(|comment| {
                comment.used
                    && comment.class == CommentClass::Trigger
                    && comment.subid == subid
                    && ((old_name != new_name && comment.name == old_name)
                        || comment
                            .pending_identity
                            .is_some_and(|identity| identity.txid == txid))
            }) {
                if old_name != new_name {
                    comment.name = new_name;
                }
                comment.pending_identity = None;
            }
        }
    }

    pub(crate) fn rollback_trigger_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingTriggerDefinition>,
    ) {
        let (current, committed_name, subid) = {
            let mut catalog = self
                .trigger_catalog
                .lock()
                .expect("trigger catalog lock poisoned");
            let trigger = &mut catalog.definitions[slot];
            let values = (
                trigger.pending_definition,
                trigger.name,
                trigger.target.comment_subid(),
            );
            trigger.pending_definition = prior;
            values
        };
        let restored_name = prior
            .map(|pending| pending.definition.name)
            .unwrap_or(committed_name);
        if let Some(current) = current {
            for comment in self.comment_catalog().entries.iter_mut().filter(|comment| {
                comment.used
                    && comment.class == CommentClass::Trigger
                    && comment.subid == subid
                    && comment
                        .pending_identity
                        .is_some_and(|identity| identity.txid == current.txid)
            }) {
                comment.pending_identity =
                    (restored_name != comment.name).then_some(PendingCommentIdentity {
                        txid: current.txid,
                        schema: comment.schema,
                        name: restored_name,
                    });
            }
        }
    }

    pub(crate) fn commit_trigger_create(&mut self, slot: usize) {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_create();
    }

    pub(crate) fn restore_trigger(
        &mut self,
        created_at: u64,
        spec: TriggerSpec,
        enabled: TriggerEnabled,
    ) -> Result<usize, SqlError> {
        bounded_catalog_generation(created_at, MAX_TRIGGER_OID_GENERATION, "trigger")?;
        if !spec.is_valid() {
            return Err(sql_err!(
                sqlstate::INTERNAL_ERROR,
                "invalid trigger definition in checkpoint"
            ));
        }
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        if catalog
            .definitions
            .iter()
            .enumerate()
            .find_map(|(slot, trigger)| {
                if trigger.database != current_database() || !trigger.visible_to(0) {
                    return None;
                }
                (trigger.target == spec.target && trigger.name_to(0) == spec.name).then_some(slot)
            })
            .is_some()
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "duplicate trigger in checkpoint"
            ));
        }
        let Some(slot) = catalog
            .definitions
            .iter()
            .position(|trigger| trigger.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many triggers in checkpoint"
            ));
        };
        self.catalog_sequence.observe(created_at);
        catalog.definitions[slot] = TriggerDef {
            database: current_database(),
            created_at,
            name: spec.name,
            target: spec.target,
            kind: spec.kind,
            function: u16::try_from(spec.function).map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "routine slot exceeds trigger capacity"
                )
            })?,
            timing: spec.timing,
            level: spec.level,
            events: spec.events,
            update_columns: spec.update_columns,
            transition_tables: spec.transition_tables,
            when: spec.when,
            arguments: spec.arguments,
            enabled,
            pending_definition: None,
            ddl_state: CatalogDdlState::Present,
        };
        Ok(slot)
    }

    pub(crate) fn rollback_trigger_create(&mut self, slot: usize) {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.rollback_create();
        if catalog.definitions[slot].ddl_state == CatalogDdlState::Absent {
            catalog.definitions[slot] = TriggerDef::EMPTY;
        }
    }

    pub(crate) fn commit_trigger_drop(&mut self, slot: usize) {
        let trigger = self.trigger(slot);
        assert_eq!(trigger.ddl_state.commit_drop(), CatalogDdlState::Absent);
        self.clear_trigger_slot(slot);
        self.clear_trigger_dependents(slot, trigger);
    }

    fn clear_trigger_slot(&self, slot: usize) {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        catalog.definitions[slot] = TriggerDef::EMPTY;
        for state in catalog.partition_states.iter_mut() {
            if usize::from(state.trigger) == slot {
                *state = PartitionTriggerState::EMPTY;
            }
        }
    }

    fn clear_trigger_dependents(&mut self, slot: usize, trigger: TriggerDef) {
        self.clear_extension_dependencies_for_object(Self::trigger_access_object(slot));
        let mut comments = self.comment_catalog();
        for comment_slot in 0..comments.entries.len() {
            let comment = &comments.entries[comment_slot];
            if comment.used
                && comment.class == CommentClass::Trigger
                && comment.name == trigger.name
                && comment.subid == trigger.target.comment_subid()
            {
                comments.entries[comment_slot].live = None;
                comments.reap(comment_slot);
            }
        }
    }

    fn drop_trigger_comments_for_target(&mut self, target: TriggerTarget) {
        let subid = target.comment_subid();
        let mut comments = self.comment_catalog();
        for slot in 0..comments.entries.len() {
            let comment = &comments.entries[slot];
            if comment.used && comment.class == CommentClass::Trigger && comment.subid == subid {
                comments.entries[slot].live = None;
                comments.reap(slot);
            }
        }
    }

    /// Triggers are internal relation dependents. A committed table drop
    /// retires them in the same catalog transition.
    pub(crate) fn commit_triggers_for_table(&mut self, table: usize) {
        let target = TriggerTarget::Table(table as u16);
        self.drop_trigger_comments_for_target(target);
        let capacity = self.trigger_capacity();
        for slot in 0..capacity {
            let trigger = self.trigger(slot);
            if trigger.ddl_state != CatalogDdlState::Absent && trigger.target == target {
                self.clear_trigger_slot(slot);
                self.clear_trigger_dependents(slot, trigger);
            }
        }
    }

    pub(crate) fn commit_triggers_for_view(&mut self, view: usize) {
        let target = TriggerTarget::View(view as u16);
        self.drop_trigger_comments_for_target(target);
        let capacity = self.trigger_capacity();
        for slot in 0..capacity {
            let trigger = self.trigger(slot);
            if trigger.ddl_state != CatalogDdlState::Absent && trigger.target == target {
                self.clear_trigger_slot(slot);
                self.clear_trigger_dependents(slot, trigger);
            }
        }
    }

    pub(crate) fn rollback_trigger_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .trigger_catalog
            .lock()
            .expect("trigger catalog lock poisoned");
        catalog.definitions[slot].ddl_state =
            catalog.definitions[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn replay_create_routine(
        &mut self,
        mut definition: RoutineDef,
        dependencies: StoredQueryDependencies,
    ) -> Result<(), SqlError> {
        definition.ownership = definition.ownership.committed();
        if let Some(slot) = self.routine_slot_by_declared_signature(
            definition.schema.as_str(),
            definition.name.as_str(),
            definition.arguments(),
            0,
        ) {
            // CREATE OR REPLACE keeps its routine object identifier.  WAL uses
            // the complete post-change definition for both creates and
            // replacements, so the matching durable identity selects an
            // in-place replay rather than a drop/reallocate cycle.
            if self.routine(slot).created_at == definition.created_at {
                self.write_committed_dependencies(
                    StoredQueryDependencyOwner::Routine(slot as u16),
                    dependencies.view(),
                )?;
                definition.pending_identity = None;
                definition.pending_definition = None;
                definition.ddl_state = CatalogDdlState::Present;
                self.routines.lock().expect("routine catalog lock poisoned")[slot] = definition;
                return Ok(());
            }
            self.drop_routine(slot, 0);
            self.commit_routine_drop(slot);
        }
        let slot = self.create_routine(
            RoutineSpec {
                identity: RoutineIdentity::Preserve {
                    created_at: definition.created_at,
                    ownership: definition.ownership,
                },
                schema: definition.schema,
                name: definition.name,
                arguments: definition.arguments,
                argument_count: definition.argument_count,
                parameters: definition.parameters,
                parameter_count: definition.parameter_count,
                kind: definition.kind,
                result_columns: definition.result_columns,
                result_column_count: definition.result_column_count,
                language: definition.language,
                attributes: definition.attributes,
                configs: definition.configs,
                config_count: definition.config_count,
                body_kind: definition.body_kind,
                body: definition.body,
                creation_path: definition.creation_path,
                dependencies,
            },
            0,
        )?;
        self.commit_routine_create(slot, 0);
        Ok(())
    }

    pub(crate) fn extended_statistics_count(&self) -> usize {
        self.extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions
            .len()
    }

    pub(crate) fn extended_statistics(&self, slot: usize) -> ExtendedStatisticsDef {
        self.extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions[slot]
    }

    pub(crate) fn extended_statistics_visible(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ExtendedStatisticsDef)> + '_ {
        ExtendedStatisticsIter {
            catalog: &self.extended_statistics_catalog,
            next_slot: 0,
        }
        .filter(move |(_, statistics)| {
            statistics.database == current_database() && statistics.visible_to(txid)
        })
    }

    pub(crate) fn extended_statistics_for_table(
        &self,
        table: usize,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ExtendedStatisticsDef)> + '_ {
        self.extended_statistics_visible(txid)
            .filter(move |(_, statistics)| usize::from(statistics.table) == table)
    }

    pub(crate) fn extended_statistics_slot(
        &self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        self.extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions
            .iter()
            .position(|statistics| {
                let definition = statistics.definition_for(txid);
                statistics.database == current_database()
                    && statistics.visible_to(txid)
                    && definition.schema.as_str() == schema
                    && definition.name.as_str() == name
            })
    }

    pub(crate) fn extended_statistics_slot_on_path(
        &self,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        if let Some(schema) = schema {
            return self.extended_statistics_slot(schema, name, txid);
        }
        self.path().entries().iter().find_map(|entry| match entry {
            PathEntry::Schema(slot) => self.extended_statistics_slot(
                self.schema_def(*slot as usize).name.as_str(),
                name,
                txid,
            ),
            PathEntry::Catalog => None,
        })
    }

    pub(crate) fn require_extended_statistics_mutation(
        &self,
        slot: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        let statistics = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions[slot];
        let Some(blocker) = statistics.pending_owner_other_than(txid) else {
            return Ok(());
        };
        Err(self.catalog_ddl_wait_error(
            txid,
            blocker,
            statistics.definition_for(txid).name.as_str(),
        ))
    }

    pub(crate) fn create_extended_statistics(
        &mut self,
        spec: ExtendedStatisticsSpec,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.require_schema_create(spec.schema.as_str(), txid)?;
        if usize::from(spec.table) >= self.tables.len()
            || !self.tables[usize::from(spec.table)].visible_to(txid)
        {
            return Err(sql_err!(
                sqlstate::UNDEFINED_TABLE,
                "statistics relation does not exist"
            ));
        }
        if spec.n_keys == 0 || usize::from(spec.n_keys) > MAX_EXTENDED_STATISTICS_KEYS {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "invalid extended statistics key count"
            ));
        }
        let ownership = self.initial_ownership(txid);
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        if let Some(blocker) = catalog.definitions.iter().find_map(|statistics| {
            (statistics.database == current_database()
                && statistics.identity_matches(spec.schema, spec.name))
            .then(|| statistics.pending_owner_other_than(txid))
            .flatten()
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, spec.name.as_str()));
        }
        if catalog.definitions.iter().any(|statistics| {
            let definition = statistics.definition_for(txid);
            statistics.database == current_database()
                && statistics.visible_to(txid)
                && definition.schema == spec.schema
                && definition.name == spec.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "statistics object \"{}\" already exists",
                spec.name.as_str()
            ));
        }
        let Some(slot) = catalog
            .definitions
            .iter()
            .position(|statistics| statistics.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many statistics objects (limit {})",
                catalog.definitions.len()
            ));
        };
        let created_at = if spec.created_at == 0 {
            self.catalog_sequence.next()
        } else {
            self.catalog_sequence.observe(spec.created_at);
            spec.created_at
        };
        catalog.definitions[slot] = ExtendedStatisticsDef {
            database: current_database(),
            created_at,
            table: spec.table,
            mutable: ExtendedStatisticsMutableDefinition {
                schema: spec.schema,
                name: spec.name,
                target: spec.target,
            },
            pending_definition: None,
            pending_keys: None,
            ownership,
            keys: spec.keys,
            n_keys: spec.n_keys,
            kinds: spec.kinds,
            expression_only: spec.expression_only,
            data: ExtendedStatisticsData::EMPTY,
            pending_data_tail: None,
            pending_data_txid: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn alter_extended_statistics(
        &mut self,
        slot: usize,
        definition: ExtendedStatisticsMutableDefinition,
        txid: u32,
    ) -> Result<Option<PendingExtendedStatisticsDefinition>, SqlError> {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = catalog.definitions[slot];
        let target_blocker = statistics.pending_owner_other_than(txid);
        let name_blocker = catalog
            .definitions
            .iter()
            .enumerate()
            .find_map(|(other, candidate)| {
                (other != slot
                    && candidate.database == current_database()
                    && candidate.identity_matches(definition.schema, definition.name))
                .then(|| candidate.pending_owner_other_than(txid))
                .flatten()
            });
        if let Some(blocker) = target_blocker.or(name_blocker) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(
                txid,
                blocker,
                statistics.definition_for(txid).name.as_str(),
            ));
        }
        if catalog
            .definitions
            .iter()
            .enumerate()
            .any(|(other, candidate)| {
                let candidate_definition = candidate.definition_for(txid);
                other != slot
                    && candidate.database == current_database()
                    && candidate.visible_to(txid)
                    && candidate_definition.schema == definition.schema
                    && candidate_definition.name == definition.name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "statistics object \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        let statistics = &mut catalog.definitions[slot];
        let prior = statistics.pending_definition;
        statistics.pending_definition =
            Some(PendingExtendedStatisticsDefinition { txid, definition });
        Ok(prior)
    }

    pub(crate) fn alter_extended_statistics_keys(
        &mut self,
        slot: usize,
        keys: [ExtendedStatisticsKey; MAX_EXTENDED_STATISTICS_KEYS],
        txid: u32,
    ) -> Result<Option<PendingExtendedStatisticsKeys>, SqlError> {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let blocker = catalog.definitions[slot].pending_owner_other_than(txid);
        if let Some(blocker) = blocker {
            let name = catalog.definitions[slot].definition_for(txid).name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let statistics = &mut catalog.definitions[slot];
        let prior = statistics.pending_keys;
        statistics.pending_keys = Some(PendingExtendedStatisticsKeys { txid, keys });
        Ok(prior)
    }

    pub(crate) fn commit_extended_statistics_create(&mut self, slot: usize) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.commit_create();
    }

    pub(crate) fn rollback_extended_statistics_create(&mut self, slot: usize) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        Self::clear_pending_extended_statistics_data(&mut catalog, slot);
        catalog.definitions[slot].pending_keys = None;
        catalog.definitions[slot].ddl_state = catalog.definitions[slot].ddl_state.rollback_create();
        if catalog.definitions[slot].ddl_state == CatalogDdlState::Absent {
            catalog.definitions[slot] = ExtendedStatisticsDef::EMPTY;
        }
    }

    pub(crate) fn commit_extended_statistics_alter(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = &mut catalog.definitions[slot];
        if let Some(pending) = statistics.pending_definition
            && pending.txid == txid
        {
            statistics.mutable = pending.definition;
            statistics.pending_definition = None;
        }
        if let Some(pending) = statistics.pending_keys
            && pending.txid == txid
        {
            statistics.keys = pending.keys;
            statistics.pending_keys = None;
        }
    }

    pub(crate) fn rollback_extended_statistics_alter(
        &mut self,
        slot: usize,
        prior: Option<PendingExtendedStatisticsDefinition>,
    ) {
        self.extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions[slot]
            .pending_definition = prior;
    }

    pub(crate) fn rollback_extended_statistics_keys(
        &mut self,
        slot: usize,
        prior: Option<PendingExtendedStatisticsKeys>,
    ) {
        self.extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned")
            .definitions[slot]
            .pending_keys = prior;
    }

    pub(crate) fn drop_extended_statistics(
        &mut self,
        slot: usize,
        txid: u32,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = catalog.definitions[slot];
        let blocker = statistics.pending_owner_other_than(txid);
        if let Some(blocker) = blocker {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(
                txid,
                blocker,
                statistics.definition_for(txid).name.as_str(),
            ));
        }
        catalog.definitions[slot].ddl_state = statistics.ddl_state.drop_by(txid);
        Ok(())
    }

    pub(crate) fn commit_extended_statistics_drop(&mut self, slot: usize) {
        assert!(matches!(
            self.extended_statistics(slot).ddl_state,
            CatalogDdlState::PendingDrop { .. }
        ));
        self.retire_extended_statistics(slot);
    }

    fn retire_extended_statistics(&mut self, slot: usize) {
        {
            let mut catalog = self
                .extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned");
            Self::clear_pending_extended_statistics_data(&mut catalog, slot);
            catalog.definitions[slot] = ExtendedStatisticsDef::EMPTY;
        }
        self.drop_comments_by_subid(CommentClass::Statistics, slot as u32);
    }

    fn commit_extended_statistics_for_table(&mut self, table: usize) {
        let capacity = self.extended_statistics_count();
        for slot in 0..capacity {
            // A PendingDrop has its own DdlUndo entry and must be promoted by
            // that entry. This path owns only unstaged internal dependents,
            // such as statistics swept up by direct journal replay.
            let statistics = self.extended_statistics(slot);
            if statistics.ddl_state == CatalogDdlState::Present
                && usize::from(statistics.table) == table
            {
                self.retire_extended_statistics(slot);
            }
        }
    }

    pub(crate) fn rollback_extended_statistics_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        catalog.definitions[slot].ddl_state =
            catalog.definitions[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn extended_statistics_data(
        &self,
        slot: usize,
        txid: u32,
    ) -> ExtendedStatisticsData {
        let catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = &catalog.definitions[slot];
        if statistics.pending_data_txid == Some(txid)
            && let Some(pending) = statistics.pending_data_tail
        {
            return catalog.pending_data[pending as usize].data;
        }
        statistics.data
    }

    pub(crate) fn pending_extended_statistics_data_for(
        &self,
        slot: usize,
        txid: u32,
    ) -> Option<ExtendedStatisticsData> {
        let catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = &catalog.definitions[slot];
        (statistics.pending_data_txid == Some(txid)).then(|| {
            statistics
                .pending_data_tail
                .map_or(statistics.data, |pending| {
                    catalog.pending_data[pending as usize].data
                })
        })
    }

    pub(crate) fn write_extended_statistics_data(
        &mut self,
        slot: usize,
        txid: u32,
        data: ExtendedStatisticsData,
    ) -> Result<(), SqlError> {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = catalog.definitions[slot];
        if statistics.pending_owner_other_than(txid).is_some() {
            return Err(sql_err!(
                sqlstate::SERIALIZATION_FAILURE,
                "could not serialize ANALYZE of statistics object \"{}\"",
                statistics.definition_for(txid).name.as_str()
            ));
        }
        let previous = statistics.pending_data_tail;
        if previous.is_some_and(|pending| {
            catalog.pending_data[pending as usize].depth >= self.max_catalog_versions_per_object
        }) {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "statistics object \"{}\" exceeds max_catalog_versions_per_object ({})",
                statistics.definition_for(txid).name.as_str(),
                self.max_catalog_versions_per_object
            ));
        }
        let depth = previous.map_or(1, |pending| {
            catalog.pending_data[pending as usize].depth + 1
        });
        let pending = match catalog.pending_data.iter().position(|entry| !entry.used) {
            Some(pending) => {
                catalog.pending_data[pending] = PendingExtendedStatisticsDataSlot {
                    used: true,
                    previous,
                    depth,
                    data,
                };
                pending
            }
            None => {
                let pending = catalog.pending_data.len();
                catalog
                    .pending_data
                    .push(PendingExtendedStatisticsDataSlot {
                        used: true,
                        previous,
                        depth,
                        data,
                    })
                    .map_err(|_| {
                        sql_err!(
                            sqlstate::PROGRAM_LIMIT_EXCEEDED,
                            "pending extended-statistics pool is exhausted"
                        )
                    })?;
                pending
            }
        };
        let statistics = &mut catalog.definitions[slot];
        statistics.pending_data_tail = Some(pending as u32);
        statistics.pending_data_txid = Some(txid);
        Ok(())
    }

    pub(crate) fn rollback_extended_statistics_data(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        let statistics = catalog.definitions[slot];
        if statistics.pending_data_txid != Some(txid) {
            return;
        }
        let Some(pending) = statistics.pending_data_tail else {
            return;
        };
        let previous = catalog.pending_data[pending as usize].previous;
        catalog.pending_data[pending as usize].used = false;
        let statistics = &mut catalog.definitions[slot];
        statistics.pending_data_tail = previous;
        if previous.is_none() {
            statistics.pending_data_txid = None;
        }
    }

    fn clear_pending_extended_statistics_data(
        catalog: &mut ExtendedStatisticsCatalog,
        slot: usize,
    ) {
        let mut tail = catalog.definitions[slot].pending_data_tail.take();
        while let Some(pending) = tail {
            let entry = &mut catalog.pending_data[pending as usize];
            tail = entry.previous;
            entry.used = false;
        }
        catalog.definitions[slot].pending_data_txid = None;
    }

    pub(crate) fn commit_extended_statistics_data(&mut self, slot: usize, txid: u32) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        if catalog.definitions[slot].pending_data_txid != Some(txid) {
            return;
        }
        let data = catalog.definitions[slot]
            .pending_data_tail
            .map_or(catalog.definitions[slot].data, |pending| {
                catalog.pending_data[pending as usize].data
            });
        catalog.definitions[slot].data = data;
        Self::clear_pending_extended_statistics_data(&mut catalog, slot);
    }

    pub(crate) fn install_extended_statistics_data(
        &mut self,
        slot: usize,
        data: ExtendedStatisticsData,
    ) {
        let mut catalog = self
            .extended_statistics_catalog
            .lock()
            .expect("extended-statistics catalog lock poisoned");
        Self::clear_pending_extended_statistics_data(&mut catalog, slot);
        catalog.definitions[slot].data = data;
    }

    pub(crate) fn replay_extended_statistics(
        &mut self,
        spec: ExtendedStatisticsSpec,
    ) -> Result<usize, SqlError> {
        {
            let mut catalog = self
                .extended_statistics_catalog
                .lock()
                .expect("extended-statistics catalog lock poisoned");
            if let Some(slot) = catalog.definitions.iter().position(|statistics| {
                statistics.ddl_state != CatalogDdlState::Absent
                    && statistics.created_at == spec.created_at
            }) {
                if catalog
                    .definitions
                    .iter()
                    .enumerate()
                    .any(|(other, statistics)| {
                        other != slot
                            && statistics.ddl_state != CatalogDdlState::Absent
                            && statistics.mutable.schema == spec.schema
                            && statistics.mutable.name == spec.name
                    })
                {
                    return Err(sql_err!(
                        sqlstate::DUPLICATE_OBJECT,
                        "journal replays duplicate statistics object \"{}\"",
                        spec.name.as_str()
                    ));
                }
                Self::clear_pending_extended_statistics_data(&mut catalog, slot);
                let statistics = &mut catalog.definitions[slot];
                statistics.table = spec.table;
                statistics.mutable = ExtendedStatisticsMutableDefinition {
                    schema: spec.schema,
                    name: spec.name,
                    target: spec.target,
                };
                statistics.pending_definition = None;
                statistics.pending_keys = None;
                statistics.keys = spec.keys;
                statistics.n_keys = spec.n_keys;
                statistics.kinds = spec.kinds;
                statistics.expression_only = spec.expression_only;
                statistics.ddl_state = CatalogDdlState::Present;
                return Ok(slot);
            }
        }
        let slot = self.create_extended_statistics(spec, 0)?;
        self.commit_extended_statistics_create(slot);
        Ok(slot)
    }

    pub(crate) fn replay_drop_extended_statistics(
        &mut self,
        schema: &str,
        name: &str,
    ) -> Result<(), SqlError> {
        let Some(slot) = self.extended_statistics_slot(schema, name, 0) else {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "journal drops unknown statistics object \"{}\"",
                name
            ));
        };
        self.drop_extended_statistics(slot, 0)?;
        self.commit_extended_statistics_drop(slot);
        Ok(())
    }

    pub fn index_exists(&self, schema: &str, name: &str, txid: u32) -> bool {
        self.index_slot(schema, name, txid).is_some()
    }

    pub(crate) fn index_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        let slot = self.index_catalog().iter().position(|index| {
            index.database == current_database()
                && index.visible_to(txid)
                && index.schema.as_str() == schema
                && index.name_for(txid).as_str() == name
        });
        if slot.is_some_and(|slot| {
            self.index_table_slot_to(slot, txid).is_some_and(|table| {
                self.table_def(table, txid).persistence == RelationPersistence::Temporary
            })
        }) {
            self.mark_temporary_transaction(txid);
        }
        slot
    }

    /// Resolves an index through PostgreSQL's relation search order. Temporary
    /// indexes share their table's virtual, session-local namespace.
    pub(crate) fn resolve_index_slot(
        &self,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        if let Some(schema) = schema {
            if schema == "pg_temp" {
                let temporary = self.temporary_schema().ok()?;
                return self.index_slot(temporary.as_str(), name, txid);
            }
            if schema.starts_with("pg_temp_") && !self.is_current_temporary_schema(schema) {
                return None;
            }
            return self.index_slot(schema, name, txid);
        }
        if let Ok(temporary) = self.temporary_schema()
            && let Some(slot) = self.index_slot(temporary.as_str(), name, txid)
        {
            return Some(slot);
        }
        self.path().entries().iter().find_map(|entry| match entry {
            PathEntry::Schema(slot) => {
                self.index_slot(self.schema_def(*slot as usize).name.as_str(), name, txid)
            }
            PathEntry::Catalog => None,
        })
    }

    /// The transaction-visible index definition. Returning the copy keeps a
    /// caller from retaining a catalog borrow across cache reconstruction.
    pub fn index_definition(&self, schema: &str, name: &str, txid: u32) -> Option<IndexDef> {
        let index = self
            .index_catalog()
            .iter()
            .find(|index| {
                index.database == current_database()
                    && index.visible_to(txid)
                    && index.schema.as_str() == schema
                    && index.name_for(txid).as_str() == name
            })
            .copied();
        if let Some(index) = index
            && self
                .find_visible(index.schema.as_str(), index.table.as_str(), txid)
                .is_some_and(|table| {
                    self.table_def(table, txid).persistence == RelationPersistence::Temporary
                })
        {
            self.mark_temporary_transaction(txid);
        }
        index
    }

    pub(crate) fn rename_index(
        &mut self,
        slot: usize,
        name: SqlName,
        txid: u32,
    ) -> Result<Option<PendingIndexName>, SqlError> {
        let image = self.index(slot);
        if self
            .non_index_relation_kind_in(image.schema.as_str(), name.as_str(), txid)
            .is_some()
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                name.as_str()
            ));
        }
        let mut catalog = self.index_catalog();
        let index = catalog[slot];
        if !index.visible_to(txid) {
            return Err(sql_err!(sqlstate::UNDEFINED_OBJECT, "index does not exist"));
        }
        if index.name_for(txid) == name {
            return Ok(index.pending_name);
        }
        if let Some(blocker) = catalog.iter().enumerate().find_map(|(other, candidate)| {
            (other != slot
                && candidate.database == index.database
                && candidate.schema == index.schema)
                .then(|| candidate.name_blocker(name, txid))
                .flatten()
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if catalog.iter().enumerate().any(|(other, candidate)| {
            other != slot
                && candidate.database == index.database
                && candidate.visible_to(txid)
                && candidate.schema == index.schema
                && candidate.name_for(txid) == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                name.as_str()
            ));
        }
        let index = &mut catalog[slot];
        if let Some(pending) = index.pending_name
            && pending.txid != txid
        {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "index \"{}\" is being renamed by another transaction",
                index.name.as_str()
            ));
        }
        let prior = index.pending_name;
        index.pending_name = Some(PendingIndexName { txid, name });
        Ok(prior)
    }

    pub(crate) fn commit_index_rename(&mut self, slot: usize, txid: u32) {
        let (database, schema, old_name, new_name) = {
            let mut catalog = self.index_catalog();
            let index = &mut catalog[slot];
            let Some(pending) = index.pending_name else {
                return;
            };
            if pending.txid != txid {
                return;
            }
            let old_name = index.name;
            index.name = pending.name;
            index.pending_name = None;
            (Some(index.database), index.schema, old_name, pending.name)
        };
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.database == database
                && comment.class == CommentClass::Relation
                && comment.schema == schema
                && comment.name == old_name
            {
                comment.name = new_name;
            }
        }
        if let Some(table) = self.index_table_slot(slot) {
            self.tables[table].mark_dirty();
        }
    }

    pub(crate) fn rollback_index_rename(&mut self, slot: usize, prior: Option<PendingIndexName>) {
        self.index_catalog()[slot].pending_name = prior;
    }

    /// Registers an index as an uncommitted CREATE owned by `def.pending`'s
    /// transaction; returns its slot. Errors on a duplicate visible name or
    /// another transaction's uncommitted DDL on the name.
    pub fn create_index(&self, mut def: IndexDef, txid: u32) -> Result<usize, SqlError> {
        let created_at = (def.created_at != 0)
            .then(|| bounded_catalog_generation(def.created_at, MAX_INDEX_OID_GENERATION, "index"))
            .transpose()?;
        def.database = current_database();
        self.require_schema_create(def.schema.as_str(), txid)?;
        match def.method {
            crate::sql::ast::IndexAccessMethod::Btree => {
                if def.mutable.options.pages_per_range.is_some()
                    || def.mutable.options.autosummarize.is_some()
                    || def.mutable.options.buffering.is_some()
                    || def.mutable.options.fastupdate.is_some()
                    || def.mutable.options.gin_pending_list_limit.is_some()
                    || def.operator_class_options[..def.n_cols]
                        .iter()
                        .any(|options| !options.is_empty())
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| {
                            matches!(
                                class,
                                Some(
                                    IndexOperatorClass::Hash(_)
                                        | IndexOperatorClass::Brin(_)
                                        | IndexOperatorClass::Gist(_)
                                        | IndexOperatorClass::Gin(_)
                                        | IndexOperatorClass::SpGist(_)
                                )
                            )
                        })
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "btree index has a non-btree operator class"
                    ));
                }
            }
            crate::sql::ast::IndexAccessMethod::Hash => {
                if def.unique
                    || def.mutable.options.deduplicate_items.is_some()
                    || def.mutable.options.pages_per_range.is_some()
                    || def.mutable.options.autosummarize.is_some()
                    || def.mutable.options.buffering.is_some()
                    || def.mutable.options.fastupdate.is_some()
                    || def.mutable.options.gin_pending_list_limit.is_some()
                    || def.n_cols != 1
                    || def.n_include_cols != 0
                    || def.descending[..def.n_cols].iter().any(|value| *value)
                    || def.nulls_first[..def.n_cols].iter().any(|value| *value)
                    || def.operator_class_options[..def.n_cols]
                        .iter()
                        .any(|options| !options.is_empty())
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| !matches!(class, Some(IndexOperatorClass::Hash(_))))
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "hash index definition has unsupported key semantics"
                    ));
                }
            }
            crate::sql::ast::IndexAccessMethod::Brin => {
                if def.unique
                    || def.mutable.options.fillfactor.is_some()
                    || def.mutable.options.deduplicate_items.is_some()
                    || def.mutable.options.buffering.is_some()
                    || def.mutable.options.fastupdate.is_some()
                    || def.mutable.options.gin_pending_list_limit.is_some()
                    || def
                        .mutable
                        .options
                        .pages_per_range
                        .is_some_and(|value| !(1..=131_072).contains(&value))
                    || def.n_include_cols != 0
                    || def.descending[..def.n_cols].iter().any(|value| *value)
                    || def.nulls_first[..def.n_cols].iter().any(|value| *value)
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| !matches!(class, Some(IndexOperatorClass::Brin(_))))
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .zip(&def.operator_class_options[..def.n_cols])
                        .any(|(class, options)| match class {
                            Some(IndexOperatorClass::Brin(class)) => match class.kind() {
                                crate::sql::types::BrinOperatorClassKind::MinmaxMulti => {
                                    options.n_distinct_per_range.is_some()
                                        || options.false_positive_rate.is_some()
                                }
                                crate::sql::types::BrinOperatorClassKind::Bloom => {
                                    options.values_per_range.is_some()
                                }
                                crate::sql::types::BrinOperatorClassKind::Minmax
                                | crate::sql::types::BrinOperatorClassKind::Inclusion => {
                                    !options.is_empty()
                                }
                            },
                            _ => true,
                        })
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "brin index definition has unsupported key semantics"
                    ));
                }
            }
            crate::sql::ast::IndexAccessMethod::Gist => {
                if def.unique
                    || def.mutable.options.deduplicate_items.is_some()
                    || def.mutable.options.pages_per_range.is_some()
                    || def.mutable.options.autosummarize.is_some()
                    || def.mutable.options.fastupdate.is_some()
                    || def.mutable.options.gin_pending_list_limit.is_some()
                    || def.descending[..def.n_cols].iter().any(|value| *value)
                    || def.nulls_first[..def.n_cols].iter().any(|value| *value)
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| !matches!(class, Some(IndexOperatorClass::Gist(_))))
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .zip(&def.operator_class_options[..def.n_cols])
                        .any(|(class, options)| match class {
                            Some(IndexOperatorClass::Gist(
                                crate::sql::types::GistOperatorClass::TsVector,
                            )) => {
                                options.values_per_range.is_some()
                                    || options.n_distinct_per_range.is_some()
                                    || options.false_positive_rate.is_some()
                            }
                            Some(IndexOperatorClass::Gist(_)) => !options.is_empty(),
                            _ => true,
                        })
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "gist index definition has unsupported key semantics"
                    ));
                }
            }
            crate::sql::ast::IndexAccessMethod::Gin => {
                if def.unique
                    || def.mutable.options.fillfactor.is_some()
                    || def.mutable.options.deduplicate_items.is_some()
                    || def.mutable.options.pages_per_range.is_some()
                    || def.mutable.options.autosummarize.is_some()
                    || def.mutable.options.buffering.is_some()
                    || def
                        .mutable
                        .options
                        .gin_pending_list_limit
                        .is_some_and(|value| !(64..=i32::MAX as u32).contains(&value))
                    || def.n_include_cols != 0
                    || def.descending[..def.n_cols].iter().any(|value| *value)
                    || def.nulls_first[..def.n_cols].iter().any(|value| *value)
                    || def.operator_class_options[..def.n_cols]
                        .iter()
                        .any(|options| !options.is_empty())
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| !matches!(class, Some(IndexOperatorClass::Gin(_))))
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "gin index definition has unsupported key semantics"
                    ));
                }
            }
            crate::sql::ast::IndexAccessMethod::SpGist => {
                if def.unique
                    || def.mutable.options.deduplicate_items.is_some()
                    || def.mutable.options.pages_per_range.is_some()
                    || def.mutable.options.autosummarize.is_some()
                    || def.mutable.options.buffering.is_some()
                    || def.mutable.options.fastupdate.is_some()
                    || def.mutable.options.gin_pending_list_limit.is_some()
                    || def.n_cols != 1
                    || def.descending[..def.n_cols].iter().any(|value| *value)
                    || def.nulls_first[..def.n_cols].iter().any(|value| *value)
                    || def.operator_class_options[..def.n_cols]
                        .iter()
                        .any(|options| !options.is_empty())
                    || def.resolved_operator_classes[..def.n_cols]
                        .iter()
                        .any(|class| !matches!(class, Some(IndexOperatorClass::SpGist(_))))
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_OBJECT_DEFINITION,
                        "spgist index definition has unsupported key semantics"
                    ));
                }
            }
        }
        if def.mutable.clustered && !matches!(def.mutable.kind, IndexKind::Ordinary) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "partitioned index cannot be selected for clustering"
            ));
        }
        if def.mutable.replica_identity && !matches!(def.mutable.kind, IndexKind::Ordinary) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "partitioned index cannot be selected as replica identity"
            ));
        }
        let brin_summarized_until_page = if def.method == crate::sql::ast::IndexAccessMethod::Brin {
            let table = self
                .find_visible(def.schema.as_str(), def.table.as_str(), txid)
                .ok_or_else(|| {
                    sql_err!(
                        sqlstate::UNDEFINED_TABLE,
                        "relation \"{}\" does not exist",
                        def.table.as_str()
                    )
                })?;
            // PostgreSQL's freshly built empty BRIN index already owns the
            // first heap range; inserts into that range update its summary
            // rather than making it a newly unsummarized range.
            let pages = (self.visible_row_count(table, txid)? as u64)
                .div_ceil(128)
                .max(1);
            let pages_per_range = u64::from(def.mutable.options.pages_per_range.unwrap_or(128));
            pages.div_ceil(pages_per_range) * pages_per_range
        } else {
            0
        };
        let ownership = self.initial_ownership(txid);
        if self
            .non_index_relation_kind_in(def.schema.as_str(), def.name.as_str(), txid)
            .is_some()
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                def.name.as_str()
            ));
        }
        let mut catalog = self.index_catalog();
        if def.mutable.clustered
            && catalog.iter().any(|index| {
                index.database == current_database()
                    && index.visible_to(txid)
                    && index.schema == def.schema
                    && index.table == def.table
                    && index.mutable_for(txid).clustered
            })
        {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "relation already has a clustered index"
            ));
        }
        if def.mutable.replica_identity
            && catalog.iter().any(|index| {
                index.database == current_database()
                    && index.visible_to(txid)
                    && index.schema == def.schema
                    && index.table == def.table
                    && index.mutable_for(txid).replica_identity
            })
        {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "relation already has a replica identity index"
            ));
        }
        if let Some(blocker) = catalog.iter().find_map(|index| {
            (index.database == def.database && index.schema == def.schema)
                .then(|| index.name_blocker(def.name, txid))
                .flatten()
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, def.name.as_str()));
        }
        if catalog.iter().any(|index| {
            index.database == def.database
                && index.visible_to(txid)
                && index.schema == def.schema
                && index.name_for(txid) == def.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_TABLE,
                "relation \"{}\" already exists",
                def.name.as_str()
            ));
        }
        let Some(i) = catalog
            .iter()
            .position(|x| x.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many indexes (limit {})",
                self.index_count()
            ));
        };
        let created_at = match created_at {
            Some(created_at) => {
                self.catalog_sequence.observe(created_at);
                created_at
            }
            None => self
                .catalog_sequence
                .next_bounded(MAX_INDEX_OID_GENERATION, "index")?,
        };
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) =
            Self::brin_entry_mut(&mut maintenance, i, self.brin_unsummarized_ranges_per_index);
        *state = BrinMaintenanceState {
            index_created_at: created_at,
            pages_per_range: def.mutable.options.pages_per_range.unwrap_or(128),
            summarized_until_page: brin_summarized_until_page,
            ..BrinMaintenanceState::EMPTY
        };
        ranges.fill(0);
        drop(maintenance);
        catalog[i] = IndexDef {
            created_at,
            ownership,
            pending_definition: None,
            pending_name: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
            ..def
        };
        Ok(i)
    }

    pub(crate) fn alter_index_definition(
        &mut self,
        slot: usize,
        definition: IndexMutableDefinition,
        txid: u32,
    ) -> Result<Option<PendingIndexDefinition>, SqlError> {
        let mut catalog = self.index_catalog();
        let options_valid = match catalog[slot].method {
            crate::sql::ast::IndexAccessMethod::Btree => {
                definition.options.pages_per_range.is_none()
                    && definition.options.autosummarize.is_none()
                    && definition.options.buffering.is_none()
                    && definition.options.fastupdate.is_none()
                    && definition.options.gin_pending_list_limit.is_none()
            }
            crate::sql::ast::IndexAccessMethod::Hash => {
                definition.options.deduplicate_items.is_none()
                    && definition.options.pages_per_range.is_none()
                    && definition.options.autosummarize.is_none()
                    && definition.options.buffering.is_none()
                    && definition.options.fastupdate.is_none()
                    && definition.options.gin_pending_list_limit.is_none()
            }
            crate::sql::ast::IndexAccessMethod::Brin => {
                definition.options.fillfactor.is_none()
                    && definition.options.deduplicate_items.is_none()
                    && definition.options.buffering.is_none()
                    && definition.options.fastupdate.is_none()
                    && definition.options.gin_pending_list_limit.is_none()
                    && definition
                        .options
                        .pages_per_range
                        .is_none_or(|value| (1..=131_072).contains(&value))
            }
            crate::sql::ast::IndexAccessMethod::Gist => {
                definition.options.deduplicate_items.is_none()
                    && definition.options.pages_per_range.is_none()
                    && definition.options.autosummarize.is_none()
                    && definition.options.fastupdate.is_none()
                    && definition.options.gin_pending_list_limit.is_none()
            }
            crate::sql::ast::IndexAccessMethod::Gin => {
                definition.options.fillfactor.is_none()
                    && definition.options.deduplicate_items.is_none()
                    && definition.options.pages_per_range.is_none()
                    && definition.options.autosummarize.is_none()
                    && definition.options.buffering.is_none()
                    && definition
                        .options
                        .gin_pending_list_limit
                        .is_none_or(|value| (64..=i32::MAX as u32).contains(&value))
            }
            crate::sql::ast::IndexAccessMethod::SpGist => {
                definition.options.deduplicate_items.is_none()
                    && definition.options.pages_per_range.is_none()
                    && definition.options.autosummarize.is_none()
                    && definition.options.buffering.is_none()
                    && definition.options.fastupdate.is_none()
                    && definition.options.gin_pending_list_limit.is_none()
            }
        };
        if !options_valid {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "index definition has storage parameters for another access method"
            ));
        }
        if definition.clustered
            && matches!(
                catalog[slot].method,
                crate::sql::ast::IndexAccessMethod::Hash
                    | crate::sql::ast::IndexAccessMethod::Brin
                    | crate::sql::ast::IndexAccessMethod::Gist
                    | crate::sql::ast::IndexAccessMethod::Gin
                    | crate::sql::ast::IndexAccessMethod::SpGist
            )
        {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::FEATURE_NOT_SUPPORTED,
                "cannot cluster on index \"{}\" because access method does not support clustering",
                catalog[slot].name.as_str()
            ));
        }
        if definition.clustered && !matches!(definition.kind, IndexKind::Ordinary) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "partitioned index cannot be selected for clustering"
            ));
        }
        if definition.replica_identity && !matches!(definition.kind, IndexKind::Ordinary) {
            return Err(sql_err!(
                crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                "partitioned index cannot be selected as replica identity"
            ));
        }
        let pending = catalog[slot].pending_definition;
        if let Some(pending) = pending
            && pending.txid != txid
        {
            let name = catalog[slot].name;
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, pending.txid, name.as_str()));
        }
        if definition.clustered {
            let index = catalog[slot];
            if catalog.iter().enumerate().any(|(other_slot, other)| {
                other_slot != slot
                    && other.database == current_database()
                    && other.visible_to(txid)
                    && other.schema == index.schema
                    && other.table == index.table
                    && other.mutable_for(txid).clustered
            }) {
                return Err(sql_err!(
                    crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                    "relation already has a clustered index"
                ));
            }
        }
        if definition.replica_identity {
            let index = catalog[slot];
            if catalog.iter().enumerate().any(|(other_slot, other)| {
                other_slot != slot
                    && other.database == current_database()
                    && other.visible_to(txid)
                    && other.schema == index.schema
                    && other.table == index.table
                    && other.mutable_for(txid).replica_identity
            }) {
                return Err(sql_err!(
                    crate::sql::eval::sqlstate::INVALID_OBJECT_DEFINITION,
                    "relation already has a replica identity index"
                ));
            }
        }
        let index = &mut catalog[slot];
        let prior = index.pending_definition;
        index.pending_definition = Some(PendingIndexDefinition { txid, definition });
        Ok(prior)
    }

    pub(crate) fn commit_index_definition(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.index_catalog();
        let index = &mut catalog[slot];
        if let Some(pending) = index.pending_definition
            && pending.txid == txid
        {
            index.mutable = pending.definition;
            index.pending_definition = None;
        }
    }

    pub(crate) fn rollback_index_definition(
        &mut self,
        slot: usize,
        prior: Option<PendingIndexDefinition>,
    ) {
        self.index_catalog()[slot].pending_definition = prior;
    }

    /// Marks every index visible to `txid` on a table pending-dropped
    /// (PostgreSQL drops a table's indexes when the table itself is dropped).
    /// Commit finalizes via [`Self::commit_indexes_for`]; rollback reverts via
    /// [`Self::rollback_indexes_for`].
    pub fn drop_indexes_for(&mut self, schema: &str, table: &str, txid: u32) {
        for i in 0..self.index_count() {
            if self.index(i).database == current_database()
                && self.index(i).visible_to(txid)
                && self.index(i).schema.as_str() == schema
                && self.index(i).table.as_str() == table
            {
                self.pending_drop_index(i, txid);
            }
        }
    }

    /// Promotes this transaction's pending index drops on a table (cascaded
    /// from its DROP TABLE) into the committed catalog.
    pub fn commit_indexes_for(&mut self, schema: &str, table: &str, txid: u32) {
        for slot in 0..self.index_count() {
            if self.index(slot).database == current_database()
                && self.index(slot).schema.as_str() == schema
                && self.index(slot).table.as_str() == table
                && self.index(slot).ddl_state == (CatalogDdlState::PendingDrop { txid })
            {
                self.commit_index_drop(slot);
            }
        }
    }

    /// Discards this transaction's pending index drops on a table (a rolled
    /// back DROP TABLE): committed indexes become visible again.
    pub fn rollback_indexes_for(&mut self, schema: &str, table: &str, txid: u32) {
        for x in self.index_catalog().iter_mut() {
            if x.database == current_database()
                && x.schema.as_str() == schema
                && x.table.as_str() == table
                && x.ddl_state == (CatalogDdlState::PendingDrop { txid })
            {
                x.ddl_state = x.ddl_state.rollback_drop(txid);
            }
        }
    }

    /// Marks the index visible to `txid` pending-dropped; returns its slot
    /// (for undo). None if absent. Errors if another transaction's uncommitted
    /// DDL holds the name.
    pub fn drop_index(
        &mut self,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut catalog = self.index_catalog();
        if let Some(blocker) = catalog.iter().find_map(|index| {
            (index.database == current_database()
                && index.schema.as_str() == schema
                && index.name_for(txid).as_str() == name)
                .then_some(index.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        }) {
            drop(catalog);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name));
        }
        let Some(i) = catalog.iter().position(|index| {
            index.database == current_database()
                && index.visible_to(txid)
                && index.schema.as_str() == schema
                && index.name_for(txid).as_str() == name
        }) else {
            return Ok(None);
        };
        catalog[i].ddl_state = catalog[i].ddl_state.drop_by(txid);
        Ok(Some(i))
    }

    /// Overlays a pending DROP on a slot: the owner's own pending-create
    /// simply evaporates.
    fn pending_drop_index(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.index_catalog();
        let x = &mut catalog[slot];
        x.ddl_state = x.ddl_state.drop_by(txid);
    }

    /// Promotes an uncommitted CREATE INDEX into the committed catalog.
    pub fn commit_index_create(&mut self, slot: usize) {
        {
            let mut catalog = self.index_catalog();
            catalog[slot].ddl_state = catalog[slot].ddl_state.commit_create();
        }
        if let Some(table) = self.index_table_slot(slot) {
            self.tables[table].mark_dirty();
        }
    }

    /// Promotes an uncommitted DROP INDEX into the committed catalog.
    pub fn commit_index_drop(&mut self, slot: usize) {
        let index = self.index(slot);
        let table = self.index_table_slot(slot);
        self.reset_index_statistics(crate::sql::catalog::explicit_index_oid(&index));
        self.drop_object_comments(
            CommentClass::Relation,
            index.schema.as_str(),
            index.name.as_str(),
        );
        self.clear_extension_dependencies_for_object(AccessObject {
            class: AccessClass::Index,
            slot: slot as u16,
        });
        self.retire_index(slot, false);
        if let Some(table) = table {
            self.tables[table].mark_dirty();
        }
    }

    fn retire_index(&self, slot: usize, rollback_create: bool) {
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Index,
            slot: slot as u16,
        });
        let mut catalog = self.index_catalog();
        if rollback_create {
            catalog[slot].ddl_state.rollback_create();
        } else {
            catalog[slot].ddl_state.commit_drop();
        }
        let mut maintenance = self.brin_maintenance();
        let (state, ranges) = Self::brin_entry_mut(
            &mut maintenance,
            slot,
            self.brin_unsummarized_ranges_per_index,
        );
        *state = BrinMaintenanceState::EMPTY;
        ranges.fill(0);
        catalog[slot] = IndexDef::EMPTY;
    }

    /// The committed table named by a retained index definition.
    pub fn index_table_slot(&self, slot: usize) -> Option<usize> {
        self.index_table_slot_to(slot, 0)
    }

    /// The transaction-visible table named by an index. DDL execution must
    /// use this form so a just-created table is not mistaken for corruption.
    pub(crate) fn index_table_slot_to(&self, slot: usize, txid: u32) -> Option<usize> {
        let index = self.index_catalog().get(slot).copied()?;
        self.find_visible(index.schema.as_str(), index.table.as_str(), txid)
    }

    /// Discards an uncommitted CREATE INDEX (rollback): the slot is freed.
    pub fn rollback_index_create(&self, slot: usize) {
        self.retire_index(slot, true);
    }

    /// Discards an uncommitted DROP INDEX (rollback); a same-transaction
    /// pending-create reverts to pending-create.
    pub fn rollback_index_drop(&mut self, slot: usize, txid: u32) {
        let mut catalog = self.index_catalog();
        let x = &mut catalog[slot];
        x.ddl_state = x.ddl_state.rollback_drop(txid);
    }

    /// Unique indexes visible to `txid` over the named table (for constraint
    /// enforcement — an uncommitted CREATE UNIQUE INDEX binds its owner).
    /// Every index on `table` that `txid` can see, including one it created in
    /// its own still-open transaction.
    pub fn indexes_for<'a>(
        &'a self,
        schema: &'a str,
        table: &'a str,
        txid: u32,
    ) -> impl Iterator<Item = IndexDef> + 'a {
        let committed_binding = self
            .find_visible(schema, table, txid)
            .map(|slot| (self.tables[slot].def.schema, self.tables[slot].def.name));
        self.matching_indexes(move |x| {
            x.database == current_database()
                && x.visible_to(txid)
                && ((x.schema.as_str() == schema && x.table.as_str() == table)
                    || committed_binding.is_some_and(|(old_schema, old_table)| {
                        x.schema == old_schema && x.table == old_table
                    }))
        })
        .map(move |(_, index)| self.project_index_binding(index, txid))
    }

    pub fn unique_indexes_for<'a>(
        &'a self,
        schema: &'a str,
        table: &'a str,
        txid: u32,
    ) -> impl Iterator<Item = IndexDef> + 'a {
        self.indexes_for(schema, table, txid).filter(|x| x.unique)
    }

    /// All committed indexes, for checkpoint serialization.
    pub fn live_indexes(&self) -> impl Iterator<Item = IndexDef> + '_ {
        self.matching_indexes(|index| {
            index.database == current_database() && index.ddl_state == CatalogDdlState::Present
        })
        .map(|(_, index)| index)
    }

    pub(crate) fn index_count(&self) -> usize {
        self.index_catalog_capacity
    }

    fn index_catalog(&self) -> std::sync::MutexGuard<'_, FixedVec<IndexDef>> {
        self.index_catalog
            .lock()
            .expect("index catalog lock poisoned")
    }

    fn index(&self, slot: usize) -> IndexDef {
        self.index_catalog()[slot]
    }

    fn matching_indexes<F: Fn(&IndexDef) -> bool>(&self, accept: F) -> IndexIter<'_, F> {
        IndexIter {
            catalog: &self.index_catalog,
            next_slot: 0,
            accept,
        }
    }

    /// Keeps the dropped catalog identity available during `sql_drop`.
    pub(crate) fn index_for_event_trigger(&self, slot: usize, txid: u32) -> Option<IndexDef> {
        let index = self.index_catalog().get(slot).copied();
        index
            .filter(|index| index.database == current_database())
            .map(|index| self.project_index_binding(index, txid))
    }

    pub(crate) fn index_visible_to(&self, slot: usize, txid: u32) -> Option<IndexDef> {
        let index = self.index_catalog().get(slot).copied();
        index
            .filter(|index| index.database == current_database() && index.visible_to(txid))
            .map(|index| self.project_index_binding(index, txid))
    }

    /// Projects committed index column ordinals through this transaction's
    /// pending table shape. A visible index that names a removed column is an
    /// executor invariant violation: DROP COLUMN must mark it pending-drop
    /// before publishing the pending table definition.
    fn project_index_binding(&self, mut index: IndexDef, txid: u32) -> IndexDef {
        // A transaction-private CREATE INDEX is already expressed against the
        // table shape visible at its creation point. Committed indexes alone
        // need projection from their committed table binding.
        if index.ddl_state != CatalogDdlState::Present {
            return index;
        }
        let Some(table_slot) = self.tables.iter().position(|table| {
            table.database == index.database
                && table.def.schema == index.schema
                && table.def.name == index.table
        }) else {
            return index;
        };
        let Some(pending) = self
            .pending_table_def(table_slot)
            .filter(|pending| pending.txid == txid)
        else {
            return index;
        };
        for key in 0..index.n_cols {
            if index.expressions[key].is_some() {
                continue;
            }
            let committed = usize::from(index.columns[key]);
            let target_name = pending.column_mapping[committed]
                .expect("visible index key cannot reference a dropped column");
            index.columns[key] = pending
                .def
                .column_index(target_name.as_str())
                .expect("pending index key name must exist in pending table definition")
                as u16;
        }
        for column in &mut index.include_columns[..index.n_include_cols] {
            let target_name = pending.column_mapping[usize::from(*column)]
                .expect("visible included index column cannot reference a dropped column");
            *column = pending
                .def
                .column_index(target_name.as_str())
                .expect("pending included column name must exist in pending table definition")
                as u16;
        }
        index.schema = pending.def.schema;
        index.table = pending.def.name;
        index
    }

    pub(crate) fn tablespace_slot(&self, name: &str, txid: u32) -> Option<usize> {
        self.tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned")
            .iter()
            .position(|tablespace| {
                tablespace.visible_to(txid) && tablespace.name_for(txid).as_str() == name
            })
    }

    /// Resolves a table access-method spelling to the durable implementation
    /// identity stored on a relation. Built-in heap has its PostgreSQL OID;
    /// user definitions retain their own stable OID rather than a catalog slot.
    pub(crate) fn table_access_method(&self, name: &str, txid: u32) -> Option<TableAccessMethod> {
        // Unquoted identifiers reach this boundary normalized to lower case.
        // A quoted spelling such as "HEAP" is distinct and must not select
        // heap merely because it differs only in case.
        if name == "heap" {
            return Some(TableAccessMethod::Heap);
        }
        AccessMethodIter {
            catalog: &self.operator_catalog,
            next_slot: 0,
        }
        .find_map(|(_, method)| {
            (method.database == current_database()
                && method.visible_to(txid)
                && method.definition.name.as_str() == name)
                .then(|| TableAccessMethod::Catalog(method.oid()))
        })
    }

    pub(crate) fn table_access_method_name(
        &self,
        method: TableAccessMethod,
        txid: u32,
    ) -> Option<SqlName> {
        match method {
            TableAccessMethod::Heap => SqlName::parse("heap").ok(),
            TableAccessMethod::Catalog(oid) => AccessMethodIter {
                catalog: &self.operator_catalog,
                next_slot: 0,
            }
            .find_map(|(_, candidate)| {
                (candidate.database == current_database()
                    && candidate.visible_to(txid)
                    && candidate.oid() == oid)
                    .then_some(candidate.definition.name)
            }),
        }
    }

    pub(crate) fn access_method_slot(&self, name: &str, txid: u32) -> Option<usize> {
        AccessMethodIter {
            catalog: &self.operator_catalog,
            next_slot: 0,
        }
        .find_map(|(slot, method)| {
            (method.database == current_database()
                && method.visible_to(txid)
                && method.definition.name.as_str() == name)
                .then_some(slot)
        })
    }

    pub(crate) fn access_method_oid_at(&self, slot: usize) -> Option<i32> {
        self.operator_catalog
            .lock()
            .expect("operator catalog lock poisoned")
            .access_methods
            .get(slot)
            .and_then(|method| {
                if method.database == current_database() && method.created_at != 0 {
                    Some(method.oid().get())
                } else {
                    None
                }
            })
    }

    pub(crate) fn access_method_name_by_oid(&self, oid: i32) -> Option<SqlName> {
        AccessMethodIter {
            catalog: &self.operator_catalog,
            next_slot: 0,
        }
        .find_map(|(_, method)| {
            if method.database == current_database()
                && method.created_at != 0
                && method.oid().get() == oid
            {
                Some(method.definition.name)
            } else {
                None
            }
        })
    }

    pub(crate) fn access_methods_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, AccessMethodDef)> + '_ {
        AccessMethodIter {
            catalog: &self.operator_catalog,
            next_slot: 0,
        }
        .filter(move |(_, method)| method.database == current_database() && method.visible_to(txid))
    }

    pub(crate) fn access_method_table_dependency(
        &self,
        oid: AccessMethodOid,
        txid: u32,
    ) -> Option<(SqlName, SqlName)> {
        (0..self.table_count()).find_map(|slot| {
            (self.table_slot_visible_to(slot, txid)
                && matches!(
                    self.table_def(slot, txid).access_method,
                    TableAccessMethod::Catalog(candidate) if candidate == oid
                ))
            .then_some((
                self.table_def(slot, txid).schema,
                self.table_def(slot, txid).name,
            ))
        })
    }

    pub(crate) fn create_access_method(
        &self,
        created_at: u64,
        definition: AccessMethodDefinition,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if matches!(
            definition.name.as_str(),
            "heap" | "btree" | "hash" | "gist" | "gin" | "brin" | "spgist"
        ) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "access method \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        let created_at = if created_at == 0 {
            self.catalog_sequence.next()
        } else {
            self.catalog_sequence.observe(created_at);
            created_at
        };
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        if catalog.access_methods.iter().any(|method| {
            method.database == current_database()
                && method.visible_to(txid)
                && method.definition.name == definition.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "access method \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        let slot = catalog
            .access_methods
            .iter()
            .position(|method| method.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "access method catalog capacity exhausted"
                )
            })?;
        catalog.access_methods[slot] = AccessMethodDef {
            database: current_database(),
            created_at,
            definition,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn drop_access_method(&self, slot: usize, txid: u32) {
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        catalog.access_methods[slot].ddl_state =
            catalog.access_methods[slot].ddl_state.drop_by(txid);
    }

    pub(crate) fn commit_access_method_create(&self, slot: usize) {
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        catalog.access_methods[slot].ddl_state =
            catalog.access_methods[slot].ddl_state.commit_create();
    }

    pub(crate) fn rollback_access_method_create(&self, slot: usize) {
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        catalog.access_methods[slot].ddl_state =
            catalog.access_methods[slot].ddl_state.rollback_create();
    }

    pub(crate) fn commit_access_method_drop(&self, slot: usize) {
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        self.drop_comments_by_subid(
            CommentClass::AccessMethod,
            catalog.access_methods[slot].oid().get() as u32,
        );
        catalog.access_methods[slot].ddl_state =
            catalog.access_methods[slot].ddl_state.commit_drop();
    }

    pub(crate) fn rollback_access_method_drop(&self, slot: usize, txid: u32) {
        let mut catalog = self
            .operator_catalog
            .lock()
            .expect("operator catalog lock poisoned");
        catalog.access_methods[slot].ddl_state =
            catalog.access_methods[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn tablespace_by_id(&self, id: u16, txid: u32) -> Option<TablespaceDef> {
        let slot = usize::from(id.checked_sub(2)?);
        if slot < 2 {
            return None;
        }
        self.tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned")
            .get(slot)
            .copied()
            .filter(|tablespace| tablespace.visible_to(txid))
    }

    pub(crate) fn tablespace_name(&self, id: u16, txid: u32) -> Option<SqlName> {
        match id {
            0 => SqlName::parse("pg_default").ok(),
            1 => SqlName::parse("pg_global").ok(),
            _ => self
                .tablespace_by_id(id, txid)
                .map(|tablespace| tablespace.name_for(txid)),
        }
    }

    pub(crate) fn tablespace_id(&self, name: &str, txid: u32) -> Option<u16> {
        if name.eq_ignore_ascii_case("pg_default") {
            return Some(0);
        }
        if name.eq_ignore_ascii_case("pg_global") {
            return Some(1);
        }
        self.tablespace_slot(name, txid)
            .and_then(|slot| u16::try_from(slot + 2).ok())
    }

    pub(crate) fn tablespaces_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TablespaceDef)> + '_ {
        TablespaceIter {
            catalog: &self.tablespaces,
            next_slot: 0,
        }
        .filter(move |(_, tablespace)| tablespace.visible_to(txid))
    }

    pub(crate) fn tablespace_capacity(&self) -> usize {
        self.tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned")
            .len()
    }

    fn tablespace(&self, slot: usize) -> TablespaceDef {
        self.tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned")[slot]
    }

    pub(crate) fn create_tablespace(
        &self,
        created_at: u64,
        name: SqlName,
        location: StackStr<TABLESPACE_LOCATION_MAX>,
        options: TablespaceOptions,
        owner: u16,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.validate_tablespace_identity(name, owner, txid)?;
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        if let Some(blocker) = tablespaces.iter().find_map(|tablespace| {
            tablespace
                .identity_matches(name)
                .then(|| tablespace.pending_owner_other_than(txid))
                .flatten()
        }) {
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        if tablespaces
            .iter()
            .any(|tablespace| tablespace.visible_to(txid) && tablespace.name_for(txid) == name)
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "tablespace \"{}\" already exists",
                name.as_str()
            ));
        }
        let slot = tablespaces
            .iter()
            .position(|tablespace| tablespace.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "tablespace catalog capacity exhausted"
                )
            })?;
        let definition = self.tablespace_definition(
            TablespaceImage {
                created_at,
                name,
                location,
                options,
                owner,
            },
            txid,
        );
        tablespaces[slot] = definition;
        drop(tablespaces);
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Tablespace,
            slot: slot as u16,
        });
        Ok(slot)
    }

    pub(crate) fn restore_tablespace(
        &self,
        slot: usize,
        created_at: u64,
        name: SqlName,
        location: StackStr<TABLESPACE_LOCATION_MAX>,
        options: TablespaceOptions,
        owner: u16,
    ) -> Result<(), SqlError> {
        if slot < 2 {
            let expected = if slot == 0 { "pg_default" } else { "pg_global" };
            if name.as_str() != expected
                || created_at != 1_663 + slot as u64
                || !location.as_str().is_empty()
                || owner != 0
            {
                return Err(sql_err!(
                    sqlstate::INTERNAL_ERROR,
                    "invalid built-in tablespace identity"
                ));
            }
            let mut tablespaces = self
                .tablespaces
                .lock()
                .expect("tablespace catalog lock poisoned");
            if let Some(blocker) = tablespaces[slot].pending_owner_other_than(0) {
                drop(tablespaces);
                return Err(self.catalog_ddl_wait_error(0, blocker, expected));
            }
            tablespaces[slot].options = options;
            return Ok(());
        }
        self.validate_tablespace_identity(name, owner, 0)?;
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        if let Some(blocker) = tablespaces
            .iter()
            .enumerate()
            .find_map(|(other, tablespace)| {
                (other != slot && tablespace.identity_matches(name))
                    .then(|| tablespace.pending_owner_other_than(0))
                    .flatten()
            })
        {
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(0, blocker, name.as_str()));
        }
        if tablespaces.iter().enumerate().any(|(other, tablespace)| {
            other != slot && tablespace.visible_to(0) && tablespace.name_for(0) == name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "tablespace \"{}\" already exists",
                name.as_str()
            ));
        }
        let Some(target) = tablespaces.get(slot) else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "tablespace slot is out of range"
            ));
        };
        if target.ddl_state != CatalogDdlState::Absent {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "tablespace slot {} is already occupied",
                slot
            ));
        }
        let mut definition = self.tablespace_definition(
            TablespaceImage {
                created_at,
                name,
                location,
                options,
                owner,
            },
            0,
        );
        definition.ddl_state = definition.ddl_state.commit_create();
        definition.ownership = definition.ownership.committed();
        tablespaces[slot] = definition;
        Ok(())
    }

    fn validate_tablespace_identity(
        &self,
        name: SqlName,
        owner: u16,
        txid: u32,
    ) -> Result<(), SqlError> {
        if name.as_str().starts_with("pg_") {
            return Err(sql_err!(
                sqlstate::RESERVED_NAME,
                "unacceptable tablespace name \"{}\"",
                name.as_str()
            ));
        }
        if self.tablespace_id(name.as_str(), txid).is_some() {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "tablespace \"{}\" already exists",
                name.as_str()
            ));
        }
        if !self.role_slot_visible(usize::from(owner), txid) {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "tablespace owner does not exist"
            ));
        }
        Ok(())
    }

    fn tablespace_definition(&self, image: TablespaceImage, txid: u32) -> TablespaceDef {
        let created_at = if image.created_at == 0 {
            self.catalog_sequence.next()
        } else {
            self.catalog_sequence.observe(image.created_at);
            image.created_at
        };
        TablespaceDef {
            created_at,
            name: image.name,
            location: image.location,
            options: image.options,
            ownership: Ownership {
                owner: 0,
                pending: Some(PendingOwnership {
                    txid,
                    owner: image.owner,
                }),
            },
            pending: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        }
    }

    pub(crate) fn alter_tablespace_definition(
        &self,
        slot: usize,
        name: SqlName,
        options: TablespaceOptions,
        txid: u32,
    ) -> Result<Option<PendingTablespaceDefinition>, SqlError> {
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        if let Some(blocker) = tablespaces[slot].pending_owner_other_than(txid) {
            let current_name = tablespaces[slot].name;
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(txid, blocker, current_name.as_str()));
        }
        if tablespaces.iter().enumerate().any(|(other, tablespace)| {
            other != slot && tablespace.visible_to(txid) && tablespace.name_for(txid) == name
        }) || ((name.as_str().eq_ignore_ascii_case("pg_default")
            || name.as_str().eq_ignore_ascii_case("pg_global"))
            && tablespaces[slot].name_for(txid) != name)
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "tablespace \"{}\" already exists",
                name.as_str()
            ));
        }
        if let Some(blocker) = tablespaces
            .iter()
            .enumerate()
            .find_map(|(other, tablespace)| {
                (other != slot && tablespace.identity_matches(name))
                    .then(|| tablespace.pending_owner_other_than(txid))
                    .flatten()
            })
        {
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(txid, blocker, name.as_str()));
        }
        let prior = tablespaces[slot].pending;
        tablespaces[slot].pending = Some(PendingTablespaceDefinition {
            txid,
            name,
            options,
        });
        Ok(prior)
    }

    pub(crate) fn drop_tablespace(&self, slot: usize, txid: u32) -> Result<(), SqlError> {
        let tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        let tablespace = tablespaces[slot];
        if let Some(blocker) = tablespace.pending_owner_other_than(txid) {
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(txid, blocker, tablespace.name.as_str()));
        }
        drop(tablespaces);
        if slot < 2 {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "cannot drop built-in tablespace \"{}\"",
                tablespace.name.as_str()
            ));
        }
        let id = u16::try_from(slot + 2).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "tablespace slot is out of range"
            )
        })?;
        if self
            .index_catalog()
            .iter()
            .any(|index| index.visible_to(txid) && index.mutable_for(txid).tablespace == id)
            || self.database_catalog().definitions.iter().any(|database| {
                database.visible_to(txid) && database.definition_for(txid).tablespace == id
            })
            || self.tables.iter().enumerate().any(|(table_slot, table)| {
                table.visible_to(txid) && self.table_def(table_slot, txid).tablespace == id
            })
        {
            return Err(sql_err!(
                sqlstate::OBJECT_IN_USE,
                "tablespace \"{}\" is not empty",
                tablespace.name_for(txid).as_str()
            ));
        }
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        if let Some(blocker) = tablespaces[slot].pending_owner_other_than(txid) {
            let current_name = tablespaces[slot].name;
            drop(tablespaces);
            return Err(self.catalog_ddl_wait_error(txid, blocker, current_name.as_str()));
        }
        tablespaces[slot].ddl_state = tablespaces[slot].ddl_state.drop_by(txid);
        Ok(())
    }

    pub(crate) fn commit_tablespace_create(&self, slot: usize) {
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        tablespaces[slot].ddl_state = tablespaces[slot].ddl_state.commit_create();
        tablespaces[slot].ownership = tablespaces[slot].ownership.committed();
    }

    pub(crate) fn commit_tablespace_alter(&self, slot: usize, txid: u32) {
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        let rename = if let Some(pending) = tablespaces[slot].pending
            && pending.txid == txid
        {
            let old_name = tablespaces[slot].name;
            tablespaces[slot].name = pending.name;
            tablespaces[slot].options = pending.options;
            tablespaces[slot].pending = None;
            Some((old_name, pending.name))
        } else {
            None
        };
        if tablespaces[slot]
            .ownership
            .pending
            .is_some_and(|pending| pending.txid == txid)
        {
            tablespaces[slot].ownership = tablespaces[slot].ownership.committed();
        }
        drop(tablespaces);
        if let Some((old_name, new_name)) = rename {
            for comment in self.comment_catalog().entries.iter_mut() {
                if comment.used
                    && comment.class == CommentClass::Tablespace
                    && comment.name == old_name
                {
                    comment.name = new_name;
                }
            }
        }
    }

    pub(crate) fn commit_tablespace_drop(&self, slot: usize) {
        let tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        let name = tablespaces[slot].name;
        drop(tablespaces);
        self.drop_object_comments(CommentClass::Tablespace, "", name.as_str());
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Tablespace,
            slot: slot as u16,
        });
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        tablespaces[slot].ddl_state = tablespaces[slot].ddl_state.commit_drop();
        tablespaces[slot] = TablespaceDef::EMPTY;
    }

    pub(crate) fn rollback_tablespace_create(&self, slot: usize) {
        self.clear_object_acl_entries(AccessObject {
            class: AccessClass::Tablespace,
            slot: slot as u16,
        });
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        tablespaces[slot].ddl_state = tablespaces[slot].ddl_state.rollback_create();
        tablespaces[slot] = TablespaceDef::EMPTY;
    }

    pub(crate) fn rollback_tablespace_alter(
        &self,
        slot: usize,
        prior: Option<PendingTablespaceDefinition>,
    ) {
        self.tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned")[slot]
            .pending = prior;
    }

    pub(crate) fn rollback_tablespace_drop(&self, slot: usize, txid: u32) {
        let mut tablespaces = self
            .tablespaces
            .lock()
            .expect("tablespace catalog lock poisoned");
        tablespaces[slot].ddl_state = tablespaces[slot].ddl_state.rollback_drop(txid);
    }

    /// A definition-only schema move (ALTER TABLE ... SET SCHEMA): the table
    /// and its indexes change schema, and every inbound foreign key follows —
    /// deterministically, so WAL replay reproduces it from the names alone.
    pub fn move_table_schema(&mut self, index: usize, new_schema: SqlName) {
        let database_oid = self.tables[index].database;
        let database = Some(database_oid);
        let old_schema = self.tables[index].def.schema;
        let name = self.tables[index].def.name;
        self.tables[index].def.schema = new_schema;
        self.tables[index].mark_dirty();
        for x in self.index_catalog().iter_mut() {
            if x.database == database_oid
                && x.ddl_state == CatalogDdlState::Present
                && x.schema.as_str() == old_schema.as_str()
                && x.table.as_str() == name.as_str()
            {
                x.schema = new_schema;
            }
        }
        let mut sequence_catalog = self.sequence_catalog();
        for sequence in sequence_catalog.definitions.iter_mut() {
            if sequence.database != database_oid || sequence.ddl_state != CatalogDdlState::Present {
                continue;
            }
            let moves_with_table = matches!(
                sequence.owner,
                Some(owner)
                    if owner.table_schema == old_schema && owner.table == name
            );
            if moves_with_table {
                sequence.schema = new_schema;
                let owner = sequence.owner.as_mut().expect("matched Some owner");
                owner.table_schema = new_schema;
            }
            if matches!(
                sequence.generator_for,
                Some(generator)
                    if generator.table_schema == old_schema && generator.table == name
            ) {
                let generator = sequence
                    .generator_for
                    .as_mut()
                    .expect("matched Some generator");
                generator.table_schema = new_schema;
            }
        }
        drop(sequence_catalog);
        for t in self.tables.iter_mut() {
            if t.database != database_oid || !t.live {
                continue;
            }
            let mut changed = false;
            for f in 0..t.def.n_fkeys {
                let fk = &mut t.def.fkeys[f];
                if fk.parent_schema.as_str() == old_schema.as_str()
                    && fk.parent.as_str() == name.as_str()
                {
                    fk.parent_schema = new_schema;
                    changed = true;
                }
            }
            if changed {
                t.mark_dirty();
            }
        }
        for comment in self.comment_catalog().entries.iter_mut() {
            if comment.used
                && comment.database == database
                && matches!(comment.class, CommentClass::Relation | CommentClass::Type)
                && comment.schema == old_schema
                && comment.name == name
            {
                comment.schema = new_schema;
                comment.pending_identity = None;
            }
        }
        self.rename_stored_query_dependency(DependencyClass::Table, index, None, new_schema, name);
    }

    /// Removes one foreign key from a table's definition by constraint name
    /// (DROP SCHEMA CASCADE severing an inbound reference), returning it for
    /// transactional undo.
    pub fn drop_fk(&mut self, index: usize, fk_name: &str) -> Option<ForeignKey> {
        let def = &mut self.tables[index].def;
        let at = (0..def.n_fkeys).find(|&f| def.fkeys[f].name.as_str() == fk_name)?;
        let removed = def.fkeys[at];
        for f in at..def.n_fkeys - 1 {
            def.fkeys[f] = def.fkeys[f + 1];
        }
        def.n_fkeys -= 1;
        self.tables[index].mark_dirty();
        Some(removed)
    }

    /// Replaces a table's definition in place (ALTER TABLE).
    pub fn set_table_def(
        &mut self,
        index: usize,
        def: TableDef,
        column_mapping: &[Option<SqlName>; MAX_COLUMNS],
    ) {
        let old = self.tables[index].def;
        let database_oid = self.tables[index].database;
        let database = Some(database_oid);
        if old.schema != def.schema {
            self.move_table_schema(index, def.schema);
        }
        let current = self.tables[index].def;
        if current.name != def.name {
            for index_def in self.index_catalog().iter_mut() {
                if index_def.database == database_oid
                    && index_def.schema == current.schema
                    && index_def.table == current.name
                {
                    index_def.table = def.name;
                }
            }
            for table in self.tables.iter_mut() {
                if table.database != database_oid {
                    continue;
                }
                let mut changed = false;
                for foreign_key in &mut table.def.fkeys[..table.def.n_fkeys] {
                    if foreign_key.parent_schema == current.schema
                        && foreign_key.parent == current.name
                    {
                        foreign_key.parent = def.name;
                        changed = true;
                    }
                }
                if changed {
                    table.mark_dirty();
                }
            }
            for comment in self.comment_catalog().entries.iter_mut() {
                if comment.used
                    && comment.database == database
                    && matches!(comment.class, CommentClass::Relation | CommentClass::Type)
                    && comment.schema == current.schema
                    && comment.name == current.name
                {
                    comment.name = def.name;
                    comment.pending_identity = None;
                }
            }
        }
        let mut sequence_catalog = self.sequence_catalog();
        for sequence in sequence_catalog.definitions.iter_mut() {
            if sequence.database != database_oid {
                continue;
            }
            sequence.owner =
                rebind_sequence_column(sequence.owner, &current, &def, column_mapping, false);
            sequence.generator_for = rebind_sequence_column(
                sequence.generator_for,
                &current,
                &def,
                column_mapping,
                true,
            );
        }
        drop(sequence_catalog);
        for index_def in self.index_catalog().iter_mut() {
            if index_def.database != database_oid
                || index_def.ddl_state != CatalogDdlState::Present
                || index_def.schema != old.schema
                || index_def.table != old.name
            {
                continue;
            }
            for column in &mut index_def.columns[..index_def.n_cols] {
                let Some(target_name) = column_mapping
                    .get(*column as usize)
                    .and_then(|target| *target)
                else {
                    continue;
                };
                if let Some(target_column) = def.column_index(target_name.as_str()) {
                    *column = target_column as u16;
                }
            }
            for column in &mut index_def.include_columns[..index_def.n_include_cols] {
                let Some(target_name) = column_mapping
                    .get(*column as usize)
                    .and_then(|target| *target)
                else {
                    continue;
                };
                if let Some(target_column) = def.column_index(target_name.as_str()) {
                    *column = target_column as u16;
                }
            }
            index_def.schema = def.schema;
            index_def.table = def.name;
        }
        self.tables[index].def = def;
        self.tables[index].mark_dirty();
        self.rename_stored_query_dependency(
            DependencyClass::Table,
            index,
            None,
            def.schema,
            def.name,
        );
    }

    pub fn next_rowid(&mut self) -> u64 {
        let id = self.next_rowid;
        self.next_rowid += 1;
        id
    }

    pub fn peek_next_rowid(&self) -> u64 {
        self.next_rowid
    }

    pub fn bump_lsn(&mut self) -> u64 {
        self.lsn += 1;
        self.lsn
    }

    pub fn lsn(&self) -> u64 {
        self.lsn
    }

    /// The current worker's command read snapshot.
    pub fn read_snapshot(&self) -> u32 {
        execution_visibility().read_snapshot
    }

    pub fn commit_snapshot(&self) -> u64 {
        execution_visibility().commit_snapshot
    }

    /// Publishes the running statement's durable snapshot to this worker.
    pub fn set_commit_snapshot(&self, snapshot: u64) {
        let mut visibility = execution_visibility();
        visibility.commit_snapshot = snapshot;
        replace_execution_visibility(visibility);
    }

    fn transaction_identity_state(&self) -> std::sync::MutexGuard<'_, TransactionIdentityState> {
        self.transaction_identities
            .lock()
            .expect("transaction identity lock poisoned")
    }

    fn lock_state(&self) -> std::sync::MutexGuard<'_, LockState> {
        self.locks.lock().expect("lock state lock poisoned")
    }

    fn snapshot_state(&self) -> std::sync::MutexGuard<'_, SnapshotState> {
        self.snapshots.lock().expect("snapshot state lock poisoned")
    }

    pub(crate) fn begin_transaction_identity(&self, transaction_id: u32) {
        let connection_id = self.current_connection_id();
        let mut identities = self.transaction_identity_state();
        identities.latest = identities.latest.max(u64::from(transaction_id));
        if identities
            .active
            .iter()
            .any(|identity| identity.transaction_id == transaction_id)
        {
            return;
        }
        identities
            .active
            .push(ActiveTransactionIdentity {
                transaction_id,
                connection_id: (connection_id > 0).then_some(connection_id),
                assigned: false,
            })
            .expect("transaction identity registry matches configured capacity");
    }

    fn transaction_wait_owner(&self, transaction_id: u32) -> crate::sql::lock::WaitOwner {
        self.transaction_identity_state()
            .active
            .iter()
            .find(|identity| identity.transaction_id == transaction_id)
            .and_then(|identity| identity.connection_id)
            .map(crate::sql::lock::connection_wait_owner)
            .unwrap_or_else(|| crate::sql::lock::prepared_wait_owner(transaction_id))
    }

    pub(crate) fn prepare_transaction_locks(&self, transaction_id: u32) {
        let prepared_owner = crate::sql::lock::prepared_wait_owner(transaction_id);
        let prior_owner = {
            let mut identities = self.transaction_identity_state();
            let Some(identity) = identities
                .active
                .iter_mut()
                .find(|identity| identity.transaction_id == transaction_id)
            else {
                return;
            };
            let prior = identity
                .connection_id
                .map(crate::sql::lock::connection_wait_owner)
                .unwrap_or(prepared_owner);
            identity.connection_id = None;
            prior
        };
        if prior_owner == prepared_owner {
            return;
        }
        let mut locks = self.lock_state();
        for lock in locks
            .table
            .iter_mut()
            .filter(|lock| lock.owner == transaction_id)
        {
            lock.wait_owner = prepared_owner;
        }
        locks.row.rebind_wait_owner(prior_owner, prepared_owner);
        locks
            .advisory
            .rebind_transaction_wait_owner(transaction_id, prior_owner, prepared_owner);
    }

    pub(crate) fn latest_transaction_identity(&self) -> u64 {
        self.transaction_identity_state().latest
    }

    pub(crate) fn observe_transaction_identity(&self, transaction_id: u64) {
        let mut identities = self.transaction_identity_state();
        identities.latest = identities.latest.max(transaction_id);
    }

    pub(crate) fn assign_transaction_identity(&self, transaction_id: u32) -> u64 {
        let mut identities = self.transaction_identity_state();
        if let Some(identity) = identities
            .active
            .iter_mut()
            .find(|identity| identity.transaction_id == transaction_id)
        {
            identity.assigned = true;
        }
        u64::from(transaction_id)
    }

    pub(crate) fn assigned_transaction_identity(&self, transaction_id: u32) -> Option<u64> {
        self.transaction_identity_state()
            .active
            .iter()
            .find(|identity| identity.transaction_id == transaction_id && identity.assigned)
            .map(|identity| u64::from(identity.transaction_id))
    }

    pub(crate) fn current_transaction_snapshot<'a>(
        &self,
        transaction_id: u32,
        arena: &'a crate::mem::arena::Arena,
    ) -> Result<crate::sql::snapshot::Snapshot<'a>, SqlError> {
        let identities = self.transaction_identity_state();
        let minimum_active = identities
            .active
            .iter()
            .filter(|identity| identity.assigned)
            .map(|identity| u64::from(identity.transaction_id))
            .min();
        let completed_xmax = identities
            .recent
            .iter()
            .map(|status| status.transaction_id)
            .max()
            .unwrap_or(0)
            .saturating_add(1);
        // PostgreSQL's xmax is one past the highest completed identity, not
        // one past an identity that is merely in progress. Internal virtual
        // transactions can leave gaps, so an active identity is also the
        // lower bound needed to keep the canonical snapshot range valid.
        let xmax = completed_xmax.max(minimum_active.unwrap_or(0)).max(1);
        let count = identities
            .active
            .iter()
            .filter(|identity| {
                identity.assigned
                    && identity.transaction_id != transaction_id
                    && u64::from(identity.transaction_id) < xmax
            })
            .count();
        let xmin = minimum_active.unwrap_or(xmax);
        crate::sql::snapshot::Snapshot::from_parts(
            xmin,
            xmax,
            count,
            identities.active.iter().filter_map(|identity| {
                (identity.assigned
                    && identity.transaction_id != transaction_id
                    && u64::from(identity.transaction_id) < xmax)
                    .then_some(u64::from(identity.transaction_id))
            }),
            arena,
        )
    }

    pub(crate) fn finish_transaction_identity(&self, transaction_id: u32, committed: bool) {
        let mut identities = self.transaction_identity_state();
        let assigned = identities
            .active
            .iter()
            .position(|identity| identity.transaction_id == transaction_id)
            .map(|index| identities.active.swap_remove(index).assigned)
            .unwrap_or(false);
        if !assigned {
            return;
        }
        Self::record_transaction_status(&mut identities, u64::from(transaction_id), committed);
    }

    fn record_transaction_status(
        identities: &mut TransactionIdentityState,
        transaction_id: u64,
        committed: bool,
    ) {
        let status = RecentTransactionStatus {
            transaction_id,
            committed,
        };
        if let Some(existing) = identities
            .recent
            .iter_mut()
            .find(|existing| existing.transaction_id == transaction_id)
        {
            existing.committed = committed;
            return;
        }
        if identities.recent.len() < identities.recent.capacity() {
            identities
                .recent
                .push(status)
                .expect("transaction status registry has free capacity");
        } else {
            let cursor = identities.recent_cursor;
            identities.recent[cursor] = status;
            identities.recent_cursor = (cursor + 1) % identities.recent.capacity();
        }
    }

    pub(crate) fn restore_transaction_status(
        &self,
        transaction_id: u64,
        committed: bool,
    ) -> Result<(), SqlError> {
        let mut identities = self.transaction_identity_state();
        if identities
            .recent
            .iter()
            .any(|status| status.transaction_id == transaction_id)
        {
            return Err(sql_err!(
                sqlstate::DATA_EXCEPTION,
                "duplicate retained transaction status"
            ));
        }
        identities.latest = identities.latest.max(transaction_id);
        Self::record_transaction_status(&mut identities, transaction_id, committed);
        Ok(())
    }

    pub(crate) fn visit_transaction_identity_state(
        &self,
        mut visit: impl FnMut(TransactionIdentityRecord),
    ) {
        let identities = self.transaction_identity_state();
        visit(TransactionIdentityRecord::Latest(identities.latest));
        for status in identities.recent.iter() {
            visit(TransactionIdentityRecord::Recent {
                transaction_id: status.transaction_id,
                committed: status.committed,
            });
        }
    }

    pub(crate) fn transaction_status(
        &self,
        transaction_id: u64,
    ) -> Result<Option<&'static str>, SqlError> {
        let identities = self.transaction_identity_state();
        if transaction_id > identities.latest {
            return Err(sql_err!(
                sqlstate::INVALID_PARAMETER_VALUE,
                "transaction ID {} is in the future",
                transaction_id
            ));
        }
        if identities.active.iter().any(|identity| {
            identity.assigned && u64::from(identity.transaction_id) == transaction_id
        }) {
            return Ok(Some("in progress"));
        }
        Ok(identities
            .recent
            .iter()
            .find(|status| status.transaction_id == transaction_id)
            .map(|status| {
                if status.committed {
                    "committed"
                } else {
                    "aborted"
                }
            }))
    }

    pub fn register_snapshot(&mut self, txid: u32, snapshot: u64) -> Result<(), SqlError> {
        let mut snapshots = self.snapshot_state();
        if let Some((_, existing)) = snapshots
            .active
            .iter_mut()
            .find(|(owner, _)| *owner == txid)
        {
            *existing = snapshot;
            return Ok(());
        }
        let capacity = snapshots.active.capacity();
        snapshots.active.push((txid, snapshot)).map_err(|_| {
            sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "more than {} active historical snapshots",
                capacity
            )
        })
    }

    pub fn release_snapshot(&mut self, txid: u32) {
        let oldest = {
            let mut snapshots = self.snapshot_state();
            let Some(index) = snapshots
                .active
                .iter()
                .position(|(owner, _)| *owner == txid)
            else {
                return;
            };
            snapshots.active.swap_remove(index);
            snapshots.active.iter().map(|(_, snapshot)| *snapshot).min()
        };
        // Schema waits can be blocked by a historical snapshot even when the
        // reader holds no row lock. Wake the shared wait graph when it ends.
        let wait_owner = self.transaction_wait_owner(txid);
        self.lock_state().row.resource_released(wait_owner);
        let row_versions = self.row_versions.exclusive();
        let (tables, versions) = (&mut self.tables, &mut row_versions.committed_row_versions);
        for table in tables.iter_mut() {
            for (_, state) in table.rows.iter_mut() {
                prune_committed_history(versions, &mut state.history, oldest);
            }
        }
        if oldest.is_none() {
            for table in self.tables.iter_mut() {
                if table.n_spill_ssts != 0 {
                    continue;
                }
                loop {
                    let mut batch = [0u64; 512];
                    let mut count = 0usize;
                    for (rowid, state) in table.rows.iter() {
                        if state.committed.is_none()
                            && state.history.is_empty()
                            && state.pending.is_none()
                        {
                            batch[count] = rowid;
                            count += 1;
                            if count == batch.len() {
                                break;
                            }
                        }
                    }
                    if count == 0 {
                        break;
                    }
                    for &rowid in &batch[..count] {
                        table.rows.remove(&rowid);
                    }
                }
            }
        }
    }

    pub fn oldest_snapshot(&self) -> Option<u64> {
        self.snapshot_state()
            .active
            .iter()
            .map(|(_, snapshot)| *snapshot)
            .min()
    }

    pub fn has_active_snapshots(&self) -> bool {
        !self.snapshot_state().active.is_empty()
    }

    pub(crate) fn acquire_advisory_lock(
        &self,
        transaction_id: u32,
        key: crate::sql::lock::AdvisoryKey,
        mode: crate::sql::lock::AdvisoryMode,
        transaction_scope: bool,
        try_only: bool,
    ) -> Result<crate::sql::lock::AdvisoryDecision, SqlError> {
        let connection_id = self.current_connection_id();
        if connection_id <= 0 {
            return Err(sql_err!(
                sqlstate::FEATURE_NOT_SUPPORTED,
                "advisory locks require a live connection"
            ));
        }
        let wait_owner = crate::sql::lock::connection_wait_owner(connection_id);
        let owner = if transaction_scope {
            crate::sql::lock::AdvisoryOwner::Transaction(transaction_id)
        } else {
            crate::sql::lock::AdvisoryOwner::Session(connection_id)
        };
        let mut locks = self.lock_state();
        let sequence = locks.next_sequence();
        let LockState { advisory, row, .. } = &mut *locks;
        advisory.acquire(key, owner, wait_owner, mode, try_only, sequence, row)
    }

    pub(crate) fn begin_advisory_statement(&self) -> Result<(), SqlError> {
        let connection_id = self.current_connection_id();
        self.lock_state().advisory.begin_statement(connection_id)
    }

    pub(crate) fn preserve_advisory_statement(&self) {
        let connection_id = self.current_connection_id();
        self.lock_state().advisory.preserve_statement(connection_id);
    }

    pub(crate) fn unlock_advisory_session(
        &self,
        key: crate::sql::lock::AdvisoryKey,
        mode: crate::sql::lock::AdvisoryMode,
    ) -> Result<bool, SqlError> {
        let connection_id = self.current_connection_id();
        let mut locks = self.lock_state();
        let LockState { advisory, row, .. } = &mut *locks;
        advisory.unlock_session(connection_id, key, mode, row)
    }

    pub(crate) fn unlock_all_advisory_session(&self) -> Result<(), SqlError> {
        let connection_id = self.current_connection_id();
        let mut locks = self.lock_state();
        let LockState { advisory, row, .. } = &mut *locks;
        advisory.unlock_all_session(connection_id, row)
    }

    pub(crate) fn release_advisory_transaction_locks(&self, transaction_id: u32) {
        let wait_owner = self.transaction_wait_owner(transaction_id);
        let mut locks = self.lock_state();
        let LockState { advisory, row, .. } = &mut *locks;
        advisory.release_transaction(transaction_id, wait_owner, row);
    }

    pub(crate) fn release_connection_advisory_locks(&self, connection_id: i32) {
        let mut locks = self.lock_state();
        let LockState { advisory, row, .. } = &mut *locks;
        advisory.drop_connection(connection_id);
        advisory
            .unlock_all_session(connection_id, row)
            .expect("connection cleanup does not enter statement replay");
    }

    pub(crate) fn blocking_backend_pids(&self, backend_pid: i32, output: &mut [i32]) -> usize {
        let locks = self.lock_state();
        if locks.advisory.blocker_pid_count(backend_pid) != 0 {
            locks.advisory.blocker_pids(backend_pid, output)
        } else {
            locks.row.blocker_pids(backend_pid, output)
        }
    }

    pub(crate) fn blocking_backend_pid_count(&self, backend_pid: i32) -> usize {
        let locks = self.lock_state();
        let advisory_count = locks.advisory.blocker_pid_count(backend_pid);
        if advisory_count != 0 {
            advisory_count
        } else {
            locks.row.blocker_pid_count(backend_pid)
        }
    }

    pub(crate) fn visit_advisory_locks(
        &self,
        visit: impl FnMut(crate::sql::lock::AdvisoryLockView),
    ) {
        self.lock_state().advisory.visit(visit);
    }

    pub(crate) fn advisory_lock_view_count(&self) -> usize {
        self.lock_state().advisory.view_count()
    }

    pub(crate) fn visit_table_locks(
        &self,
        mut visit: impl FnMut(u32, crate::sql::lock::WaitOwner, usize, crate::sql::ast::TableLockMode),
    ) {
        for lock in self.lock_state().table.iter() {
            for (mode, acquired_at) in lock.modes.iter().enumerate() {
                if *acquired_at == 0 {
                    continue;
                }
                let mode = match mode {
                    0 => crate::sql::ast::TableLockMode::AccessShare,
                    1 => crate::sql::ast::TableLockMode::RowShare,
                    2 => crate::sql::ast::TableLockMode::RowExclusive,
                    3 => crate::sql::ast::TableLockMode::ShareUpdateExclusive,
                    4 => crate::sql::ast::TableLockMode::Share,
                    5 => crate::sql::ast::TableLockMode::ShareRowExclusive,
                    6 => crate::sql::ast::TableLockMode::Exclusive,
                    _ => crate::sql::ast::TableLockMode::AccessExclusive,
                };
                visit(lock.owner, lock.wait_owner, lock.table as usize, mode);
            }
        }
    }

    pub(crate) fn table_lock_view_count(&self) -> usize {
        self.lock_state()
            .table
            .iter()
            .map(|lock| lock.modes.iter().filter(|sequence| **sequence != 0).count())
            .sum()
    }

    pub fn lock_table(
        &self,
        txid: u32,
        table: usize,
        mode: crate::sql::ast::TableLockMode,
        nowait: bool,
    ) -> Result<(), SqlError> {
        use crate::sql::ast::TableLockMode;

        fn mode_bit(mode: TableLockMode) -> u8 {
            1 << mode as u8
        }

        fn modes_conflict(left: u8, right: u8) -> bool {
            for left_index in 0..8 {
                if left & (1 << left_index) == 0 {
                    continue;
                }
                for right_index in 0..8 {
                    if right & (1 << right_index) != 0 && mode_conflicts(left_index, right_index) {
                        return true;
                    }
                }
            }
            false
        }

        fn mode_conflicts(left: u8, right: u8) -> bool {
            use TableLockMode::*;
            let left = match left {
                0 => AccessShare,
                1 => RowShare,
                2 => RowExclusive,
                3 => ShareUpdateExclusive,
                4 => Share,
                5 => ShareRowExclusive,
                6 => Exclusive,
                _ => AccessExclusive,
            };
            let right = match right {
                0 => AccessShare,
                1 => RowShare,
                2 => RowExclusive,
                3 => ShareUpdateExclusive,
                4 => Share,
                5 => ShareRowExclusive,
                6 => Exclusive,
                _ => AccessExclusive,
            };
            matches!(
                (left, right),
                (AccessShare, AccessExclusive)
                    | (RowShare, Exclusive | AccessExclusive)
                    | (
                        RowExclusive,
                        Share | ShareRowExclusive | Exclusive | AccessExclusive
                    )
                    | (
                        ShareUpdateExclusive,
                        ShareUpdateExclusive
                            | Share
                            | ShareRowExclusive
                            | Exclusive
                            | AccessExclusive
                    )
                    | (
                        Share,
                        RowExclusive
                            | ShareUpdateExclusive
                            | ShareRowExclusive
                            | Exclusive
                            | AccessExclusive
                    )
                    | (
                        ShareRowExclusive,
                        RowExclusive
                            | ShareUpdateExclusive
                            | Share
                            | ShareRowExclusive
                            | Exclusive
                            | AccessExclusive
                    )
                    | (
                        Exclusive,
                        RowShare
                            | RowExclusive
                            | ShareUpdateExclusive
                            | Share
                            | ShareRowExclusive
                            | Exclusive
                            | AccessExclusive
                    )
                    | (AccessExclusive, _)
            ) || matches!(right, AccessExclusive)
        }

        let wait_owner = self.transaction_wait_owner(txid);
        let mut locks = self.lock_state();
        let requested = mode_bit(mode);
        let own_index = locks
            .table
            .iter()
            .position(|lock| lock.owner == txid && lock.table == table as u32);
        if own_index.is_some_and(|index| locks.table[index].mask() & requested != 0) {
            return Ok(());
        }
        let combined = own_index
            .map(|index| locks.table[index].mask() | requested)
            .unwrap_or(requested);
        let blocker = locks
            .table
            .iter()
            .find(|lock| {
                lock.owner != txid
                    && lock.table == table as u32
                    && modes_conflict(combined, lock.mask())
            })
            .map(|lock| lock.wait_owner);
        if let Some(blocker) = blocker {
            if nowait {
                return Err(sql_err!(
                    sqlstate::LOCK_NOT_AVAILABLE,
                    "could not obtain lock on relation"
                ));
            }
            locks.row.wait_for(wait_owner, blocker)?;
            drop(locks);
            self.mark_current_backend_wait("Lock", "relation");
            return Err(sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for a relation lock"
            ));
        }
        let sequence = locks.next_sequence();
        if let Some(index) = own_index {
            locks.table[index].modes[mode as usize] = sequence;
            return Ok(());
        }
        let mut modes = [0; 8];
        modes[mode as usize] = sequence;
        locks
            .table
            .push(TableLock {
                owner: txid,
                wait_owner,
                table: table as u32,
                modes,
            })
            .map_err(|_| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "table-lock registry is full ({} locks)",
                    locks.table.capacity()
                )
            })
    }

    pub(crate) fn lock_mark(&self) -> u64 {
        self.lock_state().sequence
    }

    pub(crate) fn encode_transaction_locks(
        &self,
        txid: u32,
        output: &mut FixedBuf,
    ) -> Result<(), SqlError> {
        fn append_lock(
            output: &mut FixedBuf,
            kind: u8,
            mode: u8,
            rowid: u64,
            schema: &str,
            table: &str,
        ) -> Result<(), SqlError> {
            if schema.len() > u8::MAX as usize
                || table.len() > u8::MAX as usize
                || !output.append(&[kind, mode])
                || !output.append(&rowid.to_le_bytes())
                || !output.append(&[schema.len() as u8])
                || !output.append(schema.as_bytes())
                || !output.append(&[table.len() as u8])
                || !output.append(table.as_bytes())
            {
                return Err(sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "prepared transaction lock inventory exceeds wal_buffer_bytes"
                ));
            }
            Ok(())
        }

        output.clear();
        let locks = self.lock_state();
        for lock in locks.table.iter().filter(|lock| lock.owner == txid) {
            let table = &self.tables[lock.table as usize];
            if !table.live {
                continue;
            }
            for (mode, acquired_at) in lock.modes.iter().enumerate() {
                if *acquired_at != 0 {
                    append_lock(
                        output,
                        0,
                        mode as u8,
                        0,
                        table.def.schema.as_str(),
                        table.def.name.as_str(),
                    )?;
                }
            }
        }
        locks.row.visit_owner(txid, |table_slot, rowid, strength| {
            let table = &self.tables[table_slot];
            if !table.live {
                return Ok(());
            }
            append_lock(
                output,
                1,
                strength as u8,
                rowid,
                table.def.schema.as_str(),
                table.def.name.as_str(),
            )
        })?;
        let mut advisory_result = Ok(());
        locks
            .advisory
            .visit_transaction(txid, |key, advisory_mode| {
                if advisory_result.is_err() {
                    return;
                }
                let mode = match (key.object_sub_id, advisory_mode) {
                    (1, crate::sql::lock::AdvisoryMode::Shared) => 0,
                    (1, crate::sql::lock::AdvisoryMode::Exclusive) => 1,
                    (2, crate::sql::lock::AdvisoryMode::Shared) => 2,
                    (2, crate::sql::lock::AdvisoryMode::Exclusive) => 3,
                    _ => {
                        advisory_result = Err(sql_err!(
                            sqlstate::INTERNAL_ERROR,
                            "advisory lock has an invalid key namespace"
                        ));
                        return;
                    }
                };
                let packed = u64::from(key.class_id) << 32 | u64::from(key.object_id);
                advisory_result = append_lock(output, 2, mode, packed, "", "");
            });
        advisory_result
    }

    pub(crate) fn restore_transaction_locks(
        &self,
        txid: u32,
        encoded: &[u8],
    ) -> Result<(), SqlError> {
        let mut at = 0usize;
        while at < encoded.len() {
            let kind = *encoded.get(at).ok_or_else(|| {
                sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
            })?;
            let mode = *encoded.get(at + 1).ok_or_else(|| {
                sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
            })?;
            let rowid = u64::from_le_bytes(
                encoded
                    .get(at + 2..at + 10)
                    .ok_or_else(|| {
                        sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
                    })?
                    .try_into()
                    .unwrap(),
            );
            at += 10;
            let schema_len = *encoded.get(at).ok_or_else(|| {
                sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
            })? as usize;
            at += 1;
            let schema =
                core::str::from_utf8(encoded.get(at..at + schema_len).ok_or_else(|| {
                    sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
                })?)
                .map_err(|_| {
                    sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is not UTF-8")
                })?;
            at += schema_len;
            let table_len = *encoded.get(at).ok_or_else(|| {
                sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
            })? as usize;
            at += 1;
            let table = core::str::from_utf8(encoded.get(at..at + table_len).ok_or_else(|| {
                sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is truncated")
            })?)
            .map_err(|_| sql_err!(sqlstate::DATA_EXCEPTION, "prepared lock WAL is not UTF-8"))?;
            at += table_len;
            match kind {
                0 => {
                    let slot = self.find_visible(schema, table, 0).ok_or_else(|| {
                        sql_err!(
                            sqlstate::DATA_EXCEPTION,
                            "prepared lock WAL targets missing relation \"{}.{}\"",
                            schema,
                            table
                        )
                    })?;
                    let table_mode = match mode {
                        0 => crate::sql::ast::TableLockMode::AccessShare,
                        1 => crate::sql::ast::TableLockMode::RowShare,
                        2 => crate::sql::ast::TableLockMode::RowExclusive,
                        3 => crate::sql::ast::TableLockMode::ShareUpdateExclusive,
                        4 => crate::sql::ast::TableLockMode::Share,
                        5 => crate::sql::ast::TableLockMode::ShareRowExclusive,
                        6 => crate::sql::ast::TableLockMode::Exclusive,
                        7 => crate::sql::ast::TableLockMode::AccessExclusive,
                        _ => {
                            return Err(sql_err!(
                                sqlstate::DATA_EXCEPTION,
                                "prepared lock WAL has an invalid table-lock mode"
                            ));
                        }
                    };
                    self.lock_table(txid, slot, table_mode, false)?;
                }
                1 => {
                    let slot = self.find_visible(schema, table, 0).ok_or_else(|| {
                        sql_err!(
                            sqlstate::DATA_EXCEPTION,
                            "prepared lock WAL targets missing relation \"{}.{}\"",
                            schema,
                            table
                        )
                    })?;
                    let strength = match mode {
                        0 => crate::sql::ast::LockStrength::Update,
                        1 => crate::sql::ast::LockStrength::NoKeyUpdate,
                        2 => crate::sql::ast::LockStrength::Share,
                        3 => crate::sql::ast::LockStrength::KeyShare,
                        _ => {
                            return Err(sql_err!(
                                sqlstate::DATA_EXCEPTION,
                                "prepared lock WAL has an invalid row-lock mode"
                            ));
                        }
                    };
                    let decision = self.acquire_row_lock(
                        slot,
                        rowid,
                        txid,
                        strength,
                        crate::sql::ast::LockWait::Wait,
                    )?;
                    if decision != crate::sql::lock::LockDecision::Acquired {
                        return Err(sql_err!(
                            sqlstate::DATA_EXCEPTION,
                            "recovered prepared locks conflict"
                        ));
                    }
                }
                2 => {
                    let advisory_mode = match mode {
                        0 | 2 => crate::sql::lock::AdvisoryMode::Shared,
                        1 | 3 => crate::sql::lock::AdvisoryMode::Exclusive,
                        _ => {
                            return Err(sql_err!(
                                sqlstate::DATA_EXCEPTION,
                                "prepared lock WAL has an invalid advisory-lock mode"
                            ));
                        }
                    };
                    let key = crate::sql::lock::AdvisoryKey {
                        class_id: (rowid >> 32) as u32,
                        object_id: rowid as u32,
                        object_sub_id: if mode < 2 { 1 } else { 2 },
                    };
                    let wait_owner = crate::sql::lock::prepared_wait_owner(txid);
                    let mut locks = self.lock_state();
                    let sequence = locks.next_sequence();
                    let LockState { advisory, row, .. } = &mut *locks;
                    let decision = advisory.acquire(
                        key,
                        crate::sql::lock::AdvisoryOwner::Transaction(txid),
                        wait_owner,
                        advisory_mode,
                        false,
                        sequence,
                        row,
                    )?;
                    if decision != crate::sql::lock::AdvisoryDecision::Acquired {
                        return Err(sql_err!(
                            sqlstate::DATA_EXCEPTION,
                            "recovered prepared advisory locks conflict"
                        ));
                    }
                }
                _ => {
                    return Err(sql_err!(
                        sqlstate::DATA_EXCEPTION,
                        "prepared lock WAL has an invalid lock kind"
                    ));
                }
            }
        }
        Ok(())
    }

    pub(crate) fn rollback_locks_to(&self, txid: u32, mark: u64) {
        let wait_owner = self.transaction_wait_owner(txid);
        let mut locks = self.lock_state();
        let mut table_changed = false;
        let mut index = 0usize;
        while index < locks.table.len() {
            if locks.table[index].owner != txid {
                index += 1;
                continue;
            }
            for acquired_at in &mut locks.table[index].modes {
                if *acquired_at > mark {
                    *acquired_at = 0;
                    table_changed = true;
                }
            }
            if locks.table[index].mask() == 0 {
                locks.table.swap_remove(index);
            } else {
                index += 1;
            }
        }
        let LockState { advisory, row, .. } = &mut *locks;
        row.rollback_to(txid, wait_owner, mark);
        advisory.rollback_to(txid, wait_owner, mark, row);
        if table_changed {
            row.resource_released(wait_owner);
        }
    }

    pub fn release_table_locks(&self, txid: u32) {
        let wait_owner = self.transaction_wait_owner(txid);
        let mut locks = self.lock_state();
        let mut changed = false;
        let mut index = 0usize;
        while index < locks.table.len() {
            if locks.table[index].owner == txid {
                locks.table.swap_remove(index);
                changed = true;
            } else {
                index += 1;
            }
        }
        if changed {
            locks.row.resource_released(wait_owner);
        }
    }

    pub(crate) fn acquire_row_lock(
        &self,
        table: usize,
        rowid: u64,
        txid: u32,
        strength: crate::sql::ast::LockStrength,
        wait: crate::sql::ast::LockWait,
    ) -> Result<crate::sql::lock::LockDecision, SqlError> {
        let wait_owner = self.transaction_wait_owner(txid);
        let mut locks = self.lock_state();
        let sequence = locks.next_sequence();
        locks
            .row
            .acquire(table, rowid, txid, wait_owner, strength, wait, sequence)
    }

    pub(crate) fn release_row_locks(&self, txid: u32) {
        let wait_owner = self.transaction_wait_owner(txid);
        self.lock_state().row.release(txid, wait_owner);
    }

    pub(crate) fn lock_generation(&self) -> u64 {
        self.lock_state().row.generation()
    }

    pub(crate) fn begin_serializable(&self, txid: u32) -> Result<(), SqlError> {
        let mut snapshots = self.snapshot_state();
        if snapshots.serializable.iter().any(|entry| entry.0 == txid) {
            return Ok(());
        }
        let capacity = snapshots.serializable.capacity();
        for (table, definition) in self.tables.iter().enumerate() {
            snapshots
                .serializable
                .push((txid, table as u32, definition.generation, false))
                .map_err(|_| {
                    sql_err!(
                        sqlstate::PROGRAM_LIMIT_EXCEEDED,
                        "serializable snapshot registry is full ({} table snapshots)",
                        capacity
                    )
                })?;
        }
        Ok(())
    }

    pub(crate) fn record_serializable_read(&self, txid: u32, table: usize) {
        if let Some(entry) = self
            .snapshot_state()
            .serializable
            .iter_mut()
            .find(|entry| entry.0 == txid && entry.1 == table as u32)
        {
            entry.3 = true;
        }
    }

    pub(crate) fn validate_serializable(&self, txid: u32) -> Result<(), SqlError> {
        for &(owner, table, generation, read) in self.snapshot_state().serializable.iter() {
            if owner == txid && read && self.tables[table as usize].generation != generation {
                return Err(sql_err!(
                    sqlstate::SERIALIZATION_FAILURE,
                    "could not serialize access due to read/write dependencies among transactions"
                ));
            }
        }
        Ok(())
    }

    pub(crate) fn release_serializable(&self, txid: u32) {
        let mut snapshots = self.snapshot_state();
        let mut index = 0usize;
        while index < snapshots.serializable.len() {
            if snapshots.serializable[index].0 == txid {
                snapshots.serializable.swap_remove(index);
            } else {
                index += 1;
            }
        }
    }

    pub fn has_access_share_locks(&self) -> bool {
        !self.lock_state().table.is_empty()
    }

    pub(crate) fn schema_lock_blocker(&self, txid: u32) -> Option<u32> {
        let snapshots = self.snapshot_state();
        let locks = self.lock_state();
        snapshots
            .active
            .iter()
            .map(|(owner, _)| *owner)
            .chain(locks.table.iter().map(|lock| lock.owner))
            .find(|owner| *owner != txid)
    }

    pub(crate) fn wait_for_transaction(&self, waiter: u32, blocker: u32) -> Result<(), SqlError> {
        let waiter = self.transaction_wait_owner(waiter);
        let blocker = self.transaction_wait_owner(blocker);
        self.lock_state().row.wait_for(waiter, blocker)
    }

    fn catalog_ddl_wait_error(&self, waiter: u32, blocker: u32, name: &str) -> SqlError {
        match self.wait_for_transaction(waiter, blocker) {
            Err(error) => error,
            Ok(()) => sql_err!(
                sqlstate::INTERNAL_LOCK_WAIT,
                "statement is waiting for concurrent DDL on \"{}\"",
                name
            ),
        }
    }

    pub(crate) fn cast(&self, slot: usize) -> CastDef {
        self.casts.lock().expect("cast catalog lock poisoned")[slot]
    }

    pub(crate) fn casts_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, CastDef)> + '_ {
        CastIter {
            catalog: &self.casts,
            next_slot: 0,
        }
        .filter(move |(_, definition)| {
            definition.database == current_database() && definition.visible_to(txid)
        })
    }

    pub(crate) fn cast_slot(
        &self,
        source: RoutineResult,
        target: RoutineResult,
        txid: u32,
    ) -> Option<usize> {
        let casts = self.casts.lock().expect("cast catalog lock poisoned");
        casts.iter().enumerate().find_map(|(slot, definition)| {
            (definition.database == current_database()
                && definition.visible_to(txid)
                && definition.source == source
                && definition.target == target)
                .then_some(slot)
        })
    }

    pub(crate) fn cast_for_oids(
        &self,
        source_oid: i32,
        target_oid: i32,
        txid: u32,
    ) -> Option<(usize, CastDef)> {
        // Expression analysis calls this on hot paths. Scan under one lock;
        // locking once per empty catalog slot makes wide expressions costly.
        let casts = self.casts.lock().expect("cast catalog lock poisoned");
        casts.iter().enumerate().find_map(|(slot, definition)| {
            if definition.database != current_database() || !definition.visible_to(txid) {
                return None;
            }
            let source =
                self.routine_type_oid(definition.source.ctype, definition.source.user_type, txid)?;
            let target =
                self.routine_type_oid(definition.target.ctype, definition.target.user_type, txid)?;
            (source == source_oid && target == target_oid).then_some((slot, *definition))
        })
    }

    fn validate_cast_definition(&self, definition: CastDef, txid: u32) -> Result<(), SqlError> {
        if self
            .routine_type_oid(definition.source.ctype, definition.source.user_type, txid)
            .is_none()
            || self
                .routine_type_oid(definition.target.ctype, definition.target.user_type, txid)
                .is_none()
        {
            return Err(sql_err!(
                sqlstate::UNDEFINED_OBJECT,
                "cast source or target type does not exist"
            ));
        }
        match definition.method {
            CastMethod::Binary
                if !self.routine_results_binary_coercible(
                    definition.source,
                    definition.target,
                    txid,
                ) =>
            {
                Err(sql_err!(
                    sqlstate::CANNOT_COERCE,
                    "cast types are not binary compatible"
                ))
            }
            CastMethod::Function(oid) => {
                let slot = self.routine_slot_by_oid(oid, txid).ok_or_else(|| {
                    sql_err!(sqlstate::UNDEFINED_FUNCTION, "cast function does not exist")
                })?;
                let routine = self.routine_for(slot, txid);
                let RoutineKind::Function { result } = routine.kind else {
                    return Err(sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "cast support object is not a scalar function"
                    ));
                };
                let result = self.bind_routine_result(result, txid)?;
                let argument = routine.arguments().first().copied().ok_or_else(|| {
                    sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "cast function has no source argument"
                    )
                })?;
                let argument = self.bind_routine_result(
                    RoutineResult {
                        ctype: argument.ctype,
                        user_type: argument.user_type,
                    },
                    txid,
                )?;
                if !self.routine_results_binary_coercible(result, definition.target, txid)
                    || !self.routine_results_binary_coercible(definition.source, argument, txid)
                {
                    return Err(sql_err!(
                        sqlstate::INVALID_FUNCTION_DEFINITION,
                        "cast function contract does not match the cast"
                    ));
                }
                Ok(())
            }
            CastMethod::Binary | CastMethod::InOut => Ok(()),
        }
    }

    pub(crate) fn routine_results_binary_coercible(
        &self,
        source: RoutineResult,
        target: RoutineResult,
        txid: u32,
    ) -> bool {
        use ColType::*;
        if source == target {
            return true;
        }
        if source.user_type.is_some() || target.user_type.is_some() {
            let is_domain = |result: RoutineResult| {
                result.user_type.is_some_and(|identity| {
                    self.domain_identity_slot(
                        identity.schema.as_str(),
                        identity.name.as_str(),
                        txid,
                    )
                    .is_some()
                })
            };
            return source.ctype == target.ctype && (is_domain(source) || is_domain(target));
        }
        let oid_reference = |ctype| {
            matches!(
                ctype,
                Oid | Regtype
                    | Regproc
                    | Regprocedure
                    | Regoper
                    | Regoperator
                    | Regclass
                    | Regnamespace
                    | Regrole
            )
        };
        matches!(
            (source.ctype, target.ctype),
            (Text, Bpchar | Varchar)
                | (Varchar, Text | Bpchar)
                | (Bit { varying: false }, Bit { varying: true })
                | (Bit { varying: true }, Bit { varying: false })
                | (Cidr, Inet)
                | (Regproc, Regprocedure)
                | (Regprocedure, Regproc)
                | (Regoper, Regoperator)
                | (Regoperator, Regoper)
        ) || (source.ctype == Int4 && oid_reference(target.ctype))
            || (target.ctype == Int4 && oid_reference(source.ctype))
            || (source.ctype == Oid && oid_reference(target.ctype))
            || (target.ctype == Oid && oid_reference(source.ctype))
    }

    fn builtin_cast_exists(source: i32, target: i32) -> bool {
        use crate::sql::types::oid;

        let numeric = |oid| {
            matches!(
                oid,
                oid::INT2 | oid::INT4 | oid::INT8 | oid::FLOAT4 | oid::FLOAT8 | oid::NUMERIC
            )
        };
        let oid_alias = |oid| {
            matches!(
                oid,
                oid::OID
                    | oid::REGPROC
                    | oid::REGPROCEDURE
                    | oid::REGOPER
                    | oid::REGOPERATOR
                    | oid::REGCLASS
                    | oid::REGTYPE
                    | oid::REGNAMESPACE
                    | oid::REGROLE
            )
        };
        (numeric(source) && numeric(target))
            || (matches!(source, oid::INT2 | oid::INT4 | oid::INT8) && oid_alias(target))
            || (oid_alias(source) && matches!(target, oid::INT4 | oid::INT8 | oid::OID))
            || (source == oid::OID && oid_alias(target))
            || matches!(
                (source, target),
                (oid::REGPROC, oid::REGPROCEDURE)
                    | (oid::REGPROCEDURE, oid::REGPROC)
                    | (oid::REGOPER, oid::REGOPERATOR)
                    | (oid::REGOPERATOR, oid::REGOPER)
                    | (
                        oid::BOOL,
                        oid::INT4 | oid::TEXT | oid::VARCHAR | oid::BPCHAR
                    )
                    | (oid::INT4, oid::BOOL | oid::CHAR | oid::BIT)
                    | (
                        oid::CHAR,
                        oid::INT4 | oid::TEXT | oid::VARCHAR | oid::BPCHAR
                    )
                    | (oid::BYTEA, oid::INT2 | oid::INT4 | oid::INT8)
                    | (oid::INT2 | oid::INT4 | oid::INT8, oid::BYTEA)
                    | (
                        oid::TEXT,
                        oid::CHAR | oid::NAME | oid::VARCHAR | oid::BPCHAR | oid::REGCLASS
                    )
                    | (
                        oid::VARCHAR,
                        oid::CHAR | oid::NAME | oid::TEXT | oid::BPCHAR | oid::REGCLASS
                    )
                    | (
                        oid::BPCHAR,
                        oid::CHAR | oid::NAME | oid::TEXT | oid::VARCHAR
                    )
                    | (oid::NAME, oid::TEXT | oid::VARCHAR | oid::BPCHAR)
                    | (oid::DATE, oid::TIMESTAMP | oid::TIMESTAMPTZ)
                    | (oid::TIMESTAMP, oid::DATE | oid::TIME | oid::TIMESTAMPTZ)
                    | (
                        oid::TIMESTAMPTZ,
                        oid::DATE | oid::TIME | oid::TIMESTAMP | oid::TIMETZ
                    )
                    | (oid::TIME, oid::INTERVAL | oid::TIMETZ)
                    | (oid::TIMETZ, oid::TIME)
                    | (oid::INTERVAL, oid::TIME)
                    | (oid::BIT, oid::INT4 | oid::INT8 | oid::VARBIT)
                    | (oid::INT8, oid::BIT)
                    | (oid::VARBIT, oid::BIT)
                    | (
                        oid::CIDR,
                        oid::INET | oid::TEXT | oid::VARCHAR | oid::BPCHAR
                    )
                    | (
                        oid::INET,
                        oid::CIDR | oid::TEXT | oid::VARCHAR | oid::BPCHAR
                    )
                    | (oid::MACADDR, oid::MACADDR8)
                    | (oid::MACADDR8, oid::MACADDR)
                    | (oid::JSON, oid::JSONB)
                    | (
                        oid::JSONB,
                        oid::JSON
                            | oid::BOOL
                            | oid::INT2
                            | oid::INT4
                            | oid::INT8
                            | oid::FLOAT4
                            | oid::FLOAT8
                            | oid::NUMERIC
                    )
            )
    }

    pub(crate) fn create_cast(
        &mut self,
        source: RoutineResult,
        target: RoutineResult,
        method: CastMethod,
        context: CastContext,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if source == target {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "source data type and target data type are the same"
            ));
        }
        self.validate_cast_definition(
            CastDef {
                database: current_database(),
                created_at: 0,
                source,
                target,
                method,
                context,
                ddl_state: CatalogDdlState::Absent,
            },
            txid,
        )?;
        let source_oid = self
            .routine_type_oid(source.ctype, source.user_type, txid)
            .expect("validated cast source type");
        let target_oid = self
            .routine_type_oid(target.ctype, target.user_type, txid)
            .expect("validated cast target type");
        if Self::builtin_cast_exists(source_oid, target_oid) {
            return Err(sql_err!(sqlstate::DUPLICATE_OBJECT, "cast already exists"));
        }
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        if let Some(blocker) = casts.iter().find_map(|definition| {
            (definition.database == current_database()
                && definition.source == source
                && definition.target == target)
                .then_some(definition.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        }) {
            drop(casts);
            return Err(self.catalog_ddl_wait_error(txid, blocker, "cast"));
        }
        if casts.iter().any(|definition| {
            definition.database == current_database()
                && definition.visible_to(txid)
                && definition.source == source
                && definition.target == target
        }) {
            return Err(sql_err!(sqlstate::DUPLICATE_OBJECT, "cast already exists"));
        }
        let Some(slot) = casts
            .iter()
            .position(|definition| definition.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many casts (limit {})",
                casts.len()
            ));
        };
        let created_at = self.catalog_sequence.next();
        casts[slot] = CastDef {
            database: current_database(),
            created_at,
            source,
            target,
            method,
            context,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn create_cast_from_image(
        &mut self,
        mut definition: CastDef,
    ) -> Result<usize, SqlError> {
        definition.source = self.bind_routine_result(definition.source, 0)?;
        definition.target = self.bind_routine_result(definition.target, 0)?;
        self.validate_cast_definition(definition, 0)?;
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        if casts.iter().any(|candidate| {
            candidate.database == current_database()
                && candidate.visible_to(0)
                && candidate.source == definition.source
                && candidate.target == definition.target
        }) {
            return Err(sql_err!(sqlstate::DUPLICATE_OBJECT, "cast already exists"));
        }
        let Some(slot) = casts
            .iter()
            .position(|candidate| candidate.ddl_state == CatalogDdlState::Absent)
        else {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "too many casts (limit {})",
                casts.len()
            ));
        };
        self.catalog_sequence.observe(definition.created_at);
        definition.ddl_state = CatalogDdlState::Present;
        casts[slot] = definition;
        Ok(slot)
    }

    pub(crate) fn drop_cast(
        &mut self,
        source: RoutineResult,
        target: RoutineResult,
        txid: u32,
    ) -> Result<Option<usize>, SqlError> {
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        if let Some(blocker) = casts.iter().find_map(|definition| {
            (definition.database == current_database()
                && definition.source == source
                && definition.target == target)
                .then_some(definition.ddl_state.pending_txid()?)
                .filter(|&owner| owner != txid)
        }) {
            drop(casts);
            return Err(self.catalog_ddl_wait_error(txid, blocker, "cast"));
        }
        let Some(slot) = casts.iter().position(|definition| {
            definition.database == current_database()
                && definition.visible_to(txid)
                && definition.source == source
                && definition.target == target
        }) else {
            return Ok(None);
        };
        casts[slot].ddl_state = casts[slot].ddl_state.drop_by(txid);
        Ok(Some(slot))
    }

    pub(crate) fn commit_cast_create(&mut self, slot: usize) {
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        casts[slot].ddl_state = casts[slot].ddl_state.commit_create();
    }

    pub(crate) fn rollback_cast_create(&mut self, slot: usize) {
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        casts[slot].ddl_state = casts[slot].ddl_state.rollback_create();
        casts[slot] = CastDef::EMPTY;
    }

    pub(crate) fn commit_cast_drop(&mut self, slot: usize) {
        let oid = {
            let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
            let oid = casts[slot].oid() as u32;
            casts[slot].ddl_state = casts[slot].ddl_state.commit_drop();
            casts[slot] = CastDef::EMPTY;
            oid
        };
        self.drop_comments_by_subid(CommentClass::Cast, oid);
    }

    pub(crate) fn rollback_cast_drop(&mut self, slot: usize, txid: u32) {
        let mut casts = self.casts.lock().expect("cast catalog lock poisoned");
        casts[slot].ddl_state = casts[slot].ddl_state.rollback_drop(txid);
    }

    pub(crate) fn operators_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, OperatorDefinition)> + '_ {
        OperatorIter {
            catalog: &self.operator_catalog,
            next_slot: 0,
        }
        .filter(move |(_, operator)| {
            operator.database == current_database() && operator.visible_to(txid)
        })
        .map(move |(slot, operator)| (slot, operator.definition_for(txid)))
    }

    pub(crate) fn operator_count(&self) -> usize {
        self.operator_catalog
            .lock()
            .expect("operator catalog lock poisoned")
            .operators
            .len()
    }

    pub(crate) fn collations_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, CollationDefinition)> + '_ {
        CollationIter {
            catalog: &self.text_catalog,
            next_slot: 0,
        }
        .filter(move |(_, collation)| {
            collation.database == current_database() && collation.visible_to(txid)
        })
        .map(move |(slot, collation)| (slot, collation.definition_for(txid)))
    }

    pub(crate) fn collation_capacity(&self) -> usize {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .collations
            .len()
    }

    pub(crate) fn conversions_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, ConversionDefinition)> + '_ {
        ConversionIter {
            catalog: &self.text_catalog,
            next_slot: 0,
        }
        .filter(move |(_, conversion)| {
            conversion.database == current_database() && conversion.visible_to(txid)
        })
        .map(move |(slot, conversion)| (slot, conversion.definition_for(txid)))
    }

    pub(crate) fn conversion_capacity(&self) -> usize {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .conversions
            .len()
    }

    pub(crate) fn text_search_objects_visible_to(
        &self,
        txid: u32,
    ) -> impl Iterator<Item = (usize, TextSearchDefinition)> + '_ {
        TextSearchIter {
            catalog: &self.text_catalog,
            next_slot: 0,
        }
        .filter(move |(_, object)| object.database == current_database() && object.visible_to(txid))
        .map(move |(slot, object)| (slot, object.definition_for(txid)))
    }

    pub(crate) fn text_search_object_capacity(&self) -> usize {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .text_search_objects
            .len()
    }

    pub(crate) fn text_search_object(&self, slot: usize) -> TextSearchDef {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .text_search_objects[slot]
    }

    pub(crate) fn text_search_slot(
        &self,
        kind: crate::sql::ast::TextSearchObjectKind,
        schema: &str,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        self.text_search_objects_visible_to(txid)
            .find_map(|(slot, definition)| {
                (definition.kind() == kind
                    && definition.schema().as_str() == schema
                    && definition.name().as_str() == name)
                    .then_some(slot)
            })
    }

    pub(crate) fn text_search_slot_on_path(
        &self,
        kind: crate::sql::ast::TextSearchObjectKind,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        match schema {
            Some(schema) => self.text_search_slot(kind, schema, name, txid),
            None => self.path().entries().iter().find_map(|entry| match entry {
                PathEntry::Schema(slot) => self.text_search_slot(
                    kind,
                    self.schema_def(*slot as usize).name.as_str(),
                    name,
                    txid,
                ),
                PathEntry::Catalog => self.text_search_slot(kind, "pg_catalog", name, txid),
            }),
        }
    }

    pub(crate) fn text_search_slot_by_oid(
        &self,
        kind: crate::sql::ast::TextSearchObjectKind,
        oid: i32,
        txid: u32,
    ) -> Option<usize> {
        self.text_search_objects_visible_to(txid)
            .find_map(|(slot, definition)| {
                (definition.kind() == kind && definition.oid() == oid).then_some(slot)
            })
    }

    pub(crate) fn collation(&self, slot: usize) -> CollationDef {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .collations[slot]
    }

    pub(crate) fn conversion(&self, slot: usize) -> ConversionDef {
        self.text_catalog
            .lock()
            .expect("text catalog lock poisoned")
            .conversions[slot]
    }

    pub(crate) fn collation_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        self.collations_visible_to(txid)
            .find_map(|(slot, definition)| {
                (definition.schema.as_str() == schema && definition.name.as_str() == name)
                    .then_some(slot)
            })
    }

    pub(crate) fn collation_slot_on_path(
        &self,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        match schema {
            Some(schema) => self.collation_slot(schema, name, txid),
            None => self.path().entries().iter().find_map(|entry| match entry {
                PathEntry::Schema(slot) => {
                    self.collation_slot(self.schema_def(*slot as usize).name.as_str(), name, txid)
                }
                PathEntry::Catalog => None,
            }),
        }
    }

    pub(crate) fn resolve_collation(
        &self,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<Collation> {
        let catalog = schema.is_none_or(|schema| schema.eq_ignore_ascii_case("pg_catalog"));
        if catalog {
            let builtin = Collation::BUILTIN
                .into_iter()
                .find(|collation| collation.name().eq_ignore_ascii_case(name));
            if builtin.is_some() {
                return builtin;
            }
        }
        let slot = self.collation_slot_on_path(schema, name, txid)?;
        u8::try_from(slot).ok().map(Collation::Catalog)
    }

    pub(crate) fn conversion_slot(&self, schema: &str, name: &str, txid: u32) -> Option<usize> {
        self.conversions_visible_to(txid)
            .find_map(|(slot, definition)| {
                (definition.schema.as_str() == schema && definition.name.as_str() == name)
                    .then_some(slot)
            })
    }

    pub(crate) fn conversion_slot_on_path(
        &self,
        schema: Option<&str>,
        name: &str,
        txid: u32,
    ) -> Option<usize> {
        match schema {
            Some(schema) => self.conversion_slot(schema, name, txid),
            None => self.path().entries().iter().find_map(|entry| match entry {
                PathEntry::Schema(slot) => {
                    self.conversion_slot(self.schema_def(*slot as usize).name.as_str(), name, txid)
                }
                PathEntry::Catalog => None,
            }),
        }
    }

    pub(crate) fn default_conversion(
        &self,
        source: PgEncoding,
        destination: PgEncoding,
        txid: u32,
    ) -> Option<ConversionDefinition> {
        self.path().entries().iter().find_map(|entry| {
            let PathEntry::Schema(schema_slot) = entry else {
                return None;
            };
            let schema = self.schema_def(*schema_slot as usize).name;
            self.conversions_visible_to(txid)
                .find_map(|(_, definition)| {
                    (definition.schema == schema
                        && definition.source == source
                        && definition.destination == destination
                        && definition.default)
                        .then_some(definition)
                })
        })
    }

    pub(crate) fn create_collation(
        &mut self,
        definition: CollationDefinition,
        txid: u32,
    ) -> Result<usize, SqlError> {
        let behavior = self.executable_collation_behavior(
            definition.provider,
            definition.collate.as_str(),
            definition.ctype.as_str(),
            definition.locale.as_str(),
        )?;
        if behavior != definition.behavior {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "collation execution behavior does not match its definition"
            ));
        }
        self.require_schema_create(definition.schema.as_str(), txid)?;
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        if catalog.collations.iter().any(|candidate| {
            candidate.database == current_database()
                && candidate.visible_to(txid)
                && candidate.definition_for(txid).schema == definition.schema
                && candidate.definition_for(txid).name == definition.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "collation \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        let slot = catalog
            .collations
            .iter()
            .position(|candidate| candidate.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many collations (limit {})",
                    catalog.collations.len()
                )
            })?;
        let created_at = self.catalog_sequence.next();
        catalog.collations[slot] = CollationDef {
            database: current_database(),
            created_at,
            definition,
            pending: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn create_conversion(
        &mut self,
        definition: ConversionDefinition,
        txid: u32,
    ) -> Result<usize, SqlError> {
        self.require_schema_create(definition.schema.as_str(), txid)?;
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        if catalog.conversions.iter().any(|candidate| {
            candidate.database == current_database()
                && candidate.visible_to(txid)
                && candidate.definition_for(txid).schema == definition.schema
                && candidate.definition_for(txid).name == definition.name
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "conversion \"{}\" already exists",
                definition.name.as_str()
            ));
        }
        if definition.default
            && catalog.conversions.iter().any(|entry| {
                let candidate = entry.definition_for(txid);
                entry.database == current_database()
                    && entry.visible_to(txid)
                    && candidate.schema == definition.schema
                    && candidate.source == definition.source
                    && candidate.destination == definition.destination
                    && candidate.default
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "default conversion for {} to {} already exists",
                definition.source.name(),
                definition.destination.name()
            ));
        }
        let slot = catalog
            .conversions
            .iter()
            .position(|candidate| candidate.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many conversions (limit {})",
                    catalog.conversions.len()
                )
            })?;
        let created_at = self.catalog_sequence.next();
        catalog.conversions[slot] = ConversionDef {
            database: current_database(),
            created_at,
            definition,
            pending: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn create_text_search_object(
        &mut self,
        mut definition: TextSearchDefinition,
        txid: u32,
    ) -> Result<usize, SqlError> {
        if !definition.executable_shape() {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "text-search definition is not executable"
            ));
        }
        self.require_schema_create(definition.schema().as_str(), txid)?;
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        if catalog.text_search_objects.iter().any(|entry| {
            let candidate = entry.definition_for(txid);
            entry.database == current_database()
                && entry.visible_to(txid)
                && candidate.kind() == definition.kind()
                && candidate.schema() == definition.schema()
                && candidate.name() == definition.name()
        }) {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "{} \"{}\" already exists",
                definition.kind().noun(),
                definition.name().as_str()
            ));
        }
        let slot = catalog
            .text_search_objects
            .iter()
            .position(|candidate| candidate.ddl_state == CatalogDdlState::Absent)
            .ok_or_else(|| {
                sql_err!(
                    sqlstate::PROGRAM_LIMIT_EXCEEDED,
                    "too many text search objects (limit {})",
                    catalog.text_search_objects.len()
                )
            })?;
        let base = match definition.kind() {
            crate::sql::ast::TextSearchObjectKind::Parser => 310_000,
            crate::sql::ast::TextSearchObjectKind::Template => 311_000,
            crate::sql::ast::TextSearchObjectKind::Dictionary => 312_000,
            crate::sql::ast::TextSearchObjectKind::Configuration => 313_000,
        };
        definition.set_oid(base + slot as i32);
        let created_at = self.catalog_sequence.next();
        catalog.text_search_objects[slot] = TextSearchDef {
            database: current_database(),
            created_at,
            definition,
            pending: None,
            ddl_state: CatalogDdlState::PendingCreate { txid },
        };
        Ok(slot)
    }

    pub(crate) fn alter_text_search_object(
        &mut self,
        slot: usize,
        definition: TextSearchDefinition,
        txid: u32,
    ) -> Result<Option<PendingTextSearchDefinition>, SqlError> {
        if !definition.executable_shape() {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "text-search definition is not executable"
            ));
        }
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        let old = catalog.text_search_objects[slot].definition_for(txid);
        if catalog
            .text_search_objects
            .iter()
            .enumerate()
            .any(|(other, entry)| {
                let candidate = entry.definition_for(txid);
                other != slot
                    && entry.database == current_database()
                    && entry.visible_to(txid)
                    && candidate.kind() == definition.kind()
                    && candidate.schema() == definition.schema()
                    && candidate.name() == definition.name()
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "{} already exists",
                definition.kind().noun()
            ));
        }
        let prior = catalog.text_search_objects[slot].pending;
        if prior.is_some_and(|pending| pending.txid != txid) {
            return Err(sql_err!(
                sqlstate::OBJECT_NOT_IN_PREREQUISITE_STATE,
                "{} is being altered by another transaction",
                definition.kind().noun()
            ));
        }
        catalog.text_search_objects[slot].pending =
            Some(PendingTextSearchDefinition { txid, definition });
        drop(catalog);
        self.stage_object_comment_identity(
            text_search_comment_class(old.kind()),
            old.schema(),
            old.name(),
            definition.schema(),
            definition.name(),
            txid,
        );
        Ok(prior)
    }

