    pub(crate) fn replay_collation(
        &mut self,
        slot: usize,
        created_at: u64,
        definition: CollationDefinition,
    ) -> Result<(), SqlError> {
        let behavior = self.executable_collation_behavior(
            definition.provider,
            definition.collate.as_str(),
            definition.ctype.as_str(),
            definition.locale.as_str(),
        )?;
        if behavior != definition.behavior {
            return Err(sql_err!(
                sqlstate::INVALID_OBJECT_DEFINITION,
                "journal collation behavior does not match its definition"
            ));
        }
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        if slot >= catalog.collations.len() {
            return Err(sql_err!(
                sqlstate::PROGRAM_LIMIT_EXCEEDED,
                "journal collation slot is out of range"
            ));
        }
        if catalog
            .collations
            .iter()
            .enumerate()
            .any(|(other, candidate)| {
                other != slot
                    && candidate.database == current_database()
                    && candidate.ddl_state != CatalogDdlState::Absent
                    && candidate.definition.schema == definition.schema
                    && candidate.definition.name == definition.name
            })
        {
            return Err(sql_err!(
                sqlstate::DUPLICATE_OBJECT,
                "journal replays duplicate collation \"{}\"",
                definition.name.as_str()
            ));
        }
        let old = (catalog.collations[slot].ddl_state != CatalogDdlState::Absent)
            .then_some(catalog.collations[slot].definition);
        self.catalog_sequence.observe(created_at);
        catalog.collations[slot] = CollationDef {
            database: current_database(),
            created_at,
            definition,
            pending: None,
            ddl_state: CatalogDdlState::Present,
        };
        drop(catalog);
        let old_identity = if let Some(old) = old {
            self.replay_object_comment_identity(
                CommentClass::Collation,
                old.schema,
                old.name,
                definition.schema,
                definition.name,
            );
            Some((old.schema, old.name))
        } else {
            None
        };
        // Checkpoint dependencies deliberately deserialize with an unbound
        // slot. Match their old durable name during replay, then bind the slot
        // and new identity together so rename-after-checkpoint survives cold
        // recovery. A genuine create has no old identity and remains a no-op.
        self.rename_stored_query_dependency(
            DependencyClass::Collation,
            slot,
            old_identity,
            definition.schema,
            definition.name,
        );
        Ok(())
    }

    pub(crate) fn replay_drop_collation(&mut self, schema: &str, name: &str) {
        let mut catalog = self
            .text_catalog
            .lock()
            .expect("text catalog lock poisoned");
        let removed = catalog.collations.iter().position(|entry| {
            let definition = entry.definition_for(0);
            entry.database == current_database()
                && entry.visible_to(0)
                && definition.schema.as_str() == schema
                && definition.name.as_str() == name
        });
        if let Some(slot) = removed {
            catalog.collations[slot] = CollationDef::EMPTY;
        }
        drop(catalog);
        if removed.is_some() {
            self.drop_object_comments(CommentClass::Collation, schema, name);
        }
    }

